-- TO SWITCH MODELS (exactly one enabled row is the clearest mental model;
-- with several enabled, the HIGHEST priority wins):
--
--   update public.ai_model_configs set enabled = false where seam = 'assistant';
--   update public.ai_model_configs set enabled = true
--    where seam = 'assistant' and model = 'anthropic/claude-sonnet-5';

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260908120000_audit_s1_whatsapp_identities.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Audit S1 (2026-09-08) — WhatsApp verified identity moves to a server-owned
-- table; inbound writer revalidates membership + write role.
--
-- THE HOLE THIS CLOSES
-- phone_number / phone_verified_at / whatsapp_household_id sat on `profiles`,
-- covered only by "users update own profile" (id = auth.uid()). Any
-- authenticated user could self-assert a phone-verification state and pick a
-- household reference, and whatsapp_log_transaction then resolved membership
-- but explicitly tolerated a NULL result — a fabricated link could log
-- transactions into someone else's household.
--
-- THE FIX
--   1. `whatsapp_identities` — server-owned (RLS enabled, NO policies →
--      deny-all to anon/authenticated; Edge Functions use the service role,
--      which bypasses RLS). This is the only place a verified phone ↔
--      profile ↔ household binding may be written.
--   2. The legacy profiles columns are frozen by trigger: any non-service-role
--      UPDATE that changes them raises 42501. Ordinary profile edits (display
--      name, formats) pass — the guard fires only when those three columns
--      actually change.
--   3. whatsapp_log_transaction now REJECTS absent membership and viewer
--      (read-only) members instead of logging with a null member, and its
--      account resolution excludes soft-deleted rows.
--
-- The profiles columns are left in place (deprecated) so the previous Edge
-- Function deploy keeps working during the migration→deploy window; nothing
-- may write them client-side after this lands.
-- ============================================================================

BEGIN;

-- ── 1. Server-owned identity table ─────────────────────────────────────────
create table if not exists public.whatsapp_identities (
  profile_id   uuid primary key references public.profiles(id) on delete cascade,
  phone_number text not null,
  household_id uuid not null references public.households(id) on delete cascade,
  verified_at  timestamptz not null default now(),
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
-- One phone number ↔ one identity, globally.
create unique index if not exists uq_whatsapp_identities_phone
  on public.whatsapp_identities(phone_number);

alter table public.whatsapp_identities enable row level security;
-- Deliberately NO policies: deny-all to anon/authenticated.
revoke all on public.whatsapp_identities from public, anon, authenticated;
grant select, insert, update, delete on public.whatsapp_identities to service_role;

-- Backfill from the legacy columns (verified links only).
insert into public.whatsapp_identities (profile_id, phone_number, household_id, verified_at)
select id, phone_number, whatsapp_household_id, phone_verified_at
  from public.profiles
 where phone_number is not null
   and phone_verified_at is not null
   and whatsapp_household_id is not null
on conflict (profile_id) do nothing;

-- ── 2. Freeze the legacy columns against client writes ─────────────────────
create or replace function public.guard_whatsapp_profile_columns()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_claims text;
  v_role   text;
begin
  -- The service role (Edge Functions) manages these columns; everyone else —
  -- including the row owner and direct-SQL sessions (no JWT claims) — may not
  -- change them.
  v_claims := nullif(current_setting('request.jwt.claims', true), '');
  v_role := case when v_claims is null then ''
                 else coalesce(v_claims::jsonb ->> 'role', '') end;
  if v_role = 'service_role' then
    return new;
  end if;
  if new.phone_number is not distinct from old.phone_number
     and new.phone_verified_at is not distinct from old.phone_verified_at
     and new.whatsapp_household_id is not distinct from old.whatsapp_household_id then
    return new;  -- untouched by this UPDATE — ordinary profile edit
  end if;
  raise exception 'phone_number, phone_verified_at and whatsapp_household_id are server-managed; use the WhatsApp link flow'
    using errcode = '42501';
end $$;

drop trigger if exists trg_guard_whatsapp_profile_columns on public.profiles;
create trigger trg_guard_whatsapp_profile_columns
before update on public.profiles
for each row execute function public.guard_whatsapp_profile_columns();

-- ── 3. Harden the inbound writer ───────────────────────────────────────────
-- Same signature as 20260906130000 (drop+recreate because grants are dropped
-- with the function; re-issued below).
drop function if exists public.whatsapp_log_transaction(
  uuid, uuid, numeric, text, text, text, text, text, text, text, date
);

create or replace function public.whatsapp_log_transaction(
  p_profile_id      uuid,
  p_household_id    uuid,
  p_amount          numeric,
  p_currency        text,
  p_txn_type        text,
  p_category_id     text,
  p_account_alias   text,
  p_to_account_alias text,
  p_wa_message_id   text,
  p_description     text,
  p_date            date default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_member_id     uuid;
  v_member_role   text;
  v_account_id    uuid;
  v_to_account_id uuid;
  v_cash_id       uuid;
  v_txn_id        uuid;
  v_claimed       int;
  v_date          date;
begin
  -- Sanity-clamp the incoming date (see 20260906130000 for the rationale).
  v_date := coalesce(p_date, current_date);
  if v_date > current_date + interval '2 days' or v_date < current_date - interval '5 years' then
    v_date := current_date;
  end if;
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('status','error','reason','invalid_amount');
  end if;
  if p_txn_type not in ('expense','income','investment','transfer') then
    return jsonb_build_object('status','error','reason','invalid_type');
  end if;

  -- Idempotency claim-first (unchanged from v10.18/v10.20).
  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;

  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('status','duplicate');
  end if;

  -- Audit S1: membership is now MANDATORY and must carry a write role. The
  -- previous version noted "nullable is fine" — with the identity link now
  -- client-forgeable no longer, this is the second gate: a revoked member (or
  -- a viewer) cannot log, even while their identity row still exists.
  select id, role into v_member_id, v_member_role
    from public.memberships
   where household_id = p_household_id and user_id = p_profile_id
   limit 1;
  if v_member_id is null then
    return jsonb_build_object('status','error','reason','not_a_member');
  end if;
  if v_member_role = 'viewer' then
    return jsonb_build_object('status','error','reason','read_only_member');
  end if;

  -- Cash fallback account for this household (audit S1: exclude soft-deleted).
  select id into v_cash_id
    from public.accounts
   where household_id = p_household_id and lower(kind) = 'cash'
     and coalesce(is_archived,false) = false and deleted_at is null
   limit 1;

  -- Resolve source alias (name or kind).
  if p_account_alias is not null and p_account_alias <> '' then
    select id into v_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_account_alias) or lower(kind) = lower(p_account_alias))
     limit 1;
  end if;

  -- Resolve destination alias (name or kind).
  if p_to_account_alias is not null and p_to_account_alias <> '' then
    select id into v_to_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_to_account_alias) or lower(kind) = lower(p_to_account_alias))
     limit 1;
  end if;

  -- Apply the per-type account matrix + cash fallbacks.
  if p_txn_type = 'expense' then
    v_account_id := coalesce(v_account_id, v_cash_id);
    v_to_account_id := null;
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
  elsif p_txn_type = 'income' then
    v_to_account_id := coalesce(v_to_account_id, v_account_id, v_cash_id);
    v_account_id := null;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
  else  -- transfer / investment: both required, must differ
    v_account_id := coalesce(v_account_id, v_cash_id);
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
    if v_to_account_id = v_account_id then
      return jsonb_build_object('status','error','reason','same_account');
    end if;
  end if;

  insert into public.transactions (
    household_id, created_by, member_id, amount, currency, type, category,
    account_id, to_account_id, date, description
  ) values (
    p_household_id,
    p_profile_id,
    v_member_id,
    p_amount,
    coalesce(nullif(p_currency,''), 'USD'),
    p_txn_type,
    case when p_txn_type in ('expense','income')
         then coalesce(nullif(p_category_id,''), case when p_txn_type='expense' then 'other_expense' else 'other_income' end)
         else null end,
    v_account_id,
    v_to_account_id,
    v_date,
    coalesce(nullif(p_description,''), 'Logged via WhatsApp')
  ) returning id into v_txn_id;

  -- Store the parsed result on the audit row for traceability.
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload,'{}'::jsonb) || jsonb_build_object(
           'parsed', jsonb_build_object(
             'transaction_id', v_txn_id, 'amount', p_amount, 'currency', p_currency,
             'type', p_txn_type, 'category_id', p_category_id,
             'account_id', v_account_id, 'to_account_id', v_to_account_id))
   where wa_message_id = p_wa_message_id;

  return jsonb_build_object(
    'status','success',
    'transaction_id', v_txn_id,
    'amount', p_amount,
    'currency', coalesce(nullif(p_currency,''),'USD'),
    'type', p_txn_type,
    'category_id', p_category_id,
    'account_name',    (select name from public.accounts where id = v_account_id),
    'to_account_name', (select name from public.accounts where id = v_to_account_id)
  );
end;
$$;

revoke all on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date) from public, anon, authenticated;
grant execute on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date) to service_role;

comment on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date) is
  'v10.20+audit-S1 — WhatsApp/agent transaction writer. v9 CHECK-safe, claim-first idempotent on wa_message_id, p_date backdate-aware (null => today, out-of-range clamps). Audit S1: membership is mandatory and viewers are rejected; account resolution excludes soft-deleted rows. Service-role only.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260908120100_audit_s2_membership_role_grants.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Audit S2 (2026-09-08) — constrain which roles a household admin may grant.
--
-- THE HOLE
-- The memberships INSERT policy checked the CALLER is owner/admin but never
-- constrained the ROLE being inserted — a household admin could insert a new
-- 'owner' membership. Hiding "owner" in a UI dropdown is not a boundary.
-- The UPDATE policy had the mirror-image gap: its USING clause stopped an
-- admin from touching an existing owner's row, but without a WITH CHECK an
-- admin could promote a member TO owner in one UPDATE.
--
-- THE RULE NOW (database-enforced)
--   • owners may insert/update rows to any role (including owner — that is
--     the ownership-transfer building block);
--   • admins may insert/update rows only to non-owner roles;
--   • everyone else: no grants (unchanged).
-- Owner-continuity (never demote/delete the last owner) is NOT enforced here —
-- that needs a dedicated transfer-ownership RPC and is tracked separately.
-- ============================================================================

BEGIN;

drop policy if exists "owners and admins add members" on memberships;
create policy "owners and admins add members" on memberships for insert with check (
  role_in(household_id) = 'owner'
  or (role_in(household_id) = 'admin' and role <> 'owner')
);

drop policy if exists "owners change roles; admins change non-owners" on memberships;
create policy "owners change roles; admins change non-owners" on memberships for update
  using (
    -- existing row: admins may not touch an owner's membership
    role_in(household_id) = 'owner' or (role_in(household_id) = 'admin' and role <> 'owner')
  )
  with check (
    -- new row: admins may not GRANT ownership either
    role_in(household_id) = 'owner' or (role_in(household_id) = 'admin' and role <> 'owner')
  );

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260908120200_audit_s6_erase_onboarding_fix.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Audit S6 (2026-09-08) — erase_household_data violated its own schema.
--
-- THE BUG
-- The erase RPC ended with `update households set onboarding = null`, but
-- households.onboarding is `jsonb NOT NULL DEFAULT '{}'` with a CHECK that it
-- be a JSON object (20260606120000). Every real erase therefore raised 23502
-- and the WHOLE transactional wipe rolled back — "erase my data" has never
-- worked against the committed schema, and it failed silently for the user
-- behind a generic error.
--
-- THE FIX
-- Reset onboarding to its empty baseline ('{}'::jsonb) instead of null —
-- semantically identical (no onboarding state survives) and schema-legal.
-- Function body is otherwise byte-identical to 20260701120000.
-- ============================================================================

BEGIN;

create or replace function erase_household_data(h_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  caller_role text;
begin
  select role into caller_role
  from memberships
  where household_id = h_id and user_id = auth.uid()
  limit 1;

  if caller_role is null or caller_role not in ('owner', 'admin') then
    raise exception 'not authorized to erase this household''s data';
  end if;

  delete from transactions        where household_id = h_id;
  delete from budgets              where household_id = h_id;
  delete from budget_allocations   where household_id = h_id;
  delete from goals                where household_id = h_id;
  delete from debts                where household_id = h_id;
  delete from assets               where household_id = h_id;
  delete from accounts             where household_id = h_id;
  delete from recurring_schedules  where household_id = h_id;
  delete from saved_views          where household_id = h_id;
  delete from activity_log         where household_id = h_id;

  -- Onboarding baseline/reference overlay (v9.7.0) lives in households.onboarding.
  -- NOT NULL + object CHECK ⇒ reset to the empty baseline, never null (audit S6).
  update households set onboarding = '{}'::jsonb where id = h_id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id, changes)
  values (h_id, auth.uid(), 'erase_household_data', 'household', h_id, jsonb_build_object('erased_at', now()));
end;
$$;

-- `create or replace` keeps existing grants; re-assert for safety.
grant execute on function erase_household_data(uuid) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260908120300_audit_f2_record_loan_payment.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Audit F2 (2026-09-08) — record_loan_payment: ONE atomic command for an EMI.
--
-- THE BUGS THIS REPLACES
--   1. The client EMI branch was unreachable from the transaction form (the
--      form pre-assigns an id; the branch required `!t.id`), so a loan EMI was
--      stored as a plain expense — no interest/principal split, no debt
--      re-amortisation, silently.
--   2. The intended path wrote expense → principal leg → account → debt
--      SEQUENTIALLY from the browser; a failure mid-way left a half-written
--      payment.
--   3. The loan account was linked via accounts.asset_id = debt.id — a column
--      whose FK points at assets, not debts, so the cloud write violated
--      23503 the moment the branch ever ran. (Explicit linkage instead:
--      accounts.debt_id — audit §8.2.)
--
-- THE DIVISION OF LABOUR (matches "the model never computes money" rule)
--   The RE-AMORTISATION MATH (interest/principal split, tenure/EMI strategy)
--   stays in the parity-tested TypeScript port (lib/amortization.ts). This RPC
--   VALIDATES the decomposition's shape (interest+principal = amount, tenancy,
--   non-negative, within outstanding) and applies all writes in ONE
--   transaction, idempotent on p_operation_id so a retried call cannot
--   double-post.
-- ============================================================================

BEGIN;

-- ── 1. Explicit account ↔ debt linkage (audit §8.2) ────────────────────────
-- asset_id stays for asset-backed accounts; debt_id is the loan/credit-card
-- counterpart. Nullable; one loan account per debt in practice.
alter table public.accounts
  add column if not exists debt_id uuid references public.debts(id) on delete set null;
create index if not exists accounts_debt
  on public.accounts (household_id, debt_id) where debt_id is not null;

-- ── 2. Idempotency + audit record for the command ──────────────────────────
create table if not exists public.loan_payment_events (
  operation_id    uuid primary key,
  household_id    uuid not null references public.households(id) on delete cascade,
  debt_id         uuid not null references public.debts(id) on delete cascade,
  expense_txn_id  uuid references public.transactions(id) on delete set null,
  transfer_txn_id uuid references public.transactions(id) on delete set null,
  loan_account_id uuid references public.accounts(id) on delete set null,
  amount          numeric not null,
  interest        numeric not null,
  principal       numeric not null,
  created_at      timestamptz not null default now()
);
alter table public.loan_payment_events enable row level security;
-- Members may READ their household's events (retry/duplicate visibility);
-- only this function (security definer) writes them.
create policy "members read own household loan payment events"
  on public.loan_payment_events for select using (is_member(household_id));

-- ── 3. The command ─────────────────────────────────────────────────────────
create or replace function public.record_loan_payment(
  p_operation_id         uuid,
  p_debt_id              uuid,
  p_funding_account_id   uuid,
  p_amount               numeric,
  p_currency             text,
  p_date                 date,
  p_interest             numeric,
  p_principal            numeric,
  p_member_id            uuid default null,
  p_description          text default null,
  p_new_balance          numeric default null,
  p_new_remaining_months integer default null,
  p_new_minimum_payment  numeric default null,
  p_payment_log_entry    jsonb default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_hid             uuid;
  v_debt            public.debts%rowtype;
  v_expense_id      uuid;
  v_transfer_id     uuid;
  v_loan_account_id uuid;
  v_existing        public.loan_payment_events%rowtype;
  v_claimed         uuid;
begin
  -- 0. Idempotency: a retried operation returns its original outcome and
  --    writes nothing twice.
  select * into v_existing from public.loan_payment_events
   where operation_id = p_operation_id;
  if found then
    return jsonb_build_object('status','duplicate',
      'expense_txn_id',  v_existing.expense_txn_id,
      'transfer_txn_id', v_existing.transfer_txn_id,
      'loan_account_id', v_existing.loan_account_id);
  end if;

  -- 1. Debt must exist, be live; lock it so concurrent payments serialise.
  select * into v_debt from public.debts
   where id = p_debt_id and deleted_at is null
   for update;
  if not found then
    return jsonb_build_object('status','error','reason','debt_not_found');
  end if;
  v_hid := v_debt.household_id;

  -- 2. Caller must hold a WRITE role in the debt's household (viewer blocked).
  if coalesce(role_in(v_hid), 'viewer') not in ('owner','admin','member') then
    return jsonb_build_object('status','error','reason','not_authorized');
  end if;

  -- 3. Funding account must belong to the SAME household and be usable.
  if not exists (
    select 1 from public.accounts
     where id = p_funding_account_id and household_id = v_hid
       and deleted_at is null and coalesce(is_archived,false) = false
  ) then
    return jsonb_build_object('status','error','reason','funding_account_invalid');
  end if;

  -- 4. Decomposition shape: non-negative legs that sum to the amount, within
  --    the outstanding balance. The arithmetic itself was computed by the
  --    parity-tested client port; here we refuse anything that does not
  --    reconcile.
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('status','error','reason','invalid_amount');
  end if;
  if p_interest is null or p_principal is null or p_interest < 0 or p_principal < 0 then
    return jsonb_build_object('status','error','reason','invalid_split');
  end if;
  if abs((p_interest + p_principal) - p_amount) > 0.01 then
    return jsonb_build_object('status','error','reason','split_mismatch');
  end if;
  if p_interest = 0 and p_principal = 0 then
    return jsonb_build_object('status','error','reason','empty_payment');
  end if;
  if p_new_balance is not null and (p_new_balance < 0 or p_new_balance > v_debt.current_balance + 0.01) then
    return jsonb_build_object('status','error','reason','balance_out_of_range');
  end if;

  -- 5. Claim the operation id (second concurrent caller becomes a duplicate).
  insert into public.loan_payment_events (operation_id, household_id, debt_id, amount, interest, principal)
  values (p_operation_id, v_hid, p_debt_id, p_amount, p_interest, p_principal)
  on conflict (operation_id) do nothing
  returning operation_id into v_claimed;
  if v_claimed is null then
    select * into v_existing from public.loan_payment_events where operation_id = p_operation_id;
    return jsonb_build_object('status','duplicate',
      'expense_txn_id',  v_existing.expense_txn_id,
      'transfer_txn_id', v_existing.transfer_txn_id,
      'loan_account_id', v_existing.loan_account_id);
  end if;

  -- 6. Find-or-create the linked loan (liability) account — via debt_id,
  --    NOT the asset FK that broke the old path (audit F2 sub-2).
  select id into v_loan_account_id from public.accounts
   where household_id = v_hid and debt_id = p_debt_id and kind = 'loan'
     and deleted_at is null
   limit 1;
  if v_loan_account_id is null then
    insert into public.accounts (household_id, kind, name, currency, debt_id)
    values (v_hid, 'loan', v_debt.name, v_debt.currency, p_debt_id)
    returning id into v_loan_account_id;
  end if;

  -- 7. Interest leg — the visible expense (the only leg that counts as spend).
  --    transactions.amount is CHECK(amount > 0), so a zero-interest leg
  --    (0%-APR loan) is simply not written.
  if p_interest > 0 then
    insert into public.transactions (
      household_id, created_by, member_id, amount, currency, type, category,
      account_id, debt_id, date, description, extras
    ) values (
      v_hid, auth.uid(), p_member_id, p_interest,
      coalesce(nullif(p_currency,''), v_debt.currency),
      'expense', 'loan_emi', p_funding_account_id, p_debt_id,
      coalesce(p_date, current_date),
      coalesce(nullif(p_description,''), v_debt.name || ' EMI'),
      jsonb_build_object('emi_split', jsonb_build_object(
        'interest', p_interest, 'principal', p_principal, 'debt_id', p_debt_id))
    ) returning id into v_expense_id;
  end if;

  -- 8. Principal leg — system transfer INTO the loan account (spend-neutral).
  if p_principal > 0 then
    insert into public.transactions (
      household_id, created_by, member_id, amount, currency, type, category,
      account_id, to_account_id, debt_id, date, description, extras
    ) values (
      v_hid, auth.uid(), p_member_id, p_principal,
      coalesce(nullif(p_currency,''), v_debt.currency),
      'transfer', null, p_funding_account_id, v_loan_account_id, p_debt_id,
      coalesce(p_date, current_date),
      coalesce(nullif(p_description,''), v_debt.name || ' EMI') || ' — principal',
      jsonb_build_object('emi_split', jsonb_build_object(
        'interest', p_interest, 'principal', p_principal, 'debt_id', p_debt_id),
        'linkedTxnId', v_expense_id)
    ) returning id into v_transfer_id;
  end if;

  -- 9. Re-amortised debt state + payment log entry (client-computed values,
  --    shape-validated above).
  update public.debts
     set current_balance = coalesce(p_new_balance, current_balance),
         minimum_payment = coalesce(p_new_minimum_payment, minimum_payment),
         extras = coalesce(extras, '{}'::jsonb)
           || case when p_new_remaining_months is not null
                   then jsonb_build_object('remainingMonths', p_new_remaining_months)
                   else '{}'::jsonb end
           || case when p_payment_log_entry is not null
                   then jsonb_build_object('paymentLog',
                        coalesce(extras->'paymentLog', '[]'::jsonb) || p_payment_log_entry)
                   else '{}'::jsonb end,
         updated_at = now()
   where id = p_debt_id;

  -- 10. Complete the event record.
  update public.loan_payment_events
     set expense_txn_id = v_expense_id,
         transfer_txn_id = v_transfer_id,
         loan_account_id = v_loan_account_id
   where operation_id = p_operation_id;

  return jsonb_build_object(
    'status', 'success',
    'expense_txn_id',  v_expense_id,
    'transfer_txn_id', v_transfer_id,
    'loan_account_id', v_loan_account_id);
end;
$$;

revoke all on function public.record_loan_payment(uuid,uuid,uuid,numeric,text,date,numeric,numeric,uuid,text,numeric,integer,numeric,jsonb) from public, anon;
grant execute on function public.record_loan_payment(uuid,uuid,uuid,numeric,text,date,numeric,numeric,uuid,text,numeric,integer,numeric,jsonb) to authenticated;

comment on function public.record_loan_payment(uuid,uuid,uuid,numeric,text,date,numeric,numeric,uuid,text,numeric,integer,numeric,jsonb) is
  'Audit F2 — one atomic loan-payment command: validates caller role, debt/account tenancy and split reconciliation, writes interest expense + principal transfer + re-amortised debt + payment log in a single transaction, idempotent on p_operation_id. Re-amortisation math is computed by the parity-tested client port (lib/amortization.ts); this function validates shape, never arithmetic.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260909120000_audit_s3_tenant_consistency.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Audit S3 (2026-09-09) — foreign keys prove a row EXISTS, not that it belongs
-- to the same household. These triggers enforce tenant consistency at the
-- database, so no API path (form, WhatsApp, RPC, direct PostgREST) can link
-- entities across households.
--
-- Rules enforced:
--   transactions.household_id == account_id.household_id
--   transactions.household_id == to_account_id.household_id
--   transactions.household_id == member_id.household_id
--   transactions.household_id == debt_id.household_id
--   budget_allocations.household_id == budget_id.household_id
--   shared_splits.owner_household_id: the owner is a member of it, and the
--     linked txn (if any) belongs to it.
--
-- Triggers (not composite FKs) because the references carry ON DELETE SET NULL
-- and nullable columns — a trigger checks only the non-null ones. Runs as the
-- table owner's definer context so RLS on the referenced table can't mask a
-- violation from the check itself.
-- ============================================================================

BEGIN;

create or replace function public.assert_txn_tenant_consistency()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.account_id is not null and not exists (
    select 1 from public.accounts
     where id = new.account_id and household_id = new.household_id
  ) then
    raise exception 'transactions.account_id belongs to a different household'
      using errcode = '23503';
  end if;
  if new.to_account_id is not null and not exists (
    select 1 from public.accounts
     where id = new.to_account_id and household_id = new.household_id
  ) then
    raise exception 'transactions.to_account_id belongs to a different household'
      using errcode = '23503';
  end if;
  if new.member_id is not null and not exists (
    select 1 from public.memberships
     where id = new.member_id and household_id = new.household_id
  ) then
    raise exception 'transactions.member_id belongs to a different household'
      using errcode = '23503';
  end if;
  if new.debt_id is not null and not exists (
    select 1 from public.debts
     where id = new.debt_id and household_id = new.household_id
  ) then
    raise exception 'transactions.debt_id belongs to a different household'
      using errcode = '23503';
  end if;
  return new;
end $$;

drop trigger if exists trg_txn_tenant_consistency on public.transactions;
create trigger trg_txn_tenant_consistency
before insert or update on public.transactions
for each row execute function public.assert_txn_tenant_consistency();

create or replace function public.assert_allocation_tenant_consistency()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if not exists (
    select 1 from public.budgets
     where id = new.budget_id and household_id = new.household_id
  ) then
    raise exception 'budget_allocations.budget_id belongs to a different household'
      using errcode = '23503';
  end if;
  return new;
end $$;

drop trigger if exists trg_allocation_tenant_consistency on public.budget_allocations;
create trigger trg_allocation_tenant_consistency
before insert or update on public.budget_allocations
for each row execute function public.assert_allocation_tenant_consistency();

create or replace function public.assert_split_tenant_consistency()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  -- The owner must actually be a member of the household they name.
  if not exists (
    select 1 from public.memberships
     where household_id = new.owner_household_id and user_id = new.owner_user_id
  ) then
    raise exception 'shared_splits.owner_household_id is not a household the owner belongs to'
      using errcode = '23503';
  end if;
  -- A linked transaction must live in that same household.
  if new.txn_id is not null and not exists (
    select 1 from public.transactions
     where id = new.txn_id and household_id = new.owner_household_id
  ) then
    raise exception 'shared_splits.txn_id belongs to a different household'
      using errcode = '23503';
  end if;
  return new;
end $$;

drop trigger if exists trg_split_tenant_consistency on public.shared_splits;
create trigger trg_split_tenant_consistency
before insert or update on public.shared_splits
for each row execute function public.assert_split_tenant_consistency();

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260909120100_audit_a2_atomic_ai_quota.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Audit A2 (2026-09-09) — AI spend cap becomes an ATOMIC reservation, not a
-- count-then-call race.
--
-- THE HOLE
-- The gateway did: SELECT count(*) … → call the provider → INSERT usage. Every
-- concurrent request passed the same count check, a failed count read was
-- treated as zero usage, and a failed metering write was ignored. Under any
-- parallelism the cap was advisory, and it failed OPEN.
--
-- THE FIX
-- `reserve_ai_usage(user_id, cap)` — one SECURITY DEFINER function that takes
-- a row lock on the user's profile (serialising their requests), counts their
-- LLM calls in the window, and either inserts a reservation row (a pending
-- ai_usage marker) or raises 42901. Counting and reserving are one statement
-- sequence under one lock: no two concurrent requests can both pass. A failed
-- count now fails CLOSED (the error aborts the reservation, and the gateway
-- does not call the provider). After the provider answers, the gateway
-- finalises the reservation row with the real tokens/cost/latency.
-- ============================================================================

BEGIN;

-- A reservation is a normal ai_usage row with outcome='reserved' written
-- BEFORE the provider call; the gateway UPDATEs it to the real outcome after.
-- The metering migration's outcome CHECK predates reservations — widen it.
alter table public.ai_usage drop constraint if exists ai_usage_outcome_chk;
alter table public.ai_usage add constraint ai_usage_outcome_chk
  check (outcome is null or outcome in ('ok','error','blocked','fallback','clarify','reserved'));

create or replace function public.reserve_ai_usage(
  p_user_id      uuid,
  p_household_id uuid,
  p_surface      text,
  p_cap          int
) returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count int;
  v_id    uuid;
begin
  -- Serialise this user's quota decisions on their profile row. Two of their
  -- concurrent requests now run one-after-another here, so the count below is
  -- exact at decision time.
  perform 1 from public.profiles where id = p_user_id for update;

  select count(*) into v_count
    from public.ai_usage
   where user_id = p_user_id
     and backend = 'llm'
     and ts >= now() - interval '24 hours';

  if v_count >= p_cap then
    raise exception 'quota_exceeded' using errcode = '42901';
  end if;

  insert into public.ai_usage (user_id, household_id, surface, backend, outcome, ts)
  values (p_user_id, p_household_id, p_surface, 'llm', 'reserved', now())
  returning id into v_id;
  return v_id;
end $$;

-- Called by the ask-vyact Edge Function with the service role; it must NOT be
-- client-callable (a client could reserve-then-abandon to inflate usage, or
-- call with a huge cap).
revoke all on function public.reserve_ai_usage(uuid, uuid, text, int) from public, anon, authenticated;
grant execute on function public.reserve_ai_usage(uuid, uuid, text, int) to service_role;

comment on function public.reserve_ai_usage(uuid, uuid, text, int) is
  'Audit A2 — atomic AI quota reservation. Row-locks the user profile, counts 24h llm usage, inserts a reservation row (outcome=reserved) or raises 42901. Fail-closed: a count error aborts the reservation. The gateway finalises the row after the provider answers.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260909120200_audit_a4_durable_inbox.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Audit A4 (2026-09-09) — the WhatsApp inbound pipeline becomes durable and
-- batch-correct.
--
-- BEFORE: the webhook read only `entry[0].changes[0].messages[0]` (every later
-- message in the webhook was DROPPED), did the DB work before ACK, and had no
-- record of WHAT was processed vs pending — a crash after ACK lost the message
-- silently.
--
-- NOW: the webhook records EVERY message as an inbox row (status 'pending')
-- and ACKs immediately. A separate claim step processes rows — atomic claim
-- (status flips pending→claimed only if still pending), so a redelivery or a
-- concurrent worker never double-processes; a failure re-marks 'failed' with a
-- retry count; a success marks 'done'. Nothing is lost after ACK.
-- ============================================================================

BEGIN;

alter table public.whatsapp_inbound_messages
  add column if not exists status text not null default 'pending',
  add column if not exists attempts int not null default 0,
  add column if not exists claimed_at timestamptz,
  add column if not exists last_error text;

-- Claim-ability index: the worker polls pending/claimable rows.
create index if not exists idx_wa_inbound_claim
  on public.whatsapp_inbound_messages (status, created_at)
  where direction = 'inbound';

comment on column public.whatsapp_inbound_messages.status is
  'Audit A4 — pending | claimed | done | failed. Claim is atomic (pending→claimed only if still pending) so concurrent workers and Meta redeliveries never double-process.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260909130000_v1021_category_travel_merge.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.21 — merge the `transport` category into `travel`.
--
-- WHY
-- The two were indistinguishable in practice: a taxi to the airport and the
-- flight it fed were filed apart for no reason a user could articulate. One
-- category now covers getting from A to B. (The holiday half of the old
-- `travel` becomes `holiday_outstay`, which is a NEW id — no existing row
-- carries it, so nothing needs moving for that one.)
--
-- REVERSIBLE BY DESIGN
-- Every table that stores a category gets a nullable `category_prev` column,
-- written with the value this migration replaced. Reverting is a single UPDATE
-- per table, and an auditor can always see what a row used to be. The column is
-- deliberately kept afterwards rather than dropped in a later cleanup — it is
-- the only record that the reclassification happened.
--
-- 🔴 THE HAZARD THIS MIGRATION EXISTS TO HANDLE
-- `budget_allocations` has a UNIQUE index `uq_balloc_cat (budget_id, category)
-- WHERE deleted_at IS NULL`. A budget holding BOTH a transport and a travel
-- allocation therefore CANNOT simply have transport renamed — the rename
-- collides and the migration aborts, which (since v10.20.5) blocks the whole
-- release. Verified against production before writing this: exactly one budget
-- is affected, holding transport 10000 and travel 200.
--
-- Colliding pairs are MERGED, not dropped: the amounts are summed into the
-- surviving travel row and the transport row is soft-deleted. Summing is the
-- only choice that keeps the budget's allocations reconciling against its
-- container total — picking one and discarding the other would silently change
-- how much the household had budgeted.
--
-- MONEY MODEL: no transaction is created, no amount changes, no account moves.
-- This is a reclassification. The sum of allocations per budget is preserved.
-- ============================================================================

BEGIN;

-- ── 1. Backup columns ──────────────────────────────────────────────────────
alter table public.transactions       add column if not exists category_prev text;
alter table public.budget_allocations add column if not exists category_prev text;
alter table public.budgets            add column if not exists category_prev text;

-- ── 2. budget_allocations — merge collisions FIRST, then rename the rest ───
-- Fold each colliding transport row into its budget's travel row.
with collisions as (
  select t.id  as transport_id,
         v.id  as travel_id,
         t.amount as transport_amount
  from public.budget_allocations t
  join public.budget_allocations v
    on v.budget_id = t.budget_id
   and v.category  = 'travel'
   and v.deleted_at is null
  where t.category = 'transport'
    and t.deleted_at is null
),
folded as (
  update public.budget_allocations v
     set amount        = v.amount + c.transport_amount,
         category_prev = coalesce(v.category_prev, 'travel'),
         updated_at    = now()
    from collisions c
   where v.id = c.travel_id
  returning v.id
)
update public.budget_allocations t
   set deleted_at    = now(),
       category_prev = 'transport',
       updated_at    = now()
  from collisions c
 where t.id = c.transport_id;

-- Everything left is a transport allocation with no travel sibling: rename it.
update public.budget_allocations
   set category      = 'travel',
       category_prev = 'transport',
       updated_at    = now()
 where category = 'transport'
   and deleted_at is null;

-- ── 3. transactions ────────────────────────────────────────────────────────
-- No unique constraint on category here, so a straight rename is safe.
update public.transactions
   set category      = 'travel',
       category_prev = 'transport',
       updated_at    = now()
 where category = 'transport';

-- ── 4. budgets (legacy per-category rows, pre-v9.1 container model) ────────
update public.budgets
   set category      = 'travel',
       category_prev = 'transport',
       updated_at    = now()
 where category = 'transport';

-- ── 5. recurring_schedules — category lives inside the jsonb template ──────
update public.recurring_schedules
   set txn_template = jsonb_set(txn_template, '{category}', '"travel"'),
       updated_at   = now()
 where txn_template->>'category' = 'transport';

-- ── 6. category_classifications — PK is the category itself ────────────────
-- A rename would collide with the existing travel row, so drop the transport
-- row only when travel is already classified; otherwise rename it.
update public.category_classifications
   set category = 'travel'
 where category = 'transport'
   and not exists (select 1 from public.category_classifications where category = 'travel');
delete from public.category_classifications where category = 'transport';

COMMIT;

-- Verify (run manually; not part of the migration):
--   select category, count(*) from public.budget_allocations
--    where deleted_at is null group by 1 order by 1;
--   -- expect: no 'transport' row anywhere, and for the previously colliding
--   -- budget a single travel allocation of 10200.

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260909140000_correct_loan_payment_contract.sql
-- ─────────────────────────────────────────────────────────────────────
BEGIN;

alter table public.loan_payment_events add column if not exists request jsonb;

create or replace function public.record_loan_payment(
  p_operation_id uuid, p_debt_id uuid, p_funding_account_id uuid,
  p_amount numeric, p_currency text, p_date date,
  p_interest numeric, p_principal numeric, p_member_id uuid default null,
  p_description text default null, p_new_balance numeric default null,
  p_new_remaining_months integer default null, p_new_minimum_payment numeric default null,
  p_payment_log_entry jsonb default null
) returns jsonb
language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  debt_row public.debts%rowtype;
  payment_event public.loan_payment_events%rowtype;
  account_row public.accounts%rowtype;
  actor_id uuid := auth.uid();
  member_id uuid;
  request_body jsonb;
  strategy text := p_payment_log_entry->>'partChoice';
  payment_date date := coalesce(p_date, current_date);
  payment_description text;
  currency_scale numeric;
  interest_units numeric;
  interest_amount numeric;
  principal_amount numeric;
  balance_after numeric;
  remaining integer;
  minimum_after numeric;
  monthly_rate numeric;
  payment_log jsonb;
  split_details jsonb;
  is_extra boolean;
  expense_id uuid;
  transfer_id uuid;
begin
  select * into debt_row from public.debts
    where id = p_debt_id and deleted_at is null for update;
  if not found or actor_id is null then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
  select id into member_id from public.memberships
    where household_id = debt_row.household_id and user_id = actor_id
      and role in ('owner', 'admin', 'member') for share;
  if not found then raise exception 'not_authorized' using errcode = '42501'; end if;

  if p_operation_id is null or p_date is null or p_amount is null
      or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount <= 0
      or p_currency is distinct from debt_row.currency
      or coalesce(debt_row.direction, 'owed_by_me') <> 'owed_by_me' then
    raise exception 'invalid_payment' using errcode = '22023';
  end if;
  if strategy is not null and strategy not in ('reduce_tenure','reduce_emi','apply_advance') then
    raise exception 'invalid_strategy' using errcode = '22023';
  end if;
  payment_description := coalesce(nullif(p_description,''), debt_row.name || ' EMI');
  request_body := jsonb_build_object('actor', actor_id, 'debt', p_debt_id,
    'funding', p_funding_account_id, 'amount', p_amount, 'currency', p_currency,
    'date', payment_date, 'strategy', strategy, 'member', p_member_id,
    'description', payment_description);

  select * into payment_event from public.loan_payment_events where operation_id = p_operation_id;
  if found then
    if payment_event.household_id <> debt_row.household_id
        or payment_event.debt_id <> p_debt_id
        or payment_event.request is distinct from request_body then
      raise exception 'operation_id_reused' using errcode = '22023';
    end if;
    select * into account_row from public.accounts where id = payment_event.loan_account_id;
    return jsonb_build_object('status','duplicate', 'debt', to_jsonb(debt_row),
      'loan_account', to_jsonb(account_row),
      'expense_txn_id', payment_event.expense_txn_id, 'transfer_txn_id', payment_event.transfer_txn_id,
      'loan_account_id', payment_event.loan_account_id,
      'transactions', (select coalesce(jsonb_agg(to_jsonb(txn)), '[]'::jsonb)
        from public.transactions txn where id in (payment_event.expense_txn_id, payment_event.transfer_txn_id)));
  end if;

  perform 1 from public.accounts where id = p_funding_account_id
    and household_id = debt_row.household_id and kind in ('cash','bank')
    and currency = p_currency and deleted_at is null and not is_archived for share;
  if not found then raise exception 'funding_account_invalid' using errcode = '22023'; end if;
  if p_member_id is not null then
    perform 1 from public.memberships where id = p_member_id and household_id = debt_row.household_id for share;
    if not found then raise exception 'member_invalid' using errcode = '22023'; end if;
    member_id := p_member_id;
  end if;
  if p_currency not in ('USD','EUR','GBP','INR','JPY','AUD','CAD','CHF','CNY','AED','SGD','BRL') then
    raise exception 'unsupported_currency' using errcode = '22023';
  end if;
  currency_scale := case when p_currency = 'JPY' then 1 else 100 end;
  if p_amount * currency_scale <> trunc(p_amount * currency_scale) then
    raise exception 'invalid_precision' using errcode = '22023';
  end if;
  monthly_rate := debt_row.interest_rate / 1200;
  interest_units := round(debt_row.current_balance * currency_scale) * round(monthly_rate, 12);
  interest_amount := (case when interest_units - trunc(interest_units) = 0.5
    then trunc(interest_units) + mod(trunc(interest_units), 2)
    else round(interest_units) end) / currency_scale;
  if p_amount < interest_amount or p_amount > debt_row.current_balance + interest_amount then
    raise exception 'payment_out_of_range' using errcode = '22023';
  end if;
  principal_amount := p_amount - interest_amount;
  balance_after := debt_row.current_balance - principal_amount;
  if p_new_balance is distinct from balance_after or p_interest is distinct from interest_amount
      or p_principal is distinct from principal_amount then
    raise exception 'payment_state_changed_refresh_required' using errcode = '40001';
  end if;

  remaining := greatest(0, coalesce((debt_row.extras->>'remainingMonths')::integer,
    (debt_row.extras->>'tenureMonths')::integer, 0) - 1);
  minimum_after := debt_row.minimum_payment;
  is_extra := p_amount > minimum_after * 1.05;
  if balance_after = 0 then
    remaining := 0;
  elsif is_extra and strategy = 'reduce_tenure' then
    if minimum_after <= monthly_rate * balance_after then
      raise exception 'non_amortizing_payment' using errcode = '22023';
    end if;
    remaining := case when monthly_rate = 0 then ceil(balance_after / minimum_after)
      else ceil(-ln(1 - monthly_rate * balance_after / minimum_after) / ln(1 + monthly_rate)) end;
  elsif is_extra and strategy = 'reduce_emi' then
    if remaining < 1 then raise exception 'invalid_remaining_tenure' using errcode = '22023'; end if;
    minimum_after := case when monthly_rate = 0 then balance_after / remaining
      else balance_after * monthly_rate / (1 - power(1 + monthly_rate, -remaining)) end;
  elsif is_extra and strategy = 'apply_advance' then
    if minimum_after <= 0 then raise exception 'invalid_minimum_payment' using errcode = '22023'; end if;
    remaining := greatest(0, remaining - floor((p_amount - minimum_after) / minimum_after)::integer);
  end if;

  select * into account_row from public.accounts where household_id = debt_row.household_id
    and debt_id = p_debt_id and kind = 'loan' and deleted_at is null for update;
  if not found then
    insert into public.accounts (household_id, kind, name, currency, debt_id, opening_balance)
      values (debt_row.household_id, 'loan', debt_row.name, debt_row.currency, p_debt_id, -debt_row.current_balance)
      returning * into account_row;
  elsif account_row.currency <> debt_row.currency or account_row.is_archived then
    raise exception 'loan_account_invalid' using errcode = '22023';
  end if;

  split_details := jsonb_build_object('interest', interest_amount, 'principal', principal_amount,
    'debt_id', p_debt_id, 'partPaymentChoice', strategy);
  if interest_amount > 0 then
    insert into public.transactions (household_id, created_by, member_id, amount, currency,
      type, category, account_id, debt_id, date, description, extras)
    values (debt_row.household_id, actor_id, member_id, interest_amount, p_currency,
      'expense', 'loan_emi', p_funding_account_id, p_debt_id, payment_date, payment_description,
      jsonb_build_object('emi_split', split_details, 'linkedDebtId', p_debt_id)) returning id into expense_id;
  end if;
  if principal_amount > 0 then
    insert into public.transactions (household_id, created_by, member_id, amount, currency,
      type, category, account_id, to_account_id, debt_id, date, description, extras)
    values (debt_row.household_id, actor_id, member_id, principal_amount, p_currency,
      'transfer', null, p_funding_account_id, account_row.id, p_debt_id, payment_date,
      payment_description || ' - principal', jsonb_build_object('emi_split', split_details,
        'linkedDebtId', p_debt_id, 'linkedTxnId', expense_id)) returning id into transfer_id;
  end if;
  payment_log := jsonb_build_object('id', p_operation_id, 'date', payment_date, 'amount', p_amount,
    'interest', interest_amount, 'principal', principal_amount, 'outstandingAfter', balance_after,
    'isPartPayment', is_extra, 'partChoice', strategy);
  update public.debts set current_balance = balance_after, minimum_payment = minimum_after,
    extras = coalesce(extras, '{}'::jsonb) || jsonb_build_object('remainingMonths', remaining,
      'paymentLog', coalesce(extras->'paymentLog', '[]'::jsonb) || jsonb_build_array(payment_log)), updated_at = now()
    where id = p_debt_id returning * into debt_row;
  insert into public.loan_payment_events (operation_id, household_id, debt_id, expense_txn_id,
    transfer_txn_id, loan_account_id, amount, interest, principal, request)
    values (p_operation_id, debt_row.household_id, p_debt_id, expense_id, transfer_id,
      account_row.id, p_amount, interest_amount, principal_amount, request_body);
  return jsonb_build_object('status','success', 'debt', to_jsonb(debt_row),
    'loan_account', to_jsonb(account_row), 'expense_txn_id', expense_id,
    'transfer_txn_id', transfer_id, 'loan_account_id', account_row.id,
    'transactions', (select coalesce(jsonb_agg(to_jsonb(txn)), '[]'::jsonb)
      from public.transactions txn where id in (expense_id, transfer_id)));
end;
$$;

revoke all on function public.record_loan_payment(uuid,uuid,uuid,numeric,text,date,numeric,numeric,uuid,text,numeric,integer,numeric,jsonb) from public, anon;
grant execute on function public.record_loan_payment(uuid,uuid,uuid,numeric,text,date,numeric,numeric,uuid,text,numeric,integer,numeric,jsonb) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260909150000_v1022_lock_down_definer_functions.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.22 — P4 security: stop `anon` reaching SECURITY DEFINER functions, and
-- pin the search_path on the six that lack one.
--
-- WHY THIS MATTERS
-- A SECURITY DEFINER function runs as its OWNER and bypasses RLS by design.
-- Postgres grants EXECUTE on a new function to PUBLIC by default, and `anon`
-- inherits PUBLIC — so an explicit `grant ... to authenticated` does NOT take
-- the default away. Every one of the 19 functions below was reachable without
-- signing in, through `/rest/v1/rpc/<name>`.
--
-- They all fail internally on a null `auth.uid()` today, so this is not a live
-- breach. It is the same class as the two revokes already applied
-- (20260430092130 for the v4.1 RPCs, and the agent helper in
-- 20260816120000): defence that should not depend on every function
-- remembering to check. The names alone are an information leak —
-- `erase_household_data`, `transfer_ownership`, `admin_list_users` are
-- enumerable from an unauthenticated client.
--
-- VERIFIED SAFE BEFORE WRITING: every one of these requires a signed-in user
-- semantically. The only plausible pre-auth caller was the invite flow, and
-- `AcceptInvite.tsx` explicitly checks `getSession()` first and stashes the
-- token to prompt sign-in when there is none — so `anon` never calls
-- `accept_invitation_link`.
--
-- search_path: an unqualified name inside a SECURITY DEFINER function resolves
-- against the CALLER's search_path, so a caller who puts a same-named table or
-- operator earlier on the path can change what the function does while it runs
-- as the owner. Pinning it removes that.
--
-- MONEY MODEL: untouched. No table, no row, no amount.
-- ============================================================================

BEGIN;

-- ── 1. Revoke the default PUBLIC grant (which `anon` inherits) ──────────────
do $$
declare
  fn text;
  fns text[] := array[
    'public.accept_invitation(uuid)',
    'public.accept_invitation(text)',
    'public.accept_invitation_link(text)',
    'public.admin_ai_usage_summary()',
    'public.admin_dashboard_kpis()',
    'public.admin_list_users()',
    'public.admin_weekly_trend(integer)',
    'public.deactivate_my_account()',
    'public.erase_household_data(uuid)',
    'public.is_admin(text)',
    'public.is_split_participant(uuid)',
    'public.leave_household(uuid)',
    'public.my_email()',
    'public.owns_shared_split(uuid)',
    'public.reactivate_my_account()',
    'public.request_account_deletion()',
    'public.settle_share(uuid)',
    'public.transfer_ownership(uuid,uuid)',
    'public.upsert_budget(uuid,jsonb,text)',
    'public.upsert_budget_with_allocations(uuid,jsonb,jsonb,text)'
  ];
begin
  foreach fn in array fns loop
    -- to_regprocedure returns null rather than raising when a signature is
    -- absent, so a function retired later cannot break this migration.
    if to_regprocedure(fn) is not null then
      execute format('revoke all on function %s from public', fn);
      execute format('revoke all on function %s from anon',   fn);
      execute format('grant execute on function %s to authenticated', fn);
    end if;
  end loop;
end $$;

-- `service_role` keeps what it needs for the edge functions and admin paths.
do $$
declare fn text;
  fns text[] := array[
    'public.admin_ai_usage_summary()', 'public.admin_dashboard_kpis()',
    'public.admin_list_users()', 'public.admin_weekly_trend(integer)',
    'public.erase_household_data(uuid)', 'public.my_email()'
  ];
begin
  foreach fn in array fns loop
    if to_regprocedure(fn) is not null then
      execute format('grant execute on function %s to service_role', fn);
    end if;
  end loop;
end $$;

-- ── 2. Pin search_path on the six app functions that lack one ──────────────
-- pg_trgm's own functions are extension-owned and deliberately left alone;
-- moving that extension out of `public` is a separate, riskier change because
-- existing gin_trgm_ops indexes resolve their opclass through the search path.
alter function public.accept_invitation(uuid)            set search_path = public, pg_temp;
alter function public.leave_household(uuid)              set search_path = public, pg_temp;
alter function public.transfer_ownership(uuid, uuid)     set search_path = public, pg_temp;
alter function public.touch_updated_at()                 set search_path = public, pg_temp;
alter function public.set_updated_at_accounts()          set search_path = public, pg_temp;
alter function public.set_updated_at_recurring()         set search_path = public, pg_temp;

COMMIT;

-- Verify (run manually):
--   select p.oid::regprocedure::text
--     from pg_proc p join pg_namespace n on n.oid = p.pronamespace
--    where n.nspname='public' and p.prosecdef
--      and has_function_privilege('anon', p.oid, 'EXECUTE');
--   -- expect: zero rows.

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260910120000_r1_accounts_one_cash_household_currency.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.23.0 — Accounts R1: exactly one Cash in Hand per household, currency
-- from the household, and one default account.
--
-- WHY
-- 1. DUPLICATE CASH. Every cash account encodes to the same literal 'cash'
--    ledger key (react/src/lib/accountBalance.ts accountValueOf), so a second
--    one double-counts every cash transaction into both balances and into Net
--    Worth. The only guard was client-side: crudSlice.ensureDefaultCashAccount
--    checked the LOCAL store, and when it ran before that store had hydrated it
--    wrote a fresh "Cash in Hand" — in USD, because profile.baseCurrency
--    defaults to 'USD' until the profile loads. Production held exactly that:
--    two empty USD "Cash in Hand" rows beside an INR household's real "Cash".
--    Identity now lives in the database, as budget identity already does.
-- 2. CURRENCY. Currency is a household setting. A per-account currency can
--    only ever disagree with it. A trigger stamps the household's
--    base_currency on every account write, and a change of base currency flows
--    to every account.
-- 3. DEFAULT. With one currency per household, "default for <currency>"
--    collapses to one default per household. Marking a new default clears the
--    old one in the same statement, so the unique index can never be tripped by
--    an ordinary edit.
--
-- MONEY MODEL: no number moves.
--   • Only cash duplicates with ZERO live references are tombstoned. A
--     duplicate that IS referenced aborts the migration — it needs a merge,
--     not a delete.
--   • Currency is normalised only where opening_balance and
--     reconciliation_offset are both zero. computeAccountBalance never reads
--     account.currency, but a non-zero amount under a changed label would
--     change what it means, so that case aborts too.
--
-- VERIFIED IN PRODUCTION BEFORE WRITING (2026-09-10)
--   • 1 household with duplicate cash; both duplicates have 0 transactions,
--     0 schedules, 0 open splits.
--   • 3 accounts with a currency other than their household's; none hold money.
--   • 1 household with two defaults — the duplicate cash; resolved by step 1.
--   • 0 debts in a non-base currency. record_loan_payment requires the loan
--     account's currency to equal the debt's, so a foreign-currency debt would
--     become unpayable once accounts inherit the household currency. None exist.
-- ============================================================================

BEGIN;

-- ── 0. Archive every row this migration changes ─────────────────────────────
create schema if not exists maintenance;
create table if not exists maintenance.accounts_archive_20260910 as
  select a.*, now() as archived_at, ''::text as archive_reason
    from public.accounts a where false;

-- ── 1. Tombstone duplicate cash accounts ────────────────────────────────────
-- Per household keep the cash account with the most live transactions (then
-- the oldest); every other one must be unreferenced.
do $$
declare
  dup  record;
  refs int;
begin
  for dup in
    with ranked as (
      select a.id, a.household_id, a.name,
             row_number() over (
               partition by a.household_id
               order by (select count(*) from public.transactions t
                          where t.deleted_at is null
                            and (t.account_id = a.id or t.to_account_id = a.id)) desc,
                        a.created_at, a.id) as rn
        from public.accounts a
       where a.kind = 'cash' and a.deleted_at is null
    )
    select id, household_id, name from ranked where rn > 1
  loop
    select (select count(*) from public.transactions t
             where t.deleted_at is null
               and (t.account_id = dup.id or t.to_account_id = dup.id))
         + (select count(*) from public.recurring_schedules r
             where r.deleted_at is null
               and (r.txn_template->>'accountId' = dup.id::text
                    or r.txn_template->>'toAccountId' = dup.id::text))
      into refs;
    if refs > 0 then
      raise exception 'Duplicate cash account % (%) in household % has % live reference(s) — merge it into the household''s cash account before this migration can run',
        dup.id, dup.name, dup.household_id, refs;
    end if;
    insert into maintenance.accounts_archive_20260910
      select a.*, now(), 'R1: duplicate cash account with no references'
        from public.accounts a where a.id = dup.id;
    update public.accounts set deleted_at = now(), is_default = false where id = dup.id;
  end loop;
end $$;

-- Archived rows count: a second cash row double-counts whether or not it is
-- hidden from the pickers.
create unique index if not exists uq_account_cash_per_household
  on public.accounts (household_id)
  where kind = 'cash' and deleted_at is null;

-- ── 2. One default account per household ──────────────────────────────────
-- Dropped BEFORE currencies are normalised: collapsing two currencies onto one
-- would otherwise trip the per-currency index mid-migration.
drop index if exists public.accounts_default_per_currency;

-- Keep the oldest default where a household still has several. Production has
-- none after step 1; this is for any other database the file runs against.
insert into maintenance.accounts_archive_20260910
  select a.*, now(), 'R1: is_default cleared — a household has one default account'
    from public.accounts a
   where a.is_default and not a.is_archived and a.deleted_at is null
     and exists (select 1 from public.accounts b
                  where b.household_id = a.household_id
                    and b.is_default and not b.is_archived and b.deleted_at is null
                    and (b.created_at, b.id) < (a.created_at, a.id));
update public.accounts a set is_default = false
 where a.is_default and not a.is_archived and a.deleted_at is null
   and exists (select 1 from public.accounts b
                where b.household_id = a.household_id
                  and b.is_default and not b.is_archived and b.deleted_at is null
                  and (b.created_at, b.id) < (a.created_at, a.id));

create unique index if not exists uq_account_default_per_household
  on public.accounts (household_id)
  where is_default and not is_archived and deleted_at is null;

-- Marking an account default clears the previous one in the same statement.
-- The nested UPDATE re-fires this trigger on the other row with
-- is_default = false, which does nothing, so it cannot recurse.
create or replace function public.accounts_single_default()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.is_default and not new.is_archived and new.deleted_at is null then
    update public.accounts
       set is_default = false
     where household_id = new.household_id
       and id <> new.id
       and is_default and not is_archived and deleted_at is null;
  end if;
  return new;
end $$;

drop trigger if exists trg_accounts_single_default on public.accounts;
create trigger trg_accounts_single_default
  before insert or update on public.accounts
  for each row execute function public.accounts_single_default();

-- ── 3. Currency is the household's ─────────────────────────────────────────
do $$
declare n int;
begin
  select count(*) into n
    from public.accounts a
    join public.households h on h.id = a.household_id
   where a.deleted_at is null
     and a.currency <> h.base_currency
     and (a.opening_balance <> 0 or a.reconciliation_offset <> 0);
  if n > 0 then
    raise exception '% account(s) hold money under a currency other than their household''s — relabelling would change what the amount means; resolve them first', n;
  end if;
end $$;

insert into maintenance.accounts_archive_20260910
  select a.*, now(), 'R1: currency normalised to the household base_currency'
    from public.accounts a
    join public.households h on h.id = a.household_id
   where a.deleted_at is null and a.currency <> h.base_currency;

update public.accounts a
   set currency = h.base_currency
  from public.households h
 where h.id = a.household_id
   and a.deleted_at is null
   and a.currency <> h.base_currency;

-- Runs as the caller. That is enough: every member can SELECT their own
-- household (policy "members read household"), and record_loan_payment's own
-- inserts run as the function owner.
create or replace function public.accounts_currency_from_household()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare hc text;
begin
  select base_currency into hc from public.households where id = new.household_id;
  if hc is not null then
    new.currency := hc;
  end if;
  return new;
end $$;

drop trigger if exists trg_accounts_currency_from_household on public.accounts;
create trigger trg_accounts_currency_from_household
  before insert or update on public.accounts
  for each row execute function public.accounts_currency_from_household();

-- Changing the household currency relabels every account. (Amounts are
-- untouched, exactly as they already are today: computeAccountBalance treats
-- opening balances and offsets as base-currency figures.)
create or replace function public.households_currency_to_accounts()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if new.base_currency is distinct from old.base_currency then
    update public.accounts
       set currency = new.base_currency
     where household_id = new.id and deleted_at is null;
  end if;
  return new;
end $$;

drop trigger if exists trg_households_currency_to_accounts on public.households;
create trigger trg_households_currency_to_accounts
  after update of base_currency on public.households
  for each row execute function public.households_currency_to_accounts();

-- ── 4. The server owns Cash in Hand creation ────────────────────────────────
-- Idempotent: returns the household's cash account, creating it first if there
-- is none. Viewers get the existing row back but never create one.
create or replace function public.ensure_cash_account(p_household uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  caller_role text;
  acc public.accounts;
begin
  caller_role := public.role_in(p_household);
  if auth.uid() is null or caller_role is null then
    raise exception 'not_a_household_member' using errcode = '42501';
  end if;

  if caller_role in ('owner', 'admin', 'member') then
    insert into public.accounts (household_id, kind, name, currency, is_default, opening_balance, source)
    select h.id, 'cash', 'Cash in Hand', h.base_currency,
           not exists (select 1 from public.accounts d
                        where d.household_id = h.id
                          and d.is_default and not d.is_archived and d.deleted_at is null),
           0, 'user'
      from public.households h
     where h.id = p_household
    on conflict (household_id) where kind = 'cash' and deleted_at is null do nothing;
  end if;

  select * into acc
    from public.accounts
   where household_id = p_household and kind = 'cash' and deleted_at is null;
  if not found then
    return null;
  end if;
  return to_jsonb(acc);
end $$;

-- Postgres grants EXECUTE to PUBLIC by default and anon inherits it; an
-- explicit grant to authenticated does not take that away (see v10.22's
-- 20260909150000_v1022_lock_down_definer_functions.sql).
revoke all on function public.ensure_cash_account(uuid) from public;
revoke all on function public.ensure_cash_account(uuid) from anon;
grant execute on function public.ensure_cash_account(uuid) to authenticated;

COMMIT;

-- Verify (run manually):
--   select household_id, count(*) from public.accounts
--    where kind = 'cash' and deleted_at is null group by 1 having count(*) > 1;   -- 0 rows
--   select count(*) from public.accounts a join public.households h on h.id = a.household_id
--    where a.deleted_at is null and a.currency <> h.base_currency;                 -- 0
--   select has_function_privilege('anon', 'public.ensure_cash_account(uuid)', 'EXECUTE');  -- false

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260910150000_r2_accounts_card_metadata_delete_guard.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.24.0 — Accounts R2: card metadata, payment modes, a reconcile stamp, and
-- a delete that the database guards.
--
-- WHAT
-- 1. Credit cards record their credit limit, billing-cycle day and payment-due
--    day. Outstanding, available and utilisation are NOT stored — they are
--    derived from the limit and the ledger balance (react/src/lib/accountsView.ts),
--    so no figure can drift from the transactions underneath it.
-- 2. Every account records the payment modes used on it. Existing accounts get
--    the sensible set for their type, so nothing is left without a mode.
-- 3. last_reconciled_at — confirming a balance that already matches changes no
--    number and writes no log entry (INV-3b), but it must still clear the
--    "not reconciled in N days" state. Backfilled from the reconciliation log.
-- 4. Deleting an account is decided by the DATABASE, not the client cache:
--      account_dependencies  itemises what is attached
--      delete_account         tombstones only when NOTHING is attached
--      move_account_and_delete re-tags everything to another account of the
--                             same group, folds the balance across, tombstones
--
-- MONEY MODEL: no number moves.
--   • Adding nullable columns and a default mode set changes no amount.
--   • delete_account refuses whenever anything is attached, so the only accounts
--     it removes are ones no transaction, schedule or split refers to.
--   • move_account_and_delete moves every ledger row, AND folds the source's
--     opening_balance + reconciliation_offset into the destination's offset, so
--     the destination ends holding exactly what both held — balances sum the
--     same, category totals are untouched (no transaction's amount, type,
--     category or date changes), and net worth is unchanged. Moves stay within a
--     group (bank/cash ↔ bank/cash, card ↔ card) so value never crosses between
--     the asset and liability sides.
--
-- Recurring templates store the app's transactionTemplate verbatim, so the
-- account keys inside txn_template are camelCase: accountId / toAccountId.
-- ============================================================================

BEGIN;

-- ── 1–3. Columns ────────────────────────────────────────────────────────────
alter table public.accounts
  add column if not exists payment_modes      text[]        not null default '{}',
  add column if not exists credit_limit       numeric(15,2),
  add column if not exists billing_cycle_day  smallint,
  add column if not exists payment_due_day    smallint,
  add column if not exists last_reconciled_at timestamptz;

alter table public.accounts
  add constraint ck_account_payment_modes check (
    payment_modes <@ array['upi','debit_card','net_banking','cheque','auto_debit',
                           'swipe','upi_on_card','online','standing_instruction','cash']::text[]),
  add constraint ck_account_card_fields check (
    kind = 'credit_card'
    or (credit_limit is null and billing_cycle_day is null and payment_due_day is null)),
  add constraint ck_account_credit_limit check (credit_limit is null or credit_limit > 0),
  add constraint ck_account_cycle_days check (
    (billing_cycle_day is null or billing_cycle_day between 1 and 31)
    and (payment_due_day is null or payment_due_day between 1 and 31));

update public.accounts
   set payment_modes = case kind
         when 'bank'        then array['upi','debit_card','net_banking']
         when 'credit_card' then array['swipe','online']
         when 'cash'        then array['cash']
         else '{}'::text[]
       end
 where payment_modes = '{}' and deleted_at is null;

update public.accounts a
   set last_reconciled_at = (
         select max((e->>'at')::timestamptz)
           from jsonb_array_elements(a.reconciliation_log) e)
 where a.last_reconciled_at is null
   and jsonb_array_length(a.reconciliation_log) > 0;

-- ── 4a. What is attached to an account ─────────────────────────────────────
create or replace function public.account_dependencies(p_account_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  acc public.accounts;
  result jsonb;
begin
  select * into acc from public.accounts where id = p_account_id and deleted_at is null;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  if auth.uid() is null or not public.is_member(acc.household_id) then
    raise exception 'not_a_household_member' using errcode = '42501';
  end if;

  with txns as (
    select t.id, t.amount, t.date, t.category, t.type, t.description
      from public.transactions t
     where t.household_id = acc.household_id
       and t.deleted_at is null
       and (t.account_id = acc.id or t.to_account_id = acc.id)
  ), grouped as (
    select coalesce(nullif(trim(description), ''), category, type) as label,
           count(*) as n, sum(amount) as total
      from txns
     group by 1
     order by count(*) desc, sum(amount) desc
     limit 3
  )
  select jsonb_build_object(
    'accountId', acc.id,
    'transactions', jsonb_build_object(
      'count',     (select count(*) from txns),
      'total',     coalesce((select sum(amount) from txns), 0),
      'firstDate', (select min(date) from txns),
      'lastDate',  (select max(date) from txns),
      'groups',    coalesce((select jsonb_agg(jsonb_build_object('label', label, 'count', n, 'total', total))
                               from grouped), '[]'::jsonb)),
    'recurring', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id,
               'label', coalesce(nullif(r.txn_template->>'description', ''), r.txn_template->>'category', 'Recurring')))
        from public.recurring_schedules r
       where r.household_id = acc.household_id
         and r.deleted_at is null
         and (r.txn_template->>'accountId' = acc.id::text
              or r.txn_template->>'toAccountId' = acc.id::text)), '[]'::jsonb),
    'openSplits', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'txnId', s.txn_id))
        from public.shared_splits s
        join txns t on t.id = s.txn_id
       where s.closed_at is null), '[]'::jsonb),
    'loanEvents', (select count(*) from public.loan_payment_events e where e.loan_account_id = acc.id)
  ) into result;

  return result;
end $fn$;

-- ── 4b. Delete only what nothing refers to ─────────────────────────────────
create or replace function public.delete_account(p_account_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  acc  public.accounts;
  deps jsonb;
begin
  select * into acc from public.accounts
   where id = p_account_id and deleted_at is null
   for update;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  -- Mirrors the accounts_delete RLS policy: owners and admins only.
  if auth.uid() is null or coalesce(public.role_in(acc.household_id), '') not in ('owner', 'admin') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if acc.kind = 'cash' then
    raise exception 'cash_account_protected' using errcode = '22023';
  end if;
  if acc.kind = 'loan' then
    raise exception 'system_account_protected' using errcode = '22023';
  end if;

  deps := public.account_dependencies(p_account_id);
  if (deps #>> '{transactions,count}')::int > 0
     or jsonb_array_length(deps->'recurring') > 0
     or jsonb_array_length(deps->'openSplits') > 0
     or (deps->>'loanEvents')::int > 0 then
    raise exception 'account_in_use' using errcode = '23503', detail = deps::text;
  end if;

  -- A tombstone, not a row delete: under refresh-based sync another device still
  -- holding the row would otherwise upload it again. Unrecoverable from the app.
  update public.accounts set deleted_at = now(), is_default = false where id = p_account_id;
  return jsonb_build_object('status', 'deleted', 'accountId', p_account_id);
end $fn$;

-- ── 4c. Move everything to another account, then delete ────────────────────
create or replace function public.move_account_and_delete(p_from uuid, p_to uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  src      public.accounts;
  dst      public.accounts;
  deps     jsonb;
  n_debit  int;
  n_credit int;
  n_sched  int;
  n_sched2 int;
  folded   numeric;
begin
  if p_from = p_to then
    raise exception 'same_account' using errcode = '22023';
  end if;

  select * into src from public.accounts where id = p_from and deleted_at is null for update;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  select * into dst from public.accounts where id = p_to and deleted_at is null for update;
  if not found then
    raise exception 'destination_not_found' using errcode = 'P0002';
  end if;
  if src.household_id <> dst.household_id then
    raise exception 'different_household' using errcode = '22023';
  end if;
  if auth.uid() is null or coalesce(public.role_in(src.household_id), '') not in ('owner', 'admin') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  if src.kind not in ('bank', 'credit_card') then
    raise exception 'source_not_movable' using errcode = '22023';
  end if;
  if dst.is_archived then
    raise exception 'destination_archived' using errcode = '22023';
  end if;
  -- Same group only: bank/cash ↔ bank/cash, card ↔ card.
  if (src.kind = 'credit_card') <> (dst.kind = 'credit_card')
     or dst.kind not in ('bank', 'cash', 'credit_card') then
    raise exception 'destination_different_group' using errcode = '22023';
  end if;

  deps := public.account_dependencies(p_from);
  if jsonb_array_length(deps->'openSplits') > 0 then
    raise exception 'unsettled_splits' using errcode = '23503', detail = deps::text;
  end if;
  if (deps->>'loanEvents')::int > 0 then
    raise exception 'loan_history_attached' using errcode = '23503', detail = deps::text;
  end if;
  -- A transfer between the two would become a transfer from an account to
  -- itself.
  if exists (
    select 1 from public.transactions t
     where t.household_id = src.household_id
       and t.deleted_at is null
       and ((t.account_id = p_from and t.to_account_id = p_to)
         or (t.account_id = p_to and t.to_account_id = p_from))
  ) then
    raise exception 'transfers_between_accounts' using errcode = '23514';
  end if;

  -- Every row, tombstoned ones included, so no history points at a deleted account.
  update public.transactions set account_id = p_to
   where household_id = src.household_id and account_id = p_from;
  get diagnostics n_debit = row_count;
  update public.transactions set to_account_id = p_to
   where household_id = src.household_id and to_account_id = p_from;
  get diagnostics n_credit = row_count;

  update public.recurring_schedules
     set txn_template = jsonb_set(txn_template, '{accountId}', to_jsonb(p_to::text))
   where household_id = src.household_id and txn_template->>'accountId' = p_from::text;
  get diagnostics n_sched = row_count;
  update public.recurring_schedules
     set txn_template = jsonb_set(txn_template, '{toAccountId}', to_jsonb(p_to::text))
   where household_id = src.household_id and txn_template->>'toAccountId' = p_from::text;
  get diagnostics n_sched2 = row_count;

  -- The source's starting point and its reconciled drift move with its rows.
  folded := coalesce(src.opening_balance, 0) + coalesce(src.reconciliation_offset, 0);
  if folded <> 0 then
    update public.accounts
       set reconciliation_offset = reconciliation_offset + folded,
           reconciliation_log = reconciliation_log || jsonb_build_array(jsonb_build_object(
             'at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
             'delta', folded,
             'kind', 'merge',
             'stated_value', null,
             'note', 'Moved from ' || src.name))
     where id = p_to;
  end if;

  update public.accounts set deleted_at = now(), is_default = false where id = p_from;

  return jsonb_build_object(
    'status', 'moved', 'from', p_from, 'to', p_to,
    'transactions', n_debit + n_credit, 'schedules', n_sched + n_sched2, 'folded', folded);
end $fn$;

-- ── Grants ──────────────────────────────────────────────────────────────────
-- EXECUTE defaults to PUBLIC and anon inherits it; grant to authenticated only.
revoke all on function public.account_dependencies(uuid) from public;
revoke all on function public.account_dependencies(uuid) from anon;
grant execute on function public.account_dependencies(uuid) to authenticated;

revoke all on function public.delete_account(uuid) from public;
revoke all on function public.delete_account(uuid) from anon;
grant execute on function public.delete_account(uuid) to authenticated;

revoke all on function public.move_account_and_delete(uuid, uuid) from public;
revoke all on function public.move_account_and_delete(uuid, uuid) from anon;
grant execute on function public.move_account_and_delete(uuid, uuid) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260910180000_r3_transaction_payment_mode.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.25.0 (Accounts R3) — the payment mode a transaction was made with.
--
-- R2 gave every account the modes it is used with (accounts.payment_modes).
-- This records WHICH of them a transaction used: UPI vs debit card on a bank,
-- swipe vs online on a card.
--
--   transactions.payment_mode  text NULL
--     NULL is valid forever: legacy rows, recurring posts and imports carry
--     none, and an investment never has one. The mode is DESCRIPTIVE — no
--     balance, total, category or net-worth figure reads it.
--
-- The mode set exists in THREE places, like categories: this CHECK (and the
-- accounts CHECK from R2), react/src/lib/accountsView.ts, and the Deno
-- allowlists in _shared/whatsapp-parser.ts + _shared/agent/types.ts. The unit
-- parity tests fail if the TypeScript copies drift.
--
-- whatsapp_log_transaction gains p_payment_mode (default null). It is stored
-- ONLY when the resolved paying account lists that mode — a mode the account
-- does not use is dropped, never an error, so a message still logs.
-- ============================================================================

BEGIN;

alter table public.transactions
  add column if not exists payment_mode text;

alter table public.transactions drop constraint if exists ck_txn_payment_mode;
alter table public.transactions
  add constraint ck_txn_payment_mode check (
    payment_mode is null
    or (type <> 'investment'
        and payment_mode = any (array['upi','debit_card','net_banking','cheque','auto_debit',
                                      'swipe','upi_on_card','online','standing_instruction','cash']))
  );

comment on column public.transactions.payment_mode is
  'v10.25.0 — how the paying account was used (upi, swipe, …). Descriptive only; null for legacy, recurring, imports and every investment.';

-- ── WhatsApp writer: same body as audit-S1, plus the mode ────────────────────
drop function if exists public.whatsapp_log_transaction(
  uuid, uuid, numeric, text, text, text, text, text, text, text, date
);

create or replace function public.whatsapp_log_transaction(
  p_profile_id      uuid,
  p_household_id    uuid,
  p_amount          numeric,
  p_currency        text,
  p_txn_type        text,
  p_category_id     text,
  p_account_alias   text,
  p_to_account_alias text,
  p_wa_message_id   text,
  p_description     text,
  p_date            date default null,
  p_payment_mode    text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_member_id     uuid;
  v_member_role   text;
  v_account_id    uuid;
  v_to_account_id uuid;
  v_cash_id       uuid;
  v_txn_id        uuid;
  v_claimed       int;
  v_date          date;
  v_mode          text;
begin
  v_date := coalesce(p_date, current_date);
  if v_date > current_date + interval '2 days' or v_date < current_date - interval '5 years' then
    v_date := current_date;
  end if;
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('status','error','reason','invalid_amount');
  end if;
  if p_txn_type not in ('expense','income','investment','transfer') then
    return jsonb_build_object('status','error','reason','invalid_type');
  end if;

  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;

  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('status','duplicate');
  end if;

  select id, role into v_member_id, v_member_role
    from public.memberships
   where household_id = p_household_id and user_id = p_profile_id
   limit 1;
  if v_member_id is null then
    return jsonb_build_object('status','error','reason','not_a_member');
  end if;
  if v_member_role = 'viewer' then
    return jsonb_build_object('status','error','reason','read_only_member');
  end if;

  select id into v_cash_id
    from public.accounts
   where household_id = p_household_id and lower(kind) = 'cash'
     and coalesce(is_archived,false) = false and deleted_at is null
   limit 1;

  if p_account_alias is not null and p_account_alias <> '' then
    select id into v_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_account_alias) or lower(kind) = lower(p_account_alias))
     limit 1;
  end if;

  if p_to_account_alias is not null and p_to_account_alias <> '' then
    select id into v_to_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_to_account_alias) or lower(kind) = lower(p_to_account_alias))
     limit 1;
  end if;

  if p_txn_type = 'expense' then
    v_account_id := coalesce(v_account_id, v_cash_id);
    v_to_account_id := null;
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
  elsif p_txn_type = 'income' then
    v_to_account_id := coalesce(v_to_account_id, v_account_id, v_cash_id);
    v_account_id := null;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
  else
    v_account_id := coalesce(v_account_id, v_cash_id);
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
    if v_to_account_id = v_account_id then
      return jsonb_build_object('status','error','reason','same_account');
    end if;
  end if;

  -- R3: keep the mode only when the PAYING account uses it (income: the
  -- receiving account). Never for an investment. Anything else is dropped.
  if p_payment_mode is not null and p_txn_type <> 'investment' then
    select p_payment_mode into v_mode
      from public.accounts
     where id = case when p_txn_type = 'income' then v_to_account_id else v_account_id end
       and p_payment_mode = any (payment_modes);
  end if;

  insert into public.transactions (
    household_id, created_by, member_id, amount, currency, type, category,
    account_id, to_account_id, date, description, payment_mode
  ) values (
    p_household_id,
    p_profile_id,
    v_member_id,
    p_amount,
    coalesce(nullif(p_currency,''), 'USD'),
    p_txn_type,
    case when p_txn_type in ('expense','income')
         then coalesce(nullif(p_category_id,''), case when p_txn_type='expense' then 'other_expense' else 'other_income' end)
         else null end,
    v_account_id,
    v_to_account_id,
    v_date,
    coalesce(nullif(p_description,''), 'Logged via WhatsApp'),
    v_mode
  ) returning id into v_txn_id;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload,'{}'::jsonb) || jsonb_build_object(
           'parsed', jsonb_build_object(
             'transaction_id', v_txn_id, 'amount', p_amount, 'currency', p_currency,
             'type', p_txn_type, 'category_id', p_category_id,
             'account_id', v_account_id, 'to_account_id', v_to_account_id,
             'payment_mode', p_payment_mode, 'payment_mode_stored', v_mode))
   where wa_message_id = p_wa_message_id;

  return jsonb_build_object(
    'status','success',
    'transaction_id', v_txn_id,
    'amount', p_amount,
    'currency', coalesce(nullif(p_currency,''),'USD'),
    'type', p_txn_type,
    'category_id', p_category_id,
    'payment_mode', v_mode,
    'account_name',    (select name from public.accounts where id = v_account_id),
    'to_account_name', (select name from public.accounts where id = v_to_account_id)
  );
end;
$$;

revoke all on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date,text) from public, anon, authenticated;
grant execute on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date,text) to service_role;

comment on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date,text) is
  'v10.25.0 — WhatsApp/agent transaction writer. v9 CHECK-safe, claim-first idempotent on wa_message_id, p_date backdate-aware, audit-S1 membership gate. p_payment_mode is stored only when the paying account lists it (never for investments); otherwise dropped. Service-role only.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260911120000_r4_investments_to_assets.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.26.0 (Accounts R4) — investments become Net Worth assets.
--
-- Before: an investment was a transaction between two ACCOUNTS, one of them a
-- kind='investment' account. After: it moves money between an ACCOUNT and an
-- investment ASSET.
--
--   buy         account_id  = paying account,     asset_id = the asset
--   withdrawal  to_account_id = receiving account, asset_id = the asset
--
-- An investment asset's live value folds EXACTLY like an account (decision
-- "mirror accounts"):
--
--   live = assets.value (opening) + Σ buys − Σ withdrawals + valuation_offset
--
-- "Update value" moves valuation_offset with a dated valuation_log entry —
-- never `value`, never a transaction. assets.value therefore stays >= 0.
--
-- CONVERSION — every live investment account becomes an asset carrying the
-- account's opening balance, reconciliation offset and log verbatim; its
-- transactions and recurring templates are re-pointed; the account is
-- tombstoned. Inside the same transaction each converted value, and every OTHER
-- account's balance, is recomputed and the migration RAISES (rolls back) on any
-- difference. Production today: one account, "Delhi Investment Serivices",
-- live value 48,780.00 INR.
--
-- Archive-first: the affected rows are copied to maintenance.* before anything
-- changes.
-- ============================================================================

BEGIN;

-- ── 0. archive ──────────────────────────────────────────────────────────────
create table if not exists maintenance.r4_accounts_archive_20260911
  as select * from public.accounts with no data;
insert into maintenance.r4_accounts_archive_20260911
  select * from public.accounts where kind = 'investment';

create table if not exists maintenance.r4_transactions_archive_20260911
  as select * from public.transactions with no data;
insert into maintenance.r4_transactions_archive_20260911
  select t.* from public.transactions t
   where exists (select 1 from public.accounts a where a.kind = 'investment'
                   and (a.id = t.account_id or a.id = t.to_account_id));

create table if not exists maintenance.r4_recurring_archive_20260911
  as select * from public.recurring_schedules with no data;
insert into maintenance.r4_recurring_archive_20260911
  select s.* from public.recurring_schedules s
   where exists (select 1 from public.accounts a where a.kind = 'investment'
                   and (a.id::text = s.txn_template->>'accountId' or a.id::text = s.txn_template->>'toAccountId'));

-- ── 1. asset valuation (mirrors accounts.reconciliation_offset / _log) ─────
alter table public.assets
  add column if not exists valuation_offset numeric(15,2) not null default 0,
  add column if not exists valuation_log    jsonb        not null default '[]'::jsonb;

-- ── 2. transactions.asset_id ───────────────────────────────────────────────
alter table public.transactions
  add column if not exists asset_id uuid references public.assets(id) on delete restrict;
create index if not exists ix_txn_asset on public.transactions (asset_id) where asset_id is not null;

-- The old matrix requires both account FKs on an investment; the new one
-- forbids it. Swapped around the conversion, re-added below.
alter table public.transactions drop constraint if exists ck_txn_accounts_by_type;

-- ── 3. convert ─────────────────────────────────────────────────────────────
do $conv$
declare
  a            record;
  v_asset      uuid;
  v_before     numeric;
  v_after      numeric;
  v_others     jsonb;
  v_others_now jsonb;
  v_converted  int := 0;
begin
  -- Every non-investment account's balance, before. The conversion only ever
  -- NULLS the investment side of a row, so these must not move.
  select coalesce(jsonb_object_agg(x.id, x.bal), '{}'::jsonb) into v_others from (
    select ac.id,
           coalesce(ac.opening_balance, 0) + coalesce(ac.reconciliation_offset, 0)
           + coalesce((select sum(t.amount) from public.transactions t where t.to_account_id = ac.id and t.deleted_at is null), 0)
           - coalesce((select sum(t.amount) from public.transactions t where t.account_id    = ac.id and t.deleted_at is null), 0) as bal
      from public.accounts ac where ac.kind <> 'investment') x;

  for a in select * from public.accounts where kind = 'investment' and deleted_at is null loop
    if exists (select 1 from public.transactions t
                where (t.account_id = a.id or t.to_account_id = a.id) and t.type <> 'investment') then
      raise exception 'R4: account % has non-investment rows; convert by hand', a.id;
    end if;
    if exists (select 1 from public.transactions t
                where (t.account_id = a.id or t.to_account_id = a.id) and t.deleted_at is null and t.currency <> a.currency) then
      raise exception 'R4: account % has foreign-currency rows; convert by hand', a.id;
    end if;
    if coalesce(a.opening_balance, 0) < 0 then
      raise exception 'R4: account % has a negative opening balance', a.id;
    end if;

    v_before := coalesce(a.opening_balance, 0) + coalesce(a.reconciliation_offset, 0)
      + coalesce((select sum(t.amount) from public.transactions t where t.to_account_id = a.id and t.deleted_at is null), 0)
      - coalesce((select sum(t.amount) from public.transactions t where t.account_id    = a.id and t.deleted_at is null), 0);

    insert into public.assets (household_id, type, name, value, currency, liquidity, note, last_updated,
                               valuation_offset, valuation_log, confidence, source)
    values (a.household_id, 'investment', a.name, coalesce(a.opening_balance, 0), a.currency, 'short',
            'Converted from the investment account on 2026-09-11 (v10.26.0).',
            coalesce((select max((e->>'at')::timestamptz)::date from jsonb_array_elements(coalesce(a.reconciliation_log, '[]'::jsonb)) e),
                     a.created_at::date),
            coalesce(a.reconciliation_offset, 0), coalesce(a.reconciliation_log, '[]'::jsonb),
            coalesce(a.confidence, 'confirmed'), coalesce(a.source, 'user'))
    returning id into v_asset;

    -- buys: money arrived in the investment account → arrives in the asset
    update public.transactions set asset_id = v_asset, to_account_id = null
     where to_account_id = a.id and type = 'investment';
    -- withdrawals: money left the investment account → leaves the asset
    update public.transactions set asset_id = v_asset, account_id = null
     where account_id = a.id and type = 'investment';

    update public.recurring_schedules
       set txn_template = (txn_template - 'toAccountId') || jsonb_build_object('assetId', v_asset::text)
     where txn_template->>'toAccountId' = a.id::text;
    update public.recurring_schedules
       set txn_template = (txn_template - 'accountId') || jsonb_build_object('assetId', v_asset::text)
     where txn_template->>'accountId' = a.id::text;

    update public.accounts set deleted_at = now(), is_default = false where id = a.id;

    select s.value + s.valuation_offset
           + coalesce((select sum(t.amount) from public.transactions t
                        where t.asset_id = v_asset and t.account_id is not null and t.deleted_at is null), 0)
           - coalesce((select sum(t.amount) from public.transactions t
                        where t.asset_id = v_asset and t.account_id is null and t.deleted_at is null), 0)
      into v_after from public.assets s where s.id = v_asset;

    if v_after is distinct from v_before then
      raise exception 'R4: value moved converting % (% → %)', a.id, v_before, v_after;
    end if;
    v_converted := v_converted + 1;
  end loop;

  select coalesce(jsonb_object_agg(x.id, x.bal), '{}'::jsonb) into v_others_now from (
    select ac.id,
           coalesce(ac.opening_balance, 0) + coalesce(ac.reconciliation_offset, 0)
           + coalesce((select sum(t.amount) from public.transactions t where t.to_account_id = ac.id and t.deleted_at is null), 0)
           - coalesce((select sum(t.amount) from public.transactions t where t.account_id    = ac.id and t.deleted_at is null), 0) as bal
      from public.accounts ac where ac.kind <> 'investment') x;
  if v_others_now is distinct from v_others then
    raise exception 'R4: an account balance moved during the conversion';
  end if;

  raise notice 'R4: converted % investment account(s)', v_converted;
end
$conv$;

-- ── 4. the new per-type matrix ─────────────────────────────────────────────
alter table public.transactions add constraint ck_txn_accounts_by_type check (
     (type = 'expense'    and account_id is not null and to_account_id is null     and asset_id is null)
  or (type = 'income'     and account_id is null     and to_account_id is not null and asset_id is null)
  or (type = 'transfer'   and account_id is not null and to_account_id is not null and asset_id is null)
  or (type = 'investment' and asset_id is not null
        and ((account_id is not null and to_account_id is null) or (account_id is null and to_account_id is not null)))
);

-- ── 5. no live investment accounts, ever again ─────────────────────────────
-- Tombstoned ones stay (history); a live one is refused.
alter table public.accounts drop constraint if exists ck_account_no_live_investment;
alter table public.accounts add constraint ck_account_no_live_investment
  check (kind <> 'investment' or deleted_at is not null);

-- ── 6. an asset with live transactions cannot be deleted ───────────────────
-- Assets are soft-deleted. Removing one its buys still point at would take its
-- value out of net worth while the paying accounts stay debited.
create or replace function public.assets_refuse_delete_in_use()
returns trigger language plpgsql set search_path = public, pg_temp as $$
begin
  if new.deleted_at is not null and old.deleted_at is null
     and exists (select 1 from public.transactions t where t.asset_id = new.id and t.deleted_at is null) then
    raise exception 'asset_in_use' using errcode = 'P0001';
  end if;
  return new;
end
$$;
drop trigger if exists assets_refuse_delete_in_use on public.assets;
create trigger assets_refuse_delete_in_use
  before update of deleted_at on public.assets
  for each row execute function public.assets_refuse_delete_in_use();
revoke all on function public.assets_refuse_delete_in_use() from public, anon, authenticated;

-- ── 7. WhatsApp writer: an investment lands in an investment ASSET ─────────
create or replace function public.whatsapp_log_transaction(
  p_profile_id      uuid,
  p_household_id    uuid,
  p_amount          numeric,
  p_currency        text,
  p_txn_type        text,
  p_category_id     text,
  p_account_alias   text,
  p_to_account_alias text,
  p_wa_message_id   text,
  p_description     text,
  p_date            date default null,
  p_payment_mode    text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_member_id     uuid;
  v_member_role   text;
  v_account_id    uuid;
  v_to_account_id uuid;
  v_asset_id      uuid;
  v_cash_id       uuid;
  v_txn_id        uuid;
  v_claimed       int;
  v_date          date;
  v_mode          text;
begin
  v_date := coalesce(p_date, current_date);
  if v_date > current_date + interval '2 days' or v_date < current_date - interval '5 years' then
    v_date := current_date;
  end if;
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('status','error','reason','invalid_amount');
  end if;
  if p_txn_type not in ('expense','income','investment','transfer') then
    return jsonb_build_object('status','error','reason','invalid_type');
  end if;

  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;

  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('status','duplicate');
  end if;

  select id, role into v_member_id, v_member_role
    from public.memberships
   where household_id = p_household_id and user_id = p_profile_id
   limit 1;
  if v_member_id is null then
    return jsonb_build_object('status','error','reason','not_a_member');
  end if;
  if v_member_role = 'viewer' then
    return jsonb_build_object('status','error','reason','read_only_member');
  end if;

  select id into v_cash_id
    from public.accounts
   where household_id = p_household_id and lower(kind) = 'cash'
     and coalesce(is_archived,false) = false and deleted_at is null
   limit 1;

  if p_account_alias is not null and p_account_alias <> '' then
    select id into v_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_account_alias) or lower(kind) = lower(p_account_alias))
     limit 1;
  end if;

  if p_txn_type = 'investment' then
    -- R4: the destination is an investment ASSET — by name, or the household's
    -- only one when the message names none ("invested 5000").
    if p_to_account_alias is not null and p_to_account_alias <> '' and lower(p_to_account_alias) <> 'investment' then
      select id into v_asset_id from public.assets
       where household_id = p_household_id and deleted_at is null and type = 'investment'
         and lower(name) = lower(p_to_account_alias)
       limit 1;
    end if;
    if v_asset_id is null and (select count(*) from public.assets
                                where household_id = p_household_id and deleted_at is null and type = 'investment') = 1 then
      select id into v_asset_id from public.assets
       where household_id = p_household_id and deleted_at is null and type = 'investment';
    end if;
  elsif p_to_account_alias is not null and p_to_account_alias <> '' then
    select id into v_to_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_to_account_alias) or lower(kind) = lower(p_to_account_alias))
     limit 1;
  end if;

  if p_txn_type = 'expense' then
    v_account_id := coalesce(v_account_id, v_cash_id);
    v_to_account_id := null;
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
  elsif p_txn_type = 'income' then
    v_to_account_id := coalesce(v_to_account_id, v_account_id, v_cash_id);
    v_account_id := null;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
  elsif p_txn_type = 'investment' then
    v_account_id := coalesce(v_account_id, v_cash_id);
    v_to_account_id := null;
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
    if v_asset_id is null then
      return jsonb_build_object('status','error','reason','no_investment_asset');
    end if;
  else
    v_account_id := coalesce(v_account_id, v_cash_id);
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
    if v_to_account_id = v_account_id then
      return jsonb_build_object('status','error','reason','same_account');
    end if;
  end if;

  if p_payment_mode is not null and p_txn_type <> 'investment' then
    select p_payment_mode into v_mode
      from public.accounts
     where id = case when p_txn_type = 'income' then v_to_account_id else v_account_id end
       and p_payment_mode = any (payment_modes);
  end if;

  insert into public.transactions (
    household_id, created_by, member_id, amount, currency, type, category,
    account_id, to_account_id, asset_id, date, description, payment_mode
  ) values (
    p_household_id,
    p_profile_id,
    v_member_id,
    p_amount,
    coalesce(nullif(p_currency,''), 'USD'),
    p_txn_type,
    case when p_txn_type in ('expense','income')
         then coalesce(nullif(p_category_id,''), case when p_txn_type='expense' then 'other_expense' else 'other_income' end)
         else null end,
    v_account_id,
    v_to_account_id,
    v_asset_id,
    v_date,
    coalesce(nullif(p_description,''), 'Logged via WhatsApp'),
    v_mode
  ) returning id into v_txn_id;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload,'{}'::jsonb) || jsonb_build_object(
           'parsed', jsonb_build_object(
             'transaction_id', v_txn_id, 'amount', p_amount, 'currency', p_currency,
             'type', p_txn_type, 'category_id', p_category_id,
             'account_id', v_account_id, 'to_account_id', v_to_account_id, 'asset_id', v_asset_id,
             'payment_mode', p_payment_mode, 'payment_mode_stored', v_mode))
   where wa_message_id = p_wa_message_id;

  return jsonb_build_object(
    'status','success',
    'transaction_id', v_txn_id,
    'amount', p_amount,
    'currency', coalesce(nullif(p_currency,''),'USD'),
    'type', p_txn_type,
    'category_id', p_category_id,
    'payment_mode', v_mode,
    'account_name',    (select name from public.accounts where id = v_account_id),
    -- the confirmation reads "from → to"; for an investment "to" is the asset
    'to_account_name', coalesce((select name from public.accounts where id = v_to_account_id),
                                (select name from public.assets   where id = v_asset_id))
  );
end;
$$;

revoke all on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date,text) from public, anon, authenticated;
grant execute on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date,text) to service_role;

comment on function public.whatsapp_log_transaction(uuid,uuid,numeric,text,text,text,text,text,text,text,date,text) is
  'v10.26.0 — WhatsApp/agent transaction writer. v9 CHECK-safe (R4 matrix: an investment moves money from an account into an investment asset), claim-first idempotent, p_date backdate-aware, audit-S1 membership gate, p_payment_mode kept only when the paying account lists it. Service-role only.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260911150000_v1030_net_worth_snapshots.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.30.0 — recorded monthly Net Worth snapshots.
--
-- WHY
-- Reports and Net Worth can only show the position TODAY. A historical Net
-- Worth cannot be reconstructed honestly: standalone assets and debts store
-- only their current value, so any past figure would be invented. History is
-- therefore RECORDED from now on — one snapshot per household per calendar
-- month, taken from the app's canonical projection (react/src/lib/netWorth.ts).
-- Nothing is back-filled.
--
-- CONTRACT
--   • One row per (household, month). The FIRST write for a month wins
--     (`on conflict do nothing`), so two devices cannot overwrite each other
--     and a recorded month is never edited.
--   • Written only through record_net_worth_snapshot (SECURITY DEFINER), by a
--     member who may write, for the CURRENT month, in the household's base
--     currency — the last check refuses a snapshot taken before the profile
--     loaded (the app's profile currency is 'USD' until then).
--   • net_worth is derived in the database (assets − liabilities), never sent.
--   • Readable by household members (RLS). No client write policies.
-- ============================================================================

BEGIN;

create table if not exists public.net_worth_snapshots (
  id                uuid primary key default gen_random_uuid(),
  household_id      uuid not null references public.households(id) on delete cascade,
  month             date not null,
  total_assets      numeric(15,2) not null,
  total_liabilities numeric(15,2) not null,
  net_worth         numeric(15,2) generated always as (total_assets - total_liabilities) stored,
  liquid_assets     numeric(15,2) not null,
  currency          text not null,
  recorded_by       uuid references auth.users(id) on delete set null,
  recorded_at       timestamptz not null default now(),
  constraint uq_net_worth_snapshot_month unique (household_id, month),
  constraint ck_net_worth_snapshot_first_of_month check (extract(day from month) = 1),
  constraint ck_net_worth_snapshot_liabilities check (total_liabilities >= 0),
  constraint ck_net_worth_snapshot_currency check (currency ~ '^[A-Z]{3}$')
);

alter table public.net_worth_snapshots enable row level security;

drop policy if exists "net_worth_snapshots_member_read" on public.net_worth_snapshots;
create policy "net_worth_snapshots_member_read" on public.net_worth_snapshots
  for select to authenticated
  using (public.is_member(household_id));

-- No insert/update/delete policies: writes go through the function below, and
-- a recorded month is never changed.
revoke insert, update, delete on public.net_worth_snapshots from anon, authenticated;

create or replace function public.record_net_worth_snapshot(
  p_household uuid,
  p_month date,
  p_total_assets numeric,
  p_total_liabilities numeric,
  p_liquid_assets numeric,
  p_currency text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  caller_role text;
  base text;
  snap public.net_worth_snapshots;
begin
  caller_role := public.role_in(p_household);
  if auth.uid() is null or caller_role is null then
    raise exception 'not_a_household_member' using errcode = '42501';
  end if;

  if p_month is null or extract(day from p_month) <> 1 then
    raise exception 'snapshot_month_must_be_first_of_month' using errcode = '22023';
  end if;

  -- A snapshot records NOW. One day of slack either side absorbs time zones at
  -- a month boundary; anything else would be a back-dated or future record.
  if p_month < date_trunc('month', now() - interval '1 day')::date
     or p_month > date_trunc('month', now() + interval '1 day')::date then
    raise exception 'snapshot_month_not_current' using errcode = '22023';
  end if;

  select h.base_currency into base from public.households h where h.id = p_household;
  if p_currency is distinct from base then
    raise exception 'snapshot_currency_not_household_base' using errcode = '22023';
  end if;

  if caller_role in ('owner', 'admin', 'member') then
    insert into public.net_worth_snapshots
      (household_id, month, total_assets, total_liabilities, liquid_assets, currency, recorded_by)
    values
      (p_household, p_month, p_total_assets, p_total_liabilities, p_liquid_assets, p_currency, auth.uid())
    on conflict (household_id, month) do nothing;
  end if;

  select * into snap
    from public.net_worth_snapshots
   where household_id = p_household and month = p_month;
  if not found then
    return null;
  end if;
  return to_jsonb(snap);
end $$;

-- Postgres grants EXECUTE to PUBLIC by default and anon inherits it; an
-- explicit grant to authenticated does not take that away (see
-- 20260909150000_v1022_lock_down_definer_functions.sql).
revoke all on function public.record_net_worth_snapshot(uuid, date, numeric, numeric, numeric, text) from public;
revoke all on function public.record_net_worth_snapshot(uuid, date, numeric, numeric, numeric, text) from anon;
grant execute on function public.record_net_worth_snapshot(uuid, date, numeric, numeric, numeric, text) to authenticated;

-- "Erase my data" must erase recorded history too. Body identical to
-- 20260908120200_audit_s6_erase_onboarding_fix.sql plus the snapshots delete.
create or replace function erase_household_data(h_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  caller_role text;
begin
  select role into caller_role
  from memberships
  where household_id = h_id and user_id = auth.uid()
  limit 1;

  if caller_role is null or caller_role not in ('owner', 'admin') then
    raise exception 'not authorized to erase this household''s data';
  end if;

  delete from transactions        where household_id = h_id;
  delete from budgets              where household_id = h_id;
  delete from budget_allocations   where household_id = h_id;
  delete from goals                where household_id = h_id;
  delete from debts                where household_id = h_id;
  delete from assets               where household_id = h_id;
  delete from accounts             where household_id = h_id;
  delete from recurring_schedules  where household_id = h_id;
  delete from saved_views          where household_id = h_id;
  delete from net_worth_snapshots  where household_id = h_id;
  delete from activity_log         where household_id = h_id;

  -- Onboarding baseline/reference overlay (v9.7.0) lives in households.onboarding.
  -- NOT NULL + object CHECK ⇒ reset to the empty baseline, never null (audit S6).
  update households set onboarding = '{}'::jsonb where id = h_id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id, changes)
  values (h_id, auth.uid(), 'erase_household_data', 'household', h_id, jsonb_build_object('erased_at', now()));
end;
$$;

-- `create or replace` keeps existing grants; re-assert the v10.22 lock-down.
revoke all on function erase_household_data(uuid) from public;
revoke all on function erase_household_data(uuid) from anon;
grant execute on function erase_household_data(uuid) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260915120000_v1037_ask_vyact_relay.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.37.0 — Claude Code relay queue for Ask Vyact (TEST-WINDOW WORKAROUND).
--
-- WHY
-- The free OpenRouter model timed out (20 s gateway budget) on nearly every call,
-- so Ask Vyact answered "I can't reach the assistant". For the duration of a test
-- cycle the product owner asked for a developer's Claude Code session to stand in
-- as the model. The `ask-vyact` gateway queues the exact messages the model would
-- have received here; the Claude Code session writes the answer; the client polls.
--
-- CONTRACT
--   • Written and read ONLY by the service role (the gateway) and the operator's
--     Supabase access. RLS is enabled with NO policies and anon/authenticated hold
--     no privileges — no browser can read or write a row.
--   • 🔴 This table stores message CONTENT. That is a deliberate, TEMPORARY
--     exception to the ai_usage "metadata only" rule, scoped to the allowlisted
--     test account(s) in the relay's ai_model_configs row. Rows are purged when
--     testing ends, and the relay is removed (TECH_DEBT.md TD-44).
--   • Nothing else reads it; no money table, RPC or policy on an existing object
--     is touched.
-- ============================================================================

BEGIN;

create table if not exists public.ask_vyact_relay (
  id              uuid primary key default gen_random_uuid(),
  created_at      timestamptz not null default now(),
  user_id         uuid not null references auth.users(id) on delete cascade,
  household_id    uuid references public.households(id) on delete set null,
  reservation_id  uuid,
  call_kind       text not null default 'other',
  messages        jsonb not null,
  max_tokens      int,
  response        text,
  status          text not null default 'pending',
  answered_at     timestamptz,
  constraint ck_ask_vyact_relay_call_kind check (call_kind in ('classify','phrase','other')),
  constraint ck_ask_vyact_relay_status check (status in ('pending','answered','expired')),
  constraint ck_ask_vyact_relay_answered check (status <> 'answered' or (response is not null and answered_at is not null))
);

create index if not exists ix_ask_vyact_relay_pending
  on public.ask_vyact_relay (created_at) where status = 'pending';
create index if not exists ix_ask_vyact_relay_user
  on public.ask_vyact_relay (user_id, created_at desc);

alter table public.ask_vyact_relay enable row level security;
revoke all on public.ask_vyact_relay from anon, authenticated;

comment on table public.ask_vyact_relay is
  'TEMPORARY (v10.37.0, TD-44): Claude Code relay queue for Ask Vyact testing. Stores message content for allowlisted test accounts only; service role only; purge after testing.';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260926120000_w2_whatsapp_preferences_dispatch.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.42.0 (W2) — WhatsApp consent, preferences, delivery tracking, scheduler.
--
--   1. `whatsapp_preferences`: one row per profile. Marketing and insights
--      consent (off by default, with when and where it was given), muted topics,
--      and the large-spend alert threshold. Server-owned like the other WhatsApp
--      tables (RLS on, no policies); the person reads and changes their own row
--      only through the two RPCs below.
--   2. Delivery tracking on the outbound audit rows: Meta's message id and the
--      last status it reported (sent → delivered → read, or failed).
--   3. The scheduler: pg_cron calls the `whatsapp-dispatch` Edge Function through
--      pg_net. INERT until the owner stores `whatsapp_dispatch_secret` in Vault
--      (and the same value as WHATSAPP_DISPATCH_SECRET on the function): each
--      job selects the secret, so with no secret it selects no row and makes no
--      call. A preview branch, which has no such secret, never calls production.
--
-- MONEY MODEL: untouched. No transaction, account, budget or amount is written.
-- ============================================================================

BEGIN;

-- ── 1. Preferences ──────────────────────────────────────────────────────────
create table if not exists public.whatsapp_preferences (
  profile_id          uuid primary key references public.profiles(id) on delete cascade,
  marketing_opt_in    boolean not null default false,
  marketing_opt_in_at timestamptz,
  marketing_source    text,
  insights_opt_in     boolean not null default false,
  insights_opt_in_at  timestamptz,
  muted_topics        text[] not null default '{}',
  large_txn_threshold numeric(14,2) not null default 10000 check (large_txn_threshold > 0),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint ck_wa_prefs_topics check (muted_topics <@ array[
    'budgets','splits','recurring','payday','digest','summary','runway','setup','balances','weekly','tips'
  ]::text[]),
  constraint ck_wa_prefs_marketing_source check (marketing_source is null
    or marketing_source in ('app_settings','whatsapp_keyword','meta_opt_out'))
);

alter table public.whatsapp_preferences enable row level security;
-- Deliberately NO policies: deny-all to anon/authenticated. Edge Functions use
-- the service role; people use the RPCs.
revoke all on public.whatsapp_preferences from public, anon, authenticated;
grant select, insert, update, delete on public.whatsapp_preferences to service_role;

-- The caller's own preferences, defaults when no row exists yet.
create or replace function public.get_my_whatsapp_preferences()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'marketing_opt_in',    coalesce(p.marketing_opt_in, false),
    'marketing_opt_in_at', p.marketing_opt_in_at,
    'insights_opt_in',     coalesce(p.insights_opt_in, false),
    'muted_topics',        coalesce(to_jsonb(p.muted_topics), '[]'::jsonb),
    'large_txn_threshold', coalesce(p.large_txn_threshold, 10000),
    'linked',              exists (select 1 from public.whatsapp_identities i where i.profile_id = auth.uid())
  )
  from (select auth.uid() as uid) me
  left join public.whatsapp_preferences p on p.profile_id = me.uid
  where me.uid is not null;
$$;

-- Change the caller's own preferences. A null argument leaves that field as it
-- is. Turning marketing or insights ON records when, and that it was in the app.
create or replace function public.set_my_whatsapp_preferences(
  p_marketing_opt_in    boolean default null,
  p_insights_opt_in     boolean default null,
  p_muted_topics        text[]  default null,
  p_large_txn_threshold numeric default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_large_txn_threshold is not null and p_large_txn_threshold <= 0 then
    raise exception 'threshold must be positive' using errcode = '22023';
  end if;

  insert into public.whatsapp_preferences (profile_id) values (v_uid)
  on conflict (profile_id) do nothing;

  update public.whatsapp_preferences p set
    marketing_opt_in    = coalesce(p_marketing_opt_in, p.marketing_opt_in),
    marketing_opt_in_at = case when p_marketing_opt_in is true and not p.marketing_opt_in then now()
                               when p_marketing_opt_in is false then null
                               else p.marketing_opt_in_at end,
    marketing_source    = case when p_marketing_opt_in is true and not p.marketing_opt_in then 'app_settings'
                               when p_marketing_opt_in is false then null
                               else p.marketing_source end,
    insights_opt_in     = coalesce(p_insights_opt_in, p.insights_opt_in),
    insights_opt_in_at  = case when p_insights_opt_in is true and not p.insights_opt_in then now()
                               when p_insights_opt_in is false then null
                               else p.insights_opt_in_at end,
    muted_topics        = case when p_muted_topics is null then p.muted_topics
                               else coalesce((select array_agg(distinct t order by t) from unnest(p_muted_topics) t), '{}'::text[]) end,
    large_txn_threshold = coalesce(p_large_txn_threshold, p.large_txn_threshold),
    updated_at          = now()
  where p.profile_id = v_uid;

  return public.get_my_whatsapp_preferences();
end;
$$;

revoke all on function public.get_my_whatsapp_preferences() from public;
revoke all on function public.get_my_whatsapp_preferences() from anon;
grant execute on function public.get_my_whatsapp_preferences() to authenticated;
revoke all on function public.set_my_whatsapp_preferences(boolean, boolean, text[], numeric) from public;
revoke all on function public.set_my_whatsapp_preferences(boolean, boolean, text[], numeric) from anon;
grant execute on function public.set_my_whatsapp_preferences(boolean, boolean, text[], numeric) to authenticated;

-- ── 2. Delivery tracking on outbound audit rows ─────────────────────────────
alter table public.whatsapp_inbound_messages
  add column if not exists provider_message_id text,
  add column if not exists delivery_status     text,
  add column if not exists delivery_updated_at timestamptz;
create unique index if not exists uq_wa_messages_provider_id
  on public.whatsapp_inbound_messages(provider_message_id) where provider_message_id is not null;

COMMIT;

-- ── 3. Scheduler ────────────────────────────────────────────────────────────
-- Validated 25 Sep against production in a rolled-back DO block: both jobs are
-- created, the RPCs work as a signed-in user, anon cannot execute them.
create extension if not exists pg_net with schema extensions;
create extension if not exists pg_cron;

-- Every 15 minutes: large-spend, budget and split alerts.
select cron.schedule('whatsapp-dispatch-alerts', '*/15 * * * *', $job$
  select net.http_post(
    url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/whatsapp-dispatch?job=alerts',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-dispatch-secret', s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s where s.name = 'whatsapp_dispatch_secret';
$job$);

-- Sundays 18:00 IST (12:30 UTC): the weekly summary and stale-balance nudge,
-- both marketing, so they reach only people who opted in.
select cron.schedule('whatsapp-dispatch-weekly', '30 12 * * 0', $job$
  select net.http_post(
    url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/whatsapp-dispatch?job=weekly',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-dispatch-secret', s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s where s.name = 'whatsapp_dispatch_secret';
$job$);

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260927120000_w2b_whatsapp_approve_recurring.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.43.0 (W2b) — "paid Rent" on WhatsApp approves the due bill, atomically.
--
-- The bill reminder says: Reply "paid Rent" to log it. Doing that by logging a
-- plain transaction would leave the recurring schedule due, and the app would ask
-- for the same bill again — a double count. So the reply does what Approve does in
-- the app (`approveRecurring`), in ONE transaction:
--   1. claim the inbound message (a replay comes back 'duplicate');
--   2. check the approver holds a write role in the household;
--   3. lock the schedule and check THIS occurrence is the one due, and is due
--      today or earlier (the app never approves early);
--   4. check the row the Edge Function built matches the locked template
--      (type, amount, currency, date, schedule) — the service computes the row with
--      the parity-tested port, the database refuses one that disagrees;
--   5. insert it under the deterministic occurrence id (the app would use the same
--      id, so if the app already posted it, nothing is inserted twice);
--   6. advance the schedule.
-- Loan EMIs, transfers and investments are refused ('approve_in_app'): the app
-- posts an EMI through the loan-payment split, never as a plain expense.
--
-- Service role only. MONEY MODEL: the row is exactly the app's own row for this
-- occurrence; nothing here computes an amount.
-- ============================================================================

create or replace function public.whatsapp_approve_recurring(
  p_profile_id    uuid,
  p_household_id  uuid,
  p_schedule_id   uuid,
  p_occurrence    date,
  p_today         date,
  p_next_due      date,
  p_row           jsonb,
  p_wa_message_id text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_member_id  uuid;
  v_role       text;
  v_s          public.recurring_schedules%rowtype;
  v_t          jsonb;
  v_claimed    int;
  v_inserted   int;
  v_type       text;
  v_mode       text;
  v_paying     uuid;
begin
  -- 1. Claim the message, exactly as whatsapp_log_transaction does.
  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;
  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('status', 'duplicate');
  end if;

  -- 2. A write role in this household.
  select id, role into v_member_id, v_role
    from public.memberships
   where household_id = p_household_id and user_id = p_profile_id
   limit 1;
  if v_member_id is null then
    return jsonb_build_object('status', 'error', 'reason', 'not_a_member');
  end if;
  if v_role = 'viewer' then
    return jsonb_build_object('status', 'error', 'reason', 'read_only_member');
  end if;

  -- 3. The schedule, locked, and this occurrence the one due.
  select * into v_s
    from public.recurring_schedules
   where id = p_schedule_id and household_id = p_household_id and deleted_at is null
   for update;
  if not found or not v_s.active then
    return jsonb_build_object('status', 'error', 'reason', 'schedule_unavailable');
  end if;
  v_t := v_s.txn_template;
  if v_s.next_due_date > p_occurrence then
    return jsonb_build_object('status', 'already_done', 'next_due_date', v_s.next_due_date);
  end if;
  if v_s.next_due_date < p_occurrence then
    return jsonb_build_object('status', 'error', 'reason', 'not_the_due_occurrence');
  end if;
  if p_occurrence > p_today then
    return jsonb_build_object('status', 'error', 'reason', 'not_due_yet');
  end if;
  if p_next_due is null or p_next_due <= p_occurrence then
    return jsonb_build_object('status', 'error', 'reason', 'bad_next_due');
  end if;

  v_type := v_t->>'type';
  if v_type not in ('expense', 'income') or coalesce(v_t->>'category', '') = 'loan_emi'
     or nullif(v_t->>'debtId', '') is not null then
    return jsonb_build_object('status', 'error', 'reason', 'approve_in_app');
  end if;

  -- 4. The row must be this occurrence of this template.
  if (p_row->>'recurring_schedule_id')::uuid is distinct from p_schedule_id
     or (p_row->>'household_id')::uuid is distinct from p_household_id
     or (p_row->>'date')::date is distinct from p_occurrence
     or p_row->>'type' is distinct from v_type
     or (p_row->>'amount')::numeric is distinct from (v_t->>'amount')::numeric
     or coalesce(p_row->>'currency', 'USD') is distinct from coalesce(nullif(v_t->>'currency', ''), 'USD') then
    return jsonb_build_object('status', 'error', 'reason', 'row_mismatch');
  end if;

  -- A mode the paying account does not use is dropped, never an error (the
  -- store's rule, and whatsapp_log_transaction's).
  v_mode := nullif(p_row->>'payment_mode', '');
  if v_mode is not null then
    v_paying := case when v_type = 'income' then nullif(p_row->>'to_account_id', '')::uuid
                     else nullif(p_row->>'account_id', '')::uuid end;
    if exists (select 1 from public.accounts a where a.id = v_paying
                 and coalesce(array_length(a.payment_modes, 1), 0) > 0
                 and not (v_mode = any (a.payment_modes))) then
      v_mode := null;
    end if;
  end if;

  -- 5. The app's own row, under the deterministic id.
  insert into public.transactions (
    id, household_id, created_by, member_id, type, amount, currency, date, description,
    category, note, recurring, account_id, to_account_id, initiated_by,
    recurring_schedule_id, debt_id, payment_mode, extras, confidence, source, estimated_at, confirmed_at
  ) values (
    (p_row->>'id')::uuid,
    p_household_id,
    p_profile_id,
    nullif(p_row->>'member_id', '')::uuid,
    v_type,
    (p_row->>'amount')::numeric,
    coalesce(nullif(p_row->>'currency', ''), 'USD'),
    p_occurrence,
    coalesce(p_row->>'description', ''),
    nullif(p_row->>'category', ''),
    nullif(p_row->>'note', ''),
    nullif(p_row->>'recurring', ''),
    nullif(p_row->>'account_id', '')::uuid,
    nullif(p_row->>'to_account_id', '')::uuid,
    nullif(p_row->>'initiated_by', '')::uuid,
    p_schedule_id,
    null,
    v_mode,
    coalesce(p_row->'extras', '{}'::jsonb),
    coalesce(nullif(p_row->>'confidence', ''), 'confirmed'),
    coalesce(nullif(p_row->>'source', ''), 'user'),
    nullif(p_row->>'estimated_at', '')::timestamptz,
    nullif(p_row->>'confirmed_at', '')::timestamptz
  )
  on conflict (id) do nothing;
  get diagnostics v_inserted = row_count;

  -- 6. Move the schedule on.
  update public.recurring_schedules
     set last_generated = p_occurrence, next_due_date = p_next_due
   where id = p_schedule_id;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
           'approved', jsonb_build_object('schedule_id', p_schedule_id, 'occurrence', p_occurrence,
                                          'transaction_id', p_row->>'id', 'inserted', v_inserted = 1))
   where wa_message_id = p_wa_message_id;

  return jsonb_build_object(
    'status', 'success',
    'transaction_id', p_row->>'id',
    'already_posted', v_inserted = 0,
    'amount', (p_row->>'amount')::numeric,
    'currency', coalesce(nullif(p_row->>'currency', ''), 'USD'),
    'description', p_row->>'description',
    'next_due_date', p_next_due
  );
end;
$$;

revoke all on function public.whatsapp_approve_recurring(uuid, uuid, uuid, date, date, date, jsonb, text) from public, anon, authenticated;
grant execute on function public.whatsapp_approve_recurring(uuid, uuid, uuid, date, date, date, jsonb, text) to service_role;

-- Daily at 09:00 IST (03:30 UTC): bill reminders for approval schedules due today.
-- Inert until whatsapp_dispatch_secret exists, like the other dispatch jobs.
select cron.schedule('whatsapp-dispatch-bills', '30 3 * * *', $job$
  select net.http_post(
    url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/whatsapp-dispatch?job=bills',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-dispatch-secret', s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s where s.name = 'whatsapp_dispatch_secret';
$job$);

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260928120000_w3_whatsapp_capture_conversation.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.44.0 (W3) — the capture conversation on WhatsApp.
--
--   1. `whatsapp_pending_turns`: one open question per person (a missing amount,
--      a possible duplicate), with what it is waiting to log. It expires after 30
--      minutes; asking something new replaces it. Server-owned (RLS on, no
--      policies), like every WhatsApp table.
--   2. `whatsapp_undo_last`: UNDO removes the entry WhatsApp logged for this
--      person in the last 15 minutes — a soft delete, exactly like deleting it in
--      the app — unless it has been edited in the app since.
--   3. `whatsapp_correct_last`: "no, that was groceries" re-categorises that same
--      entry under the same rules.
--
-- Both act ONLY on a transaction `whatsapp_log_transaction` created (its id is
-- on the inbox row), never on anything the app wrote, never on a "paid Rent"
-- approval (undoing that would also have to rewind the schedule). Both claim the
-- message first, so a replay is silent. Service role only.
--
-- MONEY MODEL: a soft delete and a category change on one ordinary row, the same
-- two edits the app offers. No amount is changed.
-- ============================================================================

BEGIN;

create table if not exists public.whatsapp_pending_turns (
  id           uuid primary key default gen_random_uuid(),
  profile_id   uuid not null references public.profiles(id) on delete cascade,
  household_id uuid not null references public.households(id) on delete cascade,
  kind         text not null check (kind in ('missing_amount', 'duplicate_check')),
  payload      jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now(),
  expires_at   timestamptz not null default now() + interval '30 minutes',
  resolved_at  timestamptz
);
-- At most one open question per person.
create unique index if not exists uq_wa_pending_open
  on public.whatsapp_pending_turns(profile_id) where resolved_at is null;
alter table public.whatsapp_pending_turns enable row level security;
revoke all on public.whatsapp_pending_turns from public, anon, authenticated;
grant select, insert, update, delete on public.whatsapp_pending_turns to service_role;

-- The last entry WhatsApp logged for this person, locked, with why it may not be
-- touched. Shared by UNDO and correction.
create or replace function public.whatsapp_last_logged(p_profile_id uuid, p_household_id uuid, p_exclude text)
returns table (inbox_id text, txn_id uuid, reason text)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_inbox text; v_txn uuid; v_at timestamptz; v_created timestamptz; v_updated timestamptz; v_deleted timestamptz;
  v_ours timestamptz;
begin
  select m.wa_message_id, (m.payload->'parsed'->>'transaction_id')::uuid, m.processed_at,
         (m.payload->>'corrected_at')::timestamptz
    into v_inbox, v_txn, v_at, v_ours
    from public.whatsapp_inbound_messages m
   where m.direction = 'inbound' and m.profile_id = p_profile_id and m.household_id = p_household_id
     and m.wa_message_id <> p_exclude
     and m.payload->'parsed'->>'transaction_id' is not null
     and m.payload->>'undone' is null
   order by m.processed_at desc nulls last
   limit 1;
  if v_txn is null then
    return query select null::text, null::uuid, 'nothing'::text; return;
  end if;
  if v_at < now() - interval '15 minutes' then
    return query select v_inbox, v_txn, 'too_late'::text; return;
  end if;
  select t.created_at, t.updated_at, t.deleted_at into v_created, v_updated, v_deleted
    from public.transactions t where t.id = v_txn and t.household_id = p_household_id for update;
  if not found or v_deleted is not null then
    return query select v_inbox, v_txn, 'nothing'::text; return;
  end if;
  -- Edited in the app since WhatsApp wrote it: that edit is the person's, leave it.
  -- A correction made from WhatsApp also moves updated_at; it records when, so it
  -- is not mistaken for an edit in the app.
  if v_updated > greatest(v_created, coalesce(v_ours, v_created)) + interval '5 seconds' then
    return query select v_inbox, v_txn, 'edited'::text; return;
  end if;
  return query select v_inbox, v_txn, null::text;
end;
$$;

-- Claim the message and check a write role; null when both pass, else the reply status.
create or replace function public.whatsapp_claim_for_write(p_profile_id uuid, p_household_id uuid, p_wa_message_id text)
returns text
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_claimed int; v_role text;
begin
  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound') on conflict (wa_message_id) do nothing;
  update public.whatsapp_inbound_messages set processed_at = now()
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then return 'duplicate'; end if;
  select role into v_role from public.memberships where household_id = p_household_id and user_id = p_profile_id limit 1;
  if v_role is null then return 'not_a_member'; end if;
  if v_role = 'viewer' then return 'read_only_member'; end if;
  return null;
end;
$$;

create or replace function public.whatsapp_undo_last(p_profile_id uuid, p_household_id uuid, p_wa_message_id text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_block text; l record; t record;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select * into l from public.whatsapp_last_logged(p_profile_id, p_household_id, p_wa_message_id);
  if l.reason is not null then return jsonb_build_object('status', l.reason); end if;

  update public.transactions set deleted_at = now()
   where id = l.txn_id returning amount, currency, type, category into t;
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('undone', now())
   where wa_message_id = l.inbox_id;
  return jsonb_build_object('status', 'undone', 'transaction_id', l.txn_id,
    'amount', t.amount, 'currency', t.currency, 'type', t.type, 'category_id', t.category);
end;
$$;

create or replace function public.whatsapp_correct_last(
  p_profile_id uuid, p_household_id uuid, p_category text, p_wa_message_id text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_block text; l record; v_type text; t record; v_at timestamptz;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select * into l from public.whatsapp_last_logged(p_profile_id, p_household_id, p_wa_message_id);
  if l.reason is not null then return jsonb_build_object('status', l.reason); end if;

  select type into v_type from public.transactions where id = l.txn_id;
  -- Only an expense or an income carries a category; the caller checked the id is
  -- one of that type's categories.
  if v_type not in ('expense', 'income') then return jsonb_build_object('status', 'no_category'); end if;
  update public.transactions set category = p_category
   where id = l.txn_id returning amount, currency, type, category, updated_at into t;
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('corrected_at', t.updated_at)
   where wa_message_id = l.inbox_id;
  return jsonb_build_object('status', 'corrected', 'transaction_id', l.txn_id,
    'amount', t.amount, 'currency', t.currency, 'type', t.type, 'category_id', t.category);
end;
$$;

revoke all on function public.whatsapp_last_logged(uuid, uuid, text) from public, anon, authenticated;
revoke all on function public.whatsapp_claim_for_write(uuid, uuid, text) from public, anon, authenticated;
revoke all on function public.whatsapp_undo_last(uuid, uuid, text) from public, anon, authenticated;
revoke all on function public.whatsapp_correct_last(uuid, uuid, text, text) from public, anon, authenticated;
grant execute on function public.whatsapp_last_logged(uuid, uuid, text) to service_role;
grant execute on function public.whatsapp_claim_for_write(uuid, uuid, text) to service_role;
grant execute on function public.whatsapp_undo_last(uuid, uuid, text) to service_role;
grant execute on function public.whatsapp_correct_last(uuid, uuid, text, text) to service_role;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260929120000_w4_whatsapp_answers_consent.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.45.0 (W4) — Ask Vyact answers on WhatsApp, only with consent.
--
-- An answer puts figures on a phone's notification screen. So questions stay
-- hard-blocked on WhatsApp unless the person turns on "Answer my questions here"
-- in the app — a consent of its own (`reads_enabled`), OFF by default, recorded
-- with when it was given, never bundled with marketing or insights.
--
--   1. whatsapp_preferences.reads_enabled (+ reads_enabled_at).
--   2. get/set_my_whatsapp_preferences carry it (set gains p_reads_enabled; the
--      old 4-argument function is replaced, not overloaded).
--   3. whatsapp_pending_turns may hold 'chips': an answer's follow-ups, so a reply
--      of "1", "2" or "3" asks that follow-up.
--
-- MONEY MODEL: untouched.
-- ============================================================================

BEGIN;

alter table public.whatsapp_preferences
  add column if not exists reads_enabled    boolean not null default false,
  add column if not exists reads_enabled_at timestamptz;

alter table public.whatsapp_pending_turns drop constraint if exists whatsapp_pending_turns_kind_check;
alter table public.whatsapp_pending_turns drop constraint if exists ck_wa_pending_kind;
alter table public.whatsapp_pending_turns add constraint ck_wa_pending_kind
  check (kind in ('missing_amount', 'duplicate_check', 'chips'));

create or replace function public.get_my_whatsapp_preferences()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'marketing_opt_in',    coalesce(p.marketing_opt_in, false),
    'marketing_opt_in_at', p.marketing_opt_in_at,
    'insights_opt_in',     coalesce(p.insights_opt_in, false),
    'reads_enabled',       coalesce(p.reads_enabled, false),
    'muted_topics',        coalesce(to_jsonb(p.muted_topics), '[]'::jsonb),
    'large_txn_threshold', coalesce(p.large_txn_threshold, 10000),
    'linked',              exists (select 1 from public.whatsapp_identities i where i.profile_id = auth.uid())
  )
  from (select auth.uid() as uid) me
  left join public.whatsapp_preferences p on p.profile_id = me.uid
  where me.uid is not null;
$$;

drop function if exists public.set_my_whatsapp_preferences(boolean, boolean, text[], numeric);

create or replace function public.set_my_whatsapp_preferences(
  p_marketing_opt_in    boolean default null,
  p_insights_opt_in     boolean default null,
  p_muted_topics        text[]  default null,
  p_large_txn_threshold numeric default null,
  p_reads_enabled       boolean default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_large_txn_threshold is not null and p_large_txn_threshold <= 0 then
    raise exception 'threshold must be positive' using errcode = '22023';
  end if;

  insert into public.whatsapp_preferences (profile_id) values (v_uid)
  on conflict (profile_id) do nothing;

  update public.whatsapp_preferences p set
    marketing_opt_in    = coalesce(p_marketing_opt_in, p.marketing_opt_in),
    marketing_opt_in_at = case when p_marketing_opt_in is true and not p.marketing_opt_in then now()
                               when p_marketing_opt_in is false then null
                               else p.marketing_opt_in_at end,
    marketing_source    = case when p_marketing_opt_in is true and not p.marketing_opt_in then 'app_settings'
                               when p_marketing_opt_in is false then null
                               else p.marketing_source end,
    insights_opt_in     = coalesce(p_insights_opt_in, p.insights_opt_in),
    insights_opt_in_at  = case when p_insights_opt_in is true and not p.insights_opt_in then now()
                               when p_insights_opt_in is false then null
                               else p.insights_opt_in_at end,
    reads_enabled       = coalesce(p_reads_enabled, p.reads_enabled),
    reads_enabled_at    = case when p_reads_enabled is true and not p.reads_enabled then now()
                               when p_reads_enabled is false then null
                               else p.reads_enabled_at end,
    muted_topics        = case when p_muted_topics is null then p.muted_topics
                               else coalesce((select array_agg(distinct t order by t) from unnest(p_muted_topics) t), '{}'::text[]) end,
    large_txn_threshold = coalesce(p_large_txn_threshold, p.large_txn_threshold),
    updated_at          = now()
  where p.profile_id = v_uid;

  return public.get_my_whatsapp_preferences();
end;
$$;

revoke all on function public.get_my_whatsapp_preferences() from public;
revoke all on function public.get_my_whatsapp_preferences() from anon;
grant execute on function public.get_my_whatsapp_preferences() to authenticated;
revoke all on function public.set_my_whatsapp_preferences(boolean, boolean, text[], numeric, boolean) from public;
revoke all on function public.set_my_whatsapp_preferences(boolean, boolean, text[], numeric, boolean) from anon;
grant execute on function public.set_my_whatsapp_preferences(boolean, boolean, text[], numeric, boolean) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20260930120000_w5_whatsapp_answers_optin.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.46.0 (W5) — "ANSWERS ON" from the chat: consent given where it is asked.
--
-- The WhatsApp answer rule (responses spec §6): a question is answered in the
-- chat, and a link is never the answer. Someone with answers off who asks a
-- question is now OFFERED answers in the chat ("Reply ANSWERS ON"), instead of
-- being sent to the app. So consent can be given in two places, and the record
-- says which:
--   1. whatsapp_preferences.reads_source: 'app_settings' | 'whatsapp_keyword'.
--   2. set_my_whatsapp_preferences stamps 'app_settings' when answers are turned on
--      in the app (and clears it when turned off), as marketing already does.
--   3. whatsapp_pending_turns may hold 'reads_offer': the question that prompted
--      the offer, answered as soon as the person says ANSWERS ON.
--
-- MONEY MODEL: untouched.
-- ============================================================================

BEGIN;

alter table public.whatsapp_preferences
  add column if not exists reads_source text;
alter table public.whatsapp_preferences drop constraint if exists ck_wa_prefs_reads_source;
alter table public.whatsapp_preferences add constraint ck_wa_prefs_reads_source
  check (reads_source is null or reads_source in ('app_settings', 'whatsapp_keyword'));

alter table public.whatsapp_pending_turns drop constraint if exists ck_wa_pending_kind;
alter table public.whatsapp_pending_turns add constraint ck_wa_pending_kind
  check (kind in ('missing_amount', 'duplicate_check', 'chips', 'reads_offer'));

create or replace function public.set_my_whatsapp_preferences(
  p_marketing_opt_in    boolean default null,
  p_insights_opt_in     boolean default null,
  p_muted_topics        text[]  default null,
  p_large_txn_threshold numeric default null,
  p_reads_enabled       boolean default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not signed in' using errcode = '42501';
  end if;
  if p_large_txn_threshold is not null and p_large_txn_threshold <= 0 then
    raise exception 'threshold must be positive' using errcode = '22023';
  end if;

  insert into public.whatsapp_preferences (profile_id) values (v_uid)
  on conflict (profile_id) do nothing;

  update public.whatsapp_preferences p set
    marketing_opt_in    = coalesce(p_marketing_opt_in, p.marketing_opt_in),
    marketing_opt_in_at = case when p_marketing_opt_in is true and not p.marketing_opt_in then now()
                               when p_marketing_opt_in is false then null
                               else p.marketing_opt_in_at end,
    marketing_source    = case when p_marketing_opt_in is true and not p.marketing_opt_in then 'app_settings'
                               when p_marketing_opt_in is false then null
                               else p.marketing_source end,
    insights_opt_in     = coalesce(p_insights_opt_in, p.insights_opt_in),
    insights_opt_in_at  = case when p_insights_opt_in is true and not p.insights_opt_in then now()
                               when p_insights_opt_in is false then null
                               else p.insights_opt_in_at end,
    reads_enabled       = coalesce(p_reads_enabled, p.reads_enabled),
    reads_enabled_at    = case when p_reads_enabled is true and not p.reads_enabled then now()
                               when p_reads_enabled is false then null
                               else p.reads_enabled_at end,
    reads_source        = case when p_reads_enabled is true and not p.reads_enabled then 'app_settings'
                               when p_reads_enabled is false then null
                               else p.reads_source end,
    muted_topics        = case when p_muted_topics is null then p.muted_topics
                               else coalesce((select array_agg(distinct t order by t) from unnest(p_muted_topics) t), '{}'::text[]) end,
    large_txn_threshold = coalesce(p_large_txn_threshold, p.large_txn_threshold),
