-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261001120000_w6_whatsapp_name_and_update.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.47.0 (W6) — two follow-up conversations on WhatsApp.
--
--   1. "Name them here": this month's expenses still in Other are listed (up to
--      five, biggest first) and named from the chat ("1 groceries").
--      * `whatsapp_unnamed_expenses` lists them: the household's live expenses in
--        Other, never another member's private (excluded) entry.
--      * `whatsapp_name_entries` changes ONLY the category, on entries that are
--        still unnamed — never the amount, the account or the date. The caller
--        checked each category is an expense category (type-scoped).
--   2. "Reply UPDATE": stale bank, card and cash balances, one at a time.
--      * `whatsapp_reconcile_account` applies the reconcile the APP computes
--        (serverEngine.reconcileOnServer → accountBalance.reconcileAccount): the
--        new reconciliation offset, the log with its dated entry, and the stamp
--        `last_reconciled_at`, with provenance confirmed/user — exactly what
--        reconcileSlice writes. It also bridges the stated value to the linked
--        Asset or Debt, as the slice does. It refuses when the offset has moved
--        since the plan was made (another reconcile raced it).
--   3. `whatsapp_pending_turns` may hold 'name_entries' and 'balance_update'.
--
-- All three claim the message first (a replay is silent) and need a write role.
-- Service role only.
--
-- MONEY MODEL: a category change on ordinary expense rows (the app's own edit),
-- and a reconciliation that is an account offset + dated log, NEVER a
-- transaction (D2). No amount is changed; nothing is inserted into transactions.
-- ============================================================================

BEGIN;

alter table public.whatsapp_pending_turns drop constraint if exists ck_wa_pending_kind;
alter table public.whatsapp_pending_turns add constraint ck_wa_pending_kind
  check (kind in ('missing_amount', 'duplicate_check', 'chips', 'reads_offer', 'name_entries', 'balance_update'));

-- ── 1. Unnamed expenses ─────────────────────────────────────────────────────
create or replace function public.whatsapp_unnamed_expenses(
  p_profile_id uuid, p_household_id uuid, p_from date, p_limit int default 5
) returns table (id uuid, amount numeric, currency text, date date, account_name text)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select t.id, t.amount, t.currency::text, t.date, a.name
    from public.transactions t
    left join public.accounts a on a.id = t.account_id
   where t.household_id = p_household_id
     and t.deleted_at is null
     and t.type = 'expense'
     and t.category in ('other_expense', 'other')
     and t.date >= p_from
     -- Someone else's private entry is theirs to name.
     and not (coalesce((t.extras->>'excluded')::boolean, false) and t.created_by is distinct from p_profile_id)
   order by t.amount desc, t.date desc, t.id
   limit greatest(1, least(coalesce(p_limit, 5), 10));
$$;

create or replace function public.whatsapp_name_entries(
  p_profile_id uuid, p_household_id uuid, p_wa_message_id text, p_items jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_block text; v_item jsonb; t record; v_out jsonb := '[]'::jsonb; v_status text;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 10 then
    return jsonb_build_object('status', 'bad_request');
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    select x.id, x.type, x.category, x.deleted_at, x.created_by,
           coalesce((x.extras->>'excluded')::boolean, false) as excluded
      into t
      from public.transactions x
     where x.id = (v_item->>'id')::uuid and x.household_id = p_household_id
     for update;
    if not found or t.deleted_at is not null then v_status := 'gone';
    elsif t.type <> 'expense' then v_status := 'not_expense';
    elsif t.excluded and t.created_by is distinct from p_profile_id then v_status := 'private';
    elsif t.category not in ('other_expense', 'other') then v_status := 'already_named';
    else
      update public.transactions set category = v_item->>'category' where id = t.id;
      v_status := 'named';
    end if;
    v_out := v_out || jsonb_build_object('id', v_item->>'id', 'status', v_status, 'category', v_item->>'category');
  end loop;
  return jsonb_build_object('status', 'done', 'results', v_out);
end;
$$;

-- ── 2. Reconcile one account from the chat ──────────────────────────────────
create or replace function public.whatsapp_reconcile_account(
  p_profile_id uuid, p_household_id uuid, p_wa_message_id text,
  p_account_id uuid, p_expected_offset numeric, p_offset numeric, p_log jsonb, p_at timestamptz,
  p_bridge jsonb default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_block text; a record;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;

  select x.id, x.kind, x.is_archived, x.deleted_at, coalesce(x.reconciliation_offset, 0) as off
    into a
    from public.accounts x
   where x.id = p_account_id and x.household_id = p_household_id
   for update;
  if not found or a.deleted_at is not null or a.is_archived then return jsonb_build_object('status', 'gone'); end if;
  if a.kind not in ('bank', 'credit_card', 'cash') then return jsonb_build_object('status', 'not_supported'); end if;
  -- The plan was computed from this offset; if it moved, the plan is stale.
  if round(a.off, 2) <> round(coalesce(p_expected_offset, 0), 2) then
    return jsonb_build_object('status', 'changed');
  end if;
  if jsonb_typeof(p_log) <> 'array' then return jsonb_build_object('status', 'bad_request'); end if;

  update public.accounts set
    reconciliation_offset = round(p_offset, 2),
    reconciliation_log    = p_log,
    last_reconciled_at    = p_at,
    confidence = 'confirmed', source = 'user', confirmed_at = p_at
   where id = p_account_id;

  -- §6 R-AGG-5 / D2 — the stated value flows to the linked entity (reconcileSlice).
  if p_bridge is not null and p_bridge->>'debt_id' is not null then
    update public.debts set current_balance = greatest(0, (p_bridge->>'current_balance')::numeric),
           confidence = 'confirmed', source = 'user', confirmed_at = p_at
     where id = (p_bridge->>'debt_id')::uuid and household_id = p_household_id and deleted_at is null;
  elsif p_bridge is not null and p_bridge->>'asset_id' is not null then
    update public.assets set value = (p_bridge->>'value')::numeric, last_updated = (p_at at time zone 'UTC')::date,
           confidence = 'confirmed', source = 'user', confirmed_at = p_at
     where id = (p_bridge->>'asset_id')::uuid and household_id = p_household_id and deleted_at is null;
  end if;
  return jsonb_build_object('status', 'reconciled', 'offset', round(p_offset, 2));
end;
$$;

revoke all on function public.whatsapp_unnamed_expenses(uuid, uuid, date, int) from public, anon, authenticated;
revoke all on function public.whatsapp_name_entries(uuid, uuid, text, jsonb) from public, anon, authenticated;
revoke all on function public.whatsapp_reconcile_account(uuid, uuid, text, uuid, numeric, numeric, jsonb, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function public.whatsapp_unnamed_expenses(uuid, uuid, date, int) to service_role;
grant execute on function public.whatsapp_name_entries(uuid, uuid, text, jsonb) to service_role;
grant execute on function public.whatsapp_reconcile_account(uuid, uuid, text, uuid, numeric, numeric, jsonb, timestamptz, jsonb) to service_role;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261002120000_w6b_whatsapp_template_senders.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- v10.47.0 (W6b) — senders for the approved templates that had none, and the
-- replies their buttons promise (the "Template button replies" board).
--
--   1. `whatsapp_rule_state`: the last value a rule saw (the runway baseline), so a
--      runway note fires only on a real change and at most once a month.
--   2. `whatsapp_split_share_recipients`: shares created since a time, with the
--      linked WhatsApp identity of the person they were shared with (by the
--      participant's verified sign-in email, the same key shared splits use).
--   3. `whatsapp_split_even`: "Split 50/50" on partner_split_prompt. Writes the
--      SAME two things the app's split form writes: the transaction's
--      extras.split (only yourShare then counts, INV money model) and the
--      shared_splits + shared_split_shares rows the partner sees.
--   4. `whatsapp_undo_recurring_post`: "Undo" on recurring_auto_logged — removes
--      that posted entry (a soft delete, like deleting it in the app). The
--      schedule stays advanced, as the board says: "The schedule stays on for
--      next month." The 15-minute window is checked by the webhook against the
--      message it answers.
--   5. `whatsapp_pause_schedule`: "Pause this one" — the schedule's active flag,
--      exactly the app's pause.
--   6. Two scheduler jobs: the evening digest (20:30 IST) and a daily 09:10 IST
--      pass for the month close (the 1st), budget set-up (two days before a month)
--      and the runway check.
--
-- All writers claim the message first (a replay is silent) and need a write role.
-- Service role only.
-- ============================================================================

BEGIN;

create table if not exists public.whatsapp_rule_state (
  household_id uuid not null references public.households(id) on delete cascade,
  rule         text not null,
  value        numeric,
  detail       jsonb not null default '{}'::jsonb,
  updated_at   timestamptz not null default now(),
  primary key (household_id, rule)
);
alter table public.whatsapp_rule_state enable row level security;
revoke all on public.whatsapp_rule_state from public, anon, authenticated;
grant select, insert, update, delete on public.whatsapp_rule_state to service_role;

-- ── 2. Shares created since a time, with the recipient's linked number ──────
create or replace function public.whatsapp_split_share_recipients(p_since timestamptz)
returns table (
  share_id uuid, share numeric, split_id uuid, description text, currency text, total_amount numeric,
  owner_user_id uuid, recipient_profile_id uuid, recipient_household_id uuid
)
language sql
stable
security definer
set search_path = public, auth, pg_temp
as $$
  select sh.id, sh.share, sp.id, sp.description, sp.currency::text, sp.total_amount,
         sp.owner_user_id, i.profile_id, i.household_id
    from public.shared_split_shares sh
    join public.shared_splits sp on sp.id = sh.split_id and sp.closed_at is null
    join auth.users u on lower(u.email) = lower(sh.email)
    join public.whatsapp_identities i on i.profile_id = u.id
   where sh.created_at > p_since
     and not sh.paid
     and i.profile_id <> sp.owner_user_id;
$$;

-- ── 3. Split 50/50 from the chat ────────────────────────────────────────────
create or replace function public.whatsapp_split_even(
  p_profile_id uuid, p_household_id uuid, p_wa_message_id text,
  p_txn_id uuid, p_partner_email text, p_split jsonb, p_partner_share numeric
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_block text; t record; v_split uuid;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;

  select x.id, x.type, x.amount, x.currency, x.date, x.description, x.created_by, x.deleted_at, x.extras
    into t from public.transactions x
   where x.id = p_txn_id and x.household_id = p_household_id for update;
  if not found or t.deleted_at is not null then return jsonb_build_object('status', 'gone'); end if;
  if t.type <> 'expense' then return jsonb_build_object('status', 'not_expense'); end if;
  if t.created_by is distinct from p_profile_id then return jsonb_build_object('status', 'not_yours'); end if;
  if t.extras ? 'split' or exists (select 1 from public.shared_splits s where s.txn_id = t.id) then
    return jsonb_build_object('status', 'already_split');
  end if;
  -- The caller built the split from this row; refuse a mismatch rather than store it.
  if round((p_split->>'totalAmount')::numeric, 2) <> round(t.amount, 2)
     or round((p_split->>'yourShare')::numeric + p_partner_share, 2) <> round(t.amount, 2) then
    return jsonb_build_object('status', 'bad_request');
  end if;

  update public.transactions
     set extras = coalesce(extras, '{}'::jsonb) || jsonb_build_object('split', p_split)
   where id = t.id;
  insert into public.shared_splits (owner_user_id, owner_household_id, txn_id, description, currency, total_amount, txn_type, date)
    values (p_profile_id, p_household_id, t.id, t.description, t.currency, t.amount, 'expense', t.date)
    returning id into v_split;
  insert into public.shared_split_shares (split_id, email, share)
    values (v_split, lower(trim(p_partner_email)), p_partner_share);
  return jsonb_build_object('status', 'split', 'split_id', v_split, 'description', t.description,
    'currency', t.currency, 'your_share', (p_split->>'yourShare')::numeric, 'partner_share', p_partner_share);
end;
$$;

-- The person someone splits with most often (their "usual split partner"), with a
-- first name when that email belongs to a Vyact account. Null when they have never
-- shared a split: the prompt is then not sent.
create or replace function public.whatsapp_usual_split_partner(p_profile_id uuid)
returns table (email text, first_name text, times int)
language sql
stable
security definer
set search_path = public, auth, pg_temp
as $$
  select lower(sh.email) as email,
         nullif(split_part(trim(coalesce(max(p.display_name), '')), ' ', 1), '') as first_name,
         count(*)::int as times
    from public.shared_splits sp
    join public.shared_split_shares sh on sh.split_id = sp.id
    left join auth.users u on lower(u.email) = lower(sh.email)
    left join public.profiles p on p.id = u.id
   where sp.owner_user_id = p_profile_id
   group by lower(sh.email)
   order by count(*) desc, max(sp.created_at) desc
   limit 1;
$$;

-- ── 4. Undo a recurring post ────────────────────────────────────────────────
create or replace function public.whatsapp_undo_recurring_post(
  p_profile_id uuid, p_household_id uuid, p_wa_message_id text, p_txn_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_block text; t record;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select x.id, x.amount, x.currency, x.date, x.description, x.recurring_schedule_id, x.deleted_at, x.created_at, x.updated_at
    into t from public.transactions x
   where x.id = p_txn_id and x.household_id = p_household_id for update;
  if not found or t.deleted_at is not null then return jsonb_build_object('status', 'gone'); end if;
  if t.recurring_schedule_id is null then return jsonb_build_object('status', 'not_scheduled'); end if;
  -- Edited in the app since it posted: that edit is the person's; leave it.
  if t.updated_at > t.created_at + interval '5 seconds' then return jsonb_build_object('status', 'edited'); end if;
  update public.transactions set deleted_at = now() where id = t.id;
  return jsonb_build_object('status', 'undone', 'description', t.description, 'amount', t.amount,
    'currency', t.currency, 'date', t.date);
end;
$$;

-- ── 5. Pause a schedule ─────────────────────────────────────────────────────
create or replace function public.whatsapp_pause_schedule(
  p_profile_id uuid, p_household_id uuid, p_wa_message_id text, p_schedule_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_block text; s record;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select x.id, x.active, x.deleted_at, x.txn_template into s from public.recurring_schedules x
   where x.id = p_schedule_id and x.household_id = p_household_id for update;
  if not found or s.deleted_at is not null then return jsonb_build_object('status', 'gone'); end if;
  if s.active then update public.recurring_schedules set active = false where id = s.id; end if;
  return jsonb_build_object('status', case when s.active then 'paused' else 'already_paused' end,
    'name', coalesce(nullif(s.txn_template->>'description', ''), 'that schedule'));
end;
$$;

revoke all on function public.whatsapp_split_share_recipients(timestamptz) from public, anon, authenticated;
revoke all on function public.whatsapp_usual_split_partner(uuid) from public, anon, authenticated;
revoke all on function public.whatsapp_split_even(uuid, uuid, text, uuid, text, jsonb, numeric) from public, anon, authenticated;
revoke all on function public.whatsapp_undo_recurring_post(uuid, uuid, text, uuid) from public, anon, authenticated;
revoke all on function public.whatsapp_pause_schedule(uuid, uuid, text, uuid) from public, anon, authenticated;
grant execute on function public.whatsapp_split_share_recipients(timestamptz) to service_role;
grant execute on function public.whatsapp_usual_split_partner(uuid) to service_role;
grant execute on function public.whatsapp_split_even(uuid, uuid, text, uuid, text, jsonb, numeric) to service_role;
grant execute on function public.whatsapp_undo_recurring_post(uuid, uuid, text, uuid) to service_role;
grant execute on function public.whatsapp_pause_schedule(uuid, uuid, text, uuid) to service_role;

-- ── 6. Scheduler jobs (inert until the Vault secret exists, like the others) ──
select cron.unschedule(jobid) from cron.job where jobname in ('whatsapp-dispatch-digest', 'whatsapp-dispatch-monthly');

-- 20:30 IST (15:00 UTC): the evening household digest.
select cron.schedule('whatsapp-dispatch-digest', '0 15 * * *', $job$
  select net.http_post(
    url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/whatsapp-dispatch?job=digest',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-dispatch-secret', s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s where s.name = 'whatsapp_dispatch_secret';
$job$);

-- 09:10 IST (03:40 UTC) daily: month close (the 1st), budget set-up (two days before a
-- month), and the runway check (at most one note a month).
select cron.schedule('whatsapp-dispatch-monthly', '40 3 * * *', $job$
  select net.http_post(
    url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/whatsapp-dispatch?job=monthly',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-dispatch-secret', s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s where s.name = 'whatsapp_dispatch_secret';
$job$);

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261003120000_web_push.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.48.0 — Web Push for the installed app (TD-22).
--
-- Until now "Browser push" only showed a popup from an OPEN tab; nothing reached a
-- lock screen. This adds the server half:
--   • push_subscriptions — one row per device (browser push endpoint + its keys),
--     written only through the RPCs below, readable by nobody but the service;
--   • push_deliveries    — every attempt and the push service's answer (the proof a
--     device was reached), service-only;
--   • notifications.pushed_at — a notification is pushed at most once;
--   • Vault: the VAPID key pair (created by the web-push function on first use) and
--     the cron secret (created here). Nobody handles either;
--   • pg_cron: web-push dispatch every 15 minutes.

begin;

alter table public.notifications add column if not exists pushed_at timestamptz;
create index if not exists notif_unpushed_idx on public.notifications (household_id, created_at) where pushed_at is null;

create table if not exists public.push_subscriptions (
  id              uuid primary key default gen_random_uuid(),
  user_id         uuid not null references auth.users(id) on delete cascade,
  household_id    uuid not null references public.households(id) on delete cascade,
  endpoint        text not null unique,
  p256dh          text not null,
  auth            text not null,
  user_agent      text,
  tz              text,
  prefs           jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  last_status     int,
  last_success_at timestamptz,
  failures        int not null default 0,
  disabled_at     timestamptz
);
create index if not exists push_sub_household_idx on public.push_subscriptions (household_id) where disabled_at is null;
create index if not exists push_sub_user_idx on public.push_subscriptions (user_id);
alter table public.push_subscriptions enable row level security;
revoke all on public.push_subscriptions from public, anon, authenticated;
grant select, insert, update, delete on public.push_subscriptions to service_role;

create table if not exists public.push_deliveries (
  id              bigint generated always as identity primary key,
  subscription_id uuid references public.push_subscriptions(id) on delete set null,
  user_id         uuid,
  notification_id uuid,
  kind            text not null check (kind in ('test', 'notification')),
  status          int,
  error           text,
  created_at      timestamptz not null default now()
);
create index if not exists push_deliveries_user_idx on public.push_deliveries (user_id, created_at desc);
alter table public.push_deliveries enable row level security;
revoke all on public.push_deliveries from public, anon, authenticated;
grant select, insert, update, delete on public.push_deliveries to service_role;
grant usage on sequence public.push_deliveries_id_seq to service_role;

-- ── Device registration (the signed-in person, for their own device) ──────────

-- Register (or refresh) THIS device for the caller's active household. Idempotent:
-- the endpoint is the device, so a second call updates keys, zone and switches, and a
-- device that signs in as someone else moves to them.
create or replace function public.register_push_subscription(
  p_endpoint text, p_p256dh text, p_auth text, p_household_id uuid,
  p_user_agent text default null, p_tz text default null, p_prefs jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if not public.is_member(p_household_id) then raise exception 'not_a_member' using errcode = '42501'; end if;
  -- Only real push services; the dispatcher POSTs to this URL.
  if p_endpoint is null or length(p_endpoint) > 1024
     or p_endpoint !~ '^https://(fcm\.googleapis\.com|android\.googleapis\.com|updates\.push\.services\.mozilla\.com|push\.services\.mozilla\.com|web\.push\.apple\.com|[a-z0-9-]+\.push\.apple\.com|[a-z0-9-]+\.notify\.windows\.com)/' then
    raise exception 'bad_endpoint' using errcode = '22023';
  end if;
  if coalesce(length(p_p256dh), 0) not between 80 and 100 or coalesce(length(p_auth), 0) not between 16 and 30 then
    raise exception 'bad_keys' using errcode = '22023';
  end if;
  insert into public.push_subscriptions (user_id, household_id, endpoint, p256dh, auth, user_agent, tz, prefs)
  values (auth.uid(), p_household_id, p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300), left(p_tz, 64), coalesce(p_prefs, '{}'::jsonb))
  on conflict (endpoint) do update
     set user_id = excluded.user_id, household_id = excluded.household_id,
         p256dh = excluded.p256dh, auth = excluded.auth, user_agent = excluded.user_agent,
         tz = excluded.tz, prefs = excluded.prefs, updated_at = now(),
         disabled_at = null, failures = 0,
         -- A device moving to another person or household starts fresh: no backlog.
         created_at = case when push_subscriptions.user_id <> excluded.user_id
                             or push_subscriptions.household_id <> excluded.household_id
                           then now() else push_subscriptions.created_at end
  returning id into v_id;
  return jsonb_build_object('id', v_id);
end;
$$;

-- Stop this device (push switched off, or signing out).
create or replace function public.unregister_push_subscription(p_endpoint text)
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  delete from public.push_subscriptions where endpoint = p_endpoint and user_id = auth.uid();
$$;

-- What the server knows about THIS device, for the Settings status line.
create or replace function public.push_subscription_status(p_endpoint text)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((
    select jsonb_build_object('registered', true, 'active', s.disabled_at is null, 'last_status', s.last_status,
                              'last_success_at', s.last_success_at, 'household_id', s.household_id)
      from public.push_subscriptions s
     where s.endpoint = p_endpoint and s.user_id = auth.uid()
  ), jsonb_build_object('registered', false));
$$;

revoke all on function public.register_push_subscription(text, text, text, uuid, text, text, jsonb) from public, anon;
revoke all on function public.unregister_push_subscription(text) from public, anon;
revoke all on function public.push_subscription_status(text) from public, anon;
grant execute on function public.register_push_subscription(text, text, text, uuid, text, text, jsonb) to authenticated;
grant execute on function public.unregister_push_subscription(text) to authenticated;
grant execute on function public.push_subscription_status(text) to authenticated;

-- ── Service side (the web-push function only) ──────────────────────────────────

create or replace function public.web_push_vapid()
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select s.decrypted_secret::jsonb from vault.decrypted_secrets s where s.name = 'web_push_vapid' limit 1;
$$;

-- Store the key pair once; a second (concurrent) first use gets the stored pair back.
create or replace function public.web_push_store_vapid(p jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if p ? 'publicKey' and p ? 'privateJwk' and not exists (select 1 from vault.secrets where name = 'web_push_vapid') then
    begin
      perform vault.create_secret(p::text, 'web_push_vapid', 'Web Push VAPID key pair (generated by the web-push function)');
    exception when unique_violation then null;
    end;
  end if;
  return public.web_push_vapid();
end;
$$;

create or replace function public.web_push_cron_ok(p text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select length(coalesce(p, '')) >= 32
     and exists (select 1 from vault.decrypted_secrets s where s.name = 'web_push_cron_secret' and s.decrypted_secret = p);
$$;

-- A delivery's outcome on its device: gone (404/410) retires it; 5 failures in a row too.
create or replace function public.web_push_mark_device(p_id uuid, p_status int, p_ok boolean, p_gone boolean)
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  update public.push_subscriptions
     set last_status = p_status,
         last_success_at = case when p_ok then now() else last_success_at end,
         failures = case when p_ok then 0 else failures + 1 end,
         disabled_at = case when p_gone or (not p_ok and failures + 1 >= 5) then now() else disabled_at end
   where id = p_id;
$$;

revoke all on function public.web_push_vapid() from public, anon, authenticated;
revoke all on function public.web_push_store_vapid(jsonb) from public, anon, authenticated;
revoke all on function public.web_push_cron_ok(text) from public, anon, authenticated;
revoke all on function public.web_push_mark_device(uuid, int, boolean, boolean) from public, anon, authenticated;
grant execute on function public.web_push_vapid() to service_role;
grant execute on function public.web_push_store_vapid(jsonb) to service_role;
grant execute on function public.web_push_cron_ok(text) to service_role;
grant execute on function public.web_push_mark_device(uuid, int, boolean, boolean) to service_role;

-- ── The cron secret (generated here; never leaves the database and the function) ──
do $$
begin
  if not exists (select 1 from vault.secrets where name = 'web_push_cron_secret') then
    perform vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'web_push_cron_secret',
                                'pg_cron -> web-push dispatch');
  end if;
end;
$$;

-- ── Every 15 minutes: raise and push ────────────────────────────────────────────
create extension if not exists pg_cron;
select cron.unschedule(jobid) from cron.job where jobname = 'web-push-dispatch';
select cron.schedule('web-push-dispatch', '*/15 * * * *', $job$
  select net.http_post(
    url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/web-push?mode=dispatch',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s where s.name = 'web_push_cron_secret';
$job$);

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261004120000_learn_public_read.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.49.0 (#0) — the public Learn library is readable again by logged-out visitors.
--
-- Since ~9 Sep (v10.22's 20260909150000 revoked EXECUTE on the admin helpers from anon)
-- every anonymous read of content_items failed with
--   42501 permission denied for function is_admin
-- because the one SELECT policy was `status = 'published' OR is_admin('content')` for
-- role PUBLIC: Postgres checks EXECUTE on every function in the expression when it plans
-- the query, even when the first operand already decides the row. /learn and the sitemap
-- went dark.
--
-- Split the policy by role: anon reads published rows and nothing else (no function
-- call); a signed-in user reads published rows, and a content admin also drafts. The
-- write policies and the helper lock-down are unchanged.

begin;

drop policy if exists "anyone reads published" on public.content_items;
drop policy if exists "public reads published" on public.content_items;
drop policy if exists "signed-in reads published, admins all" on public.content_items;

create policy "public reads published" on public.content_items
  for select to anon
  using (status = 'published');

create policy "signed-in reads published, admins all" on public.content_items
  for select to authenticated
  using (status = 'published' or public.is_admin('content'));

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261005120000_ai_feedback.sql
-- ─────────────────────────────────────────────────────────────────────
-- ============================================================================
-- Pip answer feedback (owner request, 2 Oct 2026): a 👍 / 👎 under each Ask Vyact
-- reply, counted for the admin console.
--
-- PRIVACY — same rule as ai_usage: NO message content. A row is the rating, the
-- intent of the question it answered (classified on the client, as ai_usage does),
-- the reply's length and the surface. Never the question or the answer, which can
-- carry a household's figures.
--
-- One rating per answer per person: (user_id, turn_id) is unique, so changing your
-- mind updates the row and taking the rating back deletes it.
--
-- SCHEMA FIRST: this ships, and its Deploy run goes green, before the app change
-- that writes it (CLAUDE.md, "Schema ships before the app that needs it").
-- MONEY MODEL: untouched. No money table, row or amount.
-- ============================================================================

BEGIN;

create table if not exists public.ai_feedback (
  id            uuid primary key default gen_random_uuid(),
  household_id  uuid not null references public.households(id) on delete cascade,
  user_id       uuid not null default auth.uid() references auth.users(id) on delete cascade,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  surface       text not null default 'app' check (surface in ('app', 'whatsapp')),
  rating        smallint not null check (rating in (-1, 1)),
  intent        text check (char_length(intent) <= 64),
  response_len  integer check (response_len >= 0),
  -- The client's per-answer id (ChatMessage.turnId). Not content.
  turn_id       text not null check (char_length(turn_id) between 1 and 64),
  constraint ai_feedback_one_per_answer unique (user_id, turn_id)
);

create index if not exists ai_feedback_created_at_idx on public.ai_feedback (created_at desc);

alter table public.ai_feedback enable row level security;

-- A member rates answers in their own household, as themselves; reads and changes
-- only their own ratings. Admins read the aggregate through the definer function.
drop policy if exists "ai_feedback_insert" on public.ai_feedback;
create policy "ai_feedback_insert" on public.ai_feedback for insert to authenticated
  with check (public.is_member(household_id) and user_id = (select auth.uid()));

drop policy if exists "ai_feedback_update_own" on public.ai_feedback;
create policy "ai_feedback_update_own" on public.ai_feedback for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()) and public.is_member(household_id));

drop policy if exists "ai_feedback_delete_own" on public.ai_feedback;
create policy "ai_feedback_delete_own" on public.ai_feedback for delete to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists "ai_feedback_select_own" on public.ai_feedback;
create policy "ai_feedback_select_own" on public.ai_feedback for select to authenticated
  using (user_id = (select auth.uid()));

-- Admin console: totals, the helpful rate, per-intent split and the latest ratings.
-- Content-admin and up, like admin_ai_usage_summary.
create or replace function public.admin_ai_feedback_summary()
  returns jsonb language plpgsql security definer set search_path to 'public'
as $$
declare result jsonb;
begin
  if not public.is_admin('content') then
    raise exception 'forbidden: admin role required';
  end if;

  select jsonb_build_object(
    'total',  (select count(*) from ai_feedback),
    'up',     (select count(*) from ai_feedback where rating = 1),
    'down',   (select count(*) from ai_feedback where rating = -1),
    'last30', (select count(*) from ai_feedback where created_at > now() - interval '30 days'),
    'byIntent', (
      select coalesce(jsonb_agg(jsonb_build_object('intent', intent, 'up', up, 'down', down) order by up + down desc), '[]'::jsonb)
      from (
        select coalesce(intent, 'other') as intent,
               count(*) filter (where rating = 1)  as up,
               count(*) filter (where rating = -1) as down
        from ai_feedback group by 1
      ) t
    ),
    'recent', (
      select coalesce(jsonb_agg(r order by (r->>'at') desc), '[]'::jsonb)
      from (
        select jsonb_build_object('at', created_at, 'rating', rating, 'intent', intent,
                                  'surface', surface, 'responseLen', response_len) as r
        from ai_feedback order by created_at desc limit 50
      ) t
    )
  ) into result;
  return result;
end $$;

-- Not reachable without signing in (v10.22 rule: revoke the PUBLIC default anon inherits).
revoke all on function public.admin_ai_feedback_summary() from public, anon;
grant execute on function public.admin_ai_feedback_summary() to authenticated, service_role;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261006120000_whatsapp_dispatch_secret.sql
-- ─────────────────────────────────────────────────────────────────────
-- WhatsApp scheduler secret, generated in the database (2 Oct 2026).
--
-- The pg_cron jobs from 20260926120000 (alerts, weekly, bills, digest, monthly) post to
-- `whatsapp-dispatch` with `x-dispatch-secret` read from Vault `whatsapp_dispatch_secret`.
-- That secret was left for the owner to create by hand (plus the same value as the
-- function's WHATSAPP_DISPATCH_SECRET) and never was, so every run selected zero rows
-- and no scheduled WhatsApp message ever went out.
--
-- Same pattern as web push (20261003120000): the secret is generated here and never
-- leaves the database and the function. The function checks a header against Vault
-- through `whatsapp_dispatch_ok()` (service role only); WHATSAPP_DISPATCH_SECRET still
-- works if it is ever set. No person handles the value.

begin;

do $$
begin
  if not exists (select 1 from vault.secrets where name = 'whatsapp_dispatch_secret') then
    perform vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'whatsapp_dispatch_secret',
                                'pg_cron -> whatsapp-dispatch');
  end if;
end;
$$;

create or replace function public.whatsapp_dispatch_ok(p text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select length(coalesce(p, '')) >= 32
     and exists (select 1 from vault.decrypted_secrets s where s.name = 'whatsapp_dispatch_secret' and s.decrypted_secret = p);
$$;

revoke all on function public.whatsapp_dispatch_ok(text) from public, anon, authenticated;
grant execute on function public.whatsapp_dispatch_ok(text) to service_role;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261007120000_household_types_v2.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.59.0 — household types: Personal · Couple · Family · Business (owner, 4 Oct 2026).
--
--   personal  private: the owner only, no one can be invited
--   couple    the owner and ONE other member
--   family    the owner and as many members as they invite
--   business  as many members as they invite; Pip and Insights add business terms
--             (cash runway, setting aside for tax)
--
-- Retired: 'shared' (roommates / partner pool) → family, so nobody's members exceed a
-- limit. ('multi_biz' existed only in the app; the database never accepted it.)
-- A personal household that already has other members becomes couple (2) or family
-- (3+): the limit applies to new invitations, and nobody is ever removed by this.
--
-- The limits live HERE, not only in the app: a BEFORE INSERT trigger on invitations
-- (pending invitations count toward the limit) and on memberships (the accept RPC),
-- and a guard on changing the type to one the current members don't fit.

alter table public.households drop constraint if exists households_type_check;

update public.households set type = 'family' where type = 'shared';

update public.households h
   set type = case when m.n > 2 then 'family' else 'couple' end
  from (select household_id, count(*) as n from public.memberships group by household_id) m
 where m.household_id = h.id and h.type = 'personal' and m.n > 1;

alter table public.households
  add constraint households_type_check check (type in ('personal', 'couple', 'family', 'business'));

-- Members a household type has room for (owner included); null = no limit.
create or replace function public.household_member_limit(p_type text)
returns integer
language sql immutable
set search_path = public
as $$
  select case p_type when 'personal' then 1 when 'couple' then 2 else null end;
$$;

grant execute on function public.household_member_limit(text) to authenticated;

create or replace function public.enforce_household_member_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_type  text;
  v_limit integer;
  v_count integer;
begin
  select type into v_type from households where id = new.household_id;
  v_limit := household_member_limit(v_type);
  if v_limit is null then
    return new;
  end if;

  select count(*) into v_count from memberships where household_id = new.household_id;
  if tg_table_name = 'invitations' then
    v_count := v_count + (select count(*) from invitations
                           where household_id = new.household_id
                             and accepted_at is null and expires_at > now());
  end if;

  if v_count >= v_limit then
    raise exception 'HOUSEHOLD_FULL: a % household has room for % member%',
      v_type, v_limit, case when v_limit = 1 then '' else 's' end
      using errcode = 'P0001',
            hint = case v_type
                     when 'personal' then 'Personal households are private. Change the type to Couple or Family to invite someone.'
                     else 'A Couple household has room for one other person. Change the type to Family to invite more.'
                   end;
  end if;
  return new;
end;
$$;

drop trigger if exists trg_invitations_member_limit on public.invitations;
create trigger trg_invitations_member_limit
  before insert on public.invitations
  for each row execute function public.enforce_household_member_limit();

drop trigger if exists trg_memberships_member_limit on public.memberships;
create trigger trg_memberships_member_limit
  before insert on public.memberships
  for each row execute function public.enforce_household_member_limit();

-- A type the current members don't fit is refused (Family with 3 members → Couple).
create or replace function public.enforce_household_type_fits()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_limit integer;
  v_count integer;
begin
  if new.type is not distinct from old.type then
    return new;
  end if;
  v_limit := household_member_limit(new.type);
  if v_limit is null then
    return new;
  end if;
  select count(*) into v_count from memberships where household_id = new.id;
  if v_count > v_limit then
    raise exception 'HOUSEHOLD_TYPE_TOO_SMALL: this household has % members; a % household has room for %',
      v_count, new.type, v_limit
      using errcode = 'P0001';
  end if;
  return new;
end;
$$;

drop trigger if exists trg_households_type_fits on public.households;
create trigger trg_households_type_fits
  before update of type on public.households
  for each row execute function public.enforce_household_type_fits();

revoke execute on function public.enforce_household_member_limit() from public, anon, authenticated;
revoke execute on function public.enforce_household_type_fits() from public, anon, authenticated;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261008120000_w0_erase_household_data_commits.sql
-- ─────────────────────────────────────────────────────────────────────
-- W0 (audit 2026-10-04, DB-INT-05 / DB-OPS-04) — "Erase all data" always rolled back.
--
-- erase_household_data ended with an activity_log insert whose action was
-- 'erase_household_data'. activity_log.action is CHECKed to
-- ('created','updated','deleted','invited','accepted','removed','role_changed','transferred')
-- (baseline), so that last insert raised and Postgres rolled back every delete before
-- it: the button reported failure and nothing was erased, ever.
--
-- Body identical to 20260911150000_v1030_net_worth_snapshots.sql except the audit row,
-- which now uses an allowed action ('deleted') and says what happened in `changes`.

BEGIN;

create or replace function erase_household_data(h_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  caller_role text;
begin
  select role into caller_role
  from memberships
  where household_id = h_id and user_id = auth.uid()
  limit 1;

  if caller_role is null or caller_role not in ('owner', 'admin') then
    raise exception 'not authorized to erase this household''s data';
  end if;

  delete from transactions        where household_id = h_id;
  delete from budgets              where household_id = h_id;
  delete from budget_allocations   where household_id = h_id;
  delete from goals                where household_id = h_id;
  delete from debts                where household_id = h_id;
  delete from assets               where household_id = h_id;
  delete from accounts             where household_id = h_id;
  delete from recurring_schedules  where household_id = h_id;
  delete from saved_views          where household_id = h_id;
  delete from net_worth_snapshots  where household_id = h_id;
  delete from activity_log         where household_id = h_id;

  -- Onboarding baseline/reference overlay (v9.7.0) lives in households.onboarding.
  -- NOT NULL + object CHECK ⇒ reset to the empty baseline, never null (audit S6).
  update households set onboarding = '{}'::jsonb where id = h_id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id, changes)
  values (h_id, auth.uid(), 'deleted', 'household', h_id,
          jsonb_build_object('kind', 'erase_household_data', 'erased_at', now()));
end;
$$;

-- `create or replace` keeps existing grants; re-assert the v10.22 lock-down.
revoke all on function erase_household_data(uuid) from public;
revoke all on function erase_household_data(uuid) from anon;
grant execute on function erase_household_data(uuid) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261008120100_w0_learn_source_url_http_only.sql
-- ─────────────────────────────────────────────────────────────────────
-- W0 (audit 2026-10-04, FE-PUB-02 / ADM-01) — a lesson's source link must be http(s).
--
-- /learn/<slug> renders content_items.source_url as a clickable link on vyact.app.
-- HTML-escaping made "javascript:…" safe to print but still clickable, and a malformed
-- value made the page throw. The renderer now drops anything that isn't http(s)
-- (react/api/_page.js httpUrl); this CHECK stops the CMS storing one in the first place.
--
-- NOT VALID: existing rows are not re-checked here (the renderer already ignores a bad
-- one); every new insert and every update must satisfy it.

BEGIN;

alter table public.content_items
  drop constraint if exists ck_content_items_source_url_http;

alter table public.content_items
  add constraint ck_content_items_source_url_http
  check (source_url is null or source_url = '' or source_url ~* '^https?://')
  not valid;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261009120000_w1a_drop_replace_rpcs.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1a (audit 2026-10-04, DB-SEC-01 / DB-INT-01 / DB-OPS-01 / INT-CON-02 / INT-CON-04) —
-- drop the bulk replace RPCs.
--
-- Each replace_<entity>(h, rows) was SECURITY DEFINER and checked only is_member(h), then
-- deleted every row of that entity in the household and inserted whatever the caller sent.
-- RLS does not apply inside a definer function, so any member — a viewer or child included —
-- could call replace_memberships to delete every membership (the real owner's too) and
-- insert themselves as owner, or wipe the ledger, budgets, debts, assets and accounts.
--
-- They were built (TD-09, 29 May 2026) for the vanilla shell's "restore a backup", which was
-- archived on 1 Jun; the React app never had a restore screen. The only remaining caller is
-- the first-run demo seed, which runs only in local mode and never reaches the cloud. The
-- app (SupabaseAdapter.replaceAll) now refuses a cloud bulk replace. A future "restore from
-- backup" is in the backlog as a new owner-only command.

BEGIN;

drop function if exists public.replace_transactions(uuid, jsonb);
drop function if exists public.replace_budgets(uuid, jsonb);
drop function if exists public.replace_goals(uuid, jsonb);
drop function if exists public.replace_debts(uuid, jsonb);
drop function if exists public.replace_assets(uuid, jsonb);
drop function if exists public.replace_memberships(uuid, jsonb);
drop function if exists public.replace_accounts(uuid, jsonb);
drop function if exists public.replace_saved_views(uuid, jsonb);

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261009120100_w1a_ownership_rules.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1a (audit 2026-10-04, DB-SEC-02 / INT-CON-01 / INT-HH-01 / DB-INT-02 / INT-CON-07 /
-- INT-HH-06) — only the owner can transfer ownership, and a household with members always
-- keeps an owner.
--
-- 1. transfer_ownership guarded itself with
--      if (select role ... where user_id = auth.uid()) <> 'owner' then raise
--    For a caller who is NOT a member the sub-select is NULL, `NULL <> 'owner'` is NULL, the
--    IF does not fire, and the function promoted the target. A viewer could create a second
--    account (not a member) and use it to promote their own membership to owner. It also
--    never checked that the target is a member of the household.
--
-- 2. Nothing kept an owner in the household. RLS lets an owner delete their own membership
--    or demote themselves directly (leave_household's last-owner check is bypassed that
--    way), leaving members in a household nobody can manage. A DEFERRED constraint trigger
--    now refuses any statement that leaves a household which still has members without an
--    owner. It is checked at commit, so transfer_ownership (promote, then demote) and a whole
--    household being deleted (every membership goes with it) are fine.

BEGIN;

create or replace function public.transfer_ownership(h_id uuid, to_user uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null or public.role_in(h_id) is distinct from 'owner' then
    raise exception 'only_owner_can_transfer' using errcode = '42501';
  end if;
  if to_user is null or to_user = auth.uid() then
    raise exception 'invalid_transfer_target' using errcode = '22023';
  end if;
  perform 1 from memberships where household_id = h_id and user_id = to_user for update;
  if not found then
    raise exception 'not_a_member' using errcode = '22023';
  end if;
  update memberships set role = 'owner' where household_id = h_id and user_id = to_user;
  update memberships set role = 'admin' where household_id = h_id and user_id = auth.uid();
end;
$$;

revoke all on function public.transfer_ownership(uuid, uuid) from public;
revoke all on function public.transfer_ownership(uuid, uuid) from anon;
grant execute on function public.transfer_ownership(uuid, uuid) to authenticated;

create or replace function public.enforce_household_keeps_owner()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if OLD.role = 'owner' and (TG_OP = 'DELETE' or NEW.role is distinct from 'owner') then
    if exists (select 1 from memberships where household_id = OLD.household_id)
       and not exists (select 1 from memberships where household_id = OLD.household_id and role = 'owner') then
      raise exception 'household_needs_an_owner'
        using errcode = '23514',
              hint = 'Make another member the owner first (transfer ownership), then leave or change roles.';
    end if;
  end if;
  return null;
end;
$$;

revoke all on function public.enforce_household_keeps_owner() from public;
revoke all on function public.enforce_household_keeps_owner() from anon;

drop trigger if exists trg_household_keeps_owner on public.memberships;
create constraint trigger trg_household_keeps_owner
  after delete or update of role on public.memberships
  deferrable initially deferred
  for each row execute function public.enforce_household_keeps_owner();

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261009120200_w1a_retire_child_role.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1a (audit 2026-10-04, INT-HH-12; owner decision) — retire the 'child' app role.
--
-- The invite form offered "Child (own data only)", but a child could read every
-- transaction, account, debt and asset exactly like a viewer; the only child-specific rule
-- was that they could edit or delete only the transactions they created. The owner chose to
-- stop offering the role and make existing children members. (Member is broader: a member
-- can edit others' entries and manage goals, debts and assets.)
--
-- The household RELATIONSHIP label household_role = 'child' (Primary / Partner / Child /
-- Elder) is a different column and is untouched.
--
-- Old app builds may still send role = 'child' for one release, so the CHECKs keep the value
-- for now and a BEFORE trigger stores it as 'member'. A later migration can drop 'child' from
-- both CHECKs once no client sends it.

BEGIN;

create or replace function public.map_retired_child_role()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if NEW.role = 'child' then
    NEW.role := 'member';
  end if;
  return NEW;
end;
$$;

revoke all on function public.map_retired_child_role() from public;
revoke all on function public.map_retired_child_role() from anon;

drop trigger if exists trg_memberships_retired_child_role on public.memberships;
create trigger trg_memberships_retired_child_role
  before insert or update of role on public.memberships
  for each row execute function public.map_retired_child_role();

drop trigger if exists trg_invitations_retired_child_role on public.invitations;
create trigger trg_invitations_retired_child_role
  before insert or update of role on public.invitations
  for each row execute function public.map_retired_child_role();

update public.memberships set role = 'member' where role = 'child';
update public.invitations set role = 'member' where role = 'child';

-- The transaction write policies' child branches are dead now; restate them without it.
drop policy if exists "transactions_delete" on public.transactions;
create policy "transactions_delete" on public.transactions for delete using (
  role_in(household_id) in ('owner', 'admin', 'member'));

drop policy if exists "transactions_insert" on public.transactions;
create policy "transactions_insert" on public.transactions for insert with check (
  role_in(household_id) in ('owner', 'admin', 'member'));

drop policy if exists "transactions_update" on public.transactions;
create policy "transactions_update" on public.transactions for update using (
  role_in(household_id) in ('owner', 'admin', 'member'));

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261009120300_w1a_whatsapp_identity_follows_membership.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1a (audit 2026-10-04, BE-WA-01 / BE-PIP-01 / INT-HH-02) — a WhatsApp link ends when the
-- membership ends.
--
-- whatsapp_identities (phone ↔ profile ↔ household) was deleted only by an explicit unlink.
-- Leaving a household, or being removed from it, deleted the membership and nothing else, so
-- a removed partner could keep asking Pip on WhatsApp for net worth, spend and account names,
-- and kept receiving bill and spend alerts (the app's RLS cut them off; the WhatsApp path,
-- which runs with the service role, did not re-check). Writes were always safe: every write
-- RPC re-checks the membership.
--
-- Now the identity is deleted with the membership. The webhook and guardedSend also refuse a
-- link whose person is no longer a member (second layer, in the Edge code).

BEGIN;

create or replace function public.unlink_whatsapp_on_membership_delete()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  delete from public.whatsapp_identities
   where profile_id = OLD.user_id and household_id = OLD.household_id;
  return null;
end;
$$;

revoke all on function public.unlink_whatsapp_on_membership_delete() from public;
revoke all on function public.unlink_whatsapp_on_membership_delete() from anon;

drop trigger if exists trg_membership_delete_unlinks_whatsapp on public.memberships;
create trigger trg_membership_delete_unlinks_whatsapp
  after delete on public.memberships
  for each row execute function public.unlink_whatsapp_on_membership_delete();

-- Links that already outlived their membership.
delete from public.whatsapp_identities wi
 where not exists (
   select 1 from public.memberships m
    where m.household_id = wi.household_id and m.user_id = wi.profile_id);

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261009120400_w1a_admin_roles_no_ledger_reads.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1a (audit 2026-10-04, ADM-03 / D24) — platform admins no longer read household ledgers
-- row by row.
--
-- The domain-table SELECT policies were `is_member(household_id) or is_admin('roles')`, so a
-- 'roles' (or 'super') admin could select every family's transactions, accounts, debts,
-- assets, budgets, recurring bills and notifications. No admin page needs that: every admin
-- screen reads households / memberships / activity_log directly or calls a SECURITY DEFINER
-- RPC (admin_dashboard_kpis, admin_weekly_trend, admin_list_users, admin_ai_usage_summary,
-- admin_ai_feedback_summary), which RLS does not affect. Admin access is password-only by the
-- owner's decision (no 2FA), so the blast radius of one admin password matters.
--
-- Kept for now (admin pages read them): households, memberships, profiles, subscriptions,
-- activity_log. activity_log stores row images and is the next thing to narrow (ADM-04).

BEGIN;

-- Sweep: drop EVERY select-only policy on these tables that mentions is_admin, not just the
-- ones the migrations name. Production holds objects no migration creates (see
-- docs/DEVELOPER_INPUTS.md Q1), so a name list could leave a prod-only admin read in place.
-- Only SELECT policies are touched: a FOR ALL policy also carries members' writes.
do $$
declare p record;
begin
  for p in
    select schemaname, tablename, policyname from pg_policies
     where schemaname = 'public'
       and tablename in ('transactions', 'budgets', 'goals', 'debts', 'assets', 'accounts',
                         'recurring_schedules', 'budget_allocations', 'notifications', 'saved_views')
       and cmd = 'SELECT'
       and qual ilike '%is_admin%'
  loop
    execute format('drop policy %I on %I.%I', p.policyname, p.schemaname, p.tablename);
  end loop;
end $$;

drop policy if exists "transactions_read" on public.transactions;
create policy "transactions_read" on public.transactions for select to authenticated
  using (is_member(household_id));

drop policy if exists "budgets_read" on public.budgets;
create policy "budgets_read" on public.budgets for select to authenticated
  using (is_member(household_id));

drop policy if exists "goals_read" on public.goals;
create policy "goals_read" on public.goals for select to authenticated
  using (is_member(household_id));

drop policy if exists "debts_read" on public.debts;
create policy "debts_read" on public.debts for select to authenticated
  using (is_member(household_id));

drop policy if exists "assets_read" on public.assets;
create policy "assets_read" on public.assets for select to authenticated
  using (is_member(household_id));

drop policy if exists "accounts_read" on public.accounts;
create policy "accounts_read" on public.accounts for select to authenticated
  using (is_member(household_id));

drop policy if exists "recurring_read" on public.recurring_schedules;
create policy "recurring_read" on public.recurring_schedules for select to authenticated
  using (is_member(household_id));

drop policy if exists balloc_read on public.budget_allocations;
create policy balloc_read on public.budget_allocations for select to authenticated
  using (is_member(household_id));

drop policy if exists "notif_read" on public.notifications;
create policy "notif_read" on public.notifications for select to authenticated
  using (is_member(household_id));

drop policy if exists "saved_views_self" on public.saved_views;
create policy "saved_views_self" on public.saved_views for select to authenticated
  using (user_id = (select auth.uid()));

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261010120000_w1b_account_purge.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1b (audit 2026-10-04, INT-HH-03 / BE-FN-01 / BE-FN-02 / BE-FN-03 / BE-FN-04 / XC-PRV-04 /
-- XC-PRV-06 / DB-INT-06 / DB-OPS-05 / FE-PLT-06) — account deletion that actually happens, in
-- one step, and only after a recent sign-in.
--
-- What was wrong:
--   • delete-account ran a non-atomic chain of deletes from the Edge Function, then deleted the
--     profile and the auth user. transactions.created_by, activity_log.actor_id,
--     invitations.invited_by, households.created_by and shared_split_shares.settled_user_id
--     reference auth.users with NO ACTION, so anyone who had ever written into a household they
--     did not own could not be deleted: the data was already erased, the login stayed.
--   • The "30-day undo" was never executed by anything, and signing in silently cancelled it.
--   • An owner's deletion deleted co-members' households outright (BE-FN-04).
--   • The email-code check before deleting or erasing was enforced only in the browser.
--   • WhatsApp message text kept the person's words after their profile was deleted
--     (profile_id ON DELETE SET NULL).
--
-- Now (owner decisions D22, D25):
--   • Deletion is IMMEDIATE (no grace period) and runs in ONE transaction: purge_account().
--   • An owner whose household has other members and no other owner must transfer ownership
--     first: 'transfer_required'. Co-members never lose their household.
--   • The user-referencing FKs no longer block deletion: history stays with the household and
--     simply stops naming the deleted person (SET NULL); invitations they sent go with them.
--   • Erase and delete require a sign-in within the last 10 minutes, read from the JWT's `amr`
--     claim (the email-code step's verifyOtp issues a fresh session; a stolen idle session
--     does not pass).

BEGIN;

-- ── 1. FKs to users: never block a deletion ─────────────────────────────────────────────
-- Drop whatever FK exists on each column (production names may differ from the baseline's),
-- then add one with the intended ON DELETE.
do $$
declare r record;
begin
  for r in
    select c.conname, c.conrelid::regclass::text as tbl
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
     where c.contype = 'f' and array_length(c.conkey, 1) = 1
       and (c.conrelid::regclass::text, a.attname::text) in (
         ('households', 'created_by'), ('invitations', 'invited_by'), ('transactions', 'created_by'),
         ('activity_log', 'actor_id'), ('shared_split_shares', 'settled_user_id'),
         ('whatsapp_inbound_messages', 'profile_id'), ('whatsapp_inbound_messages', 'household_id'))
  loop
    execute format('alter table %s drop constraint %I', r.tbl, r.conname);
  end loop;
end $$;

-- households.created_by was NOT NULL; a household outlives its creator (it stays with its
-- other members), so it must be able to stop naming them.
alter table public.households alter column created_by drop not null;
alter table public.households add constraint households_created_by_fkey
  foreign key (created_by) references auth.users(id) on delete set null;
alter table public.invitations add constraint invitations_invited_by_fkey
  foreign key (invited_by) references auth.users(id) on delete cascade;
alter table public.transactions add constraint transactions_created_by_fkey
  foreign key (created_by) references auth.users(id) on delete set null;
alter table public.activity_log add constraint activity_log_actor_id_fkey
  foreign key (actor_id) references auth.users(id) on delete set null;
alter table public.shared_split_shares add constraint shared_split_shares_settled_user_id_fkey
  foreign key (settled_user_id) references auth.users(id) on delete set null;
-- WhatsApp message rows hold the person's words and phone number: they go with the person
-- and with the household (XC-PRV-07).
alter table public.whatsapp_inbound_messages add constraint whatsapp_inbound_messages_profile_id_fkey
  foreign key (profile_id) references public.profiles(id) on delete cascade;
alter table public.whatsapp_inbound_messages add constraint whatsapp_inbound_messages_household_id_fkey
  foreign key (household_id) references public.households(id) on delete cascade;

-- ── 2. Recent sign-in, checked on the server ───────────────────────────────────────────
create or replace function public.recently_reauthenticated(p_max_age_seconds int default 600)
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select exists (
    select 1
      from jsonb_array_elements(coalesce(auth.jwt() -> 'amr', '[]'::jsonb)) a
     where jsonb_typeof(a -> 'timestamp') = 'number'
       and (a ->> 'timestamp')::bigint >= extract(epoch from now())::bigint - p_max_age_seconds);
$$;

revoke all on function public.recently_reauthenticated(int) from public;
revoke all on function public.recently_reauthenticated(int) from anon;
grant execute on function public.recently_reauthenticated(int) to authenticated, service_role;

-- ── 3. Erase all household data: recent sign-in required; WhatsApp messages go too ─────
-- Body as 20261008120000 (W0) plus the re-auth check and the household's WhatsApp messages.
create or replace function erase_household_data(h_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  caller_role text;
begin
  select role into caller_role
  from memberships
  where household_id = h_id and user_id = auth.uid()
  limit 1;

  if caller_role is null or caller_role not in ('owner', 'admin') then
    raise exception 'not authorized to erase this household''s data';
  end if;
  if not public.recently_reauthenticated() then
    raise exception 'reauth_required' using errcode = '42501',
      hint = 'Confirm with the emailed code, then erase within 10 minutes.';
  end if;

  delete from transactions        where household_id = h_id;
  delete from budgets              where household_id = h_id;
  delete from budget_allocations   where household_id = h_id;
  delete from goals                where household_id = h_id;
  delete from debts                where household_id = h_id;
  delete from assets               where household_id = h_id;
  delete from accounts             where household_id = h_id;
  delete from recurring_schedules  where household_id = h_id;
  delete from saved_views          where household_id = h_id;
  delete from net_worth_snapshots  where household_id = h_id;
  delete from whatsapp_inbound_messages where household_id = h_id;
  delete from activity_log         where household_id = h_id;

  update households set onboarding = '{}'::jsonb where id = h_id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id, changes)
  values (h_id, auth.uid(), 'deleted', 'household', h_id,
          jsonb_build_object('kind', 'erase_household_data', 'erased_at', now()));
end;
$$;

revoke all on function erase_household_data(uuid) from public;
revoke all on function erase_household_data(uuid) from anon;
grant execute on function erase_household_data(uuid) to authenticated;

-- ── 4. The purge: one transaction, service role only ───────────────────────────────────
create or replace function public.purge_account(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email text;
  blocked uuid[];
  sole uuid[];
  n_households int := 0;
  n_memberships int := 0;
begin
  if p_user_id is null then
    raise exception 'invalid_user' using errcode = '22023';
  end if;

  -- D22: an owner may not leave members behind without an owner.
  select array_agg(m.household_id) into blocked
    from memberships m
   where m.user_id = p_user_id and m.role = 'owner'
     and exists (select 1 from memberships o where o.household_id = m.household_id and o.user_id <> p_user_id)
     and not exists (select 1 from memberships o
                      where o.household_id = m.household_id and o.user_id <> p_user_id and o.role = 'owner');
  if blocked is not null then
    raise exception 'transfer_required' using errcode = 'P0001', detail = array_to_string(blocked, ',');
  end if;

  -- Households where they are the only member: the household and everything in it goes
  -- (every household-scoped table cascades from households).
  select array_agg(m.household_id) into sole
    from memberships m
   where m.user_id = p_user_id
     and not exists (select 1 from memberships o where o.household_id = m.household_id and o.user_id <> p_user_id);
  if sole is not null then
    delete from households where id = any (sole);
    get diagnostics n_households = row_count;
  end if;

  -- Shared households: only their membership goes; the household keeps its history.
  delete from memberships where user_id = p_user_id;
  get diagnostics n_memberships = row_count;

  -- Personal rows that would otherwise wait for the auth delete (or outlive it).
  delete from whatsapp_inbound_messages where profile_id = p_user_id;
  delete from whatsapp_identities        where profile_id = p_user_id;
  delete from whatsapp_pending_turns     where profile_id = p_user_id;
  delete from whatsapp_verification_otps where profile_id = p_user_id;
  delete from whatsapp_preferences       where profile_id = p_user_id;
  delete from push_subscriptions         where user_id = p_user_id;

  select email into v_email from auth.users where id = p_user_id;
  if v_email is not null then
    delete from invitations where accepted_at is null and lower(invited_email) = lower(v_email);
  end if;

  delete from profiles where id = p_user_id;

  return jsonb_build_object('status', 'purged', 'households_deleted', n_households,
                            'memberships_removed', n_memberships);
end;
$$;

revoke all on function public.purge_account(uuid) from public;
revoke all on function public.purge_account(uuid) from anon;
revoke all on function public.purge_account(uuid) from authenticated;
grant execute on function public.purge_account(uuid) to service_role;

-- ── 5. The 30-day schedule is gone ──────────────────────────────────────────────────────
-- Nothing ever executed it. reactivate_my_account still clears a legacy hold on sign-in.
drop function if exists public.request_account_deletion();
comment on column public.profiles.deletion_scheduled_for is
  'Legacy (until v10.63.0): the 30-day schedule was never executed and was removed. Deletion is immediate (purge_account).';

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261010120100_w1b_whatsapp_retention.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1b (audit 2026-10-04, XC-PRV-07 / BE-WA-10; owner decision D26) — WhatsApp messages are
-- kept for 90 days.
--
-- whatsapp_inbound_messages holds every message in both directions: the person's words, their
-- phone number (in payload) and errors. Nothing ever removed a row. From now on rows older than
-- 90 days are deleted every day (the schedule is in 20261010120200). Idempotency needs only
-- recent message ids (Meta retries within hours), so whole rows can go.
--
-- Expired OTPs and long-dead pending questions go too; neither is useful after a day.

BEGIN;

create or replace function public.purge_old_whatsapp_messages(p_days int default 90)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  n_messages int;
  n_otps int;
  n_turns int;
begin
  if p_days is null or p_days < 1 then
    raise exception 'invalid_retention_days' using errcode = '22023';
  end if;
  delete from whatsapp_inbound_messages where created_at < now() - make_interval(days => p_days);
  get diagnostics n_messages = row_count;
  delete from whatsapp_verification_otps where expires_at < now() - interval '1 day';
  get diagnostics n_otps = row_count;
  delete from whatsapp_pending_turns where expires_at < now() - interval '1 day';
  get diagnostics n_turns = row_count;
  return jsonb_build_object('messages', n_messages, 'otps', n_otps, 'pending_turns', n_turns);
end;
$$;

revoke all on function public.purge_old_whatsapp_messages(int) from public;
revoke all on function public.purge_old_whatsapp_messages(int) from anon;
revoke all on function public.purge_old_whatsapp_messages(int) from authenticated;
grant execute on function public.purge_old_whatsapp_messages(int) to service_role;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261010120200_w1b_whatsapp_retention_schedule.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1b (audit 2026-10-04, D26) — run the 90-day WhatsApp retention every day at 02:40 UTC
-- (08:10 IST, after the overnight jobs). Kept apart from the function so the function can be
-- tested without pg_cron.

create extension if not exists pg_cron;
select cron.unschedule(jobid) from cron.job where jobname = 'whatsapp-retention';
select cron.schedule('whatsapp-retention', '40 2 * * *', $job$
  select public.purge_old_whatsapp_messages(90);
$job$);

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261011120000_w1c_split_email_guard.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1c (v10.64.0) — audit 2026-10-04 BE-FN-06 / INT-HH-11 / XC-PRV-13: split email can no longer
-- be used as a relay.
--
-- Before this, any signed-in user could create a split with any currency text and any number of
-- participant emails, then call send-split-email 'shared' as often as they liked: every call
-- mailed every participant again, from hello@vyact.app, with no record and no cap.
--
--   1. shared_splits.currency is three capital letters (an ISO-4217 code), like every other
--      currency in the app. NOT VALID: new and edited rows are checked; an odd legacy row does
--      not abort the deploy (the email templates drop a malformed code anyway).
--   2. split_email_log: one row per (share, event) ever sent. The unique key IS the dedupe —
--      a second 'shared' call for the same split mails only participants added since.
--      It holds ids and a time, never an address or a body.
--   3. claim_split_emails(): the only way to send. Under a per-sender lock it counts the
--      sender's emails in the last 24 hours, claims at most the remaining room among shares not
--      yet mailed for that event, and returns the claimed share ids. The Edge Function mails
--      exactly those and releases (deletes) a claim whose delivery failed, so it can be retried.
--   4. Shares that existed before this migration are recorded as already mailed for the events
--      they have been through, so the first edit after release does not re-mail old splits.
--
-- Service role only. Members never read or write the log.

update public.shared_splits
   set currency = upper(btrim(currency))
 where currency is distinct from upper(btrim(currency));

alter table public.shared_splits drop constraint if exists ck_shared_split_currency;
alter table public.shared_splits
  add constraint ck_shared_split_currency check (currency ~ '^[A-Z]{3}$') not valid;

create table if not exists public.split_email_log (
  id              bigint generated always as identity primary key,
  sender_user_id  uuid references auth.users(id) on delete cascade,
  split_id        uuid not null references public.shared_splits(id) on delete cascade,
  share_id        uuid not null references public.shared_split_shares(id) on delete cascade,
  event           text not null check (event in ('shared', 'settled', 'closed')),
  created_at      timestamptz not null default now(),
  constraint uq_split_email_once unique (share_id, event)
);

create index if not exists split_email_log_sender_idx on public.split_email_log (sender_user_id, created_at);
create index if not exists split_email_log_split_idx on public.split_email_log (split_id);

alter table public.split_email_log enable row level security;
revoke all on table public.split_email_log from public, anon, authenticated;
grant select, insert, delete on table public.split_email_log to service_role;

-- 4. Existing shares: treat what already happened as already mailed (dated when it happened, so it
--    does not count against anyone's cap today).
insert into public.split_email_log (sender_user_id, split_id, share_id, event, created_at)
select sp.owner_user_id, sp.id, sh.id, 'shared', sh.created_at
  from public.shared_split_shares sh
  join public.shared_splits sp on sp.id = sh.split_id
on conflict (share_id, event) do nothing;

insert into public.split_email_log (sender_user_id, split_id, share_id, event, created_at)
select sh.settled_user_id, sh.split_id, sh.id, 'settled', coalesce(sh.paid_at, sh.created_at)
  from public.shared_split_shares sh
 where sh.paid
on conflict (share_id, event) do nothing;

insert into public.split_email_log (sender_user_id, split_id, share_id, event, created_at)
select sp.owner_user_id, sp.id, sh.id, 'closed', sp.closed_at
  from public.shared_split_shares sh
  join public.shared_splits sp on sp.id = sh.split_id
 where sp.closed_at is not null
on conflict (share_id, event) do nothing;

create or replace function public.claim_split_emails(
  p_sender     uuid,
  p_split      uuid,
  p_event      text,
  p_share_ids  uuid[],
  p_daily_cap  int
) returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_used     int;
  v_room     int;
  v_wanted   int;
  v_claimed  uuid[];
begin
  if p_sender is null or p_split is null then
    raise exception 'invalid_claim' using errcode = '22023';
  end if;
  if p_event not in ('shared', 'settled', 'closed') then
    raise exception 'bad_event' using errcode = '22023';
  end if;
  if p_daily_cap is null or p_daily_cap < 0 then
    raise exception 'invalid_cap' using errcode = '22023';
  end if;

  -- One sender at a time: two parallel calls cannot both see the same room under the cap.
  perform pg_advisory_xact_lock(hashtextextended('split_email:' || p_sender::text, 0));

  select count(*) into v_used
    from public.split_email_log
   where sender_user_id = p_sender
     and created_at > now() - interval '24 hours';
  v_room := greatest(p_daily_cap - v_used, 0);

  select count(*) into v_wanted
    from public.shared_split_shares s
   where s.split_id = p_split
     and s.id = any(coalesce(p_share_ids, '{}'))
     and not exists (select 1 from public.split_email_log l where l.share_id = s.id and l.event = p_event);

  with pick as (
    select s.id
      from public.shared_split_shares s
     where s.split_id = p_split
       and s.id = any(coalesce(p_share_ids, '{}'))
       and not exists (select 1 from public.split_email_log l where l.share_id = s.id and l.event = p_event)
     order by s.created_at, s.id
     limit v_room
  ), ins as (
    insert into public.split_email_log (sender_user_id, split_id, share_id, event)
    select p_sender, p_split, pick.id, p_event from pick
    on conflict (share_id, event) do nothing
    returning share_id
  )
  select coalesce(array_agg(share_id), '{}') into v_claimed from ins;

  return jsonb_build_object(
    'claimed', to_jsonb(v_claimed),
    'limited', greatest(v_wanted - coalesce(array_length(v_claimed, 1), 0), 0)
  );
end;
$$;

revoke all on function public.claim_split_emails(uuid, uuid, text, uuid[], int) from public, anon, authenticated;
grant execute on function public.claim_split_emails(uuid, uuid, text, uuid[], int) to service_role;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261011120100_w1c_ai_usage_source.sql
-- ─────────────────────────────────────────────────────────────────────
-- W1c (v10.64.0) — audit 2026-10-04 BE-PIP-03 / DB-SEC-11: the AI spend gate is the server's.
--
-- Before this, any member could insert an ai_usage row with any cost_usd, tokens, provider, model
-- and outcome (the INSERT policy checks only household membership and user_id). The admin
-- Intelligence page sums cost_usd over every row, so one devtools insert could put $99,999 on the
-- §9 spend gate. And reserve_ai_usage() counted every backend='llm' row, so the app's own
-- per-question analytics row used up a third of each person's daily model-call cap.
--
--   1. ai_usage.source: 'gateway' (written by the service role: the ask-vyact gateway, the
--      WhatsApp assistant, reserve_ai_usage) or 'client' (the app's analytics row).
--      Existing rows are labelled once: a reservation, a row with a provider, or a row without
--      the client's intent/length fields is the gateway's.
--   2. A BEFORE INSERT trigger: a row written by a signed-in client is always 'client', and its
--      metering fields (provider, model, tokens, cost, tool calls) are cleared; it can never be
--      'reserved'. The client keeps what it legitimately records: intent, sentiment, length,
--      backend, tier, outcome, latency.
--   3. reserve_ai_usage() counts only gateway rows, and marks its reservation as one.
--
-- admin_ai_usage_summary() is unchanged: cost and token sums now only ever see server values,
-- because client rows carry none.

alter table public.ai_usage add column if not exists source text;

update public.ai_usage
   set source = case
     when outcome = 'reserved' or provider is not null or (intent is null and message_len is null) then 'gateway'
     else 'client'
   end
 where source is null;

alter table public.ai_usage drop constraint if exists ai_usage_source_chk;
alter table public.ai_usage add constraint ai_usage_source_chk check (source in ('client', 'gateway'));

create or replace function public.ai_usage_stamp_source()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if current_user in ('authenticated', 'anon') then
    new.source            := 'client';
    new.provider          := null;
    new.model             := null;
    new.prompt_tokens     := null;
    new.completion_tokens := null;
    new.cost_usd          := null;
    new.tool_calls        := null;
    if new.outcome = 'reserved' then new.outcome := null; end if;
  else
    new.source := coalesce(new.source, 'gateway');
  end if;
  return new;
end $$;

drop trigger if exists trg_ai_usage_stamp_source on public.ai_usage;
create trigger trg_ai_usage_stamp_source
  before insert on public.ai_usage
  for each row execute function public.ai_usage_stamp_source();

alter table public.ai_usage alter column source set not null;

create index if not exists ai_usage_gateway_user_ts_idx
  on public.ai_usage (user_id, ts) where source = 'gateway';

create or replace function public.reserve_ai_usage(
  p_user_id      uuid,
  p_household_id uuid,
  p_surface      text,
  p_cap          int
) returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_count int;
  v_id    uuid;
begin
  -- Serialise this user's quota decisions on their profile row (audit A2).
  perform 1 from public.profiles where id = p_user_id for update;

  -- W1c: only the server's own rows count. The app's analytics row no longer uses up the cap.
  select count(*) into v_count
    from public.ai_usage
   where user_id = p_user_id
     and source = 'gateway'
     and backend = 'llm'
     and ts >= now() - interval '24 hours';

  if v_count >= p_cap then
    raise exception 'quota_exceeded' using errcode = '42901';
  end if;

  insert into public.ai_usage (user_id, household_id, surface, backend, outcome, ts, source)
  values (p_user_id, p_household_id, p_surface, 'llm', 'reserved', now(), 'gateway')
  returning id into v_id;
  return v_id;
end $$;

revoke all on function public.reserve_ai_usage(uuid, uuid, text, int) from public, anon, authenticated;
grant execute on function public.reserve_ai_usage(uuid, uuid, text, int) to service_role;

comment on column public.ai_usage.source is
  'W1c — gateway: written by the service role (metering is trustworthy); client: the app''s analytics row (metering fields always null).';

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261012120000_w3a_household_timezone.sql
-- ─────────────────────────────────────────────────────────────────────
-- W3a (v10.65.0) — audit 2026-10-04 INT-TZC-03/04/05, INT-PAR-04, BE-FN-08. Owner decision D12:
-- "today" is LOCAL — the device's day in the app, the HOUSEHOLD's day on the server.
--
-- The server (WhatsApp, the scheduler, web push) has no device to ask, and its clock is UTC, so a
-- household now carries its zone:
--
--   1. households.timezone (IANA name, NOT NULL, default 'Asia/Kolkata' — every existing household
--      starts on India time, which is what the server assumed until now) and timezone_set_at
--      (null = still the default, nobody has set it).
--   2. A trigger validates every zone against pg_timezone_names, and a new household takes its
--      creator's zone from the signup metadata when the app sent one.
--   3. set_household_timezone(): the owner's device stamps its own zone, once (p_only_if_unset),
--      so a household created through Google or a magic link — which carry no metadata — still
--      ends up on the owner's real zone.
--   4. The scheduler's daily and weekly jobs run every 30 minutes instead of at one fixed UTC time
--      meant as IST; the dispatcher picks the households whose LOCAL time is in the job's slot
--      (bills 09:00, digest 20:30, monthly 09:00, weekly Sunday 18:00). Their dedupe slots already
--      make a repeated run send nothing twice. IST households see no change in timing.

alter table public.households add column if not exists timezone text not null default 'Asia/Kolkata';
alter table public.households add column if not exists timezone_set_at timestamptz;

create or replace function public.is_valid_timezone(p text)
returns boolean
language sql
stable
set search_path = public, pg_catalog
as $$
  select p is not null and exists (select 1 from pg_catalog.pg_timezone_names where name = p);
$$;

create or replace function public.households_timezone()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_meta text;
begin
  -- A new household takes its creator's device zone when the signup sent one.
  if tg_op = 'INSERT' and new.timezone_set_at is null and new.created_by is not null then
    select u.raw_user_meta_data ->> 'timezone' into v_meta from auth.users u where u.id = new.created_by;
    if public.is_valid_timezone(v_meta) then
      new.timezone := v_meta;
      new.timezone_set_at := now();
    end if;
  end if;
  if not public.is_valid_timezone(new.timezone) then
    raise exception 'invalid_timezone' using errcode = '22023', detail = coalesce(new.timezone, 'null');
  end if;
  return new;
end $$;

drop trigger if exists trg_households_timezone on public.households;
create trigger trg_households_timezone
  before insert or update of timezone on public.households
  for each row execute function public.households_timezone();

create or replace function public.set_household_timezone(
  p_household     uuid,
  p_tz            text,
  p_only_if_unset boolean default true
) returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tz text;
begin
  if auth.uid() is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  if public.role_in(p_household) is distinct from 'owner' then
    raise exception 'only_owner_sets_timezone' using errcode = '42501';
  end if;
  if not public.is_valid_timezone(p_tz) then
    raise exception 'invalid_timezone' using errcode = '22023';
  end if;
  update public.households
     set timezone = p_tz, timezone_set_at = now()
   where id = p_household
     and (not p_only_if_unset or timezone_set_at is null)
  returning timezone into v_tz;
  if v_tz is null then
    select timezone into v_tz from public.households where id = p_household;
  end if;
  return v_tz;
end $$;

revoke all on function public.set_household_timezone(uuid, text, boolean) from public, anon;
grant execute on function public.set_household_timezone(uuid, text, boolean) to authenticated, service_role;
revoke all on function public.households_timezone() from public, anon, authenticated;

-- 4. The scheduler's slots follow each household's own clock (see whatsapp-dispatch).
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.alter_job(jobid, schedule := '0,30 * * * *')
       from cron.job
      where jobname in ('whatsapp-dispatch-weekly', 'whatsapp-dispatch-bills',
                        'whatsapp-dispatch-digest', 'whatsapp-dispatch-monthly');
  end if;
end $$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261013120000_w3b_one_currency.sql
-- ─────────────────────────────────────────────────────────────────────
-- W3b (v10.66.0) — audit 2026-10-04 INT-TZC-02/07, INT-PAR-01, FE-MNY-09, DB-INT-12. Owner decision D14:
-- one currency per household, never converted; a currency change only changes the symbol; a row still
-- labelled with an older currency counts at face value (its label is ignored, never rewritten).
--
--   1. Every new or edited transaction, budget, goal, debt and asset is stamped with the household's
--      currency, as accounts already are (r1). So no writer — the app, WhatsApp, a recurring post —
--      can label a row with a currency the household does not use. Existing rows are left as they are.
--   2. record_loan_payment checks the HOUSEHOLD's currency. It compared the payment with the debt's own
--      label and the loan account's, and a currency change relabels accounts but not debts, so every
--      EMI after a change failed with invalid_payment / loan_account_invalid. Otherwise unchanged
--      (body copied from 20260909140000; it is rewritten in D19).
--
-- The exchange_rates table stays readable for now; the app no longer reads or writes it. It is dropped
-- in a later release, after the app that stops using it is live (removals go app first).

create or replace function public.stamp_household_currency()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare hc text;
begin
  select base_currency into hc from public.households where id = new.household_id;
  if hc is not null then
    new.currency := hc;
  end if;
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['transactions', 'budgets', 'goals', 'debts', 'assets'] loop
    if exists (select 1 from information_schema.columns
                where table_schema = 'public' and table_name = t and column_name = 'currency') then
      execute format('drop trigger if exists trg_%s_household_currency on public.%I', t, t);
      execute format('create trigger trg_%s_household_currency before insert or update on public.%I
                        for each row execute function public.stamp_household_currency()', t, t);
    end if;
  end loop;
end $$;

create or replace function public.record_loan_payment(
  p_operation_id uuid, p_debt_id uuid, p_funding_account_id uuid,
  p_amount numeric, p_currency text, p_date date,
  p_interest numeric, p_principal numeric, p_member_id uuid default null,
  p_description text default null, p_new_balance numeric default null,
  p_new_remaining_months integer default null, p_new_minimum_payment numeric default null,
  p_payment_log_entry jsonb default null
) returns jsonb
language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  debt_row public.debts%rowtype;
  payment_event public.loan_payment_events%rowtype;
  account_row public.accounts%rowtype;
  actor_id uuid := auth.uid();
  member_id uuid;
  request_body jsonb;
  strategy text := p_payment_log_entry->>'partChoice';
  payment_date date := coalesce(p_date, current_date);
  payment_description text;
  currency_scale numeric;
  interest_units numeric;
  interest_amount numeric;
  principal_amount numeric;
  balance_after numeric;
  remaining integer;
  minimum_after numeric;
  monthly_rate numeric;
  payment_log jsonb;
  split_details jsonb;
  is_extra boolean;
  expense_id uuid;
  transfer_id uuid;
  household_currency text;
begin
  select * into debt_row from public.debts
    where id = p_debt_id and deleted_at is null for update;
  if not found or actor_id is null then
    raise exception 'not_authorized' using errcode = '42501';
  end if;
  select id into member_id from public.memberships
    where household_id = debt_row.household_id and user_id = actor_id
      and role in ('owner', 'admin', 'member') for share;
  if not found then raise exception 'not_authorized' using errcode = '42501'; end if;
  -- W3b (D14): one currency per household. The payment is in the HOUSEHOLD's currency; the debt's
  -- own label may be older (a debt saved before a currency change) and is not read.
  select base_currency into household_currency from public.households where id = debt_row.household_id;

  if p_operation_id is null or p_date is null or p_amount is null
      or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount <= 0
      or p_currency is distinct from household_currency
      or coalesce(debt_row.direction, 'owed_by_me') <> 'owed_by_me' then
    raise exception 'invalid_payment' using errcode = '22023';
  end if;
  if strategy is not null and strategy not in ('reduce_tenure','reduce_emi','apply_advance') then
    raise exception 'invalid_strategy' using errcode = '22023';
  end if;
  payment_description := coalesce(nullif(p_description,''), debt_row.name || ' EMI');
  request_body := jsonb_build_object('actor', actor_id, 'debt', p_debt_id,
    'funding', p_funding_account_id, 'amount', p_amount, 'currency', p_currency,
    'date', payment_date, 'strategy', strategy, 'member', p_member_id,
    'description', payment_description);

  select * into payment_event from public.loan_payment_events where operation_id = p_operation_id;
  if found then
    if payment_event.household_id <> debt_row.household_id
        or payment_event.debt_id <> p_debt_id
        or payment_event.request is distinct from request_body then
      raise exception 'operation_id_reused' using errcode = '22023';
    end if;
    select * into account_row from public.accounts where id = payment_event.loan_account_id;
    return jsonb_build_object('status','duplicate', 'debt', to_jsonb(debt_row),
      'loan_account', to_jsonb(account_row),
      'expense_txn_id', payment_event.expense_txn_id, 'transfer_txn_id', payment_event.transfer_txn_id,
      'loan_account_id', payment_event.loan_account_id,
      'transactions', (select coalesce(jsonb_agg(to_jsonb(txn)), '[]'::jsonb)
        from public.transactions txn where id in (payment_event.expense_txn_id, payment_event.transfer_txn_id)));
  end if;

  perform 1 from public.accounts where id = p_funding_account_id
    and household_id = debt_row.household_id and kind in ('cash','bank')
    and currency = p_currency and deleted_at is null and not is_archived for share;
  if not found then raise exception 'funding_account_invalid' using errcode = '22023'; end if;
  if p_member_id is not null then
    perform 1 from public.memberships where id = p_member_id and household_id = debt_row.household_id for share;
    if not found then raise exception 'member_invalid' using errcode = '22023'; end if;
    member_id := p_member_id;
  end if;
  if p_currency not in ('USD','EUR','GBP','INR','JPY','AUD','CAD','CHF','CNY','AED','SGD','BRL') then
    raise exception 'unsupported_currency' using errcode = '22023';
  end if;
  currency_scale := case when p_currency = 'JPY' then 1 else 100 end;
  if p_amount * currency_scale <> trunc(p_amount * currency_scale) then
    raise exception 'invalid_precision' using errcode = '22023';
  end if;
  monthly_rate := debt_row.interest_rate / 1200;
  interest_units := round(debt_row.current_balance * currency_scale) * round(monthly_rate, 12);
  interest_amount := (case when interest_units - trunc(interest_units) = 0.5
    then trunc(interest_units) + mod(trunc(interest_units), 2)
    else round(interest_units) end) / currency_scale;
  if p_amount < interest_amount or p_amount > debt_row.current_balance + interest_amount then
    raise exception 'payment_out_of_range' using errcode = '22023';
  end if;
  principal_amount := p_amount - interest_amount;
  balance_after := debt_row.current_balance - principal_amount;
  if p_new_balance is distinct from balance_after or p_interest is distinct from interest_amount
      or p_principal is distinct from principal_amount then
    raise exception 'payment_state_changed_refresh_required' using errcode = '40001';
  end if;

  remaining := greatest(0, coalesce((debt_row.extras->>'remainingMonths')::integer,
    (debt_row.extras->>'tenureMonths')::integer, 0) - 1);
  minimum_after := debt_row.minimum_payment;
  is_extra := p_amount > minimum_after * 1.05;
  if balance_after = 0 then
    remaining := 0;
  elsif is_extra and strategy = 'reduce_tenure' then
    if minimum_after <= monthly_rate * balance_after then
      raise exception 'non_amortizing_payment' using errcode = '22023';
    end if;
    remaining := case when monthly_rate = 0 then ceil(balance_after / minimum_after)
      else ceil(-ln(1 - monthly_rate * balance_after / minimum_after) / ln(1 + monthly_rate)) end;
  elsif is_extra and strategy = 'reduce_emi' then
    if remaining < 1 then raise exception 'invalid_remaining_tenure' using errcode = '22023'; end if;
    minimum_after := case when monthly_rate = 0 then balance_after / remaining
      else balance_after * monthly_rate / (1 - power(1 + monthly_rate, -remaining)) end;
  elsif is_extra and strategy = 'apply_advance' then
    if minimum_after <= 0 then raise exception 'invalid_minimum_payment' using errcode = '22023'; end if;
    remaining := greatest(0, remaining - floor((p_amount - minimum_after) / minimum_after)::integer);
  end if;

  select * into account_row from public.accounts where household_id = debt_row.household_id
    and debt_id = p_debt_id and kind = 'loan' and deleted_at is null for update;
  if not found then
    insert into public.accounts (household_id, kind, name, currency, debt_id, opening_balance)
      values (debt_row.household_id, 'loan', debt_row.name, household_currency, p_debt_id, -debt_row.current_balance)
      returning * into account_row;
  elsif account_row.currency is distinct from household_currency or account_row.is_archived then
    raise exception 'loan_account_invalid' using errcode = '22023';
  end if;

  split_details := jsonb_build_object('interest', interest_amount, 'principal', principal_amount,
    'debt_id', p_debt_id, 'partPaymentChoice', strategy);
  if interest_amount > 0 then
    insert into public.transactions (household_id, created_by, member_id, amount, currency,
      type, category, account_id, debt_id, date, description, extras)
    values (debt_row.household_id, actor_id, member_id, interest_amount, p_currency,
      'expense', 'loan_emi', p_funding_account_id, p_debt_id, payment_date, payment_description,
      jsonb_build_object('emi_split', split_details, 'linkedDebtId', p_debt_id)) returning id into expense_id;
  end if;
  if principal_amount > 0 then
    insert into public.transactions (household_id, created_by, member_id, amount, currency,
      type, category, account_id, to_account_id, debt_id, date, description, extras)
    values (debt_row.household_id, actor_id, member_id, principal_amount, p_currency,
      'transfer', null, p_funding_account_id, account_row.id, p_debt_id, payment_date,
      payment_description || ' - principal', jsonb_build_object('emi_split', split_details,
        'linkedDebtId', p_debt_id, 'linkedTxnId', expense_id)) returning id into transfer_id;
  end if;
  payment_log := jsonb_build_object('id', p_operation_id, 'date', payment_date, 'amount', p_amount,
    'interest', interest_amount, 'principal', principal_amount, 'outstandingAfter', balance_after,
    'isPartPayment', is_extra, 'partChoice', strategy);
  update public.debts set current_balance = balance_after, minimum_payment = minimum_after,
    extras = coalesce(extras, '{}'::jsonb) || jsonb_build_object('remainingMonths', remaining,
      'paymentLog', coalesce(extras->'paymentLog', '[]'::jsonb) || jsonb_build_array(payment_log)), updated_at = now()
    where id = p_debt_id returning * into debt_row;
  insert into public.loan_payment_events (operation_id, household_id, debt_id, expense_txn_id,
    transfer_txn_id, loan_account_id, amount, interest, principal, request)
    values (p_operation_id, debt_row.household_id, p_debt_id, expense_id, transfer_id,
      account_row.id, p_amount, interest_amount, principal_amount, request_body);
  return jsonb_build_object('status','success', 'debt', to_jsonb(debt_row),
    'loan_account', to_jsonb(account_row), 'expense_txn_id', expense_id,
    'transfer_txn_id', transfer_id, 'loan_account_id', account_row.id,
    'transactions', (select coalesce(jsonb_agg(to_jsonb(txn)), '[]'::jsonb)
      from public.transactions txn where id in (expense_id, transfer_id)));
end;
$$;

revoke all on function public.record_loan_payment(uuid,uuid,uuid,numeric,text,date,numeric,numeric,uuid,text,numeric,integer,numeric,jsonb) from public, anon;
grant execute on function public.record_loan_payment(uuid,uuid,uuid,numeric,text,date,numeric,numeric,uuid,text,numeric,integer,numeric,jsonb) to authenticated;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261014120000_w3d_recurrence_schema.sql
-- ─────────────────────────────────────────────────────────────────────
-- W3d (v10.68.0) — the recurrence schema, ahead of the app that needs it (owner decision D13: every
-- option the schedule form offers works; the month-end rule is chosen per schedule). Audit INT-TXN-05,
-- DB-INT-07/08, INT-CON-03, FE-MNY-01, XC-ARC-01.
--
--   1. 'daily' is allowed on recurring_schedules.frequency and transactions.recurring. The form
--      offered Daily, and both CHECKs refused it, so a daily schedule never reached the cloud and
--      posted money on one device only (INT-TXN-05).
--   2. recurring_schedules.short_month_policy: what a schedule on the 29th–31st does in a shorter
--      month — 'last_day' (the 28th/30th; default) or 'next_month_first' (the 1st of the next month).
--   3. Every schedule carries an RRULE. The v9.1 backfill wrote 'FREQ=MONTHLY;INTERVAL=1' with no
--      day, so read by the rule a bill on the 20th would move to its creation day. Those rows, and
--      rows with no rule, get one derived from their own columns (day_of_month / weekday / start
--      date) — the same derivation the app uses. A trigger fills it whenever an older app saves a
--      schedule without one.
--   4. whatsapp_approve_recurring takes p_exhausted: the app's engine says this was the last
--      occurrence (COUNT / UNTIL), and the schedule is closed instead of advanced. Otherwise the
--      function is unchanged (body copied from 20260927120000). The old 8-argument call still
--      resolves to it (the new argument has a default), so the deployed webhook keeps working.

-- 1. 'daily' on both CHECKs (inline, auto-named constraints: found by definition).
do $$
declare c record;
begin
  for c in
    select conrelid::regclass::text as tbl, conname
      from pg_constraint
     where contype = 'c'
       and ((conrelid = 'public.recurring_schedules'::regclass and pg_get_constraintdef(oid) ilike '%frequency = any%')
         or (conrelid = 'public.transactions'::regclass and pg_get_constraintdef(oid) ilike '%(recurring = any%'))
  loop
    execute format('alter table %s drop constraint %I', c.tbl, c.conname);
  end loop;
end $$;

alter table public.recurring_schedules
  add constraint ck_recurring_frequency check (frequency in ('daily', 'weekly', 'monthly', 'yearly', 'custom_day'));
alter table public.transactions
  add constraint ck_txn_recurring check (recurring in ('', 'daily', 'weekly', 'monthly', 'yearly'));

-- 2. The month-end rule, per schedule.
alter table public.recurring_schedules
  add column if not exists short_month_policy text not null default 'last_day';
alter table public.recurring_schedules drop constraint if exists ck_recurring_short_month_policy;
alter table public.recurring_schedules
  add constraint ck_recurring_short_month_policy check (short_month_policy in ('last_day', 'next_month_first'));

-- 3. One RRULE per schedule, derived from its own columns where it has none. Weekday 0 = Sunday.
create or replace function public.recurrence_rrule_from_legacy(
  p_frequency text, p_day_of_month int, p_weekday int, p_start date
) returns text
language sql
immutable
set search_path = public, pg_catalog
as $$
  select case p_frequency
    when 'daily'  then 'FREQ=DAILY;INTERVAL=1'
    when 'weekly' then 'FREQ=WEEKLY;INTERVAL=1;BYDAY='
                       || (array['SU','MO','TU','WE','TH','FR','SA'])[coalesce(p_weekday, extract(dow from p_start)::int) + 1]
    when 'yearly' then 'FREQ=YEARLY;INTERVAL=1;BYMONTH=' || extract(month from p_start)::int
                       || ';BYMONTHDAY=' || extract(day from p_start)::int
    else 'FREQ=MONTHLY;INTERVAL=1;BYMONTHDAY=' || coalesce(p_day_of_month, extract(day from p_start)::int)
  end
$$;

update public.recurring_schedules
   set rrule = public.recurrence_rrule_from_legacy(frequency, day_of_month, weekday, start_date)
 where rrule is null
    or rrule in ('FREQ=WEEKLY;INTERVAL=1', 'FREQ=MONTHLY;INTERVAL=1', 'FREQ=YEARLY;INTERVAL=1');

create or replace function public.recurring_schedules_fill_rrule()
returns trigger
language plpgsql
set search_path = public, pg_catalog
as $$
begin
  if new.rrule is null or btrim(new.rrule) = '' then
    new.rrule := public.recurrence_rrule_from_legacy(new.frequency, new.day_of_month, new.weekday, new.start_date);
  end if;
  return new;
end $$;

drop trigger if exists trg_recurring_fill_rrule on public.recurring_schedules;
create trigger trg_recurring_fill_rrule
  before insert or update on public.recurring_schedules
  for each row execute function public.recurring_schedules_fill_rrule();

-- 4. Approving the last occurrence closes the schedule.
drop function if exists public.whatsapp_approve_recurring(uuid, uuid, uuid, date, date, date, jsonb, text);

create or replace function public.whatsapp_approve_recurring(
  p_profile_id    uuid,
  p_household_id  uuid,
  p_schedule_id   uuid,
  p_occurrence    date,
  p_today         date,
  p_next_due      date,
  p_row           jsonb,
  p_wa_message_id text,
  -- W3d: the app's engine says this was the LAST occurrence (COUNT / UNTIL reached): the
  -- schedule is closed (active = false) instead of being moved to a date that never comes.
  p_exhausted     boolean default false
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_member_id  uuid;
  v_role       text;
  v_s          public.recurring_schedules%rowtype;
  v_t          jsonb;
  v_claimed    int;
  v_inserted   int;
  v_type       text;
  v_mode       text;
  v_paying     uuid;
begin
  -- 1. Claim the message, exactly as whatsapp_log_transaction does.
  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;
  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('status', 'duplicate');
  end if;

  -- 2. A write role in this household.
  select id, role into v_member_id, v_role
    from public.memberships
   where household_id = p_household_id and user_id = p_profile_id
   limit 1;
  if v_member_id is null then
    return jsonb_build_object('status', 'error', 'reason', 'not_a_member');
  end if;
  if v_role = 'viewer' then
    return jsonb_build_object('status', 'error', 'reason', 'read_only_member');
  end if;

  -- 3. The schedule, locked, and this occurrence the one due.
  select * into v_s
    from public.recurring_schedules
   where id = p_schedule_id and household_id = p_household_id and deleted_at is null
   for update;
  if not found or not v_s.active then
    return jsonb_build_object('status', 'error', 'reason', 'schedule_unavailable');
  end if;
  v_t := v_s.txn_template;
  if v_s.next_due_date > p_occurrence then
    return jsonb_build_object('status', 'already_done', 'next_due_date', v_s.next_due_date);
  end if;
  if v_s.next_due_date < p_occurrence then
    return jsonb_build_object('status', 'error', 'reason', 'not_the_due_occurrence');
  end if;
  if p_occurrence > p_today then
    return jsonb_build_object('status', 'error', 'reason', 'not_due_yet');
  end if;
  if not coalesce(p_exhausted, false) and (p_next_due is null or p_next_due <= p_occurrence) then
    return jsonb_build_object('status', 'error', 'reason', 'bad_next_due');
  end if;

  v_type := v_t->>'type';
  if v_type not in ('expense', 'income') or coalesce(v_t->>'category', '') = 'loan_emi'
     or nullif(v_t->>'debtId', '') is not null then
    return jsonb_build_object('status', 'error', 'reason', 'approve_in_app');
  end if;

  -- 4. The row must be this occurrence of this template.
  if (p_row->>'recurring_schedule_id')::uuid is distinct from p_schedule_id
     or (p_row->>'household_id')::uuid is distinct from p_household_id
     or (p_row->>'date')::date is distinct from p_occurrence
     or p_row->>'type' is distinct from v_type
     or (p_row->>'amount')::numeric is distinct from (v_t->>'amount')::numeric
     or coalesce(p_row->>'currency', 'USD') is distinct from coalesce(nullif(v_t->>'currency', ''), 'USD') then
    return jsonb_build_object('status', 'error', 'reason', 'row_mismatch');
  end if;

  -- A mode the paying account does not use is dropped, never an error (the
  -- store's rule, and whatsapp_log_transaction's).
  v_mode := nullif(p_row->>'payment_mode', '');
  if v_mode is not null then
    v_paying := case when v_type = 'income' then nullif(p_row->>'to_account_id', '')::uuid
                     else nullif(p_row->>'account_id', '')::uuid end;
    if exists (select 1 from public.accounts a where a.id = v_paying
                 and coalesce(array_length(a.payment_modes, 1), 0) > 0
                 and not (v_mode = any (a.payment_modes))) then
      v_mode := null;
    end if;
  end if;

  -- 5. The app's own row, under the deterministic id.
  insert into public.transactions (
    id, household_id, created_by, member_id, type, amount, currency, date, description,
    category, note, recurring, account_id, to_account_id, initiated_by,
    recurring_schedule_id, debt_id, payment_mode, extras, confidence, source, estimated_at, confirmed_at
  ) values (
    (p_row->>'id')::uuid,
    p_household_id,
    p_profile_id,
    nullif(p_row->>'member_id', '')::uuid,
    v_type,
    (p_row->>'amount')::numeric,
    coalesce(nullif(p_row->>'currency', ''), 'USD'),
    p_occurrence,
    coalesce(p_row->>'description', ''),
    nullif(p_row->>'category', ''),
    nullif(p_row->>'note', ''),
    nullif(p_row->>'recurring', ''),
    nullif(p_row->>'account_id', '')::uuid,
    nullif(p_row->>'to_account_id', '')::uuid,
    nullif(p_row->>'initiated_by', '')::uuid,
    p_schedule_id,
    null,
    v_mode,
    coalesce(p_row->'extras', '{}'::jsonb),
    coalesce(nullif(p_row->>'confidence', ''), 'confirmed'),
    coalesce(nullif(p_row->>'source', ''), 'user'),
    nullif(p_row->>'estimated_at', '')::timestamptz,
    nullif(p_row->>'confirmed_at', '')::timestamptz
  )
  on conflict (id) do nothing;
  get diagnostics v_inserted = row_count;

  -- 6. Move the schedule on.
  update public.recurring_schedules
     set last_generated = p_occurrence,
         next_due_date  = case when coalesce(p_exhausted, false) then next_due_date else p_next_due end,
         active         = not coalesce(p_exhausted, false)
   where id = p_schedule_id;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
           'approved', jsonb_build_object('schedule_id', p_schedule_id, 'occurrence', p_occurrence,
                                          'transaction_id', p_row->>'id', 'inserted', v_inserted = 1))
   where wa_message_id = p_wa_message_id;

  return jsonb_build_object(
    'status', 'success',
    'transaction_id', p_row->>'id',
    'already_posted', v_inserted = 0,
    'amount', (p_row->>'amount')::numeric,
    'currency', coalesce(nullif(p_row->>'currency', ''), 'USD'),
    'description', p_row->>'description',
    'next_due_date', case when coalesce(p_exhausted, false) then null else p_next_due end,
    'finished', coalesce(p_exhausted, false)
  );
end;
$$;

revoke all on function public.whatsapp_approve_recurring(uuid, uuid, uuid, date, date, date, jsonb, text, boolean) from public, anon, authenticated;
grant execute on function public.whatsapp_approve_recurring(uuid, uuid, uuid, date, date, date, jsonb, text, boolean) to service_role;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261015120000_w4a_server_posts_recurring.sql
-- ─────────────────────────────────────────────────────────────────────
-- W4a (v10.70.0) — the SERVER posts due bills (owner decision D16; audit INT-TXN-06, FE-SYN-02).
--
-- Until now every device ran the recurring engine on its own cached copy of the schedules and
-- posted whatever it thought was due. A device that had not yet pulled a pause, an edit or a
-- delete made on another device posted the bill anyway: money that should not have moved, moved.
--
-- Now, in cloud mode, an auto-approved bill is posted by the server from the database's own copy:
--   1. post_recurring_occurrence() — posts ONE due occurrence and moves the schedule on, in one
--      transaction, with the schedule row locked. The row and the next date are computed by the
--      APP's engine (bundled into the `recurring-post` Edge Function: serverEngine.recurringPostPlan,
--      the same generateTransaction → txnToRow → advanceSchedule the app runs), under the app's
--      deterministic occurrence id, so a device that still posts the same occurrence writes the
--      same row (ON CONFLICT DO NOTHING here; an upsert of identical values there).
--      The function re-checks everything it can on its own copy: the schedule is live, active and
--      auto-approved, the occurrence is the one due, it is due in the HOUSEHOLD's zone (D12), and
--      the row is that occurrence of that template. A pointer older than the catch-up horizon is
--      moved on without posting (p_post = false), as the app does.
--   2. Loan EMIs are NOT posted here: an EMI is an interest expense plus a principal transfer, and
--      the loan model that posts it (D19) is not built yet. The app keeps posting those.
--   3. pg_cron calls the function every 30 minutes (each household's day starts at its own
--      midnight), authenticated by a secret generated into Vault here; nobody handles it.
--
-- Approval-gated bills are unchanged: they wait for Approve in the app or "paid X" on WhatsApp.

create or replace function public.post_recurring_occurrence(
  p_schedule_id    uuid,
  p_occurrence     date,
  p_post           boolean,
  p_row            jsonb,
  p_next_due       date,
  p_last_generated date,
  p_exhausted      boolean default false
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_s        public.recurring_schedules%rowtype;
  v_t        jsonb;
  v_today    date;
  v_type     text;
  v_mode     text;
  v_paying   uuid;
  v_inserted int := 0;
begin
  -- 1. The schedule, locked: nobody else moves it while this runs.
  select * into v_s
    from public.recurring_schedules
   where id = p_schedule_id and deleted_at is null
   for update;
  if not found then
    return jsonb_build_object('status', 'skipped', 'reason', 'schedule_unavailable');
  end if;
  if not v_s.active or not v_s.auto_confirm then
    return jsonb_build_object('status', 'skipped', 'reason', 'not_auto');
  end if;
  if v_s.next_due_date <> p_occurrence then
    return jsonb_build_object('status', 'skipped', 'reason', 'moved', 'next_due_date', v_s.next_due_date);
  end if;

  -- 2. Due in the household's own day (W3a, D12), never the server's.
  select (now() at time zone coalesce(nullif(h.timezone, ''), 'Asia/Kolkata'))::date into v_today
    from public.households h where h.id = v_s.household_id;
  if v_today is null then
    return jsonb_build_object('status', 'skipped', 'reason', 'household_unavailable');
  end if;
  if p_occurrence > v_today then
    return jsonb_build_object('status', 'skipped', 'reason', 'not_due_yet');
  end if;

  v_t := v_s.txn_template;
  v_type := v_t->>'type';
  if v_type not in ('expense', 'income', 'transfer', 'investment')
     or coalesce(v_t->>'category', '') = 'loan_emi'
     or nullif(v_t->>'debtId', '') is not null or nullif(v_t->>'linkedDebtId', '') is not null then
    return jsonb_build_object('status', 'skipped', 'reason', 'posted_in_app');
  end if;
  if not coalesce(p_exhausted, false) and (p_next_due is null or p_next_due <= p_occurrence) then
    return jsonb_build_object('status', 'error', 'reason', 'bad_next_due');
  end if;
  if p_last_generated is null or p_last_generated < p_occurrence then
    return jsonb_build_object('status', 'error', 'reason', 'bad_last_generated');
  end if;

  if coalesce(p_post, false) then
    -- 3. The row must be this occurrence of this template.
    if (p_row->>'recurring_schedule_id')::uuid is distinct from p_schedule_id
       or (p_row->>'household_id')::uuid is distinct from v_s.household_id
       or (p_row->>'date')::date is distinct from p_occurrence
       or p_row->>'type' is distinct from v_type
       or (p_row->>'amount')::numeric is distinct from (v_t->>'amount')::numeric then
      return jsonb_build_object('status', 'error', 'reason', 'row_mismatch');
    end if;

    -- A mode the paying account does not use is dropped, never an error (the store's rule).
    v_mode := nullif(p_row->>'payment_mode', '');
    if v_mode is not null then
      v_paying := case when v_type = 'income' then nullif(p_row->>'to_account_id', '')::uuid
                       else nullif(p_row->>'account_id', '')::uuid end;
      if v_type = 'investment' or exists (
           select 1 from public.accounts a where a.id = v_paying
              and coalesce(array_length(a.payment_modes, 1), 0) > 0
              and not (v_mode = any (a.payment_modes))) then
        v_mode := null;
      end if;
    end if;

    -- 4. The app's own row, under the deterministic id. A row the ledger refuses (a template
    --    with no account, say) is reported and the schedule is left due, never half-applied.
    begin
      insert into public.transactions (
        id, household_id, created_by, member_id, type, amount, currency, date, description,
        category, note, recurring, account_id, to_account_id, asset_id, initiated_by,
        recurring_schedule_id, debt_id, payment_mode, extras, confidence, source, estimated_at, confirmed_at
      ) values (
        (p_row->>'id')::uuid,
        v_s.household_id,
        v_s.created_by,
        nullif(p_row->>'member_id', '')::uuid,
        v_type,
        (p_row->>'amount')::numeric,
        coalesce(nullif(p_row->>'currency', ''), 'USD'),
        p_occurrence,
        coalesce(p_row->>'description', ''),
        nullif(p_row->>'category', ''),
        nullif(p_row->>'note', ''),
        nullif(p_row->>'recurring', ''),
        nullif(p_row->>'account_id', '')::uuid,
        nullif(p_row->>'to_account_id', '')::uuid,
        nullif(p_row->>'asset_id', '')::uuid,
        nullif(p_row->>'initiated_by', '')::uuid,
        p_schedule_id,
        null,
        v_mode,
        coalesce(p_row->'extras', '{}'::jsonb),
        coalesce(nullif(p_row->>'confidence', ''), 'confirmed'),
        coalesce(nullif(p_row->>'source', ''), 'user'),
        nullif(p_row->>'estimated_at', '')::timestamptz,
        nullif(p_row->>'confirmed_at', '')::timestamptz
      )
      on conflict (id) do nothing;
      get diagnostics v_inserted = row_count;
    exception when check_violation or foreign_key_violation or not_null_violation or invalid_text_representation then
      return jsonb_build_object('status', 'error', 'reason', 'row_rejected', 'detail', sqlerrm);
    end;
  end if;

  -- 5. Move the schedule on (or close it when its rule has run out).
  update public.recurring_schedules
     set last_generated = p_last_generated,
         next_due_date  = case when coalesce(p_exhausted, false) then next_due_date else p_next_due end,
         active         = not coalesce(p_exhausted, false)
   where id = p_schedule_id;

  return jsonb_build_object(
    'status', case when coalesce(p_post, false) then 'posted' else 'fast_forwarded' end,
    'transaction_id', case when coalesce(p_post, false) then p_row->>'id' end,
    'already_posted', coalesce(p_post, false) and v_inserted = 0,
    'next_due_date', case when coalesce(p_exhausted, false) then null else p_next_due end,
    'finished', coalesce(p_exhausted, false)
  );
end;
$$;

revoke all on function public.post_recurring_occurrence(uuid, date, boolean, jsonb, date, date, boolean) from public, anon, authenticated;
grant execute on function public.post_recurring_occurrence(uuid, date, boolean, jsonb, date, date, boolean) to service_role;

-- The cron secret check (plpgsql: its body is resolved at call time, not here).
create or replace function public.recurring_post_cron_ok(p text)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  return length(coalesce(p, '')) >= 32
     and exists (select 1 from vault.decrypted_secrets s where s.name = 'recurring_post_cron_secret' and s.decrypted_secret = p);
end;
$$;
revoke all on function public.recurring_post_cron_ok(text) from public, anon, authenticated;
grant execute on function public.recurring_post_cron_ok(text) to service_role;

-- The secret (generated here; it never leaves the database and the function) and the job.
do $$
begin
  -- Nested, so a database without Vault (the PGlite tests) never plans the inner query.
  if exists (select 1 from pg_namespace where nspname = 'vault') then
    if not exists (select 1 from vault.secrets where name = 'recurring_post_cron_secret') then
      perform vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'recurring_post_cron_secret',
                                  'pg_cron -> recurring-post');
    end if;
  end if;

  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'recurring-post';
    -- Every 30 minutes, so each household's bills post shortly after ITS midnight.
    perform cron.schedule('recurring-post', '10,40 * * * *', $job$
      select net.http_post(
        url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/recurring-post',
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', s.decrypted_secret),
        body    := '{}'::jsonb,
        timeout_milliseconds := 55000)
      from vault.decrypted_secrets s where s.name = 'recurring_post_cron_secret';
    $job$);
  end if;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261016120000_w4e_loan_model.sql
-- ─────────────────────────────────────────────────────────────────────
-- W4e (v10.74.0) — the loan model, ahead of the app that uses it (owner decisions D19, D17, D30;
-- audit INT-TXN-07, FE-MNY-03/04, XC-ARC-02, BE-WA-08, the live "Save failed – payment_out_of_range").
--
-- What was wrong:
--   • Two "outstanding" figures: debts.current_balance (typed, and moved by the old RPC) and the loan
--     account's ledger (what net worth reads). They drifted, and the Debts page and Net Worth disagreed.
--   • record_loan_payment charged a FULL month's interest on every payment, so a prepayment paid a
--     second month of interest, and the final EMI (which is less than a month's EMI) was refused with
--     payment_out_of_range. It had no dates, no instalments, no schedule and no undo.
--   • Credit cards were also "debts", so a card could exist twice — as a debt and as an account.
--
-- The model now (the owner's, 2026-10-07):
--   • OUTSTANDING = the loan ACCOUNT's ledger, only. debts.current_balance is a cache the functions
--     keep equal to it, for older apps. Every live loan gets its account here.
--   • Terms: principal (sanctioned), interest_rate + effective-dated rate_history, tenure_months,
--     first_emi_date (with terms_confirmed — estimated for existing loans until the owner confirms),
--     minimum_payment (the EMI), due_date (the NEXT instalment's date), instalments_paid,
--     auto_record + funding_account_id (used by the server job in a later release).
--   • pay_loan — the SERVER computes the split, per instalment, on a reducing balance:
--       emi           interest first, then principal. Instalment k's interest is fixed when its first
--                     payment arrives (outstanding × rate/12, banker's rounding to the minor unit) and
--                     its amount is min(EMI, outstanding + interest). A payment SHORT of it is accepted
--                     and the instalment stays open; MORE than it is refused (more_than_due) — the extra
--                     is a prepayment (owner).
--       prepayment    all principal; reduce_tenure keeps the EMI, reduce_emi recomputes it over the
--                     instalments that were left. Refused while an instalment is part-paid.
--       payoff        exactly outstanding + the unpaid interest of an instalment already started
--                     (owner); anything else is refused with the exact figure (payoff_amount).
--       bank_override the bank's own interest/principal for the due instalment, which it closes.
--     Each payment is ONE transaction: an interest expense (loan_emi) and a principal transfer into
--     the loan account, under an idempotent operation id.
--   • reverse_loan_payment — undo the LATEST payment on a loan only (owner), atomically.
--   • mark_loan_paid_off — the loan account reconciled to zero (offset + dated log, never a
--     transaction), the loan closed. delete_debt / the delete guard — a loan with money still owed
--     cannot be deleted (D17).
--   • Credit cards are ACCOUNTS (D30, owner): every live credit-card debt moves into a credit-card
--     account (merged with the one already linked to it, else created at its outstanding) and the
--     debt row is archived; a card debt an older app still creates is moved the same way.
--
-- record_loan_payment stays, unchanged, for the app until v10.75.0 stops calling it.

-- ── 1. Terms and instalment tracking on debts ───────────────────────────────────────────────
alter table public.debts
  add column if not exists tenure_months      integer,
  add column if not exists first_emi_date     date,
  add column if not exists terms_confirmed    boolean not null default false,
  add column if not exists rate_history       jsonb   not null default '[]'::jsonb,
  add column if not exists instalments_paid   integer not null default 0,
  add column if not exists auto_record        boolean not null default false,
  add column if not exists funding_account_id uuid references public.accounts(id) on delete set null,
  add column if not exists paid_off_at        timestamptz;
alter table public.debts drop constraint if exists ck_debt_tenure_months;
alter table public.debts add constraint ck_debt_tenure_months check (tenure_months is null or tenure_months between 1 and 600);
alter table public.debts drop constraint if exists ck_debt_instalments_paid;
alter table public.debts add constraint ck_debt_instalments_paid check (instalments_paid >= 0);
alter table public.debts drop constraint if exists ck_debt_rate_history;
alter table public.debts add constraint ck_debt_rate_history check (jsonb_typeof(rate_history) = 'array');

-- ── 2. Payment events carry the instalment they paid ─────────────────────────────────────────
alter table public.loan_payment_events
  add column if not exists kind                text,
  add column if not exists instalment_no       integer,
  add column if not exists instalment_date     date,
  add column if not exists instalment_interest numeric,
  add column if not exists instalment_due      numeric,
  add column if not exists closes_instalment   boolean not null default false,
  add column if not exists emi_before          numeric,
  add column if not exists emi_after           numeric,
  add column if not exists due_date_before     date,
  add column if not exists paid_off            boolean not null default false,
  add column if not exists prepayment_choice   text,
  add column if not exists payment_date        date,
  add column if not exists created_by          uuid references auth.users(id) on delete set null,
  add column if not exists reversed_at         timestamptz,
  add column if not exists reversed_by         uuid references auth.users(id) on delete set null;
alter table public.loan_payment_events drop constraint if exists ck_loan_event_kind;
alter table public.loan_payment_events add constraint ck_loan_event_kind
  check (kind is null or kind in ('emi', 'prepayment', 'payoff', 'bank_override', 'legacy'));
create index if not exists loan_payment_events_debt_live
  on public.loan_payment_events (debt_id, created_at desc) where reversed_at is null;

-- ── 3. The arithmetic (the app mirrors it in lib/loanSchedule.ts; parity-tested) ─────────────
create or replace function public.loan_minor_scale(p_currency text)
returns integer language sql immutable as $$
  select case when p_currency = 'JPY' then 1 else 100 end
$$;

-- The decimals a scale stands for (100 → 2, 1 → 0), so stored amounts carry the currency's own scale.
create or replace function public.loan_digits(p_scale integer)
returns integer language sql immutable as $$
  select length(p_scale::text) - 1
$$;

-- One instalment's interest: outstanding × annual/1200, in minor units, banker's rounding.
create or replace function public.loan_interest(p_outstanding numeric, p_annual numeric, p_scale integer)
returns numeric language sql immutable as $$
  select round((case when u - trunc(u) = 0.5 then trunc(u) + mod(trunc(u), 2) else round(u) end) / p_scale, public.loan_digits(p_scale))
    from (select round(p_outstanding * p_scale) * round(p_annual / 1200, 12) as u) x
$$;

-- The standard EMI P·r(1+r)^n/((1+r)^n−1), rounded UP to the minor unit (so no stub instalment).
create or replace function public.loan_emi(p_outstanding numeric, p_annual numeric, p_months integer, p_scale integer)
returns numeric language sql immutable as $$
  select round(case
    when p_months is null or p_months < 1 or p_outstanding <= 0 then null
    when p_annual = 0 then ceil(p_outstanding * p_scale / p_months) / p_scale
    else ceil(p_outstanding * (p_annual / 1200) / (1 - power(1 + p_annual / 1200, -p_months)) * p_scale - 1e-9) / p_scale
  end, public.loan_digits(p_scale))
$$;

-- Instalments left at this EMI (null when the EMI never clears it).
create or replace function public.loan_instalments_left(p_outstanding numeric, p_annual numeric, p_emi numeric)
returns integer language sql immutable as $$
  select case
    when p_outstanding <= 0 then 0
    when p_emi is null or p_emi <= 0 then null
    when p_annual = 0 then ceil(p_outstanding / p_emi - 1e-9)::integer
    when p_emi <= p_outstanding * p_annual / 1200 then null
    else ceil(-ln(1 - (p_annual / 1200) * p_outstanding / p_emi) / ln(1 + p_annual / 1200) - 1e-9)::integer
  end
$$;

-- The instalment after p_from on the loan's day of month (a 31st falls on a shorter month's last day).
create or replace function public.loan_next_instalment(p_from date, p_anchor_day integer)
returns date language sql immutable as $$
  select (date_trunc('month', p_from) + interval '1 month')::date
         + (least(p_anchor_day,
                  extract(day from (date_trunc('month', p_from) + interval '2 month' - interval '1 day'))::integer) - 1)
$$;

-- The rate on a date: the latest change on or before it; before every change, the first rate.
create or replace function public.loan_rate_on(p_history jsonb, p_current numeric, p_on date)
returns numeric language sql immutable as $$
  select case when p_on is null or jsonb_array_length(coalesce(p_history, '[]'::jsonb)) = 0 then p_current else coalesce(
    (select (e->>'rate')::numeric from jsonb_array_elements(p_history) e
      where (e->>'from')::date <= p_on order by (e->>'from')::date desc limit 1),
    (select (e->>'rate')::numeric from jsonb_array_elements(p_history) e order by (e->>'from')::date asc limit 1),
    p_current) end
$$;

-- A loan account's ledger balance (negative while money is owed): opening + offset + money in − out.
create or replace function public.loan_ledger_balance(p_account uuid)
returns numeric language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(a.opening_balance, 0) + coalesce(a.reconciliation_offset, 0)
       + coalesce((select sum(t.amount) from public.transactions t
                    where t.to_account_id = a.id and t.deleted_at is null
                      and t.type in ('income', 'transfer', 'investment')), 0)
       - coalesce((select sum(t.amount) from public.transactions t
                    where t.account_id = a.id and t.deleted_at is null
                      and t.type in ('expense', 'transfer', 'investment')), 0)
    from public.accounts a where a.id = p_account
$$;

-- The loan's account, created at the debt's outstanding when it has none. Locked.
create or replace function public.loan_account_for(p_debt public.debts)
returns public.accounts language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_acc public.accounts%rowtype;
  v_currency text;
begin
  select * into v_acc from public.accounts
   where household_id = p_debt.household_id and debt_id = p_debt.id and kind = 'loan' and deleted_at is null
   order by created_at limit 1 for update;
  if not found then
    select base_currency into v_currency from public.households where id = p_debt.household_id;
    insert into public.accounts (household_id, kind, name, currency, debt_id, opening_balance)
      values (p_debt.household_id, 'loan', p_debt.name, v_currency, p_debt.id, -p_debt.current_balance)
      returning * into v_acc;
  end if;
  return v_acc;
end;
$$;

-- The instalment due and what has been paid toward it. ONE definition, used by pay_loan (which acts on
-- it) and loan_due (which tells the app what pay_loan will accept), so the two can never disagree.
create or replace function public.loan_instalment_state(
  p_debt public.debts, p_outstanding numeric, p_scale integer, p_on date,
  out instalment_no integer, out started boolean, out paid numeric, out interest_paid numeric,
  out interest numeric, out due numeric)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  instalment_no := p_debt.instalments_paid + 1;
  select coalesce(sum(e.amount), 0), coalesce(sum(e.interest), 0), min(e.instalment_interest), min(e.instalment_due), count(*) > 0
    into paid, interest_paid, interest, due, started
    from public.loan_payment_events e
   where e.debt_id = p_debt.id and e.reversed_at is null and e.kind = 'emi' and e.instalment_no = loan_instalment_state.instalment_no;
  if not started then
    interest := public.loan_interest(p_outstanding,
      public.loan_rate_on(p_debt.rate_history, p_debt.interest_rate, coalesce(p_debt.due_date, p_on)), p_scale);
    due := least(p_debt.minimum_payment, p_outstanding + interest);
  end if;
end;
$$;

-- ── 4. Paying a loan ────────────────────────────────────────────────────────────────────────
create or replace function public.loan_payment_result(p_status text, p_operation_id uuid)
returns jsonb language sql stable security definer set search_path = public, pg_temp as $$
  select jsonb_build_object(
    'status', p_status,
    'operation_id', e.operation_id,
    'kind', e.kind,
    'interest', e.interest,
    'principal', e.principal,
    'instalment_no', e.instalment_no,
    'closes_instalment', e.closes_instalment,
    'paid_off', e.paid_off,
    'outstanding_after', greatest(0, -public.loan_ledger_balance(e.loan_account_id)),
    'next_due_date', d.due_date,
    'emi_after', d.minimum_payment,
    'debt', to_jsonb(d),
    'loan_account', to_jsonb(a),
    'transactions', (select coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb) from public.transactions t
                      where t.id in (e.expense_txn_id, e.transfer_txn_id)))
  from public.loan_payment_events e
  join public.debts d on d.id = e.debt_id
  left join public.accounts a on a.id = e.loan_account_id
  where e.operation_id = p_operation_id
$$;

create or replace function public.loan_payment_core(
  p_actor              uuid,
  p_operation_id       uuid,
  p_debt_id            uuid,
  p_kind               text,
  p_amount             numeric,
  p_date               date,
  p_funding_account_id uuid,
  p_member_id          uuid,
  p_description        text,
  p_prepayment_choice  text,
  p_bank_interest      numeric,
  p_bank_principal     numeric
) returns jsonb
language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  d               public.debts%rowtype;
  acc             public.accounts%rowtype;
  ev              public.loan_payment_events%rowtype;
  v_member        uuid;
  v_currency      text;
  v_scale         integer;
  v_choice        text;
  v_desc          text;
  v_request       jsonb;
  v_outstanding   numeric;
  v_emi           numeric;
  v_rate          numeric;
  v_k             integer;
  v_started       boolean;
  v_paid          numeric;
  v_interest_paid numeric;
  v_i_k           numeric;
  v_due_k         numeric;
  v_interest      numeric := 0;
  v_principal     numeric := 0;
  v_closes        boolean := false;
  v_after         numeric;
  v_emi_after     numeric;
  v_due_after     date;
  v_left          integer;
  v_split         jsonb;
  v_expense       uuid;
  v_transfer      uuid;
begin
  select * into d from public.debts where id = p_debt_id and deleted_at is null for update;
  if not found then raise exception 'debt_unavailable' using errcode = '22023'; end if;
  select id into v_member from public.memberships
   where household_id = d.household_id and user_id = p_actor and role in ('owner', 'admin', 'member') for share;
  if v_member is null then raise exception 'not_authorized' using errcode = '42501'; end if;
  if coalesce(d.direction, 'owed_by_me') <> 'owed_by_me' then raise exception 'not_a_loan' using errcode = '22023'; end if;
  if d.type = 'credit_card' then raise exception 'cards_are_accounts' using errcode = '22023'; end if;
  if p_kind is null or p_kind not in ('emi', 'prepayment', 'payoff', 'bank_override') then
    raise exception 'invalid_kind' using errcode = '22023';
  end if;
  if p_operation_id is null or p_date is null or p_amount is null
     or p_amount::text in ('NaN', 'Infinity', '-Infinity') or p_amount <= 0 then
    raise exception 'invalid_payment' using errcode = '22023';
  end if;
  select base_currency into v_currency from public.households where id = d.household_id;
  v_scale := public.loan_minor_scale(v_currency);
  if p_amount * v_scale <> trunc(p_amount * v_scale) then raise exception 'invalid_precision' using errcode = '22023'; end if;
  v_choice := case when p_kind = 'prepayment' then coalesce(p_prepayment_choice, 'reduce_tenure') end;
  if v_choice is not null and v_choice not in ('reduce_tenure', 'reduce_emi') then
    raise exception 'invalid_strategy' using errcode = '22023';
  end if;
  v_desc := coalesce(nullif(btrim(p_description), ''), d.name || case p_kind
              when 'prepayment' then ' prepayment' when 'payoff' then ' payoff' else ' EMI' end);
  v_request := jsonb_build_object('actor', p_actor, 'debt', p_debt_id, 'kind', p_kind, 'amount', p_amount,
    'date', p_date, 'funding', p_funding_account_id, 'member', p_member_id, 'description', v_desc,
    'choice', v_choice, 'bank_interest', p_bank_interest, 'bank_principal', p_bank_principal);

  -- A retry of the same operation returns what it did the first time; a different request under the
  -- same id is refused.
  select * into ev from public.loan_payment_events where operation_id = p_operation_id;
  if found then
    if ev.debt_id <> p_debt_id or ev.request is distinct from v_request then
      raise exception 'operation_id_reused' using errcode = '22023';
    end if;
    return public.loan_payment_result('duplicate', p_operation_id);
  end if;
  if d.paid_off_at is not null then raise exception 'loan_paid_off' using errcode = '22023'; end if;

  perform 1 from public.accounts where id = p_funding_account_id and household_id = d.household_id
     and kind in ('cash', 'bank') and deleted_at is null and not is_archived for share;
  if not found then raise exception 'funding_account_invalid' using errcode = '22023'; end if;
  if p_member_id is not null then
    perform 1 from public.memberships where id = p_member_id and household_id = d.household_id for share;
    if not found then raise exception 'member_invalid' using errcode = '22023'; end if;
    v_member := p_member_id;
  end if;

  -- The outstanding is the loan account's ledger, and nothing else.
  acc := public.loan_account_for(d);
  v_outstanding := -public.loan_ledger_balance(acc.id);
  if v_outstanding <= 0 then raise exception 'loan_paid_off' using errcode = '22023'; end if;
  v_emi := d.minimum_payment;

  -- The instalment due, and what has been paid toward it so far.
  select s.instalment_no, s.started, s.paid, s.interest_paid, s.interest, s.due
    into v_k, v_started, v_paid, v_interest_paid, v_i_k, v_due_k
    from public.loan_instalment_state(d, v_outstanding, v_scale, p_date) s;

  if p_kind = 'emi' then
    if v_emi is null or v_emi <= 0 then raise exception 'no_emi' using errcode = '22023'; end if;
    if p_amount > v_due_k - v_paid then
      raise exception 'more_than_due' using errcode = '22023', detail = (v_due_k - v_paid)::text;
    end if;
    v_interest := least(p_amount, greatest(v_i_k - v_interest_paid, 0));
    v_principal := p_amount - v_interest;
    v_closes := (v_paid + p_amount = v_due_k);
  elsif p_kind = 'prepayment' then
    if v_started then raise exception 'instalment_open' using errcode = '22023', detail = (v_due_k - v_paid)::text; end if;
    if p_amount > v_outstanding then
      raise exception 'more_than_outstanding' using errcode = '22023', detail = v_outstanding::text;
    end if;
    v_principal := p_amount;
  elsif p_kind = 'payoff' then
    v_interest := case when v_started then greatest(v_i_k - v_interest_paid, 0) else 0 end;
    if p_amount <> v_outstanding + v_interest then
      raise exception 'payoff_amount' using errcode = '22023', detail = (v_outstanding + v_interest)::text;
    end if;
    v_principal := v_outstanding;
    v_closes := v_started;
  else -- bank_override
    if v_started then raise exception 'instalment_open' using errcode = '22023', detail = (v_due_k - v_paid)::text; end if;
    if p_bank_interest is null or p_bank_principal is null or p_bank_interest < 0 or p_bank_principal < 0
       or p_bank_interest + p_bank_principal <> p_amount or p_bank_principal > v_outstanding
       or p_bank_interest * v_scale <> trunc(p_bank_interest * v_scale)
       or p_bank_principal * v_scale <> trunc(p_bank_principal * v_scale) then
      raise exception 'bank_figures_invalid' using errcode = '22023';
    end if;
    v_interest := p_bank_interest;
    v_principal := p_bank_principal;
    v_i_k := p_bank_interest;
    v_due_k := p_amount;
    v_closes := true;
  end if;

  v_after := v_outstanding - v_principal;
  v_emi_after := v_emi;
  if p_kind = 'prepayment' and v_choice = 'reduce_emi' and v_after > 0 then
    v_rate := public.loan_rate_on(d.rate_history, d.interest_rate, coalesce(d.due_date, p_date));
    v_left := public.loan_instalments_left(v_outstanding, v_rate, v_emi);
    if v_left is null then raise exception 'non_amortizing_payment' using errcode = '22023'; end if;
    v_emi_after := public.loan_emi(v_after, v_rate, v_left, v_scale);
  end if;
  v_due_after := case
    when v_after = 0 then null
    when v_closes and d.due_date is not null then
      public.loan_next_instalment(d.due_date, extract(day from coalesce(d.first_emi_date, d.due_date))::integer)
    else d.due_date end;

  -- The legs: interest is spending (Loan / EMI), principal moves money into the loan account.
  v_split := jsonb_build_object('interest', v_interest, 'principal', v_principal, 'debt_id', d.id,
    'kind', p_kind, 'instalment_no', case when p_kind = 'prepayment' then null else v_k end,
    'operation_id', p_operation_id, 'partPaymentChoice', v_choice);
  if v_interest > 0 then
    insert into public.transactions (household_id, created_by, member_id, amount, currency, type, category,
      account_id, debt_id, date, description, extras)
    values (d.household_id, p_actor, v_member, v_interest, v_currency, 'expense', 'loan_emi',
      p_funding_account_id, d.id, p_date, v_desc,
      jsonb_build_object('emi_split', v_split, 'linkedDebtId', d.id))
    returning id into v_expense;
  end if;
  if v_principal > 0 then
    insert into public.transactions (household_id, created_by, member_id, amount, currency, type, category,
      account_id, to_account_id, debt_id, date, description, extras)
    values (d.household_id, p_actor, v_member, v_principal, v_currency, 'transfer', null,
      p_funding_account_id, acc.id, d.id, p_date, v_desc || ' - principal',
      jsonb_build_object('emi_split', v_split, 'linkedDebtId', d.id, 'linkedTxnId', v_expense))
    returning id into v_transfer;
  end if;

  update public.debts
     set current_balance  = v_after,
         minimum_payment  = v_emi_after,
         instalments_paid = instalments_paid + case when v_closes then 1 else 0 end,
         due_date         = v_due_after,
         paid_off_at      = case when v_after = 0 then now() else paid_off_at end,
         updated_at       = now()
   where id = d.id;

  insert into public.loan_payment_events (
    operation_id, household_id, debt_id, expense_txn_id, transfer_txn_id, loan_account_id,
    amount, interest, principal, request, kind, instalment_no, instalment_date, instalment_interest,
    instalment_due, closes_instalment, emi_before, emi_after, due_date_before, paid_off,
    prepayment_choice, payment_date, created_by)
  values (
    p_operation_id, d.household_id, d.id, v_expense, v_transfer, acc.id,
    p_amount, v_interest, v_principal, v_request, p_kind,
    case when p_kind = 'prepayment' then null else v_k end, d.due_date,
    case when p_kind = 'prepayment' then null else v_i_k end,
    case when p_kind = 'prepayment' then null else v_due_k end,
    v_closes, v_emi, v_emi_after, d.due_date, v_after = 0, v_choice, p_date, p_actor);

  return public.loan_payment_result('success', p_operation_id);
end;
$$;

create or replace function public.pay_loan(
  p_operation_id       uuid,
  p_debt_id            uuid,
  p_kind               text,
  p_amount             numeric,
  p_date               date,
  p_funding_account_id uuid,
  p_member_id          uuid    default null,
  p_description        text    default null,
  p_prepayment_choice  text    default null,
  p_bank_interest      numeric default null,
  p_bank_principal     numeric default null
) returns jsonb
language plpgsql security definer set search_path = public, pg_temp
as $$
begin
  if auth.uid() is null then raise exception 'not_authorized' using errcode = '42501'; end if;
  return public.loan_payment_core(auth.uid(), p_operation_id, p_debt_id, p_kind, p_amount, p_date,
    p_funding_account_id, p_member_id, p_description, p_prepayment_choice, p_bank_interest, p_bank_principal);
end;
$$;

-- What pay_loan will accept today, for the app's Pay form: the instalment due (number, date, its
-- interest, the amount still due), the exact payoff figure, and the latest payment (undo). Any member
-- may read it; nothing is written (a loan without its account yet reads the debt's own figure).
create or replace function public.loan_due(p_debt_id uuid, p_on date default null)
returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp
as $$
declare
  d public.debts%rowtype;
  s record;
  v_scale integer;
  v_outstanding numeric;
  v_acc uuid;
  v_latest public.loan_payment_events%rowtype;
begin
  select * into d from public.debts where id = p_debt_id and deleted_at is null;
  if not found or not public.is_member(d.household_id) then raise exception 'debt_unavailable' using errcode = '22023'; end if;
  v_scale := public.loan_minor_scale((select base_currency from public.households where id = d.household_id));
  select id into v_acc from public.accounts where debt_id = d.id and kind = 'loan' and deleted_at is null order by created_at limit 1;
  v_outstanding := public.loan_outstanding(d);
  select * into s from public.loan_instalment_state(d, v_outstanding, v_scale, coalesce(p_on, current_date));
  select * into v_latest from public.loan_payment_events e
   where e.debt_id = d.id and e.reversed_at is null and coalesce(e.kind, '') <> 'legacy'
   order by e.created_at desc, e.operation_id desc limit 1;
  return jsonb_build_object(
    'outstanding', v_outstanding,
    'emi', d.minimum_payment,
    'paid_off', d.paid_off_at is not null or v_outstanding = 0,
    'instalment_no', s.instalment_no,
    'due_date', d.due_date,
    'interest', s.interest,
    'due', s.due,
    'paid', s.paid,
    'remaining', greatest(s.due - s.paid, 0),
    'started', s.started,
    'payoff', v_outstanding + case when s.started then greatest(s.interest - s.interest_paid, 0) else 0 end,
    'loan_account_id', v_acc,
    'latest_payment', case when v_latest.operation_id is null then null else jsonb_build_object(
      'operation_id', v_latest.operation_id, 'kind', v_latest.kind, 'amount', v_latest.amount,
      'date', v_latest.payment_date, 'created_at', v_latest.created_at) end);
end;
$$;

-- ── 5. Undo the latest payment (owner: the latest only) ───────────────────────────────────────
create or replace function public.reverse_loan_payment(p_operation_id uuid)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  ev public.loan_payment_events%rowtype;
  d  public.debts%rowtype;
  v_actor uuid := auth.uid();
begin
  if v_actor is null then raise exception 'not_authorized' using errcode = '42501'; end if;
  select * into ev from public.loan_payment_events where operation_id = p_operation_id;
  if not found then raise exception 'payment_unavailable' using errcode = '22023'; end if;
  select * into d from public.debts where id = ev.debt_id for update;
  perform 1 from public.memberships
   where household_id = d.household_id and user_id = v_actor and role in ('owner', 'admin', 'member');
  if not found then raise exception 'not_authorized' using errcode = '42501'; end if;
  -- Locked: re-read the event under the debt's lock.
  select * into ev from public.loan_payment_events where operation_id = p_operation_id;
  if ev.reversed_at is not null then return jsonb_build_object('status', 'already_reversed'); end if;
  if ev.kind = 'legacy' then raise exception 'cannot_undo_legacy' using errcode = '22023'; end if;
  if exists (select 1 from public.loan_payment_events e
              where e.debt_id = ev.debt_id and e.reversed_at is null and e.operation_id <> ev.operation_id
                and (e.created_at, e.operation_id) > (ev.created_at, ev.operation_id)) then
    raise exception 'not_latest_payment' using errcode = '22023';
  end if;

  update public.transactions set deleted_at = now(), updated_at = now()
   where id in (ev.expense_txn_id, ev.transfer_txn_id) and deleted_at is null;
  update public.loan_payment_events set reversed_at = now(), reversed_by = v_actor where operation_id = ev.operation_id;
  update public.debts
     set minimum_payment  = coalesce(ev.emi_before, minimum_payment),
         instalments_paid = greatest(0, instalments_paid - case when ev.closes_instalment then 1 else 0 end),
         due_date         = case when ev.kind is not null then ev.due_date_before else due_date end,
         paid_off_at      = case when ev.paid_off then null else paid_off_at end,
         current_balance  = case when ev.loan_account_id is not null
                                 then greatest(0, -public.loan_ledger_balance(ev.loan_account_id))
                                 else current_balance + ev.principal end,
         updated_at       = now()
   where id = d.id
  returning * into d;

  return jsonb_build_object('status', 'reversed', 'debt', to_jsonb(d),
    'removed_transaction_ids', to_jsonb(array_remove(array[ev.expense_txn_id, ev.transfer_txn_id], null)),
    'outstanding', greatest(0, -public.loan_ledger_balance(ev.loan_account_id)));
end;
$$;

-- ── 6. Closing and deleting a loan (D17) ────────────────────────────────────────────────────
create or replace function public.mark_loan_paid_off(p_debt_id uuid, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  d   public.debts%rowtype;
  acc public.accounts%rowtype;
  v_actor uuid := auth.uid();
  v_owed numeric;
begin
  if v_actor is null then raise exception 'not_authorized' using errcode = '42501'; end if;
  select * into d from public.debts where id = p_debt_id and deleted_at is null for update;
  if not found then raise exception 'debt_unavailable' using errcode = '22023'; end if;
  perform 1 from public.memberships
   where household_id = d.household_id and user_id = v_actor and role in ('owner', 'admin', 'member');
  if not found then raise exception 'not_authorized' using errcode = '42501'; end if;
  if coalesce(d.direction, 'owed_by_me') <> 'owed_by_me' then raise exception 'not_a_loan' using errcode = '22023'; end if;

  -- Reconcile, never post: the outstanding goes to zero through the account's offset, with a dated log.
  acc := public.loan_account_for(d);
  v_owed := -public.loan_ledger_balance(acc.id);
  if v_owed <> 0 then
    update public.accounts
       set reconciliation_offset = coalesce(reconciliation_offset, 0) + v_owed,
           reconciliation_log = coalesce(reconciliation_log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
             'at', now(), 'delta', v_owed, 'kind', 'loan', 'stated_value', 0,
             'note', coalesce(nullif(btrim(p_note), ''), 'Marked paid off'))),
           last_reconciled_at = now(), updated_at = now()
     where id = acc.id;
  end if;
  update public.accounts set is_archived = true, updated_at = now() where id = acc.id;
  update public.debts
     set current_balance = 0, due_date = null, auto_record = false,
         paid_off_at = coalesce(paid_off_at, now()), updated_at = now()
   where id = d.id
  returning * into d;
  return jsonb_build_object('status', 'paid_off', 'written_off', v_owed, 'debt', to_jsonb(d));
end;
$$;

create or replace function public.loan_outstanding(p_debt public.debts)
returns numeric language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(
    (select greatest(0, -public.loan_ledger_balance(a.id)) from public.accounts a
      where a.debt_id = p_debt.id and a.kind = 'loan' and a.deleted_at is null order by a.created_at limit 1),
    p_debt.current_balance)
$$;

create or replace function public.delete_debt(p_debt_id uuid)
returns jsonb
language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  d public.debts%rowtype;
  v_actor uuid := auth.uid();
  v_owed numeric;
begin
  if v_actor is null then raise exception 'not_authorized' using errcode = '42501'; end if;
  select * into d from public.debts where id = p_debt_id and deleted_at is null for update;
  if not found then return jsonb_build_object('status', 'already_deleted'); end if;
  perform 1 from public.memberships
   where household_id = d.household_id and user_id = v_actor and role in ('owner', 'admin', 'member');
  if not found then raise exception 'not_authorized' using errcode = '42501'; end if;
  if coalesce(d.direction, 'owed_by_me') = 'owed_by_me' then
    v_owed := public.loan_outstanding(d);
    if v_owed > 0 then raise exception 'debt_not_paid_off' using errcode = 'P0001', detail = v_owed::text; end if;
    update public.accounts set is_archived = true, updated_at = now()
     where debt_id = d.id and kind = 'loan' and deleted_at is null;
  end if;
  update public.debts set deleted_at = now(), updated_at = now(),
         paid_off_at = case when coalesce(direction, 'owed_by_me') = 'owed_by_me' then coalesce(paid_off_at, now()) else paid_off_at end
   where id = d.id;
  return jsonb_build_object('status', 'deleted');
end;
$$;

-- Every other path (an older app's delete) is held to the same rule.
create or replace function public.debts_refuse_unpaid_delete()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
  -- A debt deleted ON ITS OWN is guarded. A household being deleted (the account purge, W1b) takes its
  -- debts with it by cascade: by then the household row is already gone, and that must not be blocked.
  if (tg_op = 'DELETE' or (new.deleted_at is not null and old.deleted_at is null))
     and coalesce(old.direction, 'owed_by_me') = 'owed_by_me' and old.type <> 'credit_card'
     and exists (select 1 from public.households h where h.id = old.household_id)
     and public.loan_outstanding(old) > 0 then
    raise exception 'debt_not_paid_off' using errcode = 'P0001';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;
drop trigger if exists trg_debts_refuse_unpaid_delete on public.debts;
create trigger trg_debts_refuse_unpaid_delete
  before update of deleted_at or delete on public.debts
  for each row execute function public.debts_refuse_unpaid_delete();

-- ── 7. Credit cards are accounts (D30) ──────────────────────────────────────────────────────
create or replace function public.move_card_debt_to_account(p_debt_id uuid)
returns uuid language plpgsql security definer set search_path = public, pg_temp as $$
declare
  d public.debts%rowtype;
  v_acc uuid;
  v_currency text;
begin
  select * into d from public.debts where id = p_debt_id for update;
  if not found or d.type is distinct from 'credit_card' or coalesce(d.direction, 'owed_by_me') <> 'owed_by_me'
     or d.deleted_at is not null then
    return null;
  end if;
  -- The card account already linked to it holds the outstanding (net worth already counted it once).
  select id into v_acc from public.accounts
   where debt_id = d.id and kind = 'credit_card' and deleted_at is null order by created_at limit 1;
  if v_acc is null then
    select base_currency into v_currency from public.households where id = d.household_id;
    insert into public.accounts (household_id, kind, name, currency, opening_balance, debt_id, payment_modes)
      values (d.household_id, 'credit_card', d.name, v_currency, -d.current_balance, d.id, array['swipe', 'online'])
      returning id into v_acc;
  end if;
  update public.debts set deleted_at = now(), updated_at = now() where id = d.id;
  return v_acc;
end;
$$;

create or replace function public.debts_card_to_account()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
  perform public.move_card_debt_to_account(new.id);
  return null;
end;
$$;
drop trigger if exists trg_debts_card_to_account on public.debts;
create trigger trg_debts_card_to_account
  after insert on public.debts
  for each row when (new.type = 'credit_card' and new.deleted_at is null)
  execute function public.debts_card_to_account();

-- ── 8. Existing rows ────────────────────────────────────────────────────────────────────────
-- 8a. Cards move into card accounts.
select public.move_card_debt_to_account(id) from public.debts
 where type = 'credit_card' and coalesce(direction, 'owed_by_me') = 'owed_by_me' and deleted_at is null;

-- 8b. Every live loan gets its account, at the outstanding the household sees today (net worth unchanged:
--     the debt row counted it before; the account counts it now, once).
insert into public.accounts (household_id, kind, name, currency, opening_balance, debt_id)
select d.household_id, 'loan', d.name, h.base_currency, -d.current_balance, d.id
  from public.debts d join public.households h on h.id = d.household_id
 where d.deleted_at is null and coalesce(d.direction, 'owed_by_me') = 'owed_by_me' and d.type <> 'credit_card'
   and not exists (select 1 from public.accounts a where a.debt_id = d.id and a.kind = 'loan' and a.deleted_at is null);

-- 8c. Terms, estimated from what each loan recorded (terms_confirmed stays false until the owner
--     confirms them in the app, which shows them as estimates meanwhile).
update public.debts
   set tenure_months = (extras->>'tenureMonths')::integer
 where tenure_months is null and coalesce(extras->>'tenureMonths', '') ~ '^[0-9]{1,3}$'
   and (extras->>'tenureMonths')::integer between 1 and 600;
update public.debts d
   set instalments_paid = greatest(0, coalesce(
         d.tenure_months - coalesce(
           case when coalesce(d.extras->>'remainingMonths', '') ~ '^[0-9]{1,3}$' then (d.extras->>'remainingMonths')::integer end,
           public.loan_instalments_left(public.loan_outstanding(d), d.interest_rate, d.minimum_payment)),
         (select count(*) from public.loan_payment_events e where e.debt_id = d.id)::integer, 0))
 where d.deleted_at is null and coalesce(d.direction, 'owed_by_me') = 'owed_by_me' and d.type <> 'credit_card';
update public.debts
   set first_emi_date = (due_date - make_interval(months => instalments_paid))::date
 where first_emi_date is null and due_date is not null and deleted_at is null
   and coalesce(direction, 'owed_by_me') = 'owed_by_me' and type <> 'credit_card';
update public.debts d
   set paid_off_at = now()
 where d.deleted_at is null and d.paid_off_at is null and coalesce(d.direction, 'owed_by_me') = 'owed_by_me'
   and d.type <> 'credit_card' and public.loan_outstanding(d) = 0;

-- 8d. The payment log a debt kept in its extras becomes events (history only: no entries are posted).
insert into public.loan_payment_events (operation_id, household_id, debt_id, amount, interest, principal,
                                        request, kind, payment_date, created_at)
select case when x.e->>'id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            then (x.e->>'id')::uuid else gen_random_uuid() end,
       d.household_id, d.id,
       coalesce((x.e->>'amount')::numeric, 0), coalesce((x.e->>'interest')::numeric, 0),
       coalesce((x.e->>'principal')::numeric, 0),
       jsonb_build_object('legacy', true, 'entry', x.e), 'legacy',
       case when coalesce(x.e->>'date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' then left(x.e->>'date', 10)::date end,
       coalesce(case when coalesce(x.e->>'date', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}' then left(x.e->>'date', 10)::timestamptz end, d.created_at)
  from public.debts d
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(d.extras->'paymentLog') = 'array' then d.extras->'paymentLog' else '[]'::jsonb end) as x(e)
 where not exists (select 1 from public.loan_payment_events p
                    where p.operation_id::text = x.e->>'id')
on conflict (operation_id) do nothing;

-- ── 9. Who may call what ────────────────────────────────────────────────────────────────────
revoke all on function public.loan_payment_core(uuid, uuid, uuid, text, numeric, date, uuid, uuid, text, text, numeric, numeric) from public, anon, authenticated;
grant execute on function public.loan_payment_core(uuid, uuid, uuid, text, numeric, date, uuid, uuid, text, text, numeric, numeric) to service_role;
revoke all on function public.pay_loan(uuid, uuid, text, numeric, date, uuid, uuid, text, text, numeric, numeric) from public, anon;
grant execute on function public.pay_loan(uuid, uuid, text, numeric, date, uuid, uuid, text, text, numeric, numeric) to authenticated;
revoke all on function public.reverse_loan_payment(uuid) from public, anon;
grant execute on function public.reverse_loan_payment(uuid) to authenticated;
revoke all on function public.mark_loan_paid_off(uuid, text) from public, anon;
grant execute on function public.mark_loan_paid_off(uuid, text) to authenticated;
revoke all on function public.delete_debt(uuid) from public, anon;
grant execute on function public.delete_debt(uuid) to authenticated;
revoke all on function public.loan_due(uuid, date) from public, anon;
grant execute on function public.loan_due(uuid, date) to authenticated;
revoke all on function public.loan_instalment_state(public.debts, numeric, integer, date) from public, anon, authenticated;
revoke all on function public.move_card_debt_to_account(uuid) from public, anon, authenticated;
revoke all on function public.loan_account_for(public.debts) from public, anon, authenticated;
revoke all on function public.loan_ledger_balance(uuid) from public, anon, authenticated;
revoke all on function public.loan_outstanding(public.debts) from public, anon, authenticated;
revoke all on function public.loan_payment_result(text, uuid) from public, anon, authenticated;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261017120000_w4g_loan_automation.sql
-- ─────────────────────────────────────────────────────────────────────
-- W4g (v10.76.0) — loans run themselves (owner decision D19; audit BE-WA-08, INT-TXN-07).
--
--   1. whatsapp_pay_loan — "paid car EMI 15000" on WhatsApp pays the loan's due instalment through
--      loan_payment_core (the server's split: interest first, then principal). Before, the parser
--      called it a Loan / EMI expense and whatsapp_log_transaction booked the WHOLE EMI as spending,
--      never touching the loan. The message is claimed first, so a replay never pays twice; a refusal
--      (more than due, paid off, no account to pay from) comes back with its figure for the reply.
--   2. auto_record_due_emis — a loan with auto_record on has each EMI recorded ON ITS DATE (in the
--      household's zone, W3a) from its funding account, by pg_cron every 30 minutes. The operation id
--      is the loan + instalment, so a second run never records it twice. A loan whose funding account
--      is gone is skipped and counted, never half-recorded.
--   3. EMI recurring schedules move onto their loan: the loan takes the schedule's auto-approve and
--      its paying account, and the schedule is closed. (An EMI schedule posted the whole EMI as one
--      expense; the app stopped posting them in v10.75.0.) A schedule naming no live loan is left for
--      the app to flag.
--   4. record_loan_payment is dropped: the app stopped calling it in v10.75.0 (pay_loan replaced it).

-- ── 1. Paying a loan from WhatsApp ─────────────────────────────────────────────────────────
create or replace function public.whatsapp_pay_loan(
  p_profile_id    uuid,
  p_household_id  uuid,
  p_debt_id       uuid,
  p_amount        numeric,
  p_date          date,
  p_wa_message_id text,
  p_account_alias text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_member  uuid;
  v_role    text;
  v_claimed int;
  d         public.debts%rowtype;
  v_funding uuid;
  v_result  jsonb;
  v_code    text;
  v_detail  text;
begin
  -- 1. Claim the message, exactly as whatsapp_log_transaction does.
  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;
  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then return jsonb_build_object('status', 'duplicate'); end if;

  -- 2. A write role in this household.
  select id, role into v_member, v_role from public.memberships
   where household_id = p_household_id and user_id = p_profile_id limit 1;
  if v_member is null then return jsonb_build_object('status', 'error', 'reason', 'not_a_member'); end if;
  if v_role = 'viewer' then return jsonb_build_object('status', 'error', 'reason', 'read_only_member'); end if;

  select * into d from public.debts where id = p_debt_id and household_id = p_household_id and deleted_at is null;
  if not found then return jsonb_build_object('status', 'error', 'reason', 'debt_unavailable'); end if;

  -- 3. The account it was paid from: the one named, else the loan's own, else the household default.
  if nullif(btrim(p_account_alias), '') is not null then
    select id into v_funding from public.accounts
     where household_id = p_household_id and kind in ('bank', 'cash') and deleted_at is null and not is_archived
       and lower(name) like '%' || lower(btrim(p_account_alias)) || '%'
     order by is_default desc, created_at limit 1;
  end if;
  v_funding := coalesce(v_funding,
    (select id from public.accounts where id = d.funding_account_id and kind in ('bank', 'cash') and deleted_at is null and not is_archived),
    (select id from public.accounts where household_id = p_household_id and kind in ('bank', 'cash') and deleted_at is null
        and not is_archived order by is_default desc, (kind = 'bank') desc, created_at limit 1));

  -- 4. The server's split. A refusal is an answer, not a failure: the message stays claimed.
  begin
    v_result := public.loan_payment_core(p_profile_id, md5('wa-loan:' || p_wa_message_id)::uuid, d.id, 'emi',
      p_amount, coalesce(p_date, (now() at time zone 'Asia/Kolkata')::date), v_funding, v_member, null, null, null, null);
  exception when sqlstate '22023' or sqlstate '42501' then
    get stacked diagnostics v_code = message_text, v_detail = pg_exception_detail;
    return jsonb_build_object('status', 'refused', 'reason', v_code, 'figure', nullif(v_detail, ''),
      'loan', d.name);
  end;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('loan_payment',
           jsonb_build_object('debt_id', d.id, 'operation_id', v_result->>'operation_id'))
   where wa_message_id = p_wa_message_id;
  return v_result || jsonb_build_object('loan', d.name);
end;
$$;

revoke all on function public.whatsapp_pay_loan(uuid, uuid, uuid, numeric, date, text, text) from public, anon, authenticated;
grant execute on function public.whatsapp_pay_loan(uuid, uuid, uuid, numeric, date, text, text) to service_role;

-- ── 2. EMIs recorded on their date ─────────────────────────────────────────────────────────
create or replace function public.auto_record_due_emis(p_limit integer default 500)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  d        record;
  cur      public.debts%rowtype;
  s        record;
  v_actor  uuid;
  v_today  date;
  v_scale  integer;
  v_owed   numeric;
  v_left   numeric;
  v_posted integer := 0;
  v_errors integer := 0;
  v_steps  integer;
begin
  for d in
    select x.id, x.household_id, coalesce(nullif(h.timezone, ''), 'Asia/Kolkata') as tz, h.base_currency
      from public.debts x join public.households h on h.id = x.household_id
     where x.deleted_at is null and x.auto_record and x.paid_off_at is null
       and coalesce(x.direction, 'owed_by_me') = 'owed_by_me' and x.due_date is not null
       and x.due_date <= (now() at time zone coalesce(nullif(h.timezone, ''), 'Asia/Kolkata'))::date
     order by x.due_date
     limit greatest(1, p_limit)
  loop
    v_today := (now() at time zone d.tz)::date;
    v_scale := public.loan_minor_scale(d.base_currency);
    -- Recorded as the household's owner (the person who answers for its books).
    select user_id into v_actor from public.memberships
     where household_id = d.household_id and role = 'owner' and user_id is not null order by joined_at limit 1;
    if v_actor is null then v_errors := v_errors + 1; continue; end if;
    v_steps := 0;
    -- A loan a few EMIs behind catches up, one instalment at a time (bounded).
    loop
      select * into cur from public.debts where id = d.id;
      exit when not cur.auto_record or cur.paid_off_at is not null or cur.due_date is null or cur.due_date > v_today or v_steps >= 6;
      v_owed := public.loan_outstanding(cur);
      exit when v_owed <= 0;
      select * into s from public.loan_instalment_state(cur, v_owed, v_scale, cur.due_date);
      v_left := greatest(s.due - s.paid, 0);
      exit when v_left <= 0;
      begin
        perform public.loan_payment_core(v_actor, md5('auto-emi:' || cur.id || ':' || s.instalment_no)::uuid, cur.id, 'emi',
          v_left, cur.due_date, cur.funding_account_id, null, cur.name || ' EMI', null, null, null);
        v_posted := v_posted + 1;
      exception when others then
        v_errors := v_errors + 1;
        exit;
      end;
      v_steps := v_steps + 1;
    end loop;
  end loop;
  return jsonb_build_object('posted', v_posted, 'errors', v_errors);
end;
$$;

revoke all on function public.auto_record_due_emis(integer) from public, anon, authenticated;
grant execute on function public.auto_record_due_emis(integer) to service_role;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'loan-auto-record';
    perform cron.schedule('loan-auto-record', '20,50 * * * *', 'select public.auto_record_due_emis()');
  end if;
end;
$$;

-- ── 3. EMI schedules move onto their loan ─────────────────────────────────────────────────
with emi as (
  select r.id, r.active, r.auto_confirm, r.txn_template->>'accountId' as account_text,
         coalesce(nullif(r.txn_template->>'linkedDebtId', ''), nullif(r.txn_template->>'debtId', '')) as debt_text
    from public.recurring_schedules r
   where r.deleted_at is null and r.txn_template->>'category' = 'loan_emi'
), resolved as (
  select e.*, d.id as debt_id, d.household_id
    from emi e join public.debts d
      on e.debt_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     and d.id = e.debt_text::uuid and d.deleted_at is null and coalesce(d.direction, 'owed_by_me') = 'owed_by_me'
), moved as (
  update public.debts d
     set auto_record = d.auto_record or (r.active and r.auto_confirm),
         funding_account_id = coalesce(d.funding_account_id, (
           select a.id from public.accounts a
            where r.account_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              and a.id = r.account_text::uuid and a.household_id = d.household_id
              and a.kind in ('bank', 'cash') and a.deleted_at is null and not a.is_archived)),
         updated_at = now()
    from resolved r
   where d.id = r.debt_id
  returning d.id
)
-- Every resolved schedule closes (two schedules for one loan included); the loan update above runs once.
update public.recurring_schedules set deleted_at = now(), active = false, updated_at = now()
 where id in (select id from resolved) and exists (select 1 from moved);

-- ── 4. The client-computed payment command is gone ────────────────────────────────────────
drop function if exists public.record_loan_payment(uuid, uuid, uuid, numeric, text, date, numeric, numeric, uuid, text, numeric, integer, numeric, jsonb);

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261018120000_erase_household_complete.sql
-- ─────────────────────────────────────────────────────────────────────
-- "Erase all data" works for a household with a loan, and erases everything (audit 2026-10-04
-- follow-up R1, XC-PRV-08, DB-SEC-08; owner decisions 13 Oct 2026).
--
-- What was wrong:
--   • R1 (regression from W4e, 20261016120000): erase_household_data deleted the debts while the
--     loan account still existed. debts_refuse_unpaid_delete saw money owed and raised
--     debt_not_paid_off, so the WHOLE erase rolled back for any household with an unpaid loan.
--     Reordering alone does not help: once the loan account is gone, loan_outstanding falls back to
--     the cached debts.current_balance.
--   • XC-PRV-08 / DB-SEC-08: the erase left notifications (amounts, payees), open WhatsApp
--     questions, Pip agent conversations, relay messages (question text), loan payment history and
--     the household's shared splits behind.
--
-- Now (owner decisions, 13 Oct 2026):
--   • Inside the erase only, the loans are cleared first: the loan accounts go, the cached balance
--     is zeroed, then the debts go. The guard still protects every other delete of a debt.
--   • Every household table that holds the household's money or words is erased. Kept: the
--     household row, memberships, invitations, subscriptions, WhatsApp links and preferences, push
--     subscriptions, and usage metering without text (ai_usage, ai_feedback); exchange_rates is
--     unused. react/src/lib/__tests__/eraseHouseholdSql.test.ts fails when a new household table is
--     in neither list.
--   • The household's shared splits are DELETED, for everyone in them (owner's choice).
--   • The re-authentication rule (W1b) and the owner/admin check are unchanged.

BEGIN;

create or replace function erase_household_data(h_id uuid)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  caller_role text;
begin
  select role into caller_role
  from memberships
  where household_id = h_id and user_id = auth.uid()
  limit 1;

  if caller_role is null or caller_role not in ('owner', 'admin') then
    raise exception 'not authorized to erase this household''s data';
  end if;
  if not public.recently_reauthenticated() then
    raise exception 'reauth_required' using errcode = '42501',
      hint = 'Confirm with the emailed code, then erase within 10 minutes.';
  end if;

  -- Splits shared with people outside the household: deleted for everyone (shares cascade).
  delete from shared_splits        where owner_household_id = h_id;

  delete from transactions         where household_id = h_id;
  delete from budgets              where household_id = h_id;
  delete from budget_allocations   where household_id = h_id;
  delete from goals                where household_id = h_id;

  -- Loans first (R1): with no transactions left, a loan account still holds its opening balance, so
  -- debts_refuse_unpaid_delete would see money owed. Remove the loan accounts, zero the cached
  -- balance the guard falls back to, then delete the debts.
  delete from loan_payment_events  where household_id = h_id;
  delete from accounts             where household_id = h_id and kind = 'loan';
  update debts set current_balance = 0 where household_id = h_id;
  delete from debts                where household_id = h_id;

  delete from assets               where household_id = h_id;
  delete from accounts             where household_id = h_id;
  delete from recurring_schedules  where household_id = h_id;
  delete from saved_views          where household_id = h_id;
  delete from net_worth_snapshots  where household_id = h_id;
  delete from notifications        where household_id = h_id;
  delete from whatsapp_inbound_messages where household_id = h_id;
  delete from whatsapp_pending_turns    where household_id = h_id;
  delete from whatsapp_rule_state       where household_id = h_id;
  delete from agent_pending_intents     where household_id = h_id;
  delete from agent_conversations       where household_id = h_id;
  delete from ask_vyact_relay           where household_id = h_id;
  delete from activity_log         where household_id = h_id;

  update households set onboarding = '{}'::jsonb where id = h_id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id, changes)
  values (h_id, auth.uid(), 'deleted', 'household', h_id,
          jsonb_build_object('kind', 'erase_household_data', 'erased_at', now()));
end;
$$;

revoke all on function erase_household_data(uuid) from public;
revoke all on function erase_household_data(uuid) from anon;
grant execute on function erase_household_data(uuid) to authenticated;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261019120000_whatsapp_correct_to_loan.sql
-- ─────────────────────────────────────────────────────────────────────
-- A WhatsApp "no, that was loan emi" correction becomes a real loan payment (BE-WA-08, INT-TXN-07;
-- owner decisions 13 Oct 2026).
--
-- What was wrong: whatsapp_correct_last re-categorised the entry WhatsApp had just logged to any
-- category, Loan / EMI included. A ₹15,000 expense relabelled as Loan / EMI stayed one plain expense:
-- the whole amount counted as spending and the loan's outstanding never moved, so Debts, the loan's
-- schedule and the budget disagreed with what was paid.
--
-- Now:
--   1. whatsapp_correct_to_loan turns that entry into a payment on the loan the person chose, in ONE
--      transaction: the payment goes through loan_payment_core (W4e: interest first, then principal, the
--      instalment's rules, the next due date and the months left), and the plain expense is
--      soft-deleted. Its operation id is the entry, so it can never be paid twice. A refusal (more than
--      the instalment due, a part-paid instalment, a paid-off loan, no account) changes nothing and is
--      returned with its figure for the reply. It acts only on the entry WhatsApp logged for this
--      person in the last 15 minutes (whatsapp_last_logged), like UNDO.
--   2. whatsapp_correct_last refuses 'loan_emi' (status 'use_loan_payment'): defence in depth; the
--      webhook routes an EMI correction to (1).
--   3. A new pending question, 'emi_loan_choice': "Which loan?" when the household has several and the
--      message names none.
--
-- MONEY MODEL: one loan payment (an interest expense + a principal transfer into the loan account,
-- the W4e shape) replaces one plain expense of the same amount, date and paying account. Nothing else.

BEGIN;

alter table public.whatsapp_pending_turns drop constraint if exists ck_wa_pending_kind;
alter table public.whatsapp_pending_turns add constraint ck_wa_pending_kind
  check (kind in ('missing_amount', 'duplicate_check', 'chips', 'reads_offer', 'name_entries', 'balance_update',
                  'emi_loan_choice'));

create or replace function public.whatsapp_correct_to_loan(
  p_profile_id    uuid,
  p_household_id  uuid,
  p_debt_id       uuid,
  p_wa_message_id text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_block  text;
  l        record;
  t        public.transactions%rowtype;
  d        public.debts%rowtype;
  v_member uuid;
  v_result jsonb;
  v_code   text;
  v_detail text;
begin
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select * into l from public.whatsapp_last_logged(p_profile_id, p_household_id, p_wa_message_id);
  if l.reason is not null then return jsonb_build_object('status', l.reason); end if;

  select * into t from public.transactions where id = l.txn_id;
  if t.type is distinct from 'expense' then return jsonb_build_object('status', 'not_an_expense'); end if;
  select * into d from public.debts
   where id = p_debt_id and household_id = p_household_id and deleted_at is null;
  if not found then return jsonb_build_object('status', 'error', 'reason', 'debt_unavailable'); end if;
  select id into v_member from public.memberships
   where household_id = p_household_id and user_id = p_profile_id limit 1;

  -- The server's split, for the entry's own amount, date and paying account. A refusal is an answer:
  -- the payment's savepoint rolls back and the entry stays as it was.
  begin
    v_result := public.loan_payment_core(p_profile_id, md5('wa-correct-emi:' || t.id::text)::uuid, d.id, 'emi',
      t.amount, t.date, t.account_id, v_member, null, null, null, null);
  exception when sqlstate '22023' or sqlstate '42501' then
    get stacked diagnostics v_code = message_text, v_detail = pg_exception_detail;
    return jsonb_build_object('status', 'refused', 'reason', v_code, 'figure', nullif(v_detail, ''),
      'loan', d.name, 'amount', t.amount, 'currency', t.currency);
  end;

  -- The plain expense goes: the payment above replaces it (one entry, never both).
  update public.transactions set deleted_at = now() where id = t.id;
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('undone', now(),
           'converted_to_loan', jsonb_build_object('debt_id', d.id, 'operation_id', v_result->>'operation_id'))
   where wa_message_id = l.inbox_id;
  return v_result || jsonb_build_object('loan', d.name, 'amount', t.amount, 'currency', t.currency);
end;
$$;

revoke all on function public.whatsapp_correct_to_loan(uuid, uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.whatsapp_correct_to_loan(uuid, uuid, uuid, text) to service_role;

-- Body as 20260928120000 (W3), plus: an EMI is never a category change.
create or replace function public.whatsapp_correct_last(
  p_profile_id uuid, p_household_id uuid, p_category text, p_wa_message_id text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_block text; l record; v_type text; t record;
begin
  -- An EMI pays a loan (whatsapp_correct_to_loan); relabelling a plain expense would book it whole as
  -- spending and leave the loan untouched.
  if p_category = 'loan_emi' then return jsonb_build_object('status', 'use_loan_payment'); end if;
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select * into l from public.whatsapp_last_logged(p_profile_id, p_household_id, p_wa_message_id);
  if l.reason is not null then return jsonb_build_object('status', l.reason); end if;

  select type into v_type from public.transactions where id = l.txn_id;
  -- Only an expense or an income carries a category; the caller checked the id is
  -- one of that type's categories.
  if v_type not in ('expense', 'income') then return jsonb_build_object('status', 'no_category'); end if;
  update public.transactions set category = p_category
   where id = l.txn_id returning amount, currency, type, category, updated_at into t;
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('corrected_at', t.updated_at)
   where wa_message_id = l.inbox_id;
  return jsonb_build_object('status', 'corrected', 'transaction_id', l.txn_id,
    'amount', t.amount, 'currency', t.currency, 'type', t.type, 'category_id', t.category);
end;
$$;

revoke all on function public.whatsapp_correct_last(uuid, uuid, text, text) from public, anon, authenticated;
grant execute on function public.whatsapp_correct_last(uuid, uuid, text, text) to service_role;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261020120000_admin_activity_feed.sql
-- ─────────────────────────────────────────────────────────────────────
-- ADM-03 / FE-PUB-01, step 1 of 2 (v10.92.0; owner decision 13 Oct 2026): platform admins see WHO did
-- WHAT and WHEN in a household's activity log, never the values.
--
-- activity_log.changes holds row images: amounts, payees, descriptions, names. The admin Audit page
-- reads the table directly (`activity_log_read`: is_member(household_id) OR is_admin('roles')), so a
-- roles-tier admin could read every household's values. W1a (D24) stopped admin reads of the ledger
-- tables; this table was left for the next step.
--
-- This migration adds the server feed the Audit page will use. It returns the time, the household, the
-- actor, the action, the entity type and the entity id, and never `changes`. It changes nothing else:
-- the admin page still reads the table until step 2, so the page is never empty in between.
--
-- Step 2 (the admin app PR) switches the Audit page and its CSV to this function, then narrows
-- `activity_log_read` to members only. That migration must not ship before this one is live.

BEGIN;

create or replace function public.admin_activity_feed(p_limit integer default 200, p_before timestamptz default null)
  returns table (id uuid, created_at timestamptz, household_id uuid, actor_id uuid,
                 action text, entity_type text, entity_id uuid)
  language plpgsql stable security definer set search_path = public, pg_temp
as $$
begin
  if not public.is_admin('roles') then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;

  -- Newest first. p_before pages back: the next page starts below the oldest row already shown.
  -- Every column is named on purpose: `changes` must never be added here.
  return query
    select a.id, a.created_at, a.household_id, a.actor_id, a.action, a.entity_type, a.entity_id
      from public.activity_log a
     where p_before is null or a.created_at < p_before
     order by a.created_at desc, a.id desc
     limit least(greatest(coalesce(p_limit, 200), 1), 1000);
end $$;

-- Not reachable without signing in (v10.22 rule: revoke the PUBLIC default anon inherits).
revoke all on function public.admin_activity_feed(integer, timestamptz) from public, anon;
grant execute on function public.admin_activity_feed(integer, timestamptz) to authenticated, service_role;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261021120000_activity_log_members_only.sql
-- ─────────────────────────────────────────────────────────────────────
-- ADM-03 / FE-PUB-01, step 2 of 2 (v10.93.0, admin v1.4.5; owner decision 13 Oct 2026): platform admins
-- see who did what and when in a household's activity log, never the values.
--
-- Step 1 (20261020120000_admin_activity_feed.sql, v10.92.0) added `admin_activity_feed`, which returns
-- the time, household, actor, action and entity, and never `changes`. The admin Audit page reads it from
-- admin v1.4.5. This migration closes the direct read: `activity_log_read` was
-- `is_member(household_id) or is_admin('roles')`, so a roles-tier admin could still select every
-- household's rows, row images (`changes`) included. It becomes members only.
--
-- Members are unaffected: the household Activity panel reads its own household's log as before.
-- Ship order: step 1 must be live first; the admin page no longer reads the table.

BEGIN;

-- Sweep: drop EVERY select policy on activity_log that calls is_admin, not just the ones the
-- migrations name. Production holds objects no migration creates (docs/DEVELOPER_INPUTS.md Q1), so a
-- name list could leave a prod-only admin read in place (the W1a pattern).
do $$
declare p record;
begin
  for p in
    select schemaname, tablename, policyname from pg_policies
     where schemaname = 'public' and tablename = 'activity_log' and cmd = 'SELECT' and qual ilike '%is_admin%'
  loop
    execute format('drop policy %I on %I.%I', p.policyname, p.schemaname, p.tablename);
  end loop;
end $$;

drop policy if exists "activity_log_read" on public.activity_log;
create policy "activity_log_read" on public.activity_log for select to authenticated
  using (public.is_member(household_id));

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261022120000_invitation_inbox.sql
-- ─────────────────────────────────────────────────────────────────────
-- #9, step 1 of 2 (v10.94.0; owner decisions 13 Oct 2026): an invitation can be addressed to a
-- person, who is emailed and finds it in their bell (Accept / Decline). Inviters keep Revoke.
--
-- Until now an invitation was a shareable link only. `invited_email` never held an email: it holds
-- the label the inviter typed ("Partner", "Mom") or "(shareable link)". So nothing could tell the
-- invitee about it except the link itself.
--
--   1. invitations.recipient_email: the invitee's address, lower-case and email-shaped, or null
--      for a link-only invitation. Existing rows are untouched (all null); `invited_email` stays the
--      label.
--   2. my_pending_invitations(): the caller's own pending invitations, matched on the caller's
--      CONFIRMED email (an unconfirmed sign-up with someone else's address sees nothing). It returns
--      the household's name and type, who invited them, the role and the expiry, never the token.
--   3. accept_invitation_by_id(id): the link accept's rules (the same membership insert, so the same
--      HOUSEHOLD_FULL limit), for an invitation addressed to the caller. The row is locked so a
--      double tap joins once.
--   4. decline_invitation(id): the invitee removes an invitation addressed to them.
--   5. accept_invitation_link: an invitation with no relationship label joined with
--      household_role 'member', which the memberships check refuses, so that join failed. A missing
--      or unknown label is now stored as null (the check allows it). The app always sends a label,
--      so nobody hit it.
--   6. invite_email_log + claim_invite_email(): send-invite-email claims before it sends. One email
--      per invitation, ever, and a daily cap per sender. A revoked invitation keeps its log row
--      (invitation_id set to null), so revoking and re-inviting does not reset the cap. Service role
--      only; the log holds ids and a time, never an address.
--   7. purge_account: deleting an account also deletes pending invitations addressed to it.

BEGIN;

-- ── 1. The invitee's address ────────────────────────────────────────────────────────────
alter table public.invitations add column if not exists recipient_email text;
alter table public.invitations drop constraint if exists ck_invitation_recipient_email;
alter table public.invitations add constraint ck_invitation_recipient_email check (
  recipient_email is null or (
    recipient_email = lower(btrim(recipient_email))
    and length(recipient_email) <= 254
    and recipient_email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
  ));
create index if not exists invitations_recipient_idx
  on public.invitations (recipient_email) where accepted_at is null;

comment on column public.invitations.invited_email is
  'The label the inviter typed, or "(shareable link)". A legacy name: it is not the invitee''s address; that is recipient_email.';
comment on column public.invitations.recipient_email is
  'The invitee''s email (lower-case), when the invitation is addressed to a person (v10.94.0). Null for a link-only invitation.';

-- ── 2. The caller's confirmed email (internal: only the functions below call it) ────────
create or replace function public.my_verified_email()
  returns text
  language sql stable security definer set search_path = public, pg_temp
as $$
  select lower(email) from auth.users where id = auth.uid() and email_confirmed_at is not null;
$$;
revoke all on function public.my_verified_email() from public, anon, authenticated;

-- ── 3. Invitations addressed to me ──────────────────────────────────────────────────────
create or replace function public.my_pending_invitations()
  returns table (id uuid, household_id uuid, household_name text, household_type text,
                 invited_by_name text, role text, household_role text,
                 expires_at timestamptz, created_at timestamptz)
  language sql stable security definer set search_path = public, pg_temp
as $$
  select i.id, i.household_id, h.name, h.type,
         coalesce(nullif(btrim(p.display_name), ''), 'Someone'),
         i.role, i.household_role, i.expires_at, i.created_at
    from public.invitations i
    join public.households h on h.id = i.household_id
    left join public.profiles p on p.id = i.invited_by
   where i.recipient_email = public.my_verified_email()
     and i.accepted_at is null
     and i.expires_at > now()
     and not exists (select 1 from public.memberships m
                      where m.household_id = i.household_id and m.user_id = auth.uid())
   order by i.created_at desc;
$$;

-- ── 4. Accept one ───────────────────────────────────────────────────────────────────────
create or replace function public.accept_invitation_by_id(p_id uuid)
  returns jsonb
  language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  v_email text := public.my_verified_email();
  inv public.invitations%rowtype;
  existing public.memberships%rowtype;
  new_membership_id uuid;
begin
  if auth.uid() is null or v_email is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;

  select * into inv from public.invitations
   where id = p_id and recipient_email = v_email and accepted_at is null and expires_at > now()
   for update;
  if not found then
    raise exception 'invitation_not_found' using errcode = 'P0001';
  end if;

  select * into existing from public.memberships
   where household_id = inv.household_id and user_id = auth.uid();
  if found then
    update public.invitations set accepted_at = now() where id = inv.id;
    return jsonb_build_object('household_id', inv.household_id, 'membership_id', existing.id,
                              'role', existing.role, 'already_member', true);
  end if;

  -- The membership insert runs the HOUSEHOLD_FULL limit trigger, as the link accept does.
  insert into public.memberships (household_id, user_id, role, display_name, household_role)
  values (inv.household_id, auth.uid(), inv.role,
          coalesce((select nullif(btrim(display_name), '') from public.profiles where id = auth.uid()),
                   split_part(v_email, '@', 1)),
          case when inv.household_role in ('primary', 'partner', 'child', 'elder') then inv.household_role end)
  returning id into new_membership_id;

  update public.invitations set accepted_at = now() where id = inv.id;

  insert into public.activity_log (household_id, actor_id, action, entity_type, entity_id)
  values (inv.household_id, auth.uid(), 'accepted', 'invitation', inv.id);

  return jsonb_build_object('household_id', inv.household_id, 'membership_id', new_membership_id,
                            'role', inv.role, 'already_member', false);
end;
$$;

-- ── 5. Decline one ──────────────────────────────────────────────────────────────────────
create or replace function public.decline_invitation(p_id uuid)
  returns boolean
  language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  v_email text := public.my_verified_email();
begin
  if auth.uid() is null or v_email is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;
  delete from public.invitations
   where id = p_id and recipient_email = v_email and accepted_at is null;
  return found;
end;
$$;

revoke all on function public.my_pending_invitations() from public, anon;
revoke all on function public.accept_invitation_by_id(uuid) from public, anon;
revoke all on function public.decline_invitation(uuid) from public, anon;
grant execute on function public.my_pending_invitations() to authenticated, service_role;
grant execute on function public.accept_invitation_by_id(uuid) to authenticated, service_role;
grant execute on function public.decline_invitation(uuid) to authenticated, service_role;

-- ── 6. The link accept: a missing relationship label joins as null, not 'member' ────────
-- Unchanged otherwise (20260601153000_fix_shareable_invite_accept_rpc.sql).
create or replace function public.accept_invitation_link(invite_token text)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public, pg_temp
as $$
declare
  inv invitations%rowtype;
  caller_email text;
  existing memberships%rowtype;
  new_membership_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Must be signed in to accept an invitation';
  end if;

  select email into caller_email from auth.users where id = auth.uid();

  select * into inv
  from invitations
  where token = invite_token
    and accepted_at is null
    and expires_at > now();

  if not found then
    raise exception 'Invitation not found or expired';
  end if;

  select * into existing
  from memberships
  where household_id = inv.household_id
    and user_id = auth.uid();

  if found then
    update invitations set accepted_at = now() where id = inv.id;
    return jsonb_build_object(
      'household_id', inv.household_id,
      'membership_id', existing.id,
      'role', existing.role,
      'already_member', true
    );
  end if;

  insert into memberships (household_id, user_id, role, display_name, household_role)
  values (
    inv.household_id,
    auth.uid(),
    inv.role,
    coalesce((select display_name from profiles where id = auth.uid()), split_part(coalesce(caller_email, ''), '@', 1), 'member'),
    case when inv.household_role in ('primary', 'partner', 'child', 'elder') then inv.household_role end
  )
  returning id into new_membership_id;

  update invitations set accepted_at = now() where id = inv.id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id)
  values (inv.household_id, auth.uid(), 'accepted', 'invitation', inv.id);

  return jsonb_build_object(
    'household_id', inv.household_id,
    'membership_id', new_membership_id,
    'role', inv.role,
    'already_member', false
  );
end;
$$;

revoke all on function public.accept_invitation_link(text) from public, anon;
grant execute on function public.accept_invitation_link(text) to authenticated;

-- ── 7. The email claim ──────────────────────────────────────────────────────────────────
create table if not exists public.invite_email_log (
  id              bigint generated always as identity primary key,
  invitation_id   uuid references public.invitations(id) on delete set null,
  sender_user_id  uuid references auth.users(id) on delete cascade,
  created_at      timestamptz not null default now(),
  constraint uq_invite_email_once unique (invitation_id)
);
create index if not exists invite_email_log_sender_idx on public.invite_email_log (sender_user_id, created_at);

alter table public.invite_email_log enable row level security;
revoke all on table public.invite_email_log from public, anon, authenticated;
grant select, insert, delete on table public.invite_email_log to service_role;

-- 'claimed' (send it), 'already_sent' (this invitation was emailed before) or 'daily_limit'.
create or replace function public.claim_invite_email(p_sender uuid, p_invitation uuid, p_daily_cap int)
  returns text
  language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  v_used int;
begin
  if p_sender is null or p_invitation is null then
    raise exception 'invalid_claim' using errcode = '22023';
  end if;
  if p_daily_cap is null or p_daily_cap < 0 then
    raise exception 'invalid_cap' using errcode = '22023';
  end if;

  -- One sender at a time: two parallel calls cannot both see the same room under the cap.
  perform pg_advisory_xact_lock(hashtextextended('invite_email:' || p_sender::text, 0));

  if exists (select 1 from public.invite_email_log where invitation_id = p_invitation) then
    return 'already_sent';
  end if;

  select count(*) into v_used
    from public.invite_email_log
   where sender_user_id = p_sender and created_at > now() - interval '24 hours';
  if v_used >= p_daily_cap then
    return 'daily_limit';
  end if;

  insert into public.invite_email_log (invitation_id, sender_user_id) values (p_invitation, p_sender)
  on conflict (invitation_id) do nothing;
  if not found then
    return 'already_sent';
  end if;
  return 'claimed';
end;
$$;

revoke all on function public.claim_invite_email(uuid, uuid, int) from public, anon, authenticated;
grant execute on function public.claim_invite_email(uuid, uuid, int) to service_role;

-- ── 8. Deleting an account also removes invitations addressed to it ─────────────────────
-- Unchanged otherwise (20261010120000_w1b_account_purge.sql).
create or replace function public.purge_account(p_user_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email text;
  blocked uuid[];
  sole uuid[];
  n_households int := 0;
  n_memberships int := 0;
begin
  if p_user_id is null then
    raise exception 'invalid_user' using errcode = '22023';
  end if;

  -- D22: an owner may not leave members behind without an owner.
  select array_agg(m.household_id) into blocked
    from memberships m
   where m.user_id = p_user_id and m.role = 'owner'
     and exists (select 1 from memberships o where o.household_id = m.household_id and o.user_id <> p_user_id)
     and not exists (select 1 from memberships o
                      where o.household_id = m.household_id and o.user_id <> p_user_id and o.role = 'owner');
  if blocked is not null then
    raise exception 'transfer_required' using errcode = 'P0001', detail = array_to_string(blocked, ',');
  end if;

  -- Households where they are the only member: the household and everything in it goes
  -- (every household-scoped table cascades from households).
  select array_agg(m.household_id) into sole
    from memberships m
   where m.user_id = p_user_id
     and not exists (select 1 from memberships o where o.household_id = m.household_id and o.user_id <> p_user_id);
  if sole is not null then
    delete from households where id = any (sole);
    get diagnostics n_households = row_count;
  end if;

  -- Shared households: only their membership goes; the household keeps its history.
  delete from memberships where user_id = p_user_id;
  get diagnostics n_memberships = row_count;

  -- Personal rows that would otherwise wait for the auth delete (or outlive it).
  delete from whatsapp_inbound_messages where profile_id = p_user_id;
  delete from whatsapp_identities        where profile_id = p_user_id;
  delete from whatsapp_pending_turns     where profile_id = p_user_id;
  delete from whatsapp_verification_otps where profile_id = p_user_id;
  delete from whatsapp_preferences       where profile_id = p_user_id;
  delete from push_subscriptions         where user_id = p_user_id;

  select email into v_email from auth.users where id = p_user_id;
  if v_email is not null then
    delete from invitations
     where accepted_at is null
       and (lower(invited_email) = lower(v_email) or recipient_email = lower(v_email));
  end if;

  delete from profiles where id = p_user_id;

  return jsonb_build_object('status', 'purged', 'households_deleted', n_households,
                            'memberships_removed', n_memberships);
end;
$$;

revoke all on function public.purge_account(uuid) from public;
revoke all on function public.purge_account(uuid) from anon;
revoke all on function public.purge_account(uuid) from authenticated;
grant execute on function public.purge_account(uuid) to service_role;

COMMIT;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261023120000_retire_emi_schedules.sql
-- ─────────────────────────────────────────────────────────────────────
-- Track E, E6b (v10.101.0; owner decisions 13–14 Oct 2026: E-3 "retire the old EMI schedules",
-- E-11 "soft-delete them now, without a count first").
--
-- A loan's EMI is paid by the LOAN (`pay_loan`; `auto_record_due_emis` records it on its date when the
-- loan's auto_record is on), never by a recurring schedule. W4g (20261017120000) moved every EMI schedule
-- it could match to a live loan onto that loan and soft-deleted it. The ones left are those it could not
-- match: no loan link, a deleted loan, or a receivable. They no longer post (the app's engine and the
-- server's recurring-post job skip them: isLoanEmiSchedule / serverPostsSchedule), and since v10.100.0
-- (E6a) the app lists them nowhere (Recurring, the bill calendar, the bell).
--
-- This retires them in the database:
--   • the set is exactly the app's `isLoanEmiSchedule` (lib/recurring.ts): a template in Loan / EMI, or
--     one carrying a loan link (debtId / linkedDebtId), the schedules that read "no longer posts";
--   • a SOFT delete (deleted_at + active = false). The transactions any of them made keep their history
--     (their recurring_schedule_id is untouched), and nothing is recreated from other rows;
--   • updated_at moves, so every device drops its cached copy through the delta sync (a tombstone),
--     as W4g's soft delete did; no cache reset is needed;
--   • idempotent: a second run matches nothing.

update public.recurring_schedules
   set deleted_at = now(), active = false, updated_at = now()
 where deleted_at is null
   and (txn_template->>'category' = 'loan_emi'
        or nullif(txn_template->>'debtId', '') is not null
        or nullif(txn_template->>'linkedDebtId', '') is not null);

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261024120000_clear_orphan_loan_accounts.sql
-- ─────────────────────────────────────────────────────────────────────
-- Track E, E7 (v10.102.0; owner decisions: E-8 "only the orphan fix" (13 Oct 2026) and "reconcile to zero
-- + archive" (14 Oct 2026)). Audit FE-MNY-04, part 1.
--
-- Before v10.74.0 (W4e) a loan could be deleted while its loan ACCOUNT stayed live with a balance. A loan's
-- outstanding is its account's ledger, and net worth counts every liability account, archived or not
-- (lib/netWorth.ts liveLiabilityRows), so each such account kept a debt in net worth that no loan
-- explained: a phantom liability.
--
-- This clears them exactly as "Mark paid off" (`mark_loan_paid_off`) clears a loan:
--   • an orphan is a live `kind = 'loan'` account LINKED to a loan that has been deleted (`debt_id` set,
--     the debt soft-deleted). A loan account with no link at all is left alone: it may be a household's
--     only record of a real loan (the PR lists the read-only query to find any);
--   • its ledger goes to zero through the account's reconciliation OFFSET with a dated log entry
--     (kind 'loan', stated value 0), never a transaction; then it is archived. Its transactions and
--     history stay;
--   • net worth RISES by each orphan's leftover (the phantom debt leaves); no other figure moves;
--   • updated_at moves, so devices pick the change up through the delta sync;
--   • idempotent: a cleared, archived account is not touched again.

with orphans as (
  select a.id, -public.loan_ledger_balance(a.id) as owed
    from public.accounts a
    left join public.debts d on d.id = a.debt_id
   where a.kind = 'loan' and a.deleted_at is null and a.debt_id is not null
     and (d.id is null or d.deleted_at is not null)
)
update public.accounts a
   set reconciliation_offset = coalesce(a.reconciliation_offset, 0) + o.owed,
       reconciliation_log = case when o.owed <> 0
         then coalesce(a.reconciliation_log, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
           'at', now(), 'delta', o.owed, 'kind', 'loan', 'stated_value', 0,
           'note', 'Loan deleted before v10.74: balance cleared'))
         else a.reconciliation_log end,
       last_reconciled_at = case when o.owed <> 0 then now() else a.last_reconciled_at end,
       is_archived = true,
       updated_at = now()
  from orphans o
 where a.id = o.id and (o.owed <> 0 or not a.is_archived);

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261026120000_bedrock_nova_lite.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.106.1 · Amazon Nova Lite on Bedrock for Pip (owner, 16 Oct 2026: "Bedrock's Nova Lite will power Pip").
--
-- Adds ONE model row, DISABLED, like every catalogue row (20260906140000_seed_model_catalogue.sql): this
-- migration changes what Pip does by exactly zero. It goes live with one UPDATE once the AWS secrets
-- are set on the Edge Functions (see the end of this file).
--
-- THE ROUTE
--   provider 'bedrock' is the router's one non-OpenAI path (supabase/functions/_shared/agent/bedrock.ts):
--   Bedrock's Converse API at https://bedrock-runtime.<region>.amazonaws.com/model/<model>/converse.
--   Region: Asia Pacific (Sydney), ap-southeast-2, which serves Nova Lite in-region under the plain id
--   `amazon.nova-lite-v1:0` (owner's choice). The router reads the region from base_url.
--
-- AUTH
--   key_env_var 'AWS_ACCESS_KEY_ID' means: sign with AWS Signature Version 4 using the Edge Function
--   secrets AWS_ACCESS_KEY_ID + AWS_SECRET_ACCESS_KEY (+ AWS_SESSION_TOKEN if set). The keys belong to an
--   IAM user allowed only `bedrock:InvokeModel` on Nova Lite. NO SECRET IS STORED HERE; the router refuses
--   AWS credential names on any row that is not provider 'bedrock' with a bedrock-runtime host.
--   (A Bedrock API key also works: set key_env_var to 'AWS_BEARER_TOKEN_BEDROCK'.)
--
-- PRICING (operational spend for ai_usage.cost_usd, never ledger money): Nova Lite on demand, about
--   $0.063 per million input and $0.252 per million output tokens in Asia Pacific (third-party price
--   trackers, June 2026; confirm on the AWS pricing page). Cheap enough that a Pip answer (~1,500 tokens
--   in, ~150 out) costs about $0.00013.
--
-- PRIORITY 120: above the OpenRouter row enabled today (110), so enabling this row makes it Pip's model
--   for every user without touching the other row. The test-only Claude Code relay (200, one allowlisted
--   user, TD-44) still wins for that user until it is disabled.

begin;

insert into public.ai_model_configs
  (seam, provider, model, base_url, key_env_var, params, enabled, priority)
select 'assistant', 'bedrock', 'amazon.nova-lite-v1:0',
       'https://bedrock-runtime.ap-southeast-2.amazonaws.com', 'AWS_ACCESS_KEY_ID',
       '{"max_tokens":600,"temperature":0.2,"price_per_mtok_input":0.063,"price_per_mtok_output":0.252,"note":"Amazon Nova Lite, Bedrock Sydney (ap-southeast-2), SigV4"}'::jsonb,
       false, 120
where not exists (
  select 1 from public.ai_model_configs
  where seam = 'assistant' and provider = 'bedrock' and model = 'amazon.nova-lite-v1:0'
);

commit;

-- TO GO LIVE (after `supabase secrets set AWS_ACCESS_KEY_ID=… AWS_SECRET_ACCESS_KEY=…`):
--   update public.ai_model_configs set enabled = true
--   where seam = 'assistant' and provider = 'bedrock' and model = 'amazon.nova-lite-v1:0';
-- TO GO BACK: the same with enabled = false (the OpenRouter row at 110 answers again).

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261027120000_ai_usage_stage_ms.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.106.3 · Pip answer timings (16 Oct 2026).
--
-- A 14.8 s Pip answer had a 9.2 s gap after the gateway replied that nobody could explain: the app's
-- ai_usage row recorded only the total. `stage_ms` splits that total into stages, so a slow answer can
-- be traced: the classify round trip, the phrase round trip(s), and the time before, between and after
-- them (react/src/lib/aiUsage.ts `createTurnTimer`).
--
-- PRIVACY: stage_ms holds NUMBERS ONLY, under short alphabetic keys. The CHECK below refuses anything
-- else (a string, a nested object, a long key), so a mistaken or hostile client cannot store message
-- text in it. Like intent and latency_ms it is analytics, not metering: the W1c trigger
-- (ai_usage_stamp_source) still clears every metering field on a client row and leaves this one.
--
-- The gateway's own per-request stages (auth, config, membership, reservation, model) are logged by
-- ask-vyact as `[ask-vyact] timing` lines; this column is the app's side of the same answer.

create or replace function public.ai_usage_stage_ms_ok(p jsonb)
returns boolean
language sql
immutable
set search_path = public
as $$
  select p is null or (
    jsonb_typeof(p) = 'object'
    and (select count(*) from jsonb_each(p)) <= 16
    and not exists (
      select 1 from jsonb_each(p) e
       where jsonb_typeof(e.value) <> 'number' or e.key !~ '^[A-Za-z]{1,24}$'
    )
  )
$$;

alter table public.ai_usage add column if not exists stage_ms jsonb;

alter table public.ai_usage drop constraint if exists ai_usage_stage_ms_chk;
alter table public.ai_usage add constraint ai_usage_stage_ms_chk check (public.ai_usage_stage_ms_ok(stage_ms));

comment on column public.ai_usage.stage_ms is
  'v10.106.3: per-stage timings of one Pip answer in ms (numbers only, short keys). Never message text.';

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261028120000_prepare_ai_call.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.107.1 · Pip gateway: one database round trip before the model (17 Oct 2026).
--
-- WHY
--   Each Pip answer makes two gateway requests (classify, then phrase). Prod timings on 16 Oct 2026
--   (`[ask-vyact] timing`, v10.106.3): before the model is called, each request waited for
--   getUser() ‖ config read ‖ membership read (150–750 ms, run together), THEN reserve_ai_usage()
--   (140–430 ms). That second, sequential round trip is what this function removes: the gateway now
--   runs getUser() ‖ config read ‖ prepare_ai_call(), and the reservation is already made when they
--   return.
--
-- WHO IT ACTS FOR: THE CALLER, AND ONLY THE CALLER
--   The gateway calls this with the user's own JWT, so PostgREST verifies the token's signature and
--   expiry and auth.uid() is that user. There is no user id parameter: a signed-in user who calls it
--   directly can only check their own membership and reserve against their own daily cap (as calling
--   the gateway itself would), never anyone else's. The cap is clamped to 1,000, so a direct caller
--   cannot use a huge p_cap to write unbounded rows. reserve_ai_usage() stays service-only and is still
--   used by the WhatsApp assistant and as the gateway's fallback.
--
-- WHAT IT DOES, IN ORDER (the gateway's own order)
--   1. Membership of p_household_id (when given). Not a member ⇒ no reservation.
--   2. Only when asked to reserve (p_reserve), with a cap, and an enabled model row applies to this
--      user — the same rule as the gateway's filterRowsForUser() + selectModelConfig(): enabled, this
--      seam, a model and base_url, and `params.allowed_user_ids` honoured (a relay row REQUIRES the
--      caller in it). So the OFF state still writes nothing.
--   3. The quota decision exactly as reserve_ai_usage(): the profile row locked, gateway rows of the
--      last 24 h counted, and a 'reserved' row inserted when under the cap. Over the cap is returned
--      as quota = 'exceeded' (not raised), so the membership answer still comes back with it.
--   If the gateway later refuses the request for another reason (the session is no longer valid, no
--   model applies after all), it deletes the reservation it did not use.

begin;

create or replace function public.prepare_ai_call(
  p_household_id uuid,
  p_seam         text,
  p_surface      text,
  p_cap          int,
  p_reserve      boolean
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_uid        uuid := auth.uid();
  v_member     boolean := null;
  v_applicable boolean;
  v_count      int;
  v_id         uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_surface is null or p_surface not in ('chat', 'whatsapp', 'sms_share', 'receipt') then
    raise exception 'invalid_surface' using errcode = '22023';
  end if;

  if p_household_id is not null then
    select exists (
      select 1 from public.memberships where user_id = v_uid and household_id = p_household_id
    ) into v_member;
    if not v_member then
      return jsonb_build_object('member', false, 'reservation_id', null, 'quota', 'skipped');
    end if;
  end if;

  if not coalesce(p_reserve, false) or p_cap is null or p_cap < 0 or p_cap > 1000 then
    return jsonb_build_object('member', v_member, 'reservation_id', null, 'quota', 'skipped');
  end if;

  select exists (
    select 1 from public.ai_model_configs c
     where c.seam = p_seam
       and c.enabled
       and coalesce(btrim(c.model), '') <> ''
       and coalesce(btrim(c.base_url), '') <> ''
       and case
             when c.provider = 'claude-code-relay'
               then jsonb_typeof(c.params -> 'allowed_user_ids') = 'array'
                    and (c.params -> 'allowed_user_ids') ? v_uid::text
             when jsonb_typeof(c.params -> 'allowed_user_ids') = 'array'
               then (c.params -> 'allowed_user_ids') ? v_uid::text
             else true
           end
  ) into v_applicable;
  if not v_applicable then
    return jsonb_build_object('member', v_member, 'reservation_id', null, 'quota', 'skipped');
  end if;

  -- Serialise this user's quota decisions on their profile row (audit A2), as reserve_ai_usage() does.
  perform 1 from public.profiles where id = v_uid for update;

  select count(*) into v_count
    from public.ai_usage
   where user_id = v_uid
     and source = 'gateway'
     and backend = 'llm'
     and ts >= now() - interval '24 hours';

  if v_count >= p_cap then
    return jsonb_build_object('member', v_member, 'reservation_id', null, 'quota', 'exceeded');
  end if;

  insert into public.ai_usage (user_id, household_id, surface, backend, outcome, ts, source)
  values (v_uid, p_household_id, p_surface, 'llm', 'reserved', now(), 'gateway')
  returning id into v_id;

  return jsonb_build_object('member', v_member, 'reservation_id', v_id, 'quota', 'ok');
end $$;

revoke all on function public.prepare_ai_call(uuid, text, text, int, boolean) from public, anon;
grant execute on function public.prepare_ai_call(uuid, text, text, int, boolean) to authenticated, service_role;

comment on function public.prepare_ai_call(uuid, text, text, int, boolean) is
  'v10.107.1: the ask-vyact gateway''s pre-model checks in one round trip, for auth.uid() only: household membership, then (when asked, with a cap ≤ 1000 and an applicable enabled model row) the reserve_ai_usage() quota decision. Returns {member, reservation_id, quota: ok|exceeded|skipped}.';

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261029120000_unpublish_pulse_content.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.109.0 (owner decisions 16 Oct 2026: "Archive the concept of Pulse"; published content that mentions
-- it is unpublished by a migration).
--
-- The Pulse Score is archived: no screen, Pip answer or message shows it any more (its computation stays,
-- unused, like Goals and Tax). A published Learn lesson or Insights card that talks about it would describe a
-- feature the app no longer has, so every PUBLISHED content item that mentions Pulse as a word goes back to
-- 'draft'. The owner rewrites or deletes them in the admin CMS; nothing is deleted here.
--   • A whole-word match (\m … \M): "impulse" and the "HeartPulse" icon name are not Pulse.
--   • title, summary, body, the card's markdown body, its visual spec and its tags are all read.
--   • Idempotent: a second run finds nothing published to change.

update public.content_items
   set status = 'draft', updated_at = now()
 where status = 'published'
   and (title ~* '\mpulse\M'
        or coalesce(summary, '') ~* '\mpulse\M'
        or coalesce(body, '') ~* '\mpulse\M'
        or coalesce(body_md, '') ~* '\mpulse\M'
        or coalesce(visual_ref::text, '') ~* '\mpulse\M'
        or exists (select 1 from unnest(coalesce(tags, '{}'::text[])) as tag where tag ~* '^pulse$'));

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261030120000_names_follow_the_person.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.113.0 — a person's name is their own, everywhere (owner, 18 Oct 2026: "why does the name go empty
-- or prefilled by email IDs").
--
-- Two of the three causes were in the database:
--   1. Sign-up took the name only from `display_name` in the sign-up metadata, else the part of the
--      email before "@". A Google (or any OAuth) sign-in sends the name as `full_name` / `name`, so
--      every such account was named after its email ("uday.kr27").
--   2. A member's name in a household (`memberships.display_name`) is a COPY of the profile name, made
--      when they joined (with the same email fallback). Nothing updated it when the person renamed, so
--      the members list, "who paid" and splits kept showing the old, email-style name.
-- (The third, Settings' name box staying empty when opened before the profile loaded, is in the app.)
--
-- No screen sets a household-specific name (the app's upsertMember has no callers), so every household
-- copy is the profile's. A rename still updates only the copies that showed the old name, so a name set
-- for one household on purpose (if that is ever added) is kept.
--
-- MONEY MODEL: untouched. Names only.

begin;

-- ── 1. Sign-up reads the name the provider sends ─────────────────────────────────────────────────
-- Unchanged otherwise (00000000000001_production_state_baseline.sql): the profile, then the person's
-- first household (its owner membership comes from handle_new_household).
create or replace function public.handle_new_user()
  returns trigger language plpgsql security definer set search_path to 'public'
as $$
declare v_display_name text;
begin
  v_display_name := coalesce(
    nullif(btrim(new.raw_user_meta_data->>'display_name'), ''),
    nullif(btrim(new.raw_user_meta_data->>'full_name'), ''),     -- Google, Apple, GitHub via Supabase
    nullif(btrim(new.raw_user_meta_data->>'name'), ''),
    split_part(new.email, '@', 1));
  insert into profiles (id, display_name) values (new.id, v_display_name);
  insert into households (name, type, base_currency, created_by) values ('My Household', 'personal', 'USD', new.id);
  return new;
end; $$;

-- ── 2. A rename reaches every household copy that still showed the old name ──────────────────────
create or replace function public.sync_member_display_name()
  returns trigger language plpgsql security definer set search_path = public, pg_temp
as $$
begin
  if new.display_name is distinct from old.display_name and nullif(btrim(new.display_name), '') is not null then
    update public.memberships set display_name = new.display_name
     where user_id = new.id and display_name is not distinct from old.display_name;
  end if;
  return null;
end; $$;
revoke all on function public.sync_member_display_name() from public, anon, authenticated;

drop trigger if exists trg_profiles_sync_member_name on public.profiles;
create trigger trg_profiles_sync_member_name
  after update of display_name on public.profiles
  for each row execute function public.sync_member_display_name();

-- ── 3. Existing accounts ─────────────────────────────────────────────────────────────────────────
-- 3a. A profile still named after its email (the old fallback) takes the name its provider sent. The
--     trigger above carries it into the household copies that showed the email name.
update public.profiles p
   set display_name = coalesce(nullif(btrim(u.raw_user_meta_data->>'full_name'), ''),
                               nullif(btrim(u.raw_user_meta_data->>'name'), ''))
  from auth.users u
 where u.id = p.id
   and p.display_name = split_part(u.email, '@', 1)
   and coalesce(nullif(btrim(u.raw_user_meta_data->>'full_name'), ''),
                nullif(btrim(u.raw_user_meta_data->>'name'), '')) is not null;

-- 3b. A household copy that no longer matches its person's name (a rename never reached it, or it was
--     made from the email fallback) takes the profile's name. Copies are never set on purpose today.
update public.memberships m
   set display_name = p.display_name
  from public.profiles p
 where p.id = m.user_id
   and nullif(btrim(p.display_name), '') is not null
   and m.display_name is distinct from p.display_name;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261031120000_t2a_memberships_invitations.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.114.0 — Track T2, part a: who belongs to a household, and how they join.
-- Audit INT-HH-07, INT-HH-09, DB-INT-11, INT-HH-06, INT-CON-07, XC-PRV-12; owner decisions 18 Oct 2026
-- (T2 reopened Batch E; the name lookup answers for "known emails only").
--
--   1. People join only by accepting an invitation. An owner or admin could insert a membership for
--      ANY user id (a uid learnt from a settled split, say): no consent, and the stranger's profile was
--      then readable. The client INSERT policy goes; every real join is a definer function.
--   2. A membership's person and household never change (an UPDATE could re-point one).
--   3. The old phone copies on profiles, read by nothing since audit S1, are cleared (dropped next release).
--   4. One membership per person per household (a unique index). Duplicates, if any, are merged first.
--   5. The member limit counts with the household locked, so two joins at once can't overfill it.
--   6. Accepting an invitation is atomic and single-use; opening a link you're already a member through
--      no longer burns it.
--   7. The legacy accept_invitation(text / uuid), unused by the app, are dropped.
--   8. leave_household reads the caller's role null-safely.
--   9. The participant name lookup answers only for people the caller already shares something with.
--
-- MONEY MODEL: untouched. Duplicate memberships (none expected) hand their transactions and schedules to
-- the row that is kept, so no entry loses who made it.

begin;

-- ── 1. People join only by accepting an invitation (INT-HH-07) ─────────────────────────────────────
drop policy if exists "owners and admins add members" on public.memberships;
-- No client INSERT policy remains: handle_new_household, accept_invitation_link and
-- accept_invitation_by_id are SECURITY DEFINER and are the only ways in.

-- ── 2. A membership's person and household never change (INT-HH-07) ───────────────────────────────
create or replace function public.memberships_keep_identity()
  returns trigger language plpgsql set search_path = public, pg_temp
as $$
begin
  if new.user_id is distinct from old.user_id or new.household_id is distinct from old.household_id then
    raise exception 'membership_identity_fixed: a membership stays with its person and household'
      using errcode = '42501';
  end if;
  return new;
end; $$;
revoke all on function public.memberships_keep_identity() from public, anon, authenticated;
drop trigger if exists memberships_keep_identity on public.memberships;
create trigger memberships_keep_identity
  before update of user_id, household_id on public.memberships
  for each row execute function public.memberships_keep_identity();

-- ── 3. The old phone copies on profiles are cleared (INT-HH-07) ───────────────────────────────────
-- guard_whatsapp_profile_columns lets only the service role touch them; this migration acts as it.
select set_config('request.jwt.claims', '{"role":"service_role"}', true);
update public.profiles set phone_number = null, phone_verified_at = null, whatsapp_household_id = null
 where phone_number is not null or phone_verified_at is not null or whatsapp_household_id is not null;
select set_config('request.jwt.claims', '', true);

-- ── 4. One membership per person per household (DB-INT-11, INT-HH-06) ─────────────────────────────
-- A WhatsApp link ends with the membership (W1a) — but only once the person has no membership left in
-- that household, so merging a duplicate below never unlinks someone who stays.
create or replace function public.unlink_whatsapp_on_membership_delete()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  delete from public.whatsapp_identities w
   where w.profile_id = OLD.user_id and w.household_id = OLD.household_id
     and not exists (select 1 from public.memberships m
                      where m.user_id = OLD.user_id and m.household_id = OLD.household_id);
  return null;
end;
$$;

-- Keep the highest role, then the earliest; move what pointed at the others to it.
create temporary table t2a_duplicate_memberships on commit drop as
select id, keep from (
  select id, first_value(id) over (
           partition by household_id, user_id
           order by case role when 'owner' then 0 when 'admin' then 1 when 'member' then 2 when 'viewer' then 3 else 4 end,
                    joined_at, id) as keep
    from public.memberships where user_id is not null) ranked
 where id <> keep;
update public.transactions t set member_id = d.keep from t2a_duplicate_memberships d where t.member_id = d.id;
update public.transactions t set initiated_by = d.keep from t2a_duplicate_memberships d where t.initiated_by = d.id;
update public.recurring_schedules s set owner_member_id = d.keep from t2a_duplicate_memberships d where s.owner_member_id = d.id;
delete from public.memberships m using t2a_duplicate_memberships d where m.id = d.id;

create unique index if not exists uq_memberships_household_user
  on public.memberships (household_id, user_id) where user_id is not null;

-- ── 5. The member limit counts with the household locked (DB-INT-11) ──────────────────────────────
-- Unchanged otherwise (20261007120000_household_types_v2.sql). Two joins at once used to count the same
-- members and both get in: a Couple household with three.
create or replace function public.enforce_household_member_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_type  text;
  v_limit integer;
  v_count integer;
begin
  select type into v_type from households where id = new.household_id for update;
  v_limit := household_member_limit(v_type);
  if v_limit is null then
    return new;
  end if;

  select count(*) into v_count from memberships where household_id = new.household_id;
  if tg_table_name = 'invitations' then
    v_count := v_count + (select count(*) from invitations
                           where household_id = new.household_id
                             and accepted_at is null and expires_at > now());
  end if;

  if v_count >= v_limit then
    raise exception 'HOUSEHOLD_FULL: a % household has room for % member%',
      v_type, v_limit, case when v_limit = 1 then '' else 's' end
      using errcode = 'P0001',
            hint = case v_type
                     when 'personal' then 'Personal households are private. Change the type to Couple or Family to invite someone.'
                     else 'A Couple household has room for one other person. Change the type to Family to invite more.'
                   end;
  end if;
  return new;
end;
$$;
revoke execute on function public.enforce_household_member_limit() from public, anon, authenticated;

-- ── 6. Accepting is atomic and single-use (INT-HH-09) ─────────────────────────────────────────────
-- The link: the invitation and its household are locked before anything is counted; the accept is
-- claimed only while still unaccepted; someone already in the household opening the link leaves it
-- usable (it used to be burnt). Unchanged otherwise (20261022120000_invitation_inbox.sql).
create or replace function public.accept_invitation_link(invite_token text)
  returns jsonb
  language plpgsql
  security definer
  set search_path = public, pg_temp
as $$
declare
  inv invitations%rowtype;
  caller_email text;
  existing memberships%rowtype;
  new_membership_id uuid;
  claimed integer;
begin
  if auth.uid() is null then
    raise exception 'Must be signed in to accept an invitation';
  end if;

  select email into caller_email from auth.users where id = auth.uid();

  select * into inv
  from invitations
  where token = invite_token
    and accepted_at is null
    and expires_at > now()
  for update;

  if not found then
    raise exception 'Invitation not found or expired';
  end if;

  perform 1 from households where id = inv.household_id for update;

  select * into existing
  from memberships
  where household_id = inv.household_id
    and user_id = auth.uid();

  if found then
    return jsonb_build_object(
      'household_id', inv.household_id,
      'membership_id', existing.id,
      'role', existing.role,
      'already_member', true
    );
  end if;

  update invitations set accepted_at = now() where id = inv.id and accepted_at is null;
  get diagnostics claimed = row_count;
  if claimed = 0 then
    raise exception 'Invitation not found or expired';
  end if;

  insert into memberships (household_id, user_id, role, display_name, household_role)
  values (
    inv.household_id,
    auth.uid(),
    inv.role,
    coalesce((select display_name from profiles where id = auth.uid()), split_part(coalesce(caller_email, ''), '@', 1), 'member'),
    case when inv.household_role in ('primary', 'partner', 'child', 'elder') then inv.household_role end
  )
  returning id into new_membership_id;

  insert into activity_log (household_id, actor_id, action, entity_type, entity_id)
  values (inv.household_id, auth.uid(), 'accepted', 'invitation', inv.id);

  return jsonb_build_object(
    'household_id', inv.household_id,
    'membership_id', new_membership_id,
    'role', inv.role,
    'already_member', false
  );
end;
$$;
revoke all on function public.accept_invitation_link(text) from public, anon;
grant execute on function public.accept_invitation_link(text) to authenticated;

-- The inbox: the household is locked too, and the accept is claimed only while still unaccepted. An
-- invitation addressed to someone already in the household is theirs, so it is marked answered.
create or replace function public.accept_invitation_by_id(p_id uuid)
  returns jsonb
  language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  v_email text := public.my_verified_email();
  inv public.invitations%rowtype;
  existing public.memberships%rowtype;
  new_membership_id uuid;
  claimed integer;
begin
  if auth.uid() is null or v_email is null then
    raise exception 'not_signed_in' using errcode = '42501';
  end if;

  select * into inv from public.invitations
   where id = p_id and recipient_email = v_email and accepted_at is null and expires_at > now()
   for update;
  if not found then
    raise exception 'invitation_not_found' using errcode = 'P0001';
  end if;

  perform 1 from public.households where id = inv.household_id for update;

  select * into existing from public.memberships
   where household_id = inv.household_id and user_id = auth.uid();
  if found then
    update public.invitations set accepted_at = now() where id = inv.id;
    return jsonb_build_object('household_id', inv.household_id, 'membership_id', existing.id,
                              'role', existing.role, 'already_member', true);
  end if;

  update public.invitations set accepted_at = now() where id = inv.id and accepted_at is null;
  get diagnostics claimed = row_count;
  if claimed = 0 then
    raise exception 'invitation_not_found' using errcode = 'P0001';
  end if;

  -- The membership insert runs the HOUSEHOLD_FULL limit trigger, as the link accept does.
  insert into public.memberships (household_id, user_id, role, display_name, household_role)
  values (inv.household_id, auth.uid(), inv.role,
          coalesce((select nullif(btrim(display_name), '') from public.profiles where id = auth.uid()),
                   split_part(v_email, '@', 1)),
          case when inv.household_role in ('primary', 'partner', 'child', 'elder') then inv.household_role end)
  returning id into new_membership_id;

  insert into public.activity_log (household_id, actor_id, action, entity_type, entity_id)
  values (inv.household_id, auth.uid(), 'accepted', 'invitation', inv.id);

  return jsonb_build_object('household_id', inv.household_id, 'membership_id', new_membership_id,
                            'role', inv.role, 'already_member', false);
end;
$$;
revoke all on function public.accept_invitation_by_id(uuid) from public, anon;
grant execute on function public.accept_invitation_by_id(uuid) to authenticated, service_role;

-- ── 7. The legacy accept functions go (INT-HH-09) ─────────────────────────────────────────────────
-- The app calls only accept_invitation_link and accept_invitation_by_id.
drop function if exists public.accept_invitation(text);
drop function if exists public.accept_invitation(uuid);

-- ── 8. leave_household, null-safe (INT-CON-07) ────────────────────────────────────────────────────
-- Someone not in the household leaves nothing; the last owner can't leave (the W1a owner trigger
-- guards it too).
create or replace function public.leave_household(h_id uuid)
  returns void language plpgsql security definer set search_path = public, pg_temp
as $$
declare
  v_role text;
  owner_count int;
begin
  select role into v_role from memberships where household_id = h_id and user_id = auth.uid();
  if v_role is null then
    return;
  end if;
  if v_role = 'owner' then
    select count(*) into owner_count from memberships where household_id = h_id and role = 'owner';
    if owner_count = 1 then
      raise exception 'last_owner_cannot_leave';
    end if;
  end if;
  delete from memberships where household_id = h_id and user_id = auth.uid();
end; $$;

-- ── 9. Names only for people the caller already knows (XC-PRV-12; owner: "known emails only") ────
-- Anyone signed in could send thousands of emails and learn which belong to Vyact users, and their
-- names. Now an email resolves only when it is already shared with the caller: on a split they own or
-- take part in, or a member of one of their households. Everyone else gets no answer; the Split form
-- then asks by email. At most 200 emails per call.
create or replace function public.resolve_participant_names(p_emails text[])
returns table(email text, display_name text)
language plpgsql stable security definer set search_path = public, pg_temp
as $$
declare
  v_me text := public.my_email();
begin
  if auth.uid() is null then
    return;
  end if;
  if coalesce(array_length(p_emails, 1), 0) > 200 then
    raise exception 'too_many_emails: at most 200 at a time' using errcode = '22023';
  end if;
  return query
  with wanted as (
    select distinct lower(btrim(e)) as email from unnest(p_emails) e where nullif(btrim(e), '') is not null
  ), my_splits as (
    select sp.id from public.shared_splits sp where sp.owner_user_id = auth.uid()
    union
    select s.split_id from public.shared_split_shares s where v_me is not null and lower(s.email) = v_me
  ), known as (
    select lower(s.email) as email from public.shared_split_shares s where s.split_id in (select id from my_splits)
    union
    select lower(u.email) from public.shared_splits sp join auth.users u on u.id = sp.owner_user_id
     where sp.id in (select id from my_splits)
    union
    select lower(u.email) from public.memberships m join auth.users u on u.id = m.user_id
     where public.is_member(m.household_id)
  )
  select lower(u.email) as email, p.display_name
    from auth.users u
    join public.profiles p on p.id = u.id
   where lower(u.email) in (select w.email from wanted w where w.email in (select k.email from known k))
     and p.deactivated_at is null
     and p.deletion_requested_at is null;
end;
$$;
revoke execute on function public.resolve_participant_names(text[]) from public, anon;
grant execute on function public.resolve_participant_names(text[]) to authenticated;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261101120000_t2b_server_notifications_push.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.116.0 — Track T2, part b-2: the lock screen shows only what Vyact raised, and push is hardened.
-- Audit DB-SEC-06 (and FE-PLT-05), BE-FN-07; owner decision 18 Oct 2026: "push only the server's".
--
-- DB-SEC-06. Any member, even a viewer, could insert a notification, and web-push sent every unpushed
-- row to every member's lock screen: a fake "security alert, call this number" looked exactly like
-- Vyact. A viewer could also delete or mark read the real "EMI due" for everyone. Now:
--   1. every row says who raised it (`source`: 'client' from a device, 'server' from web-push);
--   2. web-push pushes only `source = 'server'` rows. When it raises a notification a device already
--      wrote (same dedupe key), it takes that row over with its own wording, so genuine pushes are
--      unchanged (raise_server_notifications);
--   3. a device may write only its own kind of row: not as a viewer, never 'server', never pre-stamped as
--      pushed, and a link only inside Vyact;
--   4. from the app, only a notification's read state can change; viewers can mark read but not delete.
-- BE-FN-07. Push services are the real ones only (Apple's web push host, Windows' WNS hosts), and a person
-- keeps at most 10 devices: registering an 11th retires the oldest. (Payload size and household paging
-- are in the web-push function.)
--
-- MONEY MODEL: untouched.

begin;

-- ── 1. Who raised it ────────────────────────────────────────────────────────────────────────────
alter table public.notifications add column if not exists source text not null default 'client';
do $$ begin
  alter table public.notifications add constraint notifications_source_check check (source in ('client', 'server'));
exception when duplicate_object then null; end $$;
-- Only server-raised rows are ever pushed: an index for the dispatcher's pending read.
create index if not exists notif_server_unpushed_idx on public.notifications (household_id, created_at)
  where source = 'server' and pushed_at is null;

-- ── 2. The server raises, and takes over a device's matching row ───────────────────────────────
create or replace function public.raise_server_notifications(p_rows jsonb)
  returns integer language plpgsql security definer set search_path = public, pg_temp
as $$
declare n integer;
begin
  insert into public.notifications (household_id, type, priority, title, body, status, due_at, member_id, amount_ref,
                                    deep_link, tint, actions, context, dedupe_key, source)
  select r.household_id, r.type, coalesce(r.priority, 'P2'), r.title, r.body, coalesce(r.status, 'unread'), r.due_at,
         r.member_id, r.amount_ref, r.deep_link, r.tint, r.actions, r.context, r.dedupe_key, 'server'
    from jsonb_populate_recordset(null::public.notifications, coalesce(p_rows, '[]'::jsonb)) r
  on conflict (household_id, dedupe_key) do update
     set type = excluded.type, priority = excluded.priority, title = excluded.title, body = excluded.body,
         due_at = excluded.due_at, member_id = excluded.member_id, amount_ref = excluded.amount_ref,
         deep_link = excluded.deep_link, tint = excluded.tint, actions = excluded.actions, context = excluded.context,
         source = 'server'
   where notifications.source = 'client';
  get diagnostics n = row_count;
  return n;
end; $$;
revoke all on function public.raise_server_notifications(jsonb) from public, anon, authenticated;
grant execute on function public.raise_server_notifications(jsonb) to service_role;

-- ── 3. What a device may write ──────────────────────────────────────────────────────────────────
drop policy if exists "notif_insert" on public.notifications;
create policy "notif_insert" on public.notifications for insert with check (
  public.is_member(household_id)
  and coalesce(public.role_in(household_id), 'viewer') <> 'viewer'
  and source = 'client'
  and pushed_at is null
  and (deep_link is null or deep_link = '/' or deep_link ~ '^/[^/\\]')
);

-- ── 4. From the app, only the read state changes; viewers don't delete ─────────────────────────
drop policy if exists "notif_update" on public.notifications;
create policy "notif_update" on public.notifications for update
  using (public.is_member(household_id)) with check (public.is_member(household_id));
drop policy if exists "notif_delete" on public.notifications;
create policy "notif_delete" on public.notifications for delete using (
  public.is_member(household_id) and coalesce(public.role_in(household_id), 'viewer') <> 'viewer'
);

create or replace function public.notifications_app_edits_status_only()
  returns trigger language plpgsql set search_path = public, pg_temp
as $$
declare v_claims text := nullif(current_setting('request.jwt.claims', true), '');
begin
  -- The web-push job (service role), migrations and scheduled jobs carry no 'authenticated' claim.
  if v_claims is null or (v_claims::jsonb ->> 'role') is distinct from 'authenticated' then
    return new;
  end if;
  if (new.household_id, new.type, new.priority, new.title, new.body, new.created_at, new.due_at, new.member_id,
      new.amount_ref, new.deep_link, new.tint, new.actions, new.context, new.dedupe_key, new.source, new.pushed_at)
     is distinct from
     (old.household_id, old.type, old.priority, old.title, old.body, old.created_at, old.due_at, old.member_id,
      old.amount_ref, old.deep_link, old.tint, old.actions, old.context, old.dedupe_key, old.source, old.pushed_at) then
    raise exception 'notification_fixed: only its read state can change' using errcode = '42501';
  end if;
  return new;
end; $$;
revoke all on function public.notifications_app_edits_status_only() from public, anon, authenticated;
drop trigger if exists notifications_app_edits_status_only on public.notifications;
create trigger notifications_app_edits_status_only
  before update on public.notifications
  for each row execute function public.notifications_app_edits_status_only();

-- ── 5. Real push services only; at most 10 devices a person (BE-FN-07) ─────────────────────────
-- Unchanged otherwise (20261003120000_web_push.sql). Apple's web push host is web.push.apple.com, and
-- Windows' are wns2-<region>.notify.windows.com; the old wildcards let anyone register a host that
-- never answers.
create or replace function public.register_push_subscription(
  p_endpoint text, p_p256dh text, p_auth text, p_household_id uuid,
  p_user_agent text default null, p_tz text default null, p_prefs jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if not public.is_member(p_household_id) then raise exception 'not_a_member' using errcode = '42501'; end if;
  -- Only real push services; the dispatcher POSTs to this URL.
  if p_endpoint is null or length(p_endpoint) > 1024
     or p_endpoint !~ '^https://(fcm\.googleapis\.com|android\.googleapis\.com|updates\.push\.services\.mozilla\.com|push\.services\.mozilla\.com|web\.push\.apple\.com|wns2-[a-z0-9-]+\.notify\.windows\.com)/' then
    raise exception 'bad_endpoint' using errcode = '22023';
  end if;
  if coalesce(length(p_p256dh), 0) not between 80 and 100 or coalesce(length(p_auth), 0) not between 16 and 30 then
    raise exception 'bad_keys' using errcode = '22023';
  end if;
  insert into public.push_subscriptions (user_id, household_id, endpoint, p256dh, auth, user_agent, tz, prefs)
  values (auth.uid(), p_household_id, p_endpoint, p_p256dh, p_auth, left(p_user_agent, 300), left(p_tz, 64), coalesce(p_prefs, '{}'::jsonb))
  on conflict (endpoint) do update
     set user_id = excluded.user_id, household_id = excluded.household_id,
         p256dh = excluded.p256dh, auth = excluded.auth, user_agent = excluded.user_agent,
         tz = excluded.tz, prefs = excluded.prefs, updated_at = now(),
         disabled_at = null, failures = 0,
         -- A device moving to another person or household starts fresh: no backlog.
         created_at = case when push_subscriptions.user_id <> excluded.user_id
                             or push_subscriptions.household_id <> excluded.household_id
                           then now() else push_subscriptions.created_at end
  returning id into v_id;
  -- At most 10 live devices a person: the oldest beyond that are retired.
  update public.push_subscriptions set disabled_at = now()
   where id in (select s.id from public.push_subscriptions s
                 where s.user_id = auth.uid() and s.disabled_at is null and s.id <> v_id
                 order by s.updated_at desc, s.created_at desc
                 offset 9);
  return jsonb_build_object('id', v_id);
end;
$$;
revoke all on function public.register_push_subscription(text, text, text, uuid, text, text, jsonb) from public, anon;
grant execute on function public.register_push_subscription(text, text, text, uuid, text, text, jsonb) to authenticated;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261102120000_t2c_ledger_integrity.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.117.0 — Track T2, part c: ledger integrity.
-- Audit DB-SEC-09 and DB-INT-09 (owner decisions 18 Oct 2026: T2 reopens Batch E; DB-INT-09 "all three guards").
--
-- DB-SEC-09. The tenant checks (audit S3, 20260909120000) proved an entry's account, member and loan were
-- the household's own, but not its investment asset, who initiated it, or its schedule; accounts and
-- schedules had no check at all. A member who learnt another household's asset id could buy into it: the
-- link (ON DELETE RESTRICT) then blocked that household's erase and deletion, and it could not even see
-- why. Every link now stays inside its household:
--   transactions: asset_id (and its account, member and loan links, as before), initiated_by,
--                 recurring_schedule_id;
--   accounts:     asset_id, debt_id;
--   schedules:    owner_member_id, and the template's accountId / toAccountId / assetId.
-- S3's header said its checks run "in the table owner's definer context"; none did. The checks here are
-- SECURITY DEFINER, so row security can't hide a row from them. (S3's allocation and split checks stay as
-- they are: they run as the caller, which refuses rather than allows when a row is hidden.)
--
-- DB-INT-09. A delete was decided by delete_account / move_account_and_delete, but nothing else held to it:
--   1. Cash in Hand can't be archived, deleted, or turned into another kind (and nothing becomes Cash);
--   2. an account is soft-deleted only by delete_account or move_account_and_delete (they set a
--      transaction-local flag), a delete is final from the app, and the app can't hard-delete accounts
--      (the unused accounts_delete policy is dropped);
--   3. an entry never makes a NEW link to a deleted account or asset: a new entry, a changed account or
--      asset, or a deleted entry brought back. Editing an old entry still works. The account or asset is
--      locked while the entry is written, so a delete running at the same moment either sees the entry
--      (and refuses: account_in_use / asset_in_use) or the entry sees the delete (and is refused).
--   ensure_cash_account never hands back an archived Cash in Hand: an archived one is restored, here and
--   whenever it is asked for.
--
-- Apart from restoring an archived Cash in Hand, rows already in place are left as they are: only new
-- writes are checked.
-- MONEY MODEL: no figure changes. An entry the database used to accept onto a deleted account (where it
-- moved no visible balance) is now refused and set aside on the device that wrote it.

begin;

-- ── 1. Entries: every link inside the household; no new link to a deleted account or asset ─────────
create or replace function public.assert_txn_tenant_consistency()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  prev     public.transactions;  -- the stored row this write replaces (an UPDATE, or an upsert's INSERT)
  had      boolean := false;
  live     boolean := new.deleted_at is null;
  revived  boolean;              -- a live entry that was not live before: a new one, or one brought back
  acc_new  boolean;
  to_new   boolean;
  asset_new boolean;
  r        record;
begin
  if tg_op = 'UPDATE' then
    prev := old; had := true;
  else
    select * into prev from public.transactions where id = new.id;
    had := found and prev.household_id = new.household_id;
  end if;
  revived   := live and (not had or prev.deleted_at is not null);
  acc_new   := live and new.account_id is not null and (revived or prev.account_id is distinct from new.account_id);
  to_new    := live and new.to_account_id is not null and (revived or prev.to_account_id is distinct from new.to_account_id);
  asset_new := live and new.asset_id is not null and (revived or prev.asset_id is distinct from new.asset_id);

  -- Every link is the household's own (account, member and loan on every write, as S3 did).
  if new.account_id is not null and not exists (
    select 1 from public.accounts where id = new.account_id and household_id = new.household_id
  ) then
    raise exception 'transactions.account_id belongs to a different household' using errcode = '23503';
  end if;
  if new.to_account_id is not null and not exists (
    select 1 from public.accounts where id = new.to_account_id and household_id = new.household_id
  ) then
    raise exception 'transactions.to_account_id belongs to a different household' using errcode = '23503';
  end if;
  if new.member_id is not null and not exists (
    select 1 from public.memberships where id = new.member_id and household_id = new.household_id
  ) then
    raise exception 'transactions.member_id belongs to a different household' using errcode = '23503';
  end if;
  if new.debt_id is not null and not exists (
    select 1 from public.debts where id = new.debt_id and household_id = new.household_id
  ) then
    raise exception 'transactions.debt_id belongs to a different household' using errcode = '23503';
  end if;
  if new.asset_id is not null and not exists (
    select 1 from public.assets where id = new.asset_id and household_id = new.household_id
  ) then
    raise exception 'transactions.asset_id belongs to a different household' using errcode = '23503';
  end if;
  -- Who initiated it, and the schedule it came from: when the link is made or changed.
  if new.initiated_by is not null and (not had or prev.initiated_by is distinct from new.initiated_by)
     and not exists (select 1 from public.memberships where id = new.initiated_by and household_id = new.household_id) then
    raise exception 'transactions.initiated_by belongs to a different household' using errcode = '23503';
  end if;
  if new.recurring_schedule_id is not null
     and (not had or prev.recurring_schedule_id is distinct from new.recurring_schedule_id)
     and not exists (select 1 from public.recurring_schedules
                      where id = new.recurring_schedule_id and household_id = new.household_id) then
    raise exception 'transactions.recurring_schedule_id belongs to a different household' using errcode = '23503';
  end if;

  -- A NEW link needs a live account or asset. It is read under a share lock (accounts in id order, so two
  -- writers never wait on each other), which a delete running at the same moment waits for: either the
  -- delete then sees this entry and refuses (account_in_use / asset_in_use), or this sees the delete.
  if acc_new or to_new then
    for r in
      select a.id, a.deleted_at from public.accounts a
       where (acc_new and a.id = new.account_id) or (to_new and a.id = new.to_account_id)
       order by a.id
         for share
    loop
      if r.deleted_at is not null then
        raise exception 'account_deleted: the account was deleted' using errcode = '23503', detail = r.id::text;
      end if;
    end loop;
  end if;
  if asset_new then
    select a.deleted_at into r from public.assets a where a.id = new.asset_id for share;
    if r.deleted_at is not null then
      raise exception 'asset_deleted: the investment was deleted' using errcode = '23503', detail = new.asset_id::text;
    end if;
  end if;
  return new;
end $$;
revoke all on function public.assert_txn_tenant_consistency() from public, anon, authenticated;

drop trigger if exists trg_txn_tenant_consistency on public.transactions;
create trigger trg_txn_tenant_consistency
  before insert or update on public.transactions
  for each row execute function public.assert_txn_tenant_consistency();

-- ── 2. Accounts: their asset and loan are the household's own ──────────────────────────────────────
create or replace function public.assert_account_tenant_consistency()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.asset_id is not null and (tg_op = 'INSERT' or old.asset_id is distinct from new.asset_id)
     and not exists (select 1 from public.assets where id = new.asset_id and household_id = new.household_id) then
    raise exception 'accounts.asset_id belongs to a different household' using errcode = '23503';
  end if;
  if new.debt_id is not null and (tg_op = 'INSERT' or old.debt_id is distinct from new.debt_id)
     and not exists (select 1 from public.debts where id = new.debt_id and household_id = new.household_id) then
    raise exception 'accounts.debt_id belongs to a different household' using errcode = '23503';
  end if;
  return new;
end $$;
revoke all on function public.assert_account_tenant_consistency() from public, anon, authenticated;

drop trigger if exists trg_account_tenant_consistency on public.accounts;
create trigger trg_account_tenant_consistency
  before insert or update on public.accounts
  for each row execute function public.assert_account_tenant_consistency();

-- ── 3. Accounts: Cash in Hand stays; a delete is the delete functions' alone, and final ────────────
-- Checked for the app (a request carrying the 'authenticated' role), directly or through a function it
-- calls. The service role, scheduled jobs and migrations carry no such claim.
create or replace function public.accounts_guard_lifecycle()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
declare v_claims text := nullif(current_setting('request.jwt.claims', true), '');
begin
  if v_claims is null or (v_claims::jsonb ->> 'role') is distinct from 'authenticated' then
    return new;
  end if;
  if old.kind = 'cash' and (new.kind is distinct from 'cash'
       or (new.is_archived and not old.is_archived)
       or (new.deleted_at is not null and old.deleted_at is null)) then
    raise exception 'cash_account_protected: Cash in Hand can be renamed, never archived or deleted'
      using errcode = '22023';
  end if;
  if new.kind = 'cash' and old.kind is distinct from 'cash' then
    raise exception 'cash_account_protected: Cash in Hand is created by the household, never converted'
      using errcode = '22023';
  end if;
  if new.deleted_at is not null and old.deleted_at is null
     and current_setting('vyact.account_delete', true) is distinct from 'on' then
    raise exception 'account_delete_guarded: delete an account with delete_account or move_account_and_delete'
      using errcode = '42501';
  end if;
  if old.deleted_at is not null and new.deleted_at is null then
    raise exception 'account_delete_final: a deleted account stays deleted' using errcode = '42501';
  end if;
  return new;
end $$;
revoke all on function public.accounts_guard_lifecycle() from public, anon, authenticated;

drop trigger if exists trg_accounts_guard_lifecycle on public.accounts;
create trigger trg_accounts_guard_lifecycle
  before update on public.accounts
  for each row execute function public.accounts_guard_lifecycle();

-- The app never removes an account row (it tombstones through the delete functions). A hard delete set
-- every entry's account to null and took its money out of every balance.
drop policy if exists "accounts_delete" on public.accounts;

-- delete_account and move_account_and_delete: unchanged but for the flag around their tombstone.
create or replace function public.delete_account(p_account_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  acc  public.accounts;
  deps jsonb;
begin
  select * into acc from public.accounts
   where id = p_account_id and deleted_at is null
   for update;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  -- Owners and admins only.
  if auth.uid() is null or coalesce(public.role_in(acc.household_id), '') not in ('owner', 'admin') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if acc.kind = 'cash' then
    raise exception 'cash_account_protected' using errcode = '22023';
  end if;
  if acc.kind = 'loan' then
    raise exception 'system_account_protected' using errcode = '22023';
  end if;

  deps := public.account_dependencies(p_account_id);
  if (deps #>> '{transactions,count}')::int > 0
     or jsonb_array_length(deps->'recurring') > 0
     or jsonb_array_length(deps->'openSplits') > 0
     or (deps->>'loanEvents')::int > 0 then
    raise exception 'account_in_use' using errcode = '23503', detail = deps::text;
  end if;

  -- A tombstone, not a row delete: under refresh-based sync another device still
  -- holding the row would otherwise upload it again. Unrecoverable from the app.
  perform set_config('vyact.account_delete', 'on', true);
  update public.accounts set deleted_at = now(), is_default = false where id = p_account_id;
  perform set_config('vyact.account_delete', '', true);
  return jsonb_build_object('status', 'deleted', 'accountId', p_account_id);
end $fn$;

create or replace function public.move_account_and_delete(p_from uuid, p_to uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  src      public.accounts;
  dst      public.accounts;
  deps     jsonb;
  n_debit  int;
  n_credit int;
  n_sched  int;
  n_sched2 int;
  folded   numeric;
begin
  if p_from = p_to then
    raise exception 'same_account' using errcode = '22023';
  end if;

  select * into src from public.accounts where id = p_from and deleted_at is null for update;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  select * into dst from public.accounts where id = p_to and deleted_at is null for update;
  if not found then
    raise exception 'destination_not_found' using errcode = 'P0002';
  end if;
  if src.household_id <> dst.household_id then
    raise exception 'different_household' using errcode = '22023';
  end if;
  if auth.uid() is null or coalesce(public.role_in(src.household_id), '') not in ('owner', 'admin') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  if src.kind not in ('bank', 'credit_card') then
    raise exception 'source_not_movable' using errcode = '22023';
  end if;
  if dst.is_archived then
    raise exception 'destination_archived' using errcode = '22023';
  end if;
  -- Same group only: bank/cash ↔ bank/cash, card ↔ card.
  if (src.kind = 'credit_card') <> (dst.kind = 'credit_card')
     or dst.kind not in ('bank', 'cash', 'credit_card') then
    raise exception 'destination_different_group' using errcode = '22023';
  end if;

  deps := public.account_dependencies(p_from);
  if jsonb_array_length(deps->'openSplits') > 0 then
    raise exception 'unsettled_splits' using errcode = '23503', detail = deps::text;
  end if;
  if (deps->>'loanEvents')::int > 0 then
    raise exception 'loan_history_attached' using errcode = '23503', detail = deps::text;
  end if;
  -- A transfer between the two would become a transfer from an account to
  -- itself.
  if exists (
    select 1 from public.transactions t
     where t.household_id = src.household_id
       and t.deleted_at is null
       and ((t.account_id = p_from and t.to_account_id = p_to)
         or (t.account_id = p_to and t.to_account_id = p_from))
  ) then
    raise exception 'transfers_between_accounts' using errcode = '23514';
  end if;

  -- Every row, tombstoned ones included, so no history points at a deleted account.
  update public.transactions set account_id = p_to
   where household_id = src.household_id and account_id = p_from;
  get diagnostics n_debit = row_count;
  update public.transactions set to_account_id = p_to
   where household_id = src.household_id and to_account_id = p_from;
  get diagnostics n_credit = row_count;

  update public.recurring_schedules
     set txn_template = jsonb_set(txn_template, '{accountId}', to_jsonb(p_to::text))
   where household_id = src.household_id and txn_template->>'accountId' = p_from::text;
  get diagnostics n_sched = row_count;
  update public.recurring_schedules
     set txn_template = jsonb_set(txn_template, '{toAccountId}', to_jsonb(p_to::text))
   where household_id = src.household_id and txn_template->>'toAccountId' = p_from::text;
  get diagnostics n_sched2 = row_count;

  -- The source's starting point and its reconciled drift move with its rows.
  folded := coalesce(src.opening_balance, 0) + coalesce(src.reconciliation_offset, 0);
  if folded <> 0 then
    update public.accounts
       set reconciliation_offset = reconciliation_offset + folded,
           reconciliation_log = reconciliation_log || jsonb_build_array(jsonb_build_object(
             'at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
             'delta', folded,
             'kind', 'merge',
             'stated_value', null,
             'note', 'Moved from ' || src.name))
     where id = p_to;
  end if;

  perform set_config('vyact.account_delete', 'on', true);
  update public.accounts set deleted_at = now(), is_default = false where id = p_from;
  perform set_config('vyact.account_delete', '', true);

  return jsonb_build_object(
    'status', 'moved', 'from', p_from, 'to', p_to,
    'transactions', n_debit + n_credit, 'schedules', n_sched + n_sched2, 'folded', folded);
end $fn$;

revoke all on function public.delete_account(uuid) from public;
revoke all on function public.delete_account(uuid) from anon;
grant execute on function public.delete_account(uuid) to authenticated;
revoke all on function public.move_account_and_delete(uuid, uuid) from public;
revoke all on function public.move_account_and_delete(uuid, uuid) from anon;
grant execute on function public.move_account_and_delete(uuid, uuid) to authenticated;

-- ── 4. Cash in Hand is never handed back archived ───────────────────────────────────────────────────
-- An archived Cash in Hand could only come from a direct write the guard above now refuses. Restore any
-- (keeping it the default only if no other live account is), so WhatsApp and the app see it again.
update public.accounts a
   set is_archived = false,
       is_default = a.is_default and not exists (
         select 1 from public.accounts d
          where d.household_id = a.household_id and d.id <> a.id
            and d.is_default and not d.is_archived and d.deleted_at is null)
 where a.kind = 'cash' and a.is_archived and a.deleted_at is null;

create or replace function public.ensure_cash_account(p_household uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  caller_role text;
  acc public.accounts;
begin
  caller_role := public.role_in(p_household);
  if auth.uid() is null or caller_role is null then
    raise exception 'not_a_household_member' using errcode = '42501';
  end if;

  if caller_role in ('owner', 'admin', 'member') then
    insert into public.accounts (household_id, kind, name, currency, is_default, opening_balance, source)
    select h.id, 'cash', 'Cash in Hand', h.base_currency,
           not exists (select 1 from public.accounts d
                        where d.household_id = h.id
                          and d.is_default and not d.is_archived and d.deleted_at is null),
           0, 'user'
      from public.households h
     where h.id = p_household
    on conflict (household_id) where kind = 'cash' and deleted_at is null do nothing;
    -- T2c (DB-INT-09): Cash in Hand is never archived; one that was is restored.
    update public.accounts a
       set is_archived = false,
           is_default = a.is_default and not exists (
             select 1 from public.accounts d
              where d.household_id = a.household_id and d.id <> a.id
                and d.is_default and not d.is_archived and d.deleted_at is null)
     where a.household_id = p_household and a.kind = 'cash' and a.is_archived and a.deleted_at is null;
  end if;

  select * into acc
    from public.accounts
   where household_id = p_household and kind = 'cash' and deleted_at is null;
  if not found then
    return null;
  end if;
  return to_jsonb(acc);
end $$;

revoke all on function public.ensure_cash_account(uuid) from public;
revoke all on function public.ensure_cash_account(uuid) from anon;
grant execute on function public.ensure_cash_account(uuid) to authenticated;

-- ── 5. Schedules: their owner and the template's account and asset are the household's own ────────
-- A template id that is not a UUID, or names no row, links nothing and is left alone.
create or replace function public.assert_recurring_tenant_consistency()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  k   text;
  v   text;
  uid uuid;
  hid uuid;
begin
  if new.owner_member_id is not null and (tg_op = 'INSERT' or old.owner_member_id is distinct from new.owner_member_id)
     and not exists (select 1 from public.memberships where id = new.owner_member_id and household_id = new.household_id) then
    raise exception 'recurring_schedules.owner_member_id belongs to a different household' using errcode = '23503';
  end if;
  foreach k in array array['accountId', 'toAccountId', 'assetId'] loop
    v := new.txn_template ->> k;
    continue when v is null or v !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    continue when tg_op = 'UPDATE' and (old.txn_template ->> k) is not distinct from v;
    uid := v::uuid;
    if k = 'assetId' then
      select household_id into hid from public.assets where id = uid;
    else
      select household_id into hid from public.accounts where id = uid;
    end if;
    if found and hid <> new.household_id then
      raise exception 'recurring_schedules.txn_template.% belongs to a different household', k using errcode = '23503';
    end if;
  end loop;
  return new;
end $$;
revoke all on function public.assert_recurring_tenant_consistency() from public, anon, authenticated;

drop trigger if exists trg_recurring_tenant_consistency on public.recurring_schedules;
create trigger trg_recurring_tenant_consistency
  before insert or update on public.recurring_schedules
  for each row execute function public.assert_recurring_tenant_consistency();

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261103120000_t2d_whatsapp_sweep_cron.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.118.0 — Track T2, part d: WhatsApp's replay sweep runs on its own.
-- Audit BE-WA-12 (owner decisions 18–19 Oct 2026: every 5 minutes; "Sorry, I couldn't process that. Please
-- send it again.").
--
-- The webhook stores every message before it answers Meta, then processes it. A message whose processing
-- failed, or whose worker died, or that was never claimed, is replayed by the sweep (`?mode=sweep`). The
-- sweep only ran when some other message arrived, so a household that went quiet kept a failed message
-- waiting, and a stale claim waited for unrelated traffic. Now pg_cron calls it every 5 minutes, with a
-- secret generated into Vault here (the recurring-post pattern, 20261015120000): the webhook checks the
-- header through `whatsapp_sweep_cron_ok`, and nobody handles the value. The webhook (deployed without JWT
-- verification, because Meta has no Supabase JWT) still accepts the service key, as before.
--
-- MONEY MODEL: untouched. A replay is safe: `whatsapp_log_transaction` claims the message id first, so a
-- message whose entry already landed comes back `duplicate`.

begin;

-- The cron secret check (plpgsql: its body is resolved at call time, not here).
create or replace function public.whatsapp_sweep_cron_ok(p text)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  return length(coalesce(p, '')) >= 32
     and exists (select 1 from vault.decrypted_secrets s where s.name = 'whatsapp_sweep_cron_secret' and s.decrypted_secret = p);
end;
$$;
revoke all on function public.whatsapp_sweep_cron_ok(text) from public, anon, authenticated;
grant execute on function public.whatsapp_sweep_cron_ok(text) to service_role;

-- The secret (generated here; it never leaves the database and the function) and the job.
do $$
begin
  -- Nested, so a database without Vault (the PGlite tests) never plans the inner query.
  if exists (select 1 from pg_namespace where nspname = 'vault') then
    if not exists (select 1 from vault.secrets where name = 'whatsapp_sweep_cron_secret') then
      perform vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'whatsapp_sweep_cron_secret',
                                  'pg_cron -> whatsapp-webhook sweep');
    end if;
  end if;

  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'whatsapp-inbox-sweep';
    perform cron.schedule('whatsapp-inbox-sweep', '*/5 * * * *', $job$
      select net.http_post(
        url     := 'https://dmxqkvploojokffuhxnz.supabase.co/functions/v1/whatsapp-webhook?mode=sweep',
        headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', s.decrypted_secret),
        body    := '{}'::jsonb,
        timeout_milliseconds := 55000)
      from vault.decrypted_secrets s where s.name = 'whatsapp_sweep_cron_secret';
    $job$);
  end if;
end;
$$;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261104120000_loan_paying_account.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.119.0 — A loan that records its EMIs automatically always has an account to pay from.
-- Follow-up to T2c (v10.117.0). Owner decisions, 19 Oct 2026:
--   * deleting an account such a loan pays from is REFUSED; "Move and delete" carries the loan;
--   * archiving it is REFUSED until the loan pays from another account (enforced here, not only in the app);
--   * loans whose paying account is ALREADY deleted or archived are kept, with "Record automatically"
--     switched off.
--
-- The gap. `auto_record_due_emis` (pg_cron, every 30 min) pays each due EMI through `loan_payment_core`, which
-- refuses a paying account that is missing, deleted, archived, not bank/cash, or another household's
-- (`funding_account_invalid`). The job counts that as an error and moves on, so a loan whose paying account
-- had been deleted or archived simply stopped recording, every run, with nobody told; the app still said
-- "Vyact records this EMI on the day". (v10.117.0's note said such EMIs had landed on the deleted account.
-- They had not: they were never recorded.)
--
--   1. Repair: every live loan set to record automatically whose paying account is not usable has
--      "Record automatically" switched off. Its EMI then shows as Pay on its day. No loan, balance or
--      entry is changed or removed.
--   2. A loan set to record automatically can only point at a usable paying account
--      (`debts_funding_account_guard`), and any paying account is the household's own (DB-SEC-09's class).
--   3. `account_dependencies` lists such loans (`loans`); `delete_account` refuses while there are any, and
--      clears the paying account of a loan that does not record automatically (it was only a default).
--   4. `move_account_and_delete` moves every live loan's paying account to the destination.
--   5. `accounts_guard_lifecycle` (from the app) refuses archiving an account such a loan pays from.
--
-- MONEY MODEL: untouched. No balance, entry or debt figure moves.

begin;

-- ── 1. Repair ────────────────────────────────────────────────────────────────────────────────────────
update public.debts d
   set auto_record = false, updated_at = now()
 where d.deleted_at is null and d.auto_record and d.paid_off_at is null
   and coalesce(d.direction, 'owed_by_me') = 'owed_by_me'
   and not exists (select 1 from public.accounts a
                    where a.id = d.funding_account_id and a.household_id = d.household_id
                      and a.kind in ('bank', 'cash') and a.deleted_at is null and not a.is_archived);

-- ── 2. A loan's paying account ──────────────────────────────────────────────────────────────────────
create or replace function public.debts_funding_account_guard()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare acc public.accounts;
begin
  if new.funding_account_id is not null then
    select * into acc from public.accounts where id = new.funding_account_id;
    if (tg_op = 'INSERT' or old.funding_account_id is distinct from new.funding_account_id)
       and (not found or acc.household_id <> new.household_id) then
      raise exception 'debts.funding_account_id belongs to a different household' using errcode = '23503';
    end if;
  end if;
  -- Recording automatically needs an account a payment will accept: checked when it is switched on, or its
  -- account changes, on a live loan.
  if new.auto_record and new.deleted_at is null and new.paid_off_at is null
     and coalesce(new.direction, 'owed_by_me') = 'owed_by_me'
     and (tg_op = 'INSERT' or old.auto_record is distinct from true
          or old.funding_account_id is distinct from new.funding_account_id)
     and (new.funding_account_id is null or acc.id is null or acc.kind not in ('bank', 'cash')
          or acc.deleted_at is not null or acc.is_archived) then
    raise exception 'loan_needs_paying_account: a loan recorded automatically needs a live bank or cash account to pay from'
      using errcode = '23514';
  end if;
  return new;
end $$;
revoke all on function public.debts_funding_account_guard() from public, anon, authenticated;

drop trigger if exists trg_debts_funding_account_guard on public.debts;
create trigger trg_debts_funding_account_guard
  before insert or update on public.debts
  for each row execute function public.debts_funding_account_guard();

-- ── 3. What is attached to an account: now also the loans that record from it ──────────────────────
-- Unchanged otherwise (20260910150000_r2_accounts_card_metadata_delete_guard.sql).
create or replace function public.account_dependencies(p_account_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $fn$
declare
  acc public.accounts;
  result jsonb;
begin
  select * into acc from public.accounts where id = p_account_id and deleted_at is null;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  if auth.uid() is null or not public.is_member(acc.household_id) then
    raise exception 'not_a_household_member' using errcode = '42501';
  end if;

  with txns as (
    select t.id, t.amount, t.date, t.category, t.type, t.description
      from public.transactions t
     where t.household_id = acc.household_id
       and t.deleted_at is null
       and (t.account_id = acc.id or t.to_account_id = acc.id)
  ), grouped as (
    select coalesce(nullif(trim(description), ''), category, type) as label,
           count(*) as n, sum(amount) as total
      from txns
     group by 1
     order by count(*) desc, sum(amount) desc
     limit 3
  )
  select jsonb_build_object(
    'accountId', acc.id,
    'transactions', jsonb_build_object(
      'count',     (select count(*) from txns),
      'total',     coalesce((select sum(amount) from txns), 0),
      'firstDate', (select min(date) from txns),
      'lastDate',  (select max(date) from txns),
      'groups',    coalesce((select jsonb_agg(jsonb_build_object('label', label, 'count', n, 'total', total))
                               from grouped), '[]'::jsonb)),
    'recurring', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', r.id,
               'label', coalesce(nullif(r.txn_template->>'description', ''), r.txn_template->>'category', 'Recurring')))
        from public.recurring_schedules r
       where r.household_id = acc.household_id
         and r.deleted_at is null
         and (r.txn_template->>'accountId' = acc.id::text
              or r.txn_template->>'toAccountId' = acc.id::text)), '[]'::jsonb),
    'openSplits', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'txnId', s.txn_id))
        from public.shared_splits s
        join txns t on t.id = s.txn_id
       where s.closed_at is null), '[]'::jsonb),
    'loanEvents', (select count(*) from public.loan_payment_events e where e.loan_account_id = acc.id),
    -- v10.119.0: live loans that record their EMIs automatically from this account.
    'loans', coalesce((
      select jsonb_agg(jsonb_build_object('id', d.id, 'name', d.name) order by d.name)
        from public.debts d
       where d.household_id = acc.household_id and d.funding_account_id = acc.id
         and d.deleted_at is null and d.paid_off_at is null and d.auto_record
         and coalesce(d.direction, 'owed_by_me') = 'owed_by_me'), '[]'::jsonb)
  ) into result;

  return result;
end $fn$;
revoke all on function public.account_dependencies(uuid) from public;
revoke all on function public.account_dependencies(uuid) from anon;
grant execute on function public.account_dependencies(uuid) to authenticated;

-- ── 4. delete_account: refused while a loan records from it ─────────────────────────────────────────
-- Unchanged otherwise (20261102120000_t2c_ledger_integrity.sql).
create or replace function public.delete_account(p_account_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  acc  public.accounts;
  deps jsonb;
begin
  select * into acc from public.accounts
   where id = p_account_id and deleted_at is null
   for update;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  -- Owners and admins only.
  if auth.uid() is null or coalesce(public.role_in(acc.household_id), '') not in ('owner', 'admin') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if acc.kind = 'cash' then
    raise exception 'cash_account_protected' using errcode = '22023';
  end if;
  if acc.kind = 'loan' then
    raise exception 'system_account_protected' using errcode = '22023';
  end if;

  deps := public.account_dependencies(p_account_id);
  if (deps #>> '{transactions,count}')::int > 0
     or jsonb_array_length(deps->'recurring') > 0
     or jsonb_array_length(deps->'openSplits') > 0
     or (deps->>'loanEvents')::int > 0
     or jsonb_array_length(deps->'loans') > 0 then
    raise exception 'account_in_use' using errcode = '23503', detail = deps::text;
  end if;

  -- A loan that does not record automatically only had this as its default paying account.
  update public.debts set funding_account_id = null, updated_at = now()
   where household_id = acc.household_id and funding_account_id = p_account_id and deleted_at is null;

  -- A tombstone, not a row delete: under refresh-based sync another device still
  -- holding the row would otherwise upload it again. Unrecoverable from the app.
  perform set_config('vyact.account_delete', 'on', true);
  update public.accounts set deleted_at = now(), is_default = false where id = p_account_id;
  perform set_config('vyact.account_delete', '', true);
  return jsonb_build_object('status', 'deleted', 'accountId', p_account_id);
end $fn$;

-- ── 5. move_account_and_delete: the loans move with the history ─────────────────────────────────────
-- Unchanged otherwise (20261102120000_t2c_ledger_integrity.sql).
create or replace function public.move_account_and_delete(p_from uuid, p_to uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  src      public.accounts;
  dst      public.accounts;
  deps     jsonb;
  n_debit  int;
  n_credit int;
  n_sched  int;
  n_sched2 int;
  n_loans  int;
  folded   numeric;
begin
  if p_from = p_to then
    raise exception 'same_account' using errcode = '22023';
  end if;

  select * into src from public.accounts where id = p_from and deleted_at is null for update;
  if not found then
    raise exception 'account_not_found' using errcode = 'P0002';
  end if;
  select * into dst from public.accounts where id = p_to and deleted_at is null for update;
  if not found then
    raise exception 'destination_not_found' using errcode = 'P0002';
  end if;
  if src.household_id <> dst.household_id then
    raise exception 'different_household' using errcode = '22023';
  end if;
  if auth.uid() is null or coalesce(public.role_in(src.household_id), '') not in ('owner', 'admin') then
    raise exception 'not_allowed' using errcode = '42501';
  end if;

  if src.kind not in ('bank', 'credit_card') then
    raise exception 'source_not_movable' using errcode = '22023';
  end if;
  if dst.is_archived then
    raise exception 'destination_archived' using errcode = '22023';
  end if;
  -- Same group only: bank/cash ↔ bank/cash, card ↔ card.
  if (src.kind = 'credit_card') <> (dst.kind = 'credit_card')
     or dst.kind not in ('bank', 'cash', 'credit_card') then
    raise exception 'destination_different_group' using errcode = '22023';
  end if;

  deps := public.account_dependencies(p_from);
  if jsonb_array_length(deps->'openSplits') > 0 then
    raise exception 'unsettled_splits' using errcode = '23503', detail = deps::text;
  end if;
  if (deps->>'loanEvents')::int > 0 then
    raise exception 'loan_history_attached' using errcode = '23503', detail = deps::text;
  end if;
  -- A transfer between the two would become a transfer from an account to
  -- itself.
  if exists (
    select 1 from public.transactions t
     where t.household_id = src.household_id
       and t.deleted_at is null
       and ((t.account_id = p_from and t.to_account_id = p_to)
         or (t.account_id = p_to and t.to_account_id = p_from))
  ) then
    raise exception 'transfers_between_accounts' using errcode = '23514';
  end if;

  -- Every row, tombstoned ones included, so no history points at a deleted account.
  update public.transactions set account_id = p_to
   where household_id = src.household_id and account_id = p_from;
  get diagnostics n_debit = row_count;
  update public.transactions set to_account_id = p_to
   where household_id = src.household_id and to_account_id = p_from;
  get diagnostics n_credit = row_count;

  update public.recurring_schedules
     set txn_template = jsonb_set(txn_template, '{accountId}', to_jsonb(p_to::text))
   where household_id = src.household_id and txn_template->>'accountId' = p_from::text;
  get diagnostics n_sched = row_count;
  update public.recurring_schedules
     set txn_template = jsonb_set(txn_template, '{toAccountId}', to_jsonb(p_to::text))
   where household_id = src.household_id and txn_template->>'toAccountId' = p_from::text;
  get diagnostics n_sched2 = row_count;

  -- v10.119.0: the loans paid from it are paid from the destination now.
  update public.debts set funding_account_id = p_to, updated_at = now()
   where household_id = src.household_id and funding_account_id = p_from and deleted_at is null;
  get diagnostics n_loans = row_count;

  -- The source's starting point and its reconciled drift move with its rows.
  folded := coalesce(src.opening_balance, 0) + coalesce(src.reconciliation_offset, 0);
  if folded <> 0 then
    update public.accounts
       set reconciliation_offset = reconciliation_offset + folded,
           reconciliation_log = reconciliation_log || jsonb_build_array(jsonb_build_object(
             'at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
             'delta', folded,
             'kind', 'merge',
             'stated_value', null,
             'note', 'Moved from ' || src.name))
     where id = p_to;
  end if;

  perform set_config('vyact.account_delete', 'on', true);
  update public.accounts set deleted_at = now(), is_default = false where id = p_from;
  perform set_config('vyact.account_delete', '', true);

  return jsonb_build_object(
    'status', 'moved', 'from', p_from, 'to', p_to,
    'transactions', n_debit + n_credit, 'schedules', n_sched + n_sched2, 'loans', n_loans, 'folded', folded);
end $fn$;

revoke all on function public.delete_account(uuid) from public;
revoke all on function public.delete_account(uuid) from anon;
grant execute on function public.delete_account(uuid) to authenticated;
revoke all on function public.move_account_and_delete(uuid, uuid) from public;
revoke all on function public.move_account_and_delete(uuid, uuid) from anon;
grant execute on function public.move_account_and_delete(uuid, uuid) to authenticated;

-- ── 6. From the app, an account a loan records from can't be archived ──────────────────────────────
-- Unchanged otherwise (20261102120000_t2c_ledger_integrity.sql).
create or replace function public.accounts_guard_lifecycle()
returns trigger
language plpgsql
security definer   -- v10.119.0: it reads loans, which row security must not hide from it
set search_path = public, pg_temp
as $$
declare
  v_claims text := nullif(current_setting('request.jwt.claims', true), '');
  v_loan   text;
begin
  if v_claims is null or (v_claims::jsonb ->> 'role') is distinct from 'authenticated' then
    return new;
  end if;
  if old.kind = 'cash' and (new.kind is distinct from 'cash'
       or (new.is_archived and not old.is_archived)
       or (new.deleted_at is not null and old.deleted_at is null)) then
    raise exception 'cash_account_protected: Cash in Hand can be renamed, never archived or deleted'
      using errcode = '22023';
  end if;
  if new.kind = 'cash' and old.kind is distinct from 'cash' then
    raise exception 'cash_account_protected: Cash in Hand is created by the household, never converted'
      using errcode = '22023';
  end if;
  if new.deleted_at is not null and old.deleted_at is null
     and current_setting('vyact.account_delete', true) is distinct from 'on' then
    raise exception 'account_delete_guarded: delete an account with delete_account or move_account_and_delete'
      using errcode = '42501';
  end if;
  if old.deleted_at is not null and new.deleted_at is null then
    raise exception 'account_delete_final: a deleted account stays deleted' using errcode = '42501';
  end if;
  -- v10.119.0 (owner, 19 Oct 2026): a loan's automatic EMI would be refused from an archived account.
  if new.is_archived and not old.is_archived then
    select string_agg(d.name, ', ' order by d.name) into v_loan
      from public.debts d
     where d.household_id = old.household_id and d.funding_account_id = old.id
       and d.deleted_at is null and d.paid_off_at is null and d.auto_record
       and coalesce(d.direction, 'owed_by_me') = 'owed_by_me';
    if v_loan is not null then
      raise exception 'account_pays_a_loan: % records its EMIs from this account; change its paying account first', v_loan
        using errcode = '23503';
    end if;
  end if;
  return new;
end $$;
revoke all on function public.accounts_guard_lifecycle() from public, anon, authenticated;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261105120000_t5c_ai_usage_summary_sources.sql
-- ─────────────────────────────────────────────────────────────────────
-- T5c (v10.122.0; audit FE-PIP-09; owner, 19 Oct 2026: "timed turns only; admin counts read only the
-- server's rows").
--
-- ai_usage holds two kinds of row (`source`, since W1c 20261011120100):
--   • 'gateway' — one per MODEL CALL, written by the server (ask-vyact, WhatsApp): provider, model,
--     tokens, cost, the call's latency and outcome. A Pip turn makes one or two (classify, phrase).
--   • 'client'  — one per TURN, written by the app: intent, sentiment, length, the turn's outcome and its
--     per-stage timings. Since v10.122.0 only for a turn that called the model.
-- admin_ai_usage_summary() counted both together, so every call figure ran two to three times over and
-- the cost, token and latency figures mixed in rows that carry none. It now reads:
--   • call figures (total, users, last 7 / 30 days, by model / provider, tokens, cost, latency, error
--     rate) from the gateway's rows;
--   • turn figures (by intent / sentiment, user segments, by backend, fallback / deterministic /
--     helpful rates) from the app's rows.
-- Same keys, same shape: the admin Intelligence page (admin v1.4.7) relabels the call counts. Grants are
-- untouched (create or replace keeps them; v10.22 locked the function to admins).

create or replace function public.admin_ai_usage_summary()
  returns jsonb language plpgsql security definer set search_path to 'public'
as $$
declare result jsonb;
begin
  if not public.is_admin('content') then
    raise exception 'forbidden: admin role required';
  end if;

  with calls as (select * from ai_usage where source = 'gateway'),
       turns as (select * from ai_usage where source = 'client')
  select jsonb_build_object(
    -- ── Model calls (the gateway's rows) ─────────────────────────────────────
    'total',     (select count(*) from calls),
    'users',     (select count(distinct user_id) from calls),
    'last7',     (select count(*) from calls where ts > now() - interval '7 days'),
    'last30',    (select count(*) from calls where ts > now() - interval '30 days'),

    -- ── Turns (the app's rows: what was asked, how it felt) ─────────────────
    'byIntent',  (select coalesce(jsonb_object_agg(intent, c), '{}'::jsonb)
                    from (select coalesce(intent,'other') as intent, count(*) c
                            from turns group by 1) t),
    'bySentiment', (select coalesce(jsonb_object_agg(sentiment, c), '{}'::jsonb)
                    from (select coalesce(sentiment,'neutral') as sentiment, count(*) c
                            from turns group by 1) t),
    'segments', (
      select coalesce(jsonb_agg(seg order by (seg->>'interactions')::int desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'userId',       u.user_id,
          'email',        au.email,
          'interactions', u.interactions,
          'topIntent',    u.top_intent,
          'avgSentiment', u.avg_sentiment,
          'lastSeen',     u.last_seen
        ) as seg
        from (
          select user_id,
                 count(*)                                   as interactions,
                 mode() within group (order by intent)      as top_intent,
                 round(avg(sentiment_score)::numeric, 2)    as avg_sentiment,
                 max(ts)                                    as last_seen
          from turns
          where user_id is not null
          group by user_id
          order by count(*) desc
          limit 200
        ) u
        left join auth.users au on au.id = u.user_id
      ) s
    ),

    -- ── The spend gate (model calls) ─────────────────────────────────────────
    'byModel', (
      select coalesce(jsonb_object_agg(model, n), '{}'::jsonb)
      from (select coalesce(model,'n/a') as model, count(*) n
              from calls where ts > now() - interval '30 days'
             group by 1 order by 2 desc limit 25) t),
    'byProvider', (
      select coalesce(jsonb_object_agg(provider, n), '{}'::jsonb)
      from (select coalesce(provider,'n/a') as provider, count(*) n
              from calls where ts > now() - interval '30 days' group by 1) t),
    'byBackend', (
      select coalesce(jsonb_object_agg(backend, n), '{}'::jsonb)
      from (select coalesce(backend,'unknown') as backend, count(*) n
              from turns where ts > now() - interval '30 days' group by 1) t),
    'tokens30', jsonb_build_object(
      'prompt',     coalesce((select sum(prompt_tokens)     from calls where ts > now() - interval '30 days'), 0),
      'completion', coalesce((select sum(completion_tokens) from calls where ts > now() - interval '30 days'), 0)),
    'cost30Usd',  coalesce((select round(sum(cost_usd), 4) from calls where ts > now() - interval '30 days'), 0),
    'cost7Usd',   coalesce((select round(sum(cost_usd), 4) from calls where ts > now() - interval '7 days'), 0),
    'latencyMsP50', (
      select coalesce(percentile_disc(0.5) within group (order by latency_ms), 0)
        from calls where latency_ms is not null and ts > now() - interval '30 days'),
    'latencyMsP95', (
      select coalesce(percentile_disc(0.95) within group (order by latency_ms), 0)
        from calls where latency_ms is not null and ts > now() - interval '30 days'),
    -- §10 targets: fallback rate < 15% (a turn's), thumbs-up >= 75% (a turn's), errors (a call's).
    'fallbackRate30', (
      select case when count(*) = 0 then 0
             else round(count(*) filter (where outcome = 'fallback')::numeric / count(*), 4) end
        from turns where ts > now() - interval '30 days'),
    'errorRate30', (
      select case when count(*) = 0 then 0
             else round(count(*) filter (where outcome = 'error')::numeric / count(*), 4) end
        from calls where ts > now() - interval '30 days'),
    'deterministicRate30', (
      select case when count(*) filter (where backend is not null) = 0 then 0
             else round(count(*) filter (where backend = 'rules')::numeric
                        / count(*) filter (where backend is not null), 4) end
        from turns where ts > now() - interval '30 days'),
    'helpfulRate30', (
      select case when count(*) filter (where helpful is not null) = 0 then 0
             else round(count(*) filter (where helpful)::numeric
                        / count(*) filter (where helpful is not null), 4) end
        from turns where ts > now() - interval '30 days'),
    'ratedCount30', (
      select count(*) from turns where helpful is not null and ts > now() - interval '30 days')
  ) into result;

  return result;
end;
$$;

comment on function public.admin_ai_usage_summary() is
  'T5c (v10.122.0, FE-PIP-09): call figures (total, users, last7/30, model, provider, tokens, cost, latency, error rate) from source = gateway rows (one per model call); turn figures (intent, sentiment, segments, backend, fallback, deterministic, helpful) from source = client rows (one per turn that called the model). Admins only.';

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261106120000_t5d_cron_project_url.sql
-- ─────────────────────────────────────────────────────────────────────
-- T5d (v10.123.0; audit DB-OPS-07, BE-FN-11; owner, 19 Oct 2026: "Deploy writes it").
--
-- Every scheduled job that calls an Edge Function named the PRODUCTION host in its command
-- (https://dmxqkvploojokffuhxnz.supabase.co/...). A database restored from these migrations, such as
-- vyact-test, generated its own cron secrets and then called production with them every few minutes
-- (production refused them, so nothing ran, but every call left a 403 in its logs and nothing in the test
-- project ever ran its jobs).
--
-- Each project now stores its own base URL in Vault as `project_url`, written by its deploy workflow
-- (deploy.yml for production, deploy-test-functions.yml for vyact-test) through set_project_url() below.
-- Every job builds its URL from it. A database with no `project_url` calls nothing: the job's query
-- finds no row, so net.http_post is never reached.
--
-- The eight jobs, each keeping its schedule, header and secret:
--   whatsapp-dispatch-alerts / -weekly / -bills / -digest / -monthly   x-dispatch-secret  whatsapp_dispatch_secret
--   web-push-dispatch                                                  x-cron-secret      web_push_cron_secret
--   recurring-post                                                     x-cron-secret      recurring_post_cron_secret
--   whatsapp-inbox-sweep                                               x-cron-secret      whatsapp_sweep_cron_secret
-- (whatsapp-retention and loan-auto-record run SQL only and call no URL.)

-- ── set_project_url: the one writer of `project_url` ────────────────────────────────────────────────
-- Only a Supabase project URL is accepted, so a typo can't point every job somewhere else. Not callable
-- from the app (anon / authenticated); the deploy workflows call it through the Management API.
create or replace function public.set_project_url(p_url text)
  returns text language plpgsql security definer set search_path = public, pg_temp
as $$
declare v_url text := rtrim(trim(p_url), '/');
        v_id uuid;
begin
  if v_url !~ '^https://[a-z0-9]{20}\.supabase\.co$' then
    raise exception 'project_url_invalid' using errcode = '22023',
      detail = 'Expected https://<20-character project ref>.supabase.co';
  end if;
  select id into v_id from vault.secrets where name = 'project_url';
  if v_id is null then
    perform vault.create_secret(v_url, 'project_url', 'This project''s base URL: pg_cron jobs call its Edge Functions (T5d)');
  else
    perform vault.update_secret(v_id, v_url);
  end if;
  return v_url;
end;
$$;
revoke all on function public.set_project_url(text) from public, anon, authenticated;
grant execute on function public.set_project_url(text) to service_role;
comment on function public.set_project_url(text) is
  'T5d (v10.123.0): stores this project''s base URL in Vault (project_url) for the pg_cron jobs. Called by the deploy workflows; https://<ref>.supabase.co only.';

-- ── The jobs read it ──────────────────────────────────────────────────────────────────────────────────
do $$
declare
  j record;
begin
  if not exists (select 1 from pg_namespace where nspname = 'cron') then return; end if;
  for j in
    select * from (values
      ('whatsapp-dispatch-alerts',  '/functions/v1/whatsapp-dispatch?job=alerts',  'x-dispatch-secret', 'whatsapp_dispatch_secret'),
      ('whatsapp-dispatch-weekly',  '/functions/v1/whatsapp-dispatch?job=weekly',  'x-dispatch-secret', 'whatsapp_dispatch_secret'),
      ('whatsapp-dispatch-bills',   '/functions/v1/whatsapp-dispatch?job=bills',   'x-dispatch-secret', 'whatsapp_dispatch_secret'),
      ('whatsapp-dispatch-digest',  '/functions/v1/whatsapp-dispatch?job=digest',  'x-dispatch-secret', 'whatsapp_dispatch_secret'),
      ('whatsapp-dispatch-monthly', '/functions/v1/whatsapp-dispatch?job=monthly', 'x-dispatch-secret', 'whatsapp_dispatch_secret'),
      ('web-push-dispatch',         '/functions/v1/web-push?mode=dispatch',        'x-cron-secret',     'web_push_cron_secret'),
      ('recurring-post',            '/functions/v1/recurring-post',                'x-cron-secret',     'recurring_post_cron_secret'),
      ('whatsapp-inbox-sweep',      '/functions/v1/whatsapp-webhook?mode=sweep',   'x-cron-secret',     'whatsapp_sweep_cron_secret')
    ) as t(jobname, path, header, secret)
  loop
    perform cron.alter_job(c.jobid, command := format($cmd$
  select net.http_post(
    url     := u.decrypted_secret || %L,
    headers := jsonb_build_object('Content-Type', 'application/json', %L, s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s, vault.decrypted_secrets u
  where s.name = %L and u.name = 'project_url';
$cmd$, j.path, j.header, j.secret))
    from cron.job c where c.jobname = j.jobname;
  end loop;
end;
$$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261107120000_t4a_consent_and_confirmed_email.sql
-- ─────────────────────────────────────────────────────────────────────
-- T4a (v10.124.0; audit XC-PRV-09, DB-INT-15; owner decisions 19 Oct 2026: "server record + accept on
-- change"; "confirmed email only").
--
-- 1. CONSENT IS RECORDED BY THE SERVER AT SIGN-UP (XC-PRV-09).
--    The app recorded acceptance from the browser after sign-up, keyed on a sessionStorage flag. When the
--    project asks an email sign-up to confirm first, the verification link opens in a new tab, the flag is
--    gone, and nothing recorded that the person accepted. The sign-up form now sends the policy version
--    the person ticked in the sign-up metadata (`policy_version`), and handle_new_user stamps it on the
--    profile in the same transaction that creates the account. A sign-up without it (Google: an OAuth
--    sign-up carries no form data) is recorded by the app as before, and the app asks anyone whose
--    record is not the current version to accept it (T4b).
--
-- 2. A SPLIT FINDS YOU BY YOUR CONFIRMED EMAIL (DB-INT-15).
--    my_email() said it was "the verified-email analogue of is_member()", but it read auth.users.email
--    whether or not it was confirmed. Every split check reads it: is_split_participant, the
--    shared_split_shares_select policy, settle_share and resolve_participant_names. Where a person can
--    sign in before confirming, someone could register with another person's address and see, or settle,
--    the splits sent to it. It now returns the email only once it is confirmed (as my_verified_email()
--    does for household invitations). A person who hasn't confirmed sees their splits once they do; a
--    Google sign-in is confirmed already.

-- ── 1 ─────────────────────────────────────────────────────────────────────────────────────────────────
create or replace function public.handle_new_user()
  returns trigger language plpgsql security definer set search_path to 'public'
as $$
declare v_display_name text;
        v_policy text;
begin
  v_display_name := coalesce(
    nullif(btrim(new.raw_user_meta_data->>'display_name'), ''),
    nullif(btrim(new.raw_user_meta_data->>'full_name'), ''),     -- Google, Apple, GitHub via Supabase
    nullif(btrim(new.raw_user_meta_data->>'name'), ''),
    split_part(new.email, '@', 1));
  -- T4a (XC-PRV-09): the version of the Terms / Privacy / Cookies the person accepted on the sign-up form
  -- (an ISO date, lib/policyVersion.ts). Anything else is not a version and records nothing.
  v_policy := nullif(btrim(new.raw_user_meta_data->>'policy_version'), '');
  if v_policy !~ '^\d{4}-\d{2}-\d{2}$' then v_policy := null; end if;
  insert into profiles (id, display_name, tos_accepted_at, tos_version, privacy_accepted_at, privacy_version)
  values (new.id, v_display_name,
          case when v_policy is not null then now() end, v_policy,
          case when v_policy is not null then now() end, v_policy);
  insert into households (name, type, base_currency, created_by) values ('My Household', 'personal', 'USD', new.id);
  return new;
end; $$;

-- ── 2 ─────────────────────────────────────────────────────────────────────────────────────────────────
create or replace function public.my_email()
returns text
language sql stable security definer set search_path = public
as $$ select lower(email) from auth.users where id = auth.uid() and email_confirmed_at is not null; $$;

grant execute on function public.my_email() to authenticated;

-- Settling says why it can't, instead of "Must be signed in" to someone who is signed in but unconfirmed.
create or replace function public.settle_share(p_share_id uuid)
returns void
language plpgsql security definer set search_path = public
as $$
declare
  v_email text;
  v_matched uuid;
begin
  if auth.uid() is null then
    raise exception 'Must be signed in to settle a split share';
  end if;
  v_email := my_email();
  if v_email is null then
    raise exception 'Confirm your email address to settle splits shared with you' using errcode = '42501';
  end if;

  select id into v_matched from shared_split_shares
   where id = p_share_id and email = v_email;

  if v_matched is null then
    raise exception 'Share not found, or it is not yours to settle';
  end if;

  update shared_split_shares
     set paid = true, paid_at = now(), settled_user_id = auth.uid()
   where id = p_share_id;
end;
$$;

grant execute on function public.settle_share(uuid) to authenticated;

comment on function public.my_email() is
  'T4a (v10.124.0, DB-INT-15): the caller''s email, lower-case, once it is CONFIRMED (null before). Split sharing keys on it (is_split_participant, shared_split_shares_select, settle_share, resolve_participant_names).';

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261108120000_t4d_native_push.sql
-- ─────────────────────────────────────────────────────────────────────
-- T4d (v10.127.0) — lock-screen notifications for the Vyact Android app, through Firebase Cloud Messaging.
--
-- The Play Store app is the web app inside an Android WebView, which has no Web Push: it could never
-- register, so its alerts reached the phone only as local notifications raised while the app happened to be
-- running. Owner decisions, 19 Oct 2026:
--   • ONE device list: an Android app device is a `push_subscriptions` row of kind 'fcm' with its FCM
--     registration token, beside the browsers' 'webpush' rows. The same 10-device cap, test, sign-out and
--     dispatcher rules (P1 only, the device's switches, quiet hours in its zone, never a backlog, members
--     only, "Show details on the lock screen") apply to both;
--   • the server is the only source on a registered phone (the app stops its own local notifications);
--   • on by default in the app; a tap opens the app on the alert.
-- The web-push function sends a kind 'fcm' row through FCM's HTTP v1 API with the project's service account
-- (Edge Function secret FCM_SERVICE_ACCOUNT_JSON); no person handles a token.

begin;

alter table public.push_subscriptions
  add column if not exists kind text not null default 'webpush',
  add column if not exists fcm_token text;

alter table public.push_subscriptions drop constraint if exists push_subscriptions_kind_check;
alter table public.push_subscriptions add constraint push_subscriptions_kind_check check (kind in ('webpush', 'fcm'));

-- A Web Push row has an endpoint and its keys; an FCM row has only its token.
alter table public.push_subscriptions alter column endpoint drop not null;
alter table public.push_subscriptions alter column p256dh drop not null;
alter table public.push_subscriptions alter column auth drop not null;
alter table public.push_subscriptions drop constraint if exists ck_push_subscription_shape;
alter table public.push_subscriptions add constraint ck_push_subscription_shape check (
  (kind = 'webpush' and endpoint is not null and p256dh is not null and auth is not null and fcm_token is null)
  or (kind = 'fcm' and fcm_token is not null and endpoint is null and p256dh is null and auth is null)
);
create unique index if not exists uq_push_sub_fcm_token on public.push_subscriptions (fcm_token);

comment on column public.push_subscriptions.kind is
  'T4d (v10.127.0): webpush = a browser or installed web app (endpoint + keys); fcm = the Vyact Android app (fcm_token).';
comment on column public.push_subscriptions.fcm_token is
  'T4d: the Android app''s Firebase Cloud Messaging registration token. Written only by register_native_push.';

-- ── The Android app's device (the signed-in person, for their own phone) ─────────────────────────────────

-- Register (or refresh) THIS phone for the caller's active household. The token is the device: a second call
-- updates the household, zone and switches, and a phone that signs in as someone else moves to them, starting
-- fresh (no backlog), exactly as register_push_subscription does for a browser.
create or replace function public.register_native_push(
  p_token text, p_household_id uuid,
  p_user_agent text default null, p_tz text default null, p_prefs jsonb default '{}'::jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if not public.is_member(p_household_id) then raise exception 'not_a_member' using errcode = '42501'; end if;
  -- An FCM registration token: base64url characters and colons, a few hundred at most.
  if p_token is null or length(p_token) not between 32 and 4096 or p_token !~ '^[A-Za-z0-9_:-]+$' then
    raise exception 'bad_token' using errcode = '22023';
  end if;
  insert into public.push_subscriptions (user_id, household_id, kind, fcm_token, user_agent, tz, prefs)
  values (auth.uid(), p_household_id, 'fcm', p_token, left(p_user_agent, 300), left(p_tz, 64), coalesce(p_prefs, '{}'::jsonb))
  on conflict (fcm_token) do update
     set user_id = excluded.user_id, household_id = excluded.household_id,
         user_agent = excluded.user_agent, tz = excluded.tz, prefs = excluded.prefs, updated_at = now(),
         disabled_at = null, failures = 0,
         created_at = case when push_subscriptions.user_id <> excluded.user_id
                             or push_subscriptions.household_id <> excluded.household_id
                           then now() else push_subscriptions.created_at end
  returning id into v_id;
  -- One list: at most 10 live devices a person, browsers and phones together (as register_push_subscription).
  update public.push_subscriptions set disabled_at = now()
   where id in (select s.id from public.push_subscriptions s
                 where s.user_id = auth.uid() and s.disabled_at is null and s.id <> v_id
                 order by s.updated_at desc, s.created_at desc
                 offset 9);
  return jsonb_build_object('id', v_id);
end;
$$;

-- Stop this phone (switched off in Settings, or signing out).
create or replace function public.unregister_native_push(p_token text)
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  delete from public.push_subscriptions where kind = 'fcm' and fcm_token = p_token and user_id = auth.uid();
$$;

-- What the server knows about THIS phone, for the Settings status line.
create or replace function public.native_push_status(p_token text)
returns jsonb
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce((
    select jsonb_build_object('registered', true, 'active', s.disabled_at is null, 'last_status', s.last_status,
                              'last_success_at', s.last_success_at, 'household_id', s.household_id)
      from public.push_subscriptions s
     where s.kind = 'fcm' and s.fcm_token = p_token and s.user_id = auth.uid()
  ), jsonb_build_object('registered', false));
$$;

revoke all on function public.register_native_push(text, uuid, text, text, jsonb) from public, anon;
revoke all on function public.unregister_native_push(text) from public, anon;
revoke all on function public.native_push_status(text) from public, anon;
grant execute on function public.register_native_push(text, uuid, text, text, jsonb) to authenticated;
grant execute on function public.unregister_native_push(text) to authenticated;
grant execute on function public.native_push_status(text) to authenticated;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120000_q3a_budget_writes_owner_admin.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit DB-SEC-03, DB-OPS-03; owner decision D4, 20 Oct 2026).
--
-- upsert_budget is the single writer of budgets (CLAUDE.md, "Budget identity lives in the DB"). It is SECURITY
-- DEFINER and checked only that the caller was a member of the household it was given, so:
--   - a member or viewer could write a budget, which the budgets policies keep to owners and admins (production
--     carried an owner/admin guard the repo never had: DB-OPS-03);
--   - in replace mode, an id naming another household's budget rewrote THAT budget (`on conflict (id) do
--     update`): DB-SEC-03, pinned by the Q2 access matrix (Q2-AZ-007, Q2-AZ-009).
-- This is the function as the migrations left it, with those two checks added. upsert_budget_with_allocations
-- calls it first, so it inherits both.

CREATE OR REPLACE FUNCTION public.upsert_budget(h uuid, b jsonb, p_mode text DEFAULT 'create'::text)
 RETURNS SETOF budgets
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v   budgets%rowtype;
  rec budgets%rowtype;
  sc  text := nullif(b->>'scope','');
begin
  if auth.uid() is null then raise exception 'Must be signed in' using errcode = '28000'; end if;
  if not is_member(h) then raise exception 'Not a member of this household' using errcode = '42501'; end if;
  -- Q3a (DB-SEC-03; owner decision D4): budgets are the owner's and admins', as the budgets policies say.
  if coalesce(public.role_in(h), '') not in ('owner', 'admin') then
    raise exception 'budget_owner_or_admin: only the owner or an admin can change budgets' using errcode = '42501';
  end if;
  if p_mode not in ('create','replace') then raise exception 'bad mode %', p_mode; end if;

  v := jsonb_populate_record(null::budgets, b);
  v.household_id := h;
  if v.id is null then v.id := gen_random_uuid(); end if;
  -- Q3a (DB-SEC-03): an id that names another household's budget is refused, never rewritten through this one
  -- (replace mode's `on conflict (id) do update` rewrote it).
  if exists (select 1 from budgets where id = v.id and household_id is distinct from h) then
    raise exception 'budget_not_found' using errcode = 'P0002';
  end if;
  if v.currency   is null or v.currency   = '' then v.currency   := 'USD';       end if;
  if v.period     is null or v.period     = '' then v.period     := 'monthly';   end if;
  if v.confidence is null or v.confidence = '' then v.confidence := 'confirmed'; end if;
  if v.source     is null or v.source     = '' then v.source     := 'user';      end if;
  if v.created_at is null then v.created_at := now(); end if;
  v.updated_at := now();
  v.deleted_at := null;   -- a write always yields a LIVE row

  if p_mode = 'create' then
    if sc = 'month' then
      insert into budgets (id,household_id,category,monthly_limit,currency,color,period,period_start,period_end,scope,period_year,period_month,custom_name,confidence,source,estimated_at,confirmed_at,created_at,updated_at,deleted_at)
      values (v.id,h,v.category,v.monthly_limit,v.currency,v.color,v.period,v.period_start,v.period_end,'month',v.period_year,v.period_month,v.custom_name,v.confidence,v.source,v.estimated_at,v.confirmed_at,v.created_at,v.updated_at,null)
      on conflict (household_id,period_year,period_month) where scope='month' and deleted_at is null
      do nothing returning * into rec;
    elsif sc = 'annual' then
      insert into budgets (id,household_id,category,monthly_limit,currency,color,period,period_start,period_end,scope,period_year,period_month,custom_name,confidence,source,estimated_at,confirmed_at,created_at,updated_at,deleted_at)
      values (v.id,h,v.category,v.monthly_limit,v.currency,v.color,v.period,v.period_start,v.period_end,'annual',v.period_year,v.period_month,v.custom_name,v.confidence,v.source,v.estimated_at,v.confirmed_at,v.created_at,v.updated_at,null)
      on conflict (household_id,period_year) where scope='annual' and deleted_at is null
      do nothing returning * into rec;
    else
      insert into budgets (id,household_id,category,monthly_limit,currency,color,period,period_start,period_end,scope,period_year,period_month,custom_name,confidence,source,estimated_at,confirmed_at,created_at,updated_at,deleted_at)
      values (v.id,h,v.category,v.monthly_limit,v.currency,v.color,v.period,v.period_start,v.period_end,v.scope,v.period_year,v.period_month,v.custom_name,v.confidence,v.source,v.estimated_at,v.confirmed_at,v.created_at,v.updated_at,null)
      on conflict (id) do nothing returning * into rec;
    end if;

    if rec.id is null then
      raise exception 'BUDGET_EXISTS'
        using errcode = '23505',
              detail = concat('scope=', coalesce(sc,''), ' year=', v.period_year, ' month=', coalesce(v.period_month::text,''));
    end if;
    return next rec; return;
  end if;

  -- p_mode = 'replace'
  if sc = 'month' then
    insert into budgets (id,household_id,category,monthly_limit,currency,color,period,period_start,period_end,scope,period_year,period_month,custom_name,confidence,source,estimated_at,confirmed_at,created_at,updated_at,deleted_at)
    values (v.id,h,v.category,v.monthly_limit,v.currency,v.color,v.period,v.period_start,v.period_end,'month',v.period_year,v.period_month,v.custom_name,v.confidence,v.source,v.estimated_at,v.confirmed_at,v.created_at,v.updated_at,null)
    on conflict (household_id,period_year,period_month) where scope='month' and deleted_at is null
    do update set category=excluded.category, monthly_limit=excluded.monthly_limit, currency=excluded.currency, color=excluded.color, period=excluded.period, period_start=excluded.period_start, period_end=excluded.period_end, custom_name=excluded.custom_name, confidence=excluded.confidence, source=excluded.source, updated_at=now(), deleted_at=null
    returning * into rec;
  elsif sc = 'annual' then
    insert into budgets (id,household_id,category,monthly_limit,currency,color,period,period_start,period_end,scope,period_year,period_month,custom_name,confidence,source,estimated_at,confirmed_at,created_at,updated_at,deleted_at)
    values (v.id,h,v.category,v.monthly_limit,v.currency,v.color,v.period,v.period_start,v.period_end,'annual',v.period_year,v.period_month,v.custom_name,v.confidence,v.source,v.estimated_at,v.confirmed_at,v.created_at,v.updated_at,null)
    on conflict (household_id,period_year) where scope='annual' and deleted_at is null
    do update set category=excluded.category, monthly_limit=excluded.monthly_limit, currency=excluded.currency, color=excluded.color, period=excluded.period, period_start=excluded.period_start, period_end=excluded.period_end, custom_name=excluded.custom_name, confidence=excluded.confidence, source=excluded.source, updated_at=now(), deleted_at=null
    returning * into rec;
  else
    insert into budgets (id,household_id,category,monthly_limit,currency,color,period,period_start,period_end,scope,period_year,period_month,custom_name,confidence,source,estimated_at,confirmed_at,created_at,updated_at,deleted_at)
    values (v.id,h,v.category,v.monthly_limit,v.currency,v.color,v.period,v.period_start,v.period_end,v.scope,v.period_year,v.period_month,v.custom_name,v.confidence,v.source,v.estimated_at,v.confirmed_at,v.created_at,v.updated_at,null)
    on conflict (id) do update set category=excluded.category, monthly_limit=excluded.monthly_limit, currency=excluded.currency, color=excluded.color, period=excluded.period, period_start=excluded.period_start, period_end=excluded.period_end, custom_name=excluded.custom_name, confidence=excluded.confidence, source=excluded.source, updated_at=now(), deleted_at=null
    returning * into rec;
  end if;
  return next rec; return;
end;
$function$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120100_q3a_production_only_objects.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit DB-OPS-03, DB-OPS-16; owner decision D4, 20 Oct 2026: "codify + drop the backups").
--
-- Objects that exist only in production (the 28 May baseline recorded them, or the dashboard made them) are
-- brought under the migrations:
--
-- 1. migration_issues: the v9 migration's issue log. It had no row-level security, and Supabase's default grants
--    left it readable and writable through the API by anyone, signed out included (the Q2 access matrix pinned
--    it). Only the server reads it now.
-- 2. _backup_v9_*: the v9 redesign's in-database restore point (June 2026). The redesign shipped four months ago
--    and every later migration builds on it; the copies hold old transactions, accounts and budgets that no
--    erase, export or purge reaches. Dropped (irreversible).
-- 3. pg_trgm: installed in public by the baseline, used by nothing in the repo. Dropped when nothing in this
--    database uses it either; otherwise left as it is, with a notice, so a production-only dependent never breaks.

-- ── 1. migration_issues: server only ────────────────────────────────────────────────────────────────────────────
do $$
begin
  if to_regclass('public.migration_issues') is not null then
    alter table public.migration_issues enable row level security;
    revoke all on table public.migration_issues from public, anon, authenticated;
    grant select, insert, update, delete on table public.migration_issues to service_role;
  end if;
end $$;

-- ── 2. the v9 backups ───────────────────────────────────────────────────────────────────────────────────────────
do $$
declare t record;
begin
  for t in select c.relname from pg_class c
            where c.relnamespace = 'public'::regnamespace and c.relkind = 'r' and c.relname like '\_backup\_v9\_%'
  loop
    begin
      execute format('drop table public.%I', t.relname);
      raise notice 'Q3a: dropped the v9 backup table %', t.relname;
    exception when insufficient_privilege then
      -- Owned by a platform role: say so in the Deploy log rather than fail every later migration.
      raise notice 'Q3a: could not drop % (not its owner); drop it in the SQL editor', t.relname;
    end;
  end loop;
end $$;

-- ── 3. pg_trgm, only if nothing uses it ─────────────────────────────────────────────────────────────────────────
do $$
declare
  v_indexes   int;
  v_functions int;
begin
  if not exists (select 1 from pg_extension where extname = 'pg_trgm') then return; end if;

  -- An index built on one of its operator classes.
  select count(*) into v_indexes
    from pg_index i
    join pg_opclass o on o.oid = any (i.indclass::oid[])
    join pg_depend d on d.classid = 'pg_opclass'::regclass and d.objid = o.oid and d.deptype = 'e'
    join pg_extension e on e.oid = d.refobjid and e.extname = 'pg_trgm';

  -- A function body that calls it (pg_depend does not see inside a body).
  select count(*) into v_functions
    from pg_proc p
   where p.pronamespace not in ('pg_catalog'::regnamespace, 'information_schema'::regnamespace)
     and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
     and p.prosrc ~* '(similarity|show_trgm|show_limit|set_limit|_trgm)';

  if v_indexes = 0 and v_functions = 0 then
    begin
      drop extension pg_trgm;
      raise notice 'Q3a: pg_trgm dropped (nothing used it)';
    exception when insufficient_privilege then
      raise notice 'Q3a: pg_trgm is unused but owned by a platform role; drop it from the dashboard';
    end;
  else
    raise notice 'Q3a: pg_trgm kept: % index(es) and % function(s) use it', v_indexes, v_functions;
  end if;
end $$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120200_q3a_staff_tiers.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit ADM-05, ADM-06, ADM-14; owner decisions 20 Oct 2026). Staff see what their tier is for.
--
-- ADM-05: the needs/wants table (category_classifications) overrides the app's NEEDS_WANTS_MAP for every
--   household (the emergency floor, Pip's essentials, the runway). A content-tier admin could rewrite it. Only
--   super admins write it now, and a category must at least look like one of the app's ids (a lowercase id;
--   the list itself lives in constants.ts and the two Deno allowlists, never a fourth copy here).
-- ADM-06: content-tier admins saw every Pip user's email and per-person sentiment (the AI usage summary's
--   segments) and could read the whole ai_usage table. Segments are for super admins; ai_usage is read by its
--   own household's members, and staff read the summaries.
-- ADM-14: the dashboard's MRR summed every active row across currencies (INR 999 + USD 12 = "USD 1,011").
--   It is now per currency, counting active and trialing subscriptions; the summed figure is gone.

-- ── ADM-05 ─────────────────────────────────────────────────────────────────────────────────────────────────────
drop policy if exists cc_admin_write on public.category_classifications;
create policy cc_admin_write on public.category_classifications for all to authenticated
  using (public.is_admin('super')) with check (public.is_admin('super'));
alter table public.category_classifications drop constraint if exists ck_cc_category_id;
alter table public.category_classifications
  add constraint ck_cc_category_id check (category ~ '^[a-z][a-z0-9_]{0,39}$') not valid;

-- ── ADM-06 ─────────────────────────────────────────────────────────────────────────────────────────────────────
drop policy if exists ai_usage_select on public.ai_usage;
create policy ai_usage_select on public.ai_usage for select to authenticated using (public.is_member(household_id));

CREATE OR REPLACE FUNCTION public.admin_ai_usage_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare result jsonb;
begin
  if not public.is_admin('content') then
    raise exception 'forbidden: admin role required';
  end if;

  with calls as (select * from ai_usage where source = 'gateway'),
       turns as (select * from ai_usage where source = 'client')
  select jsonb_build_object(
    -- ── Model calls (the gateway's rows) ─────────────────────────────────────
    'total',     (select count(*) from calls),
    'users',     (select count(distinct user_id) from calls),
    'last7',     (select count(*) from calls where ts > now() - interval '7 days'),
    'last30',    (select count(*) from calls where ts > now() - interval '30 days'),

    -- ── Turns (the app's rows: what was asked, how it felt) ─────────────────
    'byIntent',  (select coalesce(jsonb_object_agg(intent, c), '{}'::jsonb)
                    from (select coalesce(intent,'other') as intent, count(*) c
                            from turns group by 1) t),
    'bySentiment', (select coalesce(jsonb_object_agg(sentiment, c), '{}'::jsonb)
                    from (select coalesce(sentiment,'neutral') as sentiment, count(*) c
                            from turns group by 1) t),
    -- Q3a (ADM-06): who asked what, by email, is for super admins only.
    'segments', case when not public.is_admin('super') then '[]'::jsonb else (
      select coalesce(jsonb_agg(seg order by (seg->>'interactions')::int desc), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'userId',       u.user_id,
          'email',        au.email,
          'interactions', u.interactions,
          'topIntent',    u.top_intent,
          'avgSentiment', u.avg_sentiment,
          'lastSeen',     u.last_seen
        ) as seg
        from (
          select user_id,
                 count(*)                                   as interactions,
                 mode() within group (order by intent)      as top_intent,
                 round(avg(sentiment_score)::numeric, 2)    as avg_sentiment,
                 max(ts)                                    as last_seen
          from turns
          where user_id is not null
          group by user_id
          order by count(*) desc
          limit 200
        ) u
        left join auth.users au on au.id = u.user_id
      ) s
    ) end,

    -- ── The spend gate (model calls) ─────────────────────────────────────────
    'byModel', (
      select coalesce(jsonb_object_agg(model, n), '{}'::jsonb)
      from (select coalesce(model,'n/a') as model, count(*) n
              from calls where ts > now() - interval '30 days'
             group by 1 order by 2 desc limit 25) t),
    'byProvider', (
      select coalesce(jsonb_object_agg(provider, n), '{}'::jsonb)
      from (select coalesce(provider,'n/a') as provider, count(*) n
              from calls where ts > now() - interval '30 days' group by 1) t),
    'byBackend', (
      select coalesce(jsonb_object_agg(backend, n), '{}'::jsonb)
      from (select coalesce(backend,'unknown') as backend, count(*) n
              from turns where ts > now() - interval '30 days' group by 1) t),
    'tokens30', jsonb_build_object(
      'prompt',     coalesce((select sum(prompt_tokens)     from calls where ts > now() - interval '30 days'), 0),
      'completion', coalesce((select sum(completion_tokens) from calls where ts > now() - interval '30 days'), 0)),
    'cost30Usd',  coalesce((select round(sum(cost_usd), 4) from calls where ts > now() - interval '30 days'), 0),
    'cost7Usd',   coalesce((select round(sum(cost_usd), 4) from calls where ts > now() - interval '7 days'), 0),
    'latencyMsP50', (
      select coalesce(percentile_disc(0.5) within group (order by latency_ms), 0)
        from calls where latency_ms is not null and ts > now() - interval '30 days'),
    'latencyMsP95', (
      select coalesce(percentile_disc(0.95) within group (order by latency_ms), 0)
        from calls where latency_ms is not null and ts > now() - interval '30 days'),
    -- §10 targets: fallback rate < 15% (a turn's), thumbs-up >= 75% (a turn's), errors (a call's).
    'fallbackRate30', (
      select case when count(*) = 0 then 0
             else round(count(*) filter (where outcome = 'fallback')::numeric / count(*), 4) end
        from turns where ts > now() - interval '30 days'),
    'errorRate30', (
      select case when count(*) = 0 then 0
             else round(count(*) filter (where outcome = 'error')::numeric / count(*), 4) end
        from calls where ts > now() - interval '30 days'),
    'deterministicRate30', (
      select case when count(*) filter (where backend is not null) = 0 then 0
             else round(count(*) filter (where backend = 'rules')::numeric
                        / count(*) filter (where backend is not null), 4) end
        from turns where ts > now() - interval '30 days'),
    'helpfulRate30', (
      select case when count(*) filter (where helpful is not null) = 0 then 0
             else round(count(*) filter (where helpful)::numeric
                        / count(*) filter (where helpful is not null), 4) end
        from turns where ts > now() - interval '30 days'),
    'ratedCount30', (
      select count(*) from turns where helpful is not null and ts > now() - interval '30 days')
  ) into result;

  return result;
end;
$function$;

-- ── ADM-14 ─────────────────────────────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.admin_dashboard_kpis()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  total_users int; total_households int; multi_member_pct numeric;
  active_7d int; active_households_7d int; signups_7d int; signups_30d int;
  total_txns int; txns_7d int; published_articles int; total_favorites int;
  paid_subscriptions int; mrr_by_currency jsonb;
begin
  if not public.is_admin('roles') then raise exception 'forbidden'; end if;
  select count(*) into total_users      from auth.users;
  select count(*) into total_households from households;
  select count(*) into total_txns       from transactions;
  select count(*) into signups_7d  from auth.users where created_at > now() - interval '7 days';
  select count(*) into signups_30d from auth.users where created_at > now() - interval '30 days';
  select count(distinct m.user_id) into active_7d from memberships m
    join auth.users u on u.id = m.user_id where u.last_sign_in_at > now() - interval '7 days';
  select count(distinct t.household_id) into active_households_7d from transactions t
    where t.created_at > now() - interval '7 days';
  select case when total_households > 0
    then round(100.0 * count(*) filter (where member_count >= 2) / total_households, 1) else 0 end
    into multi_member_pct
    from (select household_id, count(*) as member_count from memberships group by household_id) t;
  select count(*) into txns_7d from transactions where created_at > now() - interval '7 days';
  select count(*) into published_articles from content_items where status = 'published';
  select count(*) into total_favorites    from content_favorites;
  -- Q3a (ADM-14): paying = active or trialing; revenue per currency, never summed across currencies.
  select count(*) into paid_subscriptions from subscriptions
   where tier <> 'free' and status in ('active', 'trialing');
  select coalesce(jsonb_object_agg(cur, amount), '{}'::jsonb) into mrr_by_currency
    from (select upper(coalesce(nullif(btrim(currency), ''), '?')) as cur, sum(monthly_amount) as amount
            from subscriptions where tier <> 'free' and status in ('active', 'trialing') group by 1) m;
  return jsonb_build_object(
    'totalUsers', total_users, 'totalHouseholds', total_households,
    'multiMemberPct', multi_member_pct, 'activeUsers7d', active_7d,
    'activeHouseholds7d', active_households_7d, 'signups7d', signups_7d,
    'signups30d', signups_30d, 'totalTransactions', total_txns,
    'transactions7d', txns_7d, 'publishedArticles', published_articles,
    'contentFavorites', total_favorites, 'paidSubscriptions', paid_subscriptions,
    'mrrByCurrency', mrr_by_currency, 'computedAt', now());
end; $function$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120300_q3a_public_content.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit FE-PUB-08, ADM-10, ADM-11; owner, 20 Oct 2026).
--
-- FE-PUB-08: a signed-out visitor could read every column of a published Learn item through the API, the
--   author's user id among them. They may now read only the columns the public pages and the app's video
--   and infographic lookup use (react/api/learn.js LESSON_COLS and LIST_COLS, sitemap.js, llms.js, v.js,
--   react/src/lib/insightVideos.ts), plus the ones those queries filter on. The "public reads published"
--   policy still decides WHICH rows. migrationReplay/authz tests check that every column react/api asks for
--   stays in this list.
-- ADM-10: the infographics bucket takes images only (PNG, JPEG, WebP), at most 5 MB each.
-- ADM-11: until admin v1.4.x an edit wrote the editor's email as the author. Those bylines become "Vyact"
--   (CONTENT_BYLINE). Publish dates that edits reset are not recoverable and stay as they are.

-- ── FE-PUB-08 ──────────────────────────────────────────────────────────────────────────────────────────────────
revoke select on table public.content_items from anon;
grant select (slug, title, category, format, status, tags, body_md, reading_seconds, why_it_matters,
              video_url, video_updated_at, infographic_url, source_name, source_url, published_at, updated_at)
  on table public.content_items to anon;

-- ── ADM-10 ─────────────────────────────────────────────────────────────────────────────────────────────────────
update storage.buckets
   set allowed_mime_types = array['image/png', 'image/jpeg', 'image/webp'],
       file_size_limit    = 5242880
 where id = 'insight-infographics';

-- ── ADM-11 ─────────────────────────────────────────────────────────────────────────────────────────────────────
update public.content_items set author_name = 'Vyact' where author_name like '%@%';

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120400_q3a_staff_audit.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit ADM-04; owner brought it in from the backlog, 20 Oct 2026).
--
-- What Vyact staff change, and who changed it, is recorded and cannot be edited:
--   - admin_roles: a role granted, changed or revoked;
--   - content_items: a Learn item created, edited (which fields; never the text), published or deleted;
--   - category_classifications: a category's need/want changed (old → new);
--   - ai_model_configs: Pip's model settings changed (which fields; seam, provider, model and the enabled flag
--     by value; params are never copied, though a CHECK keeps secrets out of them).
-- A change made in the Supabase dashboard or by a migration has no signed-in user: it is recorded with no actor
-- ("dashboard"). Rows are never updated or deleted (a trigger refuses it, for every role). There is no
-- household data here, so it is not part of a household erase.
--
-- Roles are granted and revoked through grant_admin_role / revoke_admin_role (super admins only); the last
-- super admin can neither be demoted nor removed. Super admins read the trail through admin_staff_audit.

create table if not exists public.admin_audit (
  id           bigint generated always as identity primary key,
  at           timestamptz not null default now(),
  -- auth.users id, intentionally not a foreign key: the trail outlives an account (it holds no other data).
  actor_id     uuid,
  action       text not null check (action in ('insert', 'update', 'delete')),
  target_table text not null check (target_table in ('admin_roles', 'content_items', 'category_classifications', 'ai_model_configs')),
  target_id    text,
  changed      text[] not null default '{}',
  detail       jsonb not null default '{}'::jsonb
);
create index if not exists ix_admin_audit_at on public.admin_audit (at desc);

alter table public.admin_audit enable row level security;
revoke all on table public.admin_audit from public, anon, authenticated;
grant select on table public.admin_audit to service_role;

-- Append-only, for everyone (service role and dashboard included).
create or replace function public.admin_audit_append_only()
returns trigger language plpgsql set search_path = public, pg_temp as $$
begin
  raise exception 'admin_audit_append_only: the staff audit trail is never changed' using errcode = '42501';
end $$;
drop trigger if exists trg_admin_audit_append_only on public.admin_audit;
create trigger trg_admin_audit_append_only before update or delete on public.admin_audit
  for each row execute function public.admin_audit_append_only();
revoke all on function public.admin_audit_append_only() from public, anon, authenticated;

-- One row per staff-managed change.
create or replace function public.log_staff_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  o jsonb := case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end;
  n jsonb := case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end;
  r jsonb := coalesce(n, o);
  v_changed text[] := '{}';
  v_detail  jsonb;
  v_target  text;
begin
  if tg_op = 'UPDATE' then
    select coalesce(array_agg(k order by k), '{}') into v_changed
      from jsonb_object_keys(n) k
     where k not in ('updated_at', 'created_at') and (o -> k) is distinct from (n -> k);
    if cardinality(v_changed) = 0 then return null; end if;   -- a no-op update records nothing
  end if;

  if tg_table_name = 'admin_roles' then
    v_target := r ->> 'user_id';
    v_detail := jsonb_build_object('role_before', o ->> 'role', 'role_after', n ->> 'role');
  elsif tg_table_name = 'content_items' then
    v_target := r ->> 'id';
    v_detail := jsonb_build_object('slug', r ->> 'slug', 'status_before', o ->> 'status', 'status_after', n ->> 'status');
  elsif tg_table_name = 'category_classifications' then
    v_target := r ->> 'category';
    v_detail := jsonb_build_object('before', o ->> 'classification', 'after', n ->> 'classification');
  elsif tg_table_name = 'ai_model_configs' then
    v_target := r ->> 'id';
    v_detail := jsonb_build_object('seam', r ->> 'seam', 'provider', r ->> 'provider', 'model', r ->> 'model',
                                   'enabled_before', o -> 'enabled', 'enabled_after', n -> 'enabled');
  else
    return null;
  end if;

  insert into public.admin_audit (actor_id, action, target_table, target_id, changed, detail)
  values (auth.uid(), lower(tg_op), tg_table_name, v_target, v_changed, jsonb_strip_nulls(v_detail));
  return null;
end $$;
revoke all on function public.log_staff_change() from public, anon, authenticated;

do $$
declare t text;
begin
  foreach t in array array['admin_roles', 'content_items', 'category_classifications', 'ai_model_configs'] loop
    execute format('drop trigger if exists trg_%1$s_staff_audit on public.%1$I', t);
    execute format('create trigger trg_%1$s_staff_audit after insert or update or delete on public.%1$I
                      for each row execute function public.log_staff_change()', t);
  end loop;
end $$;

-- ── Granting and revoking staff roles ────────────────────────────────────────────────────────────────────────────
create or replace function public.grant_admin_role(p_user uuid, p_role text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin('super') then
    raise exception 'only_super_admins_grant_roles' using errcode = '42501';
  end if;
  if p_role is null or p_role not in ('super', 'roles', 'content') then
    raise exception 'invalid_admin_role' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users where id = p_user) then
    raise exception 'user_not_found' using errcode = 'P0002';
  end if;
  -- Serialise role changes, so two demotions cannot leave no super admin.
  lock table public.admin_roles in share row exclusive mode;
  if p_role <> 'super'
     and exists (select 1 from public.admin_roles where user_id = p_user and role = 'super')
     and (select count(*) from public.admin_roles where role = 'super') <= 1 then
    raise exception 'last_super_admin: grant another super admin first' using errcode = '42501';
  end if;
  insert into public.admin_roles (user_id, role, granted_by, granted_at)
  values (p_user, p_role, auth.uid(), now())
  on conflict (user_id) do update set role = excluded.role, granted_by = excluded.granted_by, granted_at = excluded.granted_at;
end $$;

create or replace function public.revoke_admin_role(p_user uuid)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin('super') then
    raise exception 'only_super_admins_revoke_roles' using errcode = '42501';
  end if;
  lock table public.admin_roles in share row exclusive mode;
  if exists (select 1 from public.admin_roles where user_id = p_user and role = 'super')
     and (select count(*) from public.admin_roles where role = 'super') <= 1 then
    raise exception 'last_super_admin: grant another super admin first' using errcode = '42501';
  end if;
  delete from public.admin_roles where user_id = p_user;
  return found;
end $$;

-- ── Reading the trail ────────────────────────────────────────────────────────────────────────────────────────────
create or replace function public.admin_staff_audit(p_limit int default 100, p_before timestamptz default null)
returns table (id bigint, at timestamptz, actor_id uuid, actor_email text, action text, target_table text,
               target_id text, changed text[], detail jsonb)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin('super') then
    raise exception 'forbidden: super admin required' using errcode = '42501';
  end if;
  return query
    select a.id, a.at, a.actor_id, u.email::text, a.action, a.target_table, a.target_id, a.changed, a.detail
      from public.admin_audit a
      left join auth.users u on u.id = a.actor_id
     where p_before is null or a.at < p_before
     order by a.at desc, a.id desc
     limit greatest(1, least(coalesce(p_limit, 100), 500));
end $$;

revoke all on function public.grant_admin_role(uuid, text) from public, anon;
revoke all on function public.revoke_admin_role(uuid) from public, anon;
revoke all on function public.admin_staff_audit(int, timestamptz) from public, anon;
grant execute on function public.grant_admin_role(uuid, text) to authenticated;
grant execute on function public.revoke_admin_role(uuid) to authenticated;
grant execute on function public.admin_staff_audit(int, timestamptz) to authenticated;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120500_q3a_admin_lists.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit ADM-08, INT-HH-14; owner brought them in from the backlog, 20 Oct 2026).
--
-- The admin Users and Households pages read whole tables, and the API returns at most 1,000 rows a request, so
-- past 1,000 people or memberships the lists and the member counts were cut short without a word. These read
-- one page at a time (newest first), search on the server, count members with a GROUP BY, and return the total
-- that matched with every row. Roles-tier staff only (super included), as admin_list_users.
-- admin_list_users stays for the admin app until v1.5.0 reads these; it is retired after that.

create or replace function public.admin_list_users_page(p_limit int default 100, p_offset int default 0, p_query text default null)
returns table (id uuid, email text, display_name text, email_confirmed boolean, created_at timestamptz,
               last_sign_in_at timestamptz, household_count int, is_admin boolean, admin_role text, total bigint)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
begin
  if not public.is_admin('roles') then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;
  return query
    with matched as (
      select u.id, u.email::text as email, p.display_name, (u.email_confirmed_at is not null) as email_confirmed,
             u.created_at, u.last_sign_in_at
        from auth.users u
        left join public.profiles p on p.id = u.id
       where v_q is null
          or u.email ilike '%' || v_q || '%'
          or p.display_name ilike '%' || v_q || '%'
    )
    select m.id, m.email, m.display_name, m.email_confirmed, m.created_at, m.last_sign_in_at,
           (select count(*)::int from public.memberships ms where ms.user_id = m.id) as household_count,
           (a.user_id is not null) as is_admin, a.role as admin_role,
           count(*) over () as total
      from matched m
      left join public.admin_roles a on a.user_id = m.id
     order by m.created_at desc, m.id
     limit greatest(1, least(coalesce(p_limit, 100), 500))
    offset greatest(0, coalesce(p_offset, 0));
end $$;

create or replace function public.admin_list_households(p_limit int default 100, p_offset int default 0, p_query text default null)
returns table (id uuid, name text, type text, base_currency text, created_by uuid, created_at timestamptz,
               member_count int, total bigint)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
begin
  if not public.is_admin('roles') then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;
  return query
    select h.id, h.name, h.type, h.base_currency, h.created_by, h.created_at,
           coalesce(c.n, 0)::int as member_count,
           count(*) over () as total
      from public.households h
      left join (select household_id, count(*) as n from public.memberships group by household_id) c
             on c.household_id = h.id
     where v_q is null or h.name ilike '%' || v_q || '%'
     order by h.created_at desc, h.id
     limit greatest(1, least(coalesce(p_limit, 100), 500))
    offset greatest(0, coalesce(p_offset, 0));
end $$;

-- The pages' headline counts, which they used to work out from the whole (truncated) list.
create or replace function public.admin_people_summary()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin('roles') then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'users', jsonb_build_object(
      'total',          (select count(*) from auth.users),
      'confirmed',      (select count(*) from auth.users where email_confirmed_at is not null),
      'admins',         (select count(*) from public.admin_roles),
      'multiHousehold', (select count(*) from (select user_id from public.memberships
                                                group by user_id having count(*) > 1) m)),
    'households', jsonb_build_object(
      'total',       (select count(*) from public.households),
      'multiMember', (select count(*) from (select household_id from public.memberships
                                             group by household_id having count(*) >= 2) m),
      'byType',      (select coalesce(jsonb_object_agg(type, n), '{}'::jsonb)
                        from (select type, count(*) as n from public.households group by type) t)));
end $$;

revoke all on function public.admin_people_summary() from public, anon;
grant execute on function public.admin_people_summary() to authenticated;
revoke all on function public.admin_list_users_page(int, int, text) from public, anon;
revoke all on function public.admin_list_households(int, int, text) from public, anon;
grant execute on function public.admin_list_users_page(int, int, text) to authenticated;
grant execute on function public.admin_list_households(int, int, text) to authenticated;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120600_q3a_activity_actor.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit INT-TXN-14, DB-INT-13, DB-INT-14; owner decisions 20 Oct 2026).
--
-- The household activity log (log_domain_activity) named its actor from auth.uid(), so every entry the server
-- wrote (WhatsApp, the bill and EMI jobs) had no actor, and a soft delete (deleted_at set) read as "updated".
--   - Owner: "the person, else Vyact". Each WhatsApp writer below sets the transaction-local `vyact.actor` to
--     the person the message came from, and the trigger reads it when there is no signed-in user. Scheduled
--     jobs set nothing: no actor, which the apps show as "Vyact (automatic)". A signed-in request always wins,
--     and only these SECURITY DEFINER functions set it (the API cannot set a setting).
--   - Setting deleted_at is logged as "deleted".
-- Each WhatsApp function is its current definition with that one line added at the top; whatsapp_log_transaction
-- also picks an account deterministically (DB-INT-13) and refuses a Loan / EMI expense (DB-INT-14; the webhook
-- already sends those to the loan).

create or replace function public.log_domain_activity()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  h       uuid;
  act     text;
  ent     text := tg_table_name;
  ent_id  uuid;
  ch      jsonb;
  actor   uuid := coalesce(auth.uid(), nullif(current_setting('vyact.actor', true), '')::uuid);
begin
  if tg_op = 'INSERT' then
    act    := 'created';
    h      := new.household_id;
    ent_id := new.id;
    ch     := to_jsonb(new);
  elsif tg_op = 'UPDATE' then
    -- A soft delete is a delete (the row stays for sync; the person deleted it).
    act    := case when (to_jsonb(old) ->> 'deleted_at') is null and (to_jsonb(new) ->> 'deleted_at') is not null
                   then 'deleted' else 'updated' end;
    h      := new.household_id;
    ent_id := new.id;
    ch     := jsonb_build_object('old', to_jsonb(old), 'new', to_jsonb(new));
  elsif tg_op = 'DELETE' then
    act    := 'deleted';
    h      := old.household_id;
    ent_id := old.id;
    ch     := to_jsonb(old);
  else
    return null;
  end if;

  begin
    insert into activity_log (household_id, actor_id, action, entity_type, entity_id, changes)
    values (h, actor, act, ent, ent_id, ch);
  exception when foreign_key_violation then
    -- The household (or the actor's account) is being deleted in this same transaction.
    null;
  end;

  return null;
end;
$$;

CREATE OR REPLACE FUNCTION public.whatsapp_log_transaction(p_profile_id uuid, p_household_id uuid, p_amount numeric, p_currency text, p_txn_type text, p_category_id text, p_account_alias text, p_to_account_alias text, p_wa_message_id text, p_description text, p_date date DEFAULT NULL::date, p_payment_mode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member_id     uuid;
  v_member_role   text;
  v_account_id    uuid;
  v_to_account_id uuid;
  v_asset_id      uuid;
  v_cash_id       uuid;
  v_txn_id        uuid;
  v_claimed       int;
  v_date          date;
  v_mode          text;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  v_date := coalesce(p_date, current_date);
  if v_date > current_date + interval '2 days' or v_date < current_date - interval '5 years' then
    v_date := current_date;
  end if;
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('status','error','reason','invalid_amount');
  end if;
  if p_txn_type not in ('expense','income','investment','transfer') then
    return jsonb_build_object('status','error','reason','invalid_type');
  end if;

  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;

  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('status','duplicate');
  end if;

  select id, role into v_member_id, v_member_role
    from public.memberships
   where household_id = p_household_id and user_id = p_profile_id
   limit 1;
  if v_member_id is null then
    return jsonb_build_object('status','error','reason','not_a_member');
  end if;
  if v_member_role = 'viewer' then
    return jsonb_build_object('status','error','reason','read_only_member');
  end if;
  -- Q3a (DB-INT-14): a loan payment goes through the loan (whatsapp_pay_loan), never as a plain expense.
  if p_category_id = 'loan_emi' then
    return jsonb_build_object('status','error','reason','loan_emi_needs_loan');
  end if;

  select id into v_cash_id
    from public.accounts
   where household_id = p_household_id and lower(kind) = 'cash'
     and coalesce(is_archived,false) = false and deleted_at is null
   limit 1;

  if p_account_alias is not null and p_account_alias <> '' then
    select id into v_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_account_alias) or lower(kind) = lower(p_account_alias))
     -- Q3a (DB-INT-13; owner, 20 Oct 2026: "use the default"): the account named exactly, else the household's
     -- default when it is of that kind, else the oldest of that kind. The reply names the account.
     order by (lower(name) = lower(p_account_alias)) desc, coalesce(is_default, false) desc, created_at, id
     limit 1;
  end if;

  if p_txn_type = 'investment' then
    -- R4: the destination is an investment ASSET — by name, or the household's
    -- only one when the message names none ("invested 5000").
    if p_to_account_alias is not null and p_to_account_alias <> '' and lower(p_to_account_alias) <> 'investment' then
      select id into v_asset_id from public.assets
       where household_id = p_household_id and deleted_at is null and type = 'investment'
         and lower(name) = lower(p_to_account_alias)
       limit 1;
    end if;
    if v_asset_id is null and (select count(*) from public.assets
                                where household_id = p_household_id and deleted_at is null and type = 'investment') = 1 then
      select id into v_asset_id from public.assets
       where household_id = p_household_id and deleted_at is null and type = 'investment';
    end if;
  elsif p_to_account_alias is not null and p_to_account_alias <> '' then
    select id into v_to_account_id
      from public.accounts
     where household_id = p_household_id
       and coalesce(is_archived,false) = false
       and deleted_at is null
       and (lower(name) = lower(p_to_account_alias) or lower(kind) = lower(p_to_account_alias))
     -- Q3a (DB-INT-13; owner, 20 Oct 2026: "use the default"): the account named exactly, else the household's
     -- default when it is of that kind, else the oldest of that kind. The reply names the account.
     order by (lower(name) = lower(p_to_account_alias)) desc, coalesce(is_default, false) desc, created_at, id
     limit 1;
  end if;

  if p_txn_type = 'expense' then
    v_account_id := coalesce(v_account_id, v_cash_id);
    v_to_account_id := null;
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
  elsif p_txn_type = 'income' then
    v_to_account_id := coalesce(v_to_account_id, v_account_id, v_cash_id);
    v_account_id := null;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
  elsif p_txn_type = 'investment' then
    v_account_id := coalesce(v_account_id, v_cash_id);
    v_to_account_id := null;
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
    if v_asset_id is null then
      return jsonb_build_object('status','error','reason','no_investment_asset');
    end if;
  else
    v_account_id := coalesce(v_account_id, v_cash_id);
    if v_account_id is null then
      return jsonb_build_object('status','error','reason','no_source_account');
    end if;
    if v_to_account_id is null then
      return jsonb_build_object('status','error','reason','no_destination_account');
    end if;
    if v_to_account_id = v_account_id then
      return jsonb_build_object('status','error','reason','same_account');
    end if;
  end if;

  if p_payment_mode is not null and p_txn_type <> 'investment' then
    select p_payment_mode into v_mode
      from public.accounts
     where id = case when p_txn_type = 'income' then v_to_account_id else v_account_id end
       and p_payment_mode = any (payment_modes);
  end if;

  insert into public.transactions (
    household_id, created_by, member_id, amount, currency, type, category,
    account_id, to_account_id, asset_id, date, description, payment_mode
  ) values (
    p_household_id,
    p_profile_id,
    v_member_id,
    p_amount,
    coalesce(nullif(p_currency,''), 'USD'),
    p_txn_type,
    case when p_txn_type in ('expense','income')
         then coalesce(nullif(p_category_id,''), case when p_txn_type='expense' then 'other_expense' else 'other_income' end)
         else null end,
    v_account_id,
    v_to_account_id,
    v_asset_id,
    v_date,
    coalesce(nullif(p_description,''), 'Logged via WhatsApp'),
    v_mode
  ) returning id into v_txn_id;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload,'{}'::jsonb) || jsonb_build_object(
           'parsed', jsonb_build_object(
             'transaction_id', v_txn_id, 'amount', p_amount, 'currency', p_currency,
             'type', p_txn_type, 'category_id', p_category_id,
             'account_id', v_account_id, 'to_account_id', v_to_account_id, 'asset_id', v_asset_id,
             'payment_mode', p_payment_mode, 'payment_mode_stored', v_mode))
   where wa_message_id = p_wa_message_id;

  return jsonb_build_object(
    'status','success',
    'transaction_id', v_txn_id,
    'amount', p_amount,
    'currency', coalesce(nullif(p_currency,''),'USD'),
    'type', p_txn_type,
    'category_id', p_category_id,
    'payment_mode', v_mode,
    'account_name',    (select name from public.accounts where id = v_account_id),
    -- the confirmation reads "from → to"; for an investment "to" is the asset
    'to_account_name', coalesce((select name from public.accounts where id = v_to_account_id),
                                (select name from public.assets   where id = v_asset_id))
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_approve_recurring(p_profile_id uuid, p_household_id uuid, p_schedule_id uuid, p_occurrence date, p_today date, p_next_due date, p_row jsonb, p_wa_message_id text, p_exhausted boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member_id  uuid;
  v_role       text;
  v_s          public.recurring_schedules%rowtype;
  v_t          jsonb;
  v_claimed    int;
  v_inserted   int;
  v_type       text;
  v_mode       text;
  v_paying     uuid;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  -- 1. Claim the message, exactly as whatsapp_log_transaction does.
  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;
  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then
    return jsonb_build_object('status', 'duplicate');
  end if;

  -- 2. A write role in this household.
  select id, role into v_member_id, v_role
    from public.memberships
   where household_id = p_household_id and user_id = p_profile_id
   limit 1;
  if v_member_id is null then
    return jsonb_build_object('status', 'error', 'reason', 'not_a_member');
  end if;
  if v_role = 'viewer' then
    return jsonb_build_object('status', 'error', 'reason', 'read_only_member');
  end if;

  -- 3. The schedule, locked, and this occurrence the one due.
  select * into v_s
    from public.recurring_schedules
   where id = p_schedule_id and household_id = p_household_id and deleted_at is null
   for update;
  if not found or not v_s.active then
    return jsonb_build_object('status', 'error', 'reason', 'schedule_unavailable');
  end if;
  v_t := v_s.txn_template;
  if v_s.next_due_date > p_occurrence then
    return jsonb_build_object('status', 'already_done', 'next_due_date', v_s.next_due_date);
  end if;
  if v_s.next_due_date < p_occurrence then
    return jsonb_build_object('status', 'error', 'reason', 'not_the_due_occurrence');
  end if;
  if p_occurrence > p_today then
    return jsonb_build_object('status', 'error', 'reason', 'not_due_yet');
  end if;
  if not coalesce(p_exhausted, false) and (p_next_due is null or p_next_due <= p_occurrence) then
    return jsonb_build_object('status', 'error', 'reason', 'bad_next_due');
  end if;

  v_type := v_t->>'type';
  if v_type not in ('expense', 'income') or coalesce(v_t->>'category', '') = 'loan_emi'
     or nullif(v_t->>'debtId', '') is not null then
    return jsonb_build_object('status', 'error', 'reason', 'approve_in_app');
  end if;

  -- 4. The row must be this occurrence of this template.
  if (p_row->>'recurring_schedule_id')::uuid is distinct from p_schedule_id
     or (p_row->>'household_id')::uuid is distinct from p_household_id
     or (p_row->>'date')::date is distinct from p_occurrence
     or p_row->>'type' is distinct from v_type
     or (p_row->>'amount')::numeric is distinct from (v_t->>'amount')::numeric
     or coalesce(p_row->>'currency', 'USD') is distinct from coalesce(nullif(v_t->>'currency', ''), 'USD') then
    return jsonb_build_object('status', 'error', 'reason', 'row_mismatch');
  end if;

  -- A mode the paying account does not use is dropped, never an error (the
  -- store's rule, and whatsapp_log_transaction's).
  v_mode := nullif(p_row->>'payment_mode', '');
  if v_mode is not null then
    v_paying := case when v_type = 'income' then nullif(p_row->>'to_account_id', '')::uuid
                     else nullif(p_row->>'account_id', '')::uuid end;
    if exists (select 1 from public.accounts a where a.id = v_paying
                 and coalesce(array_length(a.payment_modes, 1), 0) > 0
                 and not (v_mode = any (a.payment_modes))) then
      v_mode := null;
    end if;
  end if;

  -- 5. The app's own row, under the deterministic id.
  insert into public.transactions (
    id, household_id, created_by, member_id, type, amount, currency, date, description,
    category, note, recurring, account_id, to_account_id, initiated_by,
    recurring_schedule_id, debt_id, payment_mode, extras, confidence, source, estimated_at, confirmed_at
  ) values (
    (p_row->>'id')::uuid,
    p_household_id,
    p_profile_id,
    nullif(p_row->>'member_id', '')::uuid,
    v_type,
    (p_row->>'amount')::numeric,
    coalesce(nullif(p_row->>'currency', ''), 'USD'),
    p_occurrence,
    coalesce(p_row->>'description', ''),
    nullif(p_row->>'category', ''),
    nullif(p_row->>'note', ''),
    nullif(p_row->>'recurring', ''),
    nullif(p_row->>'account_id', '')::uuid,
    nullif(p_row->>'to_account_id', '')::uuid,
    nullif(p_row->>'initiated_by', '')::uuid,
    p_schedule_id,
    null,
    v_mode,
    coalesce(p_row->'extras', '{}'::jsonb),
    coalesce(nullif(p_row->>'confidence', ''), 'confirmed'),
    coalesce(nullif(p_row->>'source', ''), 'user'),
    nullif(p_row->>'estimated_at', '')::timestamptz,
    nullif(p_row->>'confirmed_at', '')::timestamptz
  )
  on conflict (id) do nothing;
  get diagnostics v_inserted = row_count;

  -- 6. Move the schedule on.
  update public.recurring_schedules
     set last_generated = p_occurrence,
         next_due_date  = case when coalesce(p_exhausted, false) then next_due_date else p_next_due end,
         active         = not coalesce(p_exhausted, false)
   where id = p_schedule_id;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object(
           'approved', jsonb_build_object('schedule_id', p_schedule_id, 'occurrence', p_occurrence,
                                          'transaction_id', p_row->>'id', 'inserted', v_inserted = 1))
   where wa_message_id = p_wa_message_id;

  return jsonb_build_object(
    'status', 'success',
    'transaction_id', p_row->>'id',
    'already_posted', v_inserted = 0,
    'amount', (p_row->>'amount')::numeric,
    'currency', coalesce(nullif(p_row->>'currency', ''), 'USD'),
    'description', p_row->>'description',
    'next_due_date', case when coalesce(p_exhausted, false) then null else p_next_due end,
    'finished', coalesce(p_exhausted, false)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_correct_last(p_profile_id uuid, p_household_id uuid, p_category text, p_wa_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_block text; l record; v_type text; t record;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  -- An EMI pays a loan (whatsapp_correct_to_loan); relabelling a plain expense would book it whole as
  -- spending and leave the loan untouched.
  if p_category = 'loan_emi' then return jsonb_build_object('status', 'use_loan_payment'); end if;
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select * into l from public.whatsapp_last_logged(p_profile_id, p_household_id, p_wa_message_id);
  if l.reason is not null then return jsonb_build_object('status', l.reason); end if;

  select type into v_type from public.transactions where id = l.txn_id;
  -- Only an expense or an income carries a category; the caller checked the id is
  -- one of that type's categories.
  if v_type not in ('expense', 'income') then return jsonb_build_object('status', 'no_category'); end if;
  update public.transactions set category = p_category
   where id = l.txn_id returning amount, currency, type, category, updated_at into t;
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('corrected_at', t.updated_at)
   where wa_message_id = l.inbox_id;
  return jsonb_build_object('status', 'corrected', 'transaction_id', l.txn_id,
    'amount', t.amount, 'currency', t.currency, 'type', t.type, 'category_id', t.category);
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_correct_to_loan(p_profile_id uuid, p_household_id uuid, p_debt_id uuid, p_wa_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_block  text;
  l        record;
  t        public.transactions%rowtype;
  d        public.debts%rowtype;
  v_member uuid;
  v_result jsonb;
  v_code   text;
  v_detail text;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select * into l from public.whatsapp_last_logged(p_profile_id, p_household_id, p_wa_message_id);
  if l.reason is not null then return jsonb_build_object('status', l.reason); end if;

  select * into t from public.transactions where id = l.txn_id;
  if t.type is distinct from 'expense' then return jsonb_build_object('status', 'not_an_expense'); end if;
  select * into d from public.debts
   where id = p_debt_id and household_id = p_household_id and deleted_at is null;
  if not found then return jsonb_build_object('status', 'error', 'reason', 'debt_unavailable'); end if;
  select id into v_member from public.memberships
   where household_id = p_household_id and user_id = p_profile_id limit 1;

  -- The server's split, for the entry's own amount, date and paying account. A refusal is an answer:
  -- the payment's savepoint rolls back and the entry stays as it was.
  begin
    v_result := public.loan_payment_core(p_profile_id, md5('wa-correct-emi:' || t.id::text)::uuid, d.id, 'emi',
      t.amount, t.date, t.account_id, v_member, null, null, null, null);
  exception when sqlstate '22023' or sqlstate '42501' then
    get stacked diagnostics v_code = message_text, v_detail = pg_exception_detail;
    return jsonb_build_object('status', 'refused', 'reason', v_code, 'figure', nullif(v_detail, ''),
      'loan', d.name, 'amount', t.amount, 'currency', t.currency);
  end;

  -- The plain expense goes: the payment above replaces it (one entry, never both).
  update public.transactions set deleted_at = now() where id = t.id;
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('undone', now(),
           'converted_to_loan', jsonb_build_object('debt_id', d.id, 'operation_id', v_result->>'operation_id'))
   where wa_message_id = l.inbox_id;
  return v_result || jsonb_build_object('loan', d.name, 'amount', t.amount, 'currency', t.currency);
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_name_entries(p_profile_id uuid, p_household_id uuid, p_wa_message_id text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_block text; v_item jsonb; t record; v_out jsonb := '[]'::jsonb; v_status text;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  if jsonb_typeof(p_items) <> 'array' or jsonb_array_length(p_items) = 0 or jsonb_array_length(p_items) > 10 then
    return jsonb_build_object('status', 'bad_request');
  end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    select x.id, x.type, x.category, x.deleted_at, x.created_by,
           coalesce((x.extras->>'excluded')::boolean, false) as excluded
      into t
      from public.transactions x
     where x.id = (v_item->>'id')::uuid and x.household_id = p_household_id
     for update;
    if not found or t.deleted_at is not null then v_status := 'gone';
    elsif t.type <> 'expense' then v_status := 'not_expense';
    elsif t.excluded and t.created_by is distinct from p_profile_id then v_status := 'private';
    elsif t.category not in ('other_expense', 'other') then v_status := 'already_named';
    else
      update public.transactions set category = v_item->>'category' where id = t.id;
      v_status := 'named';
    end if;
    v_out := v_out || jsonb_build_object('id', v_item->>'id', 'status', v_status, 'category', v_item->>'category');
  end loop;
  return jsonb_build_object('status', 'done', 'results', v_out);
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_pay_loan(p_profile_id uuid, p_household_id uuid, p_debt_id uuid, p_amount numeric, p_date date, p_wa_message_id text, p_account_alias text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_member  uuid;
  v_role    text;
  v_claimed int;
  d         public.debts%rowtype;
  v_funding uuid;
  v_result  jsonb;
  v_code    text;
  v_detail  text;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  -- 1. Claim the message, exactly as whatsapp_log_transaction does.
  insert into public.whatsapp_inbound_messages (wa_message_id, profile_id, household_id, direction)
    values (p_wa_message_id, p_profile_id, p_household_id, 'inbound')
    on conflict (wa_message_id) do nothing;
  update public.whatsapp_inbound_messages
     set processed_at = now(),
         profile_id   = coalesce(profile_id, p_profile_id),
         household_id = coalesce(household_id, p_household_id)
   where wa_message_id = p_wa_message_id and processed_at is null;
  get diagnostics v_claimed = row_count;
  if v_claimed = 0 then return jsonb_build_object('status', 'duplicate'); end if;

  -- 2. A write role in this household.
  select id, role into v_member, v_role from public.memberships
   where household_id = p_household_id and user_id = p_profile_id limit 1;
  if v_member is null then return jsonb_build_object('status', 'error', 'reason', 'not_a_member'); end if;
  if v_role = 'viewer' then return jsonb_build_object('status', 'error', 'reason', 'read_only_member'); end if;

  select * into d from public.debts where id = p_debt_id and household_id = p_household_id and deleted_at is null;
  if not found then return jsonb_build_object('status', 'error', 'reason', 'debt_unavailable'); end if;

  -- 3. The account it was paid from: the one named, else the loan's own, else the household default.
  if nullif(btrim(p_account_alias), '') is not null then
    select id into v_funding from public.accounts
     where household_id = p_household_id and kind in ('bank', 'cash') and deleted_at is null and not is_archived
       and lower(name) like '%' || lower(btrim(p_account_alias)) || '%'
     order by is_default desc, created_at limit 1;
  end if;
  v_funding := coalesce(v_funding,
    (select id from public.accounts where id = d.funding_account_id and kind in ('bank', 'cash') and deleted_at is null and not is_archived),
    (select id from public.accounts where household_id = p_household_id and kind in ('bank', 'cash') and deleted_at is null
        and not is_archived order by is_default desc, (kind = 'bank') desc, created_at limit 1));

  -- 4. The server's split. A refusal is an answer, not a failure: the message stays claimed.
  begin
    v_result := public.loan_payment_core(p_profile_id, md5('wa-loan:' || p_wa_message_id)::uuid, d.id, 'emi',
      p_amount, coalesce(p_date, (now() at time zone 'Asia/Kolkata')::date), v_funding, v_member, null, null, null, null);
  exception when sqlstate '22023' or sqlstate '42501' then
    get stacked diagnostics v_code = message_text, v_detail = pg_exception_detail;
    return jsonb_build_object('status', 'refused', 'reason', v_code, 'figure', nullif(v_detail, ''),
      'loan', d.name);
  end;

  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('loan_payment',
           jsonb_build_object('debt_id', d.id, 'operation_id', v_result->>'operation_id'))
   where wa_message_id = p_wa_message_id;
  return v_result || jsonb_build_object('loan', d.name);
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_reconcile_account(p_profile_id uuid, p_household_id uuid, p_wa_message_id text, p_account_id uuid, p_expected_offset numeric, p_offset numeric, p_log jsonb, p_at timestamp with time zone, p_bridge jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_block text; a record;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;

  select x.id, x.kind, x.is_archived, x.deleted_at, coalesce(x.reconciliation_offset, 0) as off
    into a
    from public.accounts x
   where x.id = p_account_id and x.household_id = p_household_id
   for update;
  if not found or a.deleted_at is not null or a.is_archived then return jsonb_build_object('status', 'gone'); end if;
  if a.kind not in ('bank', 'credit_card', 'cash') then return jsonb_build_object('status', 'not_supported'); end if;
  -- The plan was computed from this offset; if it moved, the plan is stale.
  if round(a.off, 2) <> round(coalesce(p_expected_offset, 0), 2) then
    return jsonb_build_object('status', 'changed');
  end if;
  if jsonb_typeof(p_log) <> 'array' then return jsonb_build_object('status', 'bad_request'); end if;

  update public.accounts set
    reconciliation_offset = round(p_offset, 2),
    reconciliation_log    = p_log,
    last_reconciled_at    = p_at,
    confidence = 'confirmed', source = 'user', confirmed_at = p_at
   where id = p_account_id;

  -- §6 R-AGG-5 / D2 — the stated value flows to the linked entity (reconcileSlice).
  if p_bridge is not null and p_bridge->>'debt_id' is not null then
    update public.debts set current_balance = greatest(0, (p_bridge->>'current_balance')::numeric),
           confidence = 'confirmed', source = 'user', confirmed_at = p_at
     where id = (p_bridge->>'debt_id')::uuid and household_id = p_household_id and deleted_at is null;
  elsif p_bridge is not null and p_bridge->>'asset_id' is not null then
    update public.assets set value = (p_bridge->>'value')::numeric, last_updated = (p_at at time zone 'UTC')::date,
           confidence = 'confirmed', source = 'user', confirmed_at = p_at
     where id = (p_bridge->>'asset_id')::uuid and household_id = p_household_id and deleted_at is null;
  end if;
  return jsonb_build_object('status', 'reconciled', 'offset', round(p_offset, 2));
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_split_even(p_profile_id uuid, p_household_id uuid, p_wa_message_id text, p_txn_id uuid, p_partner_email text, p_split jsonb, p_partner_share numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_block text; t record; v_split uuid;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;

  select x.id, x.type, x.amount, x.currency, x.date, x.description, x.created_by, x.deleted_at, x.extras
    into t from public.transactions x
   where x.id = p_txn_id and x.household_id = p_household_id for update;
  if not found or t.deleted_at is not null then return jsonb_build_object('status', 'gone'); end if;
  if t.type <> 'expense' then return jsonb_build_object('status', 'not_expense'); end if;
  if t.created_by is distinct from p_profile_id then return jsonb_build_object('status', 'not_yours'); end if;
  if t.extras ? 'split' or exists (select 1 from public.shared_splits s where s.txn_id = t.id) then
    return jsonb_build_object('status', 'already_split');
  end if;
  -- The caller built the split from this row; refuse a mismatch rather than store it.
  if round((p_split->>'totalAmount')::numeric, 2) <> round(t.amount, 2)
     or round((p_split->>'yourShare')::numeric + p_partner_share, 2) <> round(t.amount, 2) then
    return jsonb_build_object('status', 'bad_request');
  end if;

  update public.transactions
     set extras = coalesce(extras, '{}'::jsonb) || jsonb_build_object('split', p_split)
   where id = t.id;
  insert into public.shared_splits (owner_user_id, owner_household_id, txn_id, description, currency, total_amount, txn_type, date)
    values (p_profile_id, p_household_id, t.id, t.description, t.currency, t.amount, 'expense', t.date)
    returning id into v_split;
  insert into public.shared_split_shares (split_id, email, share)
    values (v_split, lower(trim(p_partner_email)), p_partner_share);
  return jsonb_build_object('status', 'split', 'split_id', v_split, 'description', t.description,
    'currency', t.currency, 'your_share', (p_split->>'yourShare')::numeric, 'partner_share', p_partner_share);
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_undo_last(p_profile_id uuid, p_household_id uuid, p_wa_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_block text; l record; t record;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select * into l from public.whatsapp_last_logged(p_profile_id, p_household_id, p_wa_message_id);
  if l.reason is not null then return jsonb_build_object('status', l.reason); end if;

  update public.transactions set deleted_at = now()
   where id = l.txn_id returning amount, currency, type, category into t;
  update public.whatsapp_inbound_messages
     set payload = coalesce(payload, '{}'::jsonb) || jsonb_build_object('undone', now())
   where wa_message_id = l.inbox_id;
  return jsonb_build_object('status', 'undone', 'transaction_id', l.txn_id,
    'amount', t.amount, 'currency', t.currency, 'type', t.type, 'category_id', t.category);
end;
$function$;

CREATE OR REPLACE FUNCTION public.whatsapp_undo_recurring_post(p_profile_id uuid, p_household_id uuid, p_wa_message_id text, p_txn_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_block text; t record;
begin
  -- Q3a (INT-TXN-14): the activity log names the person this message came from.
  perform set_config('vyact.actor', p_profile_id::text, true);
  v_block := public.whatsapp_claim_for_write(p_profile_id, p_household_id, p_wa_message_id);
  if v_block is not null then return jsonb_build_object('status', v_block); end if;
  select x.id, x.amount, x.currency, x.date, x.description, x.recurring_schedule_id, x.deleted_at, x.created_at, x.updated_at
    into t from public.transactions x
   where x.id = p_txn_id and x.household_id = p_household_id for update;
  if not found or t.deleted_at is not null then return jsonb_build_object('status', 'gone'); end if;
  if t.recurring_schedule_id is null then return jsonb_build_object('status', 'not_scheduled'); end if;
  -- Edited in the app since it posted: that edit is the person's; leave it.
  if t.updated_at > t.created_at + interval '5 seconds' then return jsonb_build_object('status', 'edited'); end if;
  update public.transactions set deleted_at = now() where id = t.id;
  return jsonb_build_object('status', 'undone', 'description', t.description, 'amount', t.amount,
    'currency', t.currency, 'date', t.date);
end;
$function$;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120700_q3a_integrity_checks.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit DB-INT-14, INT-HH-08; owner decisions 20 Oct 2026).
--
-- DB-INT-14: two money rules the app keeps but the database did not.
--   - A transfer moves money between two DIFFERENT accounts (one to itself changes nothing and reads as
--     activity). The WhatsApp writer already refused it; now every writer is held to it.
--   - A budget line's amount is never below zero.
--   Both are NOT VALID: they hold every new or changed row from now on, and a row that already breaks one
--   cannot fail this deploy. (Loan / EMI through WhatsApp is refused in 20261109120600; budget scope stays
--   optional, because the older category budgets have none.)
-- INT-HH-08 (database half): language becomes per person. profiles.language unset means "follow the
--   household" (households.language); the stored default 'en' is cleared to unset, so nobody's language changes
--   today. The app reads and writes the person's own language in Track Q5.

alter table public.transactions drop constraint if exists ck_txn_transfer_accounts_differ;
alter table public.transactions
  add constraint ck_txn_transfer_accounts_differ
  check (type <> 'transfer' or account_id is distinct from to_account_id) not valid;

alter table public.budget_allocations drop constraint if exists ck_balloc_amount_not_negative;
alter table public.budget_allocations
  add constraint ck_balloc_amount_not_negative check (amount >= 0) not valid;

alter table public.profiles alter column language drop default;
alter table public.profiles alter column language drop not null;
update public.profiles set language = null where language = 'en';

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261109120800_q3a_indexes.sql
-- ─────────────────────────────────────────────────────────────────────
-- Q3a (v10.130.0; audit DB-OPS-09; owner, 20 Oct 2026: "indexes only").
--
-- Foreign keys that the app, the RLS policies or a delete look up by, with no index leading on them; and three
-- indexes created twice under different names (v9.1 and its feedback batch). The policy rewrite the audit also
-- suggested is not done: it pays off at a scale Vyact is far from, and the Q2 access matrix will guard it then.

-- Balances, ledgers, account_dependencies and delete/move read transactions by account.
create index if not exists ix_txn_account    on public.transactions (account_id)    where account_id is not null;
create index if not exists ix_txn_to_account on public.transactions (to_account_id) where to_account_id is not null;
-- account_dependencies, delete_account and the funding-account guard.
create index if not exists ix_debts_funding_account on public.debts (funding_account_id) where funding_account_id is not null;
-- loan_account_for and the loan functions find a loan's account by debt.
create index if not exists ix_accounts_debt on public.accounts (debt_id) where debt_id is not null;
-- Policies and the household views read these by household.
create index if not exists ix_invitations_household        on public.invitations (household_id);
create index if not exists ix_loan_events_household        on public.loan_payment_events (household_id);
create index if not exists ix_ai_feedback_household        on public.ai_feedback (household_id);
-- The household erase, a member's unlink and the account purge.
create index if not exists ix_wa_inbound_household on public.whatsapp_inbound_messages (household_id);
create index if not exists ix_wa_inbound_profile   on public.whatsapp_inbound_messages (profile_id);
create index if not exists ix_wa_pending_household on public.whatsapp_pending_turns (household_id);
create index if not exists ix_wa_identities_household on public.whatsapp_identities (household_id);
-- A shared split's transaction, and the loan events that point at a deleted transaction.
create index if not exists ix_shared_splits_txn on public.shared_splits (txn_id) where txn_id is not null;
create index if not exists ix_loan_events_expense_txn  on public.loan_payment_events (expense_txn_id)  where expense_txn_id is not null;
create index if not exists ix_loan_events_transfer_txn on public.loan_payment_events (transfer_txn_id) where transfer_txn_id is not null;

-- The same index twice: keep the v9.1 names.
drop index if exists public.ix_balloc_budget;    -- = idx_balloc_budget
drop index if exists public.ix_txn_schedule;     -- = idx_txn_recurring
drop index if exists public.ix_txn_debt;         -- = idx_txn_debt

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261110120000_q4_job_runs.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.132.0 — Track Q, part 4: every scheduled job leaves a record, and the owner is told when one stops.
-- Audit OPS-06, DB-OPS-08 (owner decision D9, 20 Oct 2026: "job_runs, a Health page, an email when a job fails or
-- misses").
--
-- Eleven pg_cron jobs do Vyact's server work. A run's answer lived only in net._http_response, which pg_net keeps for
-- about 6 hours, so "nothing to send" and "broken" looked the same, and nobody was told when a job stopped running.
--
--   1. job_runs: one row per run of each job: when it started and finished, how it ended (ok · partial · failed),
--      what it did (counts only, never a household's data) and the error. The Edge jobs record their own runs
--      (`_shared/jobRuns.ts` → record_job_run); the two SQL jobs now run through wrappers that do. Kept 30 days.
--   2. job_health(): each job Vyact schedules (job_expectations) against its cadence: the latest run, runs and
--      failures in 24 hours, and the problem, if any: failed (the latest run), partial (the latest two), late (no
--      run for two of its intervals). admin_job_health() / admin_job_runs() are the admin Health page's reads
--      (roles tier). A job only ever late, never recorded, counts from the first run recorded anywhere.
--   3. job-health (pg_cron, hourly, the T5d form) asks the `job-health` Edge Function to email the owner
--      (HEALTH_ALERT_EMAIL) about the problems; claim_job_alert keeps it to one email per job and problem a day.
--
-- MONEY MODEL: untouched. The wrappers call the same functions; a run that fails rolls its own writes back, as
-- before, and is recorded as failed.

begin;

-- ── 1. job_runs ───────────────────────────────────────────────────────────────────────────────────────────────
create table if not exists public.job_runs (
  id          bigint generated always as identity primary key,
  job         text not null check (job ~ '^[a-z0-9-]{1,64}$'),
  started_at  timestamptz not null,
  finished_at timestamptz not null default now(),
  status      text not null check (status in ('ok', 'partial', 'failed')),
  summary     jsonb not null default '{}'::jsonb check (jsonb_typeof(summary) = 'object'),
  error       text check (char_length(error) <= 500)
);
create index if not exists ix_job_runs_job_started on public.job_runs (job, started_at desc);
create index if not exists ix_job_runs_started on public.job_runs (started_at);
alter table public.job_runs enable row level security;
revoke all on public.job_runs from public, anon, authenticated;
comment on table public.job_runs is
  'Q4 (v10.132.0, OPS-06): one row per scheduled job run (counts only). Server-only; read by job_health(). Kept 30 days (run_retention).';

-- One email per job and problem a day (claim first, as split and invite emails are).
create table if not exists public.job_alerts (
  job          text not null,
  kind         text not null check (kind in ('failed', 'partial', 'late')),
  last_sent_at timestamptz not null default now(),
  primary key (job, kind)
);
alter table public.job_alerts enable row level security;
revoke all on public.job_alerts from public, anon, authenticated;

create or replace function public.record_job_run(p_job text, p_started_at timestamptz, p_status text,
                                                 p_summary jsonb default '{}'::jsonb, p_error text default null)
returns bigint
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id bigint;
begin
  insert into job_runs (job, started_at, finished_at, status, summary, error)
  values (p_job, coalesce(p_started_at, now()), clock_timestamp(), p_status,
          -- A summary is a few counts; anything else (or anything large) is not kept.
          case when jsonb_typeof(p_summary) = 'object' and pg_column_size(p_summary) <= 4096 then p_summary else '{}'::jsonb end,
          left(nullif(btrim(p_error), ''), 500))
  returning id into v_id;
  return v_id;
end;
$$;

-- ── The two SQL jobs record their runs ──────────────────────────────────────────────────────────────────────
create or replace function public.run_loan_auto_record()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_started timestamptz := clock_timestamp();
  v_result jsonb;
begin
  begin
    v_result := public.auto_record_due_emis();
  exception when others then
    -- The block's writes are rolled back (as a failed run's always were); the failure is kept.
    perform public.record_job_run('loan-auto-record', v_started, 'failed', '{}'::jsonb, sqlerrm);
    return jsonb_build_object('status', 'failed');
  end;
  perform public.record_job_run('loan-auto-record', v_started,
    case when coalesce((v_result->>'errors')::int, 0) > 0 then 'partial' else 'ok' end, v_result, null);
  return v_result;
end;
$$;

create or replace function public.run_retention()
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_started timestamptz := clock_timestamp();
  v_result jsonb;
  v_runs int;
begin
  begin
    v_result := public.purge_old_whatsapp_messages(90);
    delete from job_runs where started_at < now() - interval '30 days';
    get diagnostics v_runs = row_count;
  exception when others then
    perform public.record_job_run('whatsapp-retention', v_started, 'failed', '{}'::jsonb, sqlerrm);
    return jsonb_build_object('status', 'failed');
  end;
  v_result := v_result || jsonb_build_object('job_runs', v_runs);
  perform public.record_job_run('whatsapp-retention', v_started, 'ok', v_result, null);
  return v_result;
end;
$$;

-- ── 2. Health ─────────────────────────────────────────────────────────────────────────────────────────────────
-- Every job Vyact schedules and how often it runs. migrationReplaySql (Q4-RP-007) fails when cron.job and this
-- list disagree, so a new job is watched from the day it ships.
create or replace function public.job_expectations()
returns table (job text, every_minutes int)
language sql
immutable
set search_path = public, pg_temp
as $$
  select * from (values
    ('job-health', 60), ('loan-auto-record', 30), ('recurring-post', 30), ('web-push-dispatch', 15),
    ('whatsapp-dispatch-alerts', 15), ('whatsapp-dispatch-bills', 30), ('whatsapp-dispatch-digest', 30),
    ('whatsapp-dispatch-monthly', 30), ('whatsapp-dispatch-weekly', 30), ('whatsapp-inbox-sweep', 5),
    ('whatsapp-retention', 1440)
  ) as t(job, every_minutes);
$$;

create or replace function public.job_health()
returns table (job text, every_minutes int, last_started_at timestamptz, last_finished_at timestamptz,
               last_status text, last_summary jsonb, last_error text, runs_24h int, failed_24h int, problem text)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with watch as (select min(r.started_at) as since from job_runs r),
  latest as (
    select e.job, e.every_minutes, l1.started_at, l1.finished_at, l1.status, l1.summary, l1.error, l2.status as prev_status,
           (select count(*)::int from job_runs r where r.job = e.job and r.started_at > now() - interval '24 hours') as runs_24h,
           (select count(*)::int from job_runs r
             where r.job = e.job and r.started_at > now() - interval '24 hours' and r.status = 'failed') as failed_24h
      from job_expectations() e
      left join lateral (select r.* from job_runs r where r.job = e.job order by r.started_at desc limit 1) l1 on true
      left join lateral (select r.status from job_runs r where r.job = e.job order by r.started_at desc offset 1 limit 1) l2 on true
  )
  select l.job, l.every_minutes, l.started_at, l.finished_at, l.status, l.summary, l.error, l.runs_24h, l.failed_24h,
         case
           -- Two of its intervals (and 10 minutes' grace) with no run. A job never recorded counts from the first
           -- run recorded anywhere, so nothing is late before recording starts.
           when coalesce(l.started_at, w.since) < now() - make_interval(mins => 2 * l.every_minutes + 10) then 'late'
           when l.status = 'failed' then 'failed'
           when l.status = 'partial' and l.prev_status = 'partial' then 'partial'
         end
    from latest l cross join watch w
   order by l.job;
$$;

create or replace function public.admin_job_health()
returns table (job text, every_minutes int, last_started_at timestamptz, last_finished_at timestamptz,
               last_status text, last_summary jsonb, last_error text, runs_24h int, failed_24h int, problem text)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin('roles') then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;
  return query select * from public.job_health();
end;
$$;

create or replace function public.admin_job_runs(p_job text, p_limit int default 20)
returns table (id bigint, job text, started_at timestamptz, finished_at timestamptz, status text, summary jsonb, error text)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin('roles') then
    raise exception 'forbidden: admin role required' using errcode = '42501';
  end if;
  return query
    select r.id, r.job, r.started_at, r.finished_at, r.status, r.summary, r.error
      from public.job_runs r
     where r.job = p_job
     order by r.started_at desc
     limit greatest(1, least(coalesce(p_limit, 20), 100));
end;
$$;

-- ── 3. The alert ──────────────────────────────────────────────────────────────────────────────────────────────
-- True when this run may email about (job, kind): nothing was sent about it in the last p_hours.
create or replace function public.claim_job_alert(p_job text, p_kind text, p_hours int default 24)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_claimed boolean;
begin
  insert into job_alerts as a (job, kind, last_sent_at) values (p_job, p_kind, now())
  on conflict (job, kind) do update set last_sent_at = excluded.last_sent_at
    where a.last_sent_at < now() - make_interval(hours => greatest(1, coalesce(p_hours, 24)))
  returning true into v_claimed;
  return coalesce(v_claimed, false);
end;
$$;

-- An email that could not be sent gives its claim back, so the next hourly check tries again.
create or replace function public.release_job_alert(p_job text, p_kind text)
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  delete from job_alerts where job = p_job and kind = p_kind;
$$;

create or replace function public.job_health_cron_ok(p text)
returns boolean
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  return length(coalesce(p, '')) >= 32
     and exists (select 1 from vault.decrypted_secrets s where s.name = 'job_health_cron_secret' and s.decrypted_secret = p);
end;
$$;

do $$
declare
  f text;
begin
  foreach f in array array[
    'record_job_run(text,timestamptz,text,jsonb,text)', 'run_loan_auto_record()', 'run_retention()',
    'job_expectations()', 'job_health()', 'claim_job_alert(text,text,integer)', 'release_job_alert(text,text)',
    'job_health_cron_ok(text)', 'admin_job_health()', 'admin_job_runs(text,integer)'
  ] loop
    execute format('revoke all on function public.%s from public, anon, authenticated', f);
    execute format('grant execute on function public.%s to service_role', f);
  end loop;
end;
$$;
-- The Health page's reads check the staff tier themselves.
grant execute on function public.admin_job_health() to authenticated;
grant execute on function public.admin_job_runs(text, integer) to authenticated;

-- ── The jobs ──────────────────────────────────────────────────────────────────────────────────────────────────
do $$
begin
  -- Nested, so a database without Vault never plans the inner query.
  if exists (select 1 from pg_namespace where nspname = 'vault') then
    if not exists (select 1 from vault.secrets where name = 'job_health_cron_secret') then
      perform vault.create_secret(encode(extensions.gen_random_bytes(32), 'hex'), 'job_health_cron_secret',
                                  'pg_cron -> job-health');
    end if;
  end if;

  if exists (select 1 from pg_namespace where nspname = 'cron') then
    -- The SQL jobs run through their recording wrappers.
    perform cron.alter_job(c.jobid, command := 'select public.run_loan_auto_record()')
       from cron.job c where c.jobname = 'loan-auto-record';
    perform cron.alter_job(c.jobid, command := 'select public.run_retention()')
       from cron.job c where c.jobname = 'whatsapp-retention';
    -- The hourly check, in the T5d form: this project's own URL from Vault, or no call.
    perform cron.unschedule(c.jobid) from cron.job c where c.jobname = 'job-health';
    perform cron.schedule('job-health', '55 * * * *', $job$
  select net.http_post(
    url     := u.decrypted_secret || '/functions/v1/job-health',
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-secret', s.decrypted_secret),
    body    := '{}'::jsonb,
    timeout_milliseconds := 55000)
  from vault.decrypted_secrets s, vault.decrypted_secrets u
  where s.name = 'job_health_cron_secret' and u.name = 'project_url';
$job$);
  end if;
end;
$$;

commit;

-- ─────────────────────────────────────────────────────────────────────
-- supabase/migrations/20261111120000_q5_archive_at_zero.sql
-- ─────────────────────────────────────────────────────────────────────
-- v10.133.0 — Track Q5: an account is archived at zero (audit FE-MNY-12; owner decision 20 Oct 2026: "refuse
-- archiving an account with a balance", shipped with the app's dialog so no one meets a bare error).
--
-- An archived account left the Accounts screen's "Spendable now" while Net Worth and Pip still counted its money, so
-- the three disagreed. From the app (an authenticated request), archiving an account whose balance is not zero is now
-- refused: `account_has_balance` (23514, so a queued save is set aside, never lost). Move the money out (a transfer,
-- or move_account_and_delete) or reconcile it to zero first. It applies to the kinds the Accounts summary reads: bank
-- accounts and cards. Cash in Hand could never be archived; a loan's account is archived by the loan functions
-- (mark_loan_paid_off, delete_debt) and is never part of "Spendable now". Accounts archived before this
-- keep what they hold, and the app now counts it everywhere (FE-UIC-12).
--
-- account_ledger_balance() is the app's fold (lib/accountBalance.ts computeAccountBalance), on the server: opening
-- balance + reconciliation offset + what arrived (income, transfers and investment withdrawals into it) − what left
-- (expenses, transfers and investment buys out of it), deleted entries excluded, a split entry at YOUR share
-- (`extras.split.yourShare`, as effectiveAmount reads it). Q5-SQL-001 holds the two folds equal.
--
-- MONEY MODEL: untouched. Nothing is written; an archive the balance forbids does not happen.

begin;

create or replace function public.account_ledger_balance(p_account uuid)
returns numeric
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with amounts as (
    select t.type, t.account_id, t.to_account_id,
           case when t.extras -> 'split' ->> 'isSplit' = 'true'
                 and jsonb_typeof(t.extras -> 'split' -> 'yourShare') = 'number'
                then (t.extras -> 'split' ->> 'yourShare')::numeric
                else t.amount end as amount
      from public.transactions t
     where t.deleted_at is null and (t.account_id = p_account or t.to_account_id = p_account)
  )
  select round(coalesce(a.opening_balance, 0) + coalesce(a.reconciliation_offset, 0)
       + coalesce((select sum(m.amount) from amounts m
                    where m.to_account_id = a.id and m.type in ('income', 'transfer', 'investment')), 0)
       - coalesce((select sum(m.amount) from amounts m
                    where m.account_id = a.id and m.type in ('expense', 'transfer', 'investment')), 0), 2)
    from public.accounts a where a.id = p_account
$$;
revoke all on function public.account_ledger_balance(uuid) from public, anon, authenticated;
grant execute on function public.account_ledger_balance(uuid) to service_role;
comment on function public.account_ledger_balance(uuid) is
  'Q5 (v10.133.0): an account''s balance as the app folds it (computeAccountBalance; a split at your share). Read by accounts_guard_lifecycle.';

create or replace function public.accounts_guard_lifecycle()
returns trigger
language plpgsql
security definer   -- v10.119.0: it reads loans, which row security must not hide from it
set search_path = public, pg_temp
as $$
declare
  v_claims  text := nullif(current_setting('request.jwt.claims', true), '');
  v_loan    text;
  v_balance numeric;
begin
  if v_claims is null or (v_claims::jsonb ->> 'role') is distinct from 'authenticated' then
    return new;
  end if;
  if old.kind = 'cash' and (new.kind is distinct from 'cash'
       or (new.is_archived and not old.is_archived)
       or (new.deleted_at is not null and old.deleted_at is null)) then
    raise exception 'cash_account_protected: Cash in Hand can be renamed, never archived or deleted'
      using errcode = '22023';
  end if;
  if new.kind = 'cash' and old.kind is distinct from 'cash' then
    raise exception 'cash_account_protected: Cash in Hand is created by the household, never converted'
      using errcode = '22023';
  end if;
  if new.deleted_at is not null and old.deleted_at is null
     and current_setting('vyact.account_delete', true) is distinct from 'on' then
    raise exception 'account_delete_guarded: delete an account with delete_account or move_account_and_delete'
      using errcode = '42501';
  end if;
  if old.deleted_at is not null and new.deleted_at is null then
    raise exception 'account_delete_final: a deleted account stays deleted' using errcode = '42501';
  end if;
  -- v10.119.0 (owner, 19 Oct 2026): a loan's automatic EMI would be refused from an archived account.
  if new.is_archived and not old.is_archived then
    select string_agg(d.name, ', ' order by d.name) into v_loan
      from public.debts d
     where d.household_id = old.household_id and d.funding_account_id = old.id
       and d.deleted_at is null and d.paid_off_at is null and d.auto_record
       and coalesce(d.direction, 'owed_by_me') = 'owed_by_me';
    if v_loan is not null then
      raise exception 'account_pays_a_loan: % records its EMIs from this account; change its paying account first', v_loan
        using errcode = '23503';
    end if;
    -- v10.133.0 (Q5, FE-MNY-12): a bank account or card is archived at zero. The balance is the NEW row's (its offset
    -- as this write leaves it), so a reconcile to zero and the archive can be one write.
    if old.kind in ('bank', 'credit_card') then
    v_balance := round(coalesce(new.opening_balance, 0) + coalesce(new.reconciliation_offset, 0)
                 - coalesce(old.opening_balance, 0) - coalesce(old.reconciliation_offset, 0)
                 + public.account_ledger_balance(old.id), 2);
    if abs(v_balance) >= 0.005 then
      raise exception 'account_has_balance: % still holds %; move the money out or reconcile it to zero before archiving',
        new.name, v_balance using errcode = '23514';
    end if;
    end if;
  end if;
  return new;
end $$;
revoke all on function public.accounts_guard_lifecycle() from public, anon, authenticated;

commit;
